int run_field_scene26_maglock_descriptor_route_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::error_code error;
    std::filesystem::remove_all(output, error);
    if (error) {
        std::cerr << "Scene-26 descriptor route QA: cannot clear output: "
                  << error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output / "sequence", error);
    if (error) {
        return 3;
    }

    constexpr std::uint16_t kScene = 26U;
    constexpr auto kElevatorEvent = FieldCollisionEventCode::event_29;
    constexpr std::uint8_t kMaglockSelection = 2U;
    constexpr auto kMaglockEvent = FieldCollisionEventCode::event_2;
    constexpr std::uint16_t kMaglockCollision = 0x00A2U;
    constexpr std::uint16_t kSecondaryMaglockCollision = 0x0082U;
    const auto& metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& rectangles = metadata.terrain_collision_rectangles;
    const auto spawn = field_scene.field_entity_world_position();
    if (field_scene.field_scene_reference_for_dump() != kScene ||
        spawn.x != 0x0A00U || spawn.y != 0x0500U ||
        field_scene.field_interaction_mode_for_dump() != 2U ||
        rectangles.size() <= 117U || rectangles[117U].left != 0x0100U ||
        rectangles[117U].right != 0x011FU ||
        rectangles[117U].top != 0x0160U ||
        rectangles[117U].bottom != 0x017FU ||
        rectangles[117U].value != kMaglockCollision ||
        rectangles.size() <= 110U || rectangles[110U].left != 0x01A0U ||
        rectangles[110U].right != 0x01BFU ||
        rectangles[110U].top != 0x0100U ||
        rectangles[110U].bottom != 0x011FU ||
        rectangles[110U].value != kSecondaryMaglockCollision) {
        std::cerr << "Scene-26 descriptor route QA: descriptor spawn or ROM "
                     "maglock records 110/117 do not match\n";
        return 3;
    }

    // The source passkey handler (ROM 0x21628) scans only live party slots,
    // then compares item +0x6E against the active event's selection. Give the
    // active Joshua record one explicit QA passkey with quality 2; all route,
    // interaction, result, and passage inputs remain ordinary controller
    // input.
    constexpr std::uint8_t kMaglockPasskeyItem = 0x14U;
    constexpr std::uint8_t kPasskeyQuality = 2U;
    const auto active_slot = field_scene.field_active_party_slot_for_dump();
    if (!field_scene.field_party_slot_active_for_dump(active_slot) ||
        (field_scene.active_runner_record().flags & 0x0100U) == 0U) {
        std::cerr << "Scene-26 passkey route QA: no live active runner record\n";
        return 3;
    }
    for (std::size_t slot = 0U;
         slot < field_scene.field_party_records_for_dump().size(); ++slot) {
        const auto& party_member =
            field_scene.field_party_records_for_dump()[slot];
        if (!field_scene.field_party_slot_active_for_dump(slot) ||
            (party_member.flags & 0x0100U) == 0U) {
            continue;
        }
        if (std::find(party_member.inventory_item_codes.begin(),
                      party_member.inventory_item_codes.end(),
                      kMaglockPasskeyItem) !=
            party_member.inventory_item_codes.end()) {
            std::cerr << "Scene-26 passkey route QA: New Game party already "
                         "has a Maglock Passkey\n";
            return 3;
        }
    }
    std::optional<std::size_t> passkey_slot;
    for (std::size_t slot = 0U;
         slot < field_scene.active_runner_record().inventory_item_codes.size();
         ++slot) {
        if (field_scene.active_runner_record().inventory_item_codes[slot] ==
            0U) {
            passkey_slot = slot;
            break;
        }
    }
    if (!passkey_slot.has_value()) {
        std::cerr << "Scene-26 passkey route QA: active runner inventory is full\n";
        return 3;
    }
    field_scene.active_runner_record().inventory_item_codes[*passkey_slot] =
        kMaglockPasskeyItem;
    field_scene.active_runner_record().inventory_phase_bytes[*passkey_slot] =
        kPasskeyQuality;

    const auto render = [&field_scene](const bool scene_only = false) { return render_qa_field(field_scene, scene_only); };
    const auto save = [&output, &render](const std::string_view name,
                                         const bool scene_only = false) {
        const auto image = render(scene_only);
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
               image.save(QString::fromStdWString(
                   (output / (std::string(name) + ".bmp")).wstring()));
    };
    const auto dump_collision_map = [&field_scene, &output](
                                       const std::string_view name) {
        const auto& collision_map =
            field_scene.state().field_scene_buffers.source_metadata
                .terrain_collision_map;
        if (collision_map.size() != 64U * 64U) {
            return false;
        }
        std::ofstream map_file(
            output / (std::string(name) + ".tsv"), std::ios::trunc);
        if (!map_file) {
            return false;
        }
        map_file << "row/col";
        for (std::size_t column = 0U; column < 64U; ++column) {
            map_file << '\t' << column;
        }
        map_file << '\n' << std::hex << std::setfill('0');
        for (std::size_t row = 0U; row < 64U; ++row) {
            map_file << std::dec << row;
            for (std::size_t column = 0U; column < 64U; ++column) {
                map_file << '\t' << std::hex << std::setw(2)
                         << static_cast<unsigned>(
                                collision_map[row * 64U + column]);
            }
            map_file << '\n';
        }
        return static_cast<bool>(map_file);
    };
    if (!dump_collision_map("terrain-collision-map-at-entry")) {
        std::cerr << "Scene-26 descriptor route QA: collision map is not a "
                     "64x64 grid or could not be captured\n";
        return 3;
    }
    std::ofstream trace(output / "route.tsv", std::ios::trunc);
    if (!trace) {
        return 3;
    }
    trace << "stage\tframe\tinput\tscene\tx\ty\tworld_mode\tfield_mode"
             "\tcollision\tactivity_selection\tevent\tnegative_probes"
             "\tcontinuation\ttransition_kind\tselector_open"
             "\tinteraction_open\tinteraction_options\tentity_visible"
             "\tscreen_x\tscreen_y\tcamera_x\tcamera_y\theading"
             "\ttarget_heading\tcamera_min_x\tcamera_max_x"
             "\tcamera_step_x\tcamera_layer_x_dirty"
             "\tcamera_layer_y_dirty\tcamera_interaction_locked"
             "\taudio_events\n";
    std::uint32_t frame = 0U;
    const auto audio_start = field_audio_events.size();
    const auto boundary_start = source_boundaries.size();
    const auto capture = [&](const std::string_view stage,
                             const std::string_view input) {
        const auto image = render();
        std::ostringstream name;
        name << "frame-" << std::setw(6) << std::setfill('0') << frame
             << ".bmp";
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(
                ((output / "sequence") / name.str()).wstring()))) {
            return false;
        }
        const auto position = field_scene.field_entity_world_position();
        const auto& movement =
            field_scene.last_field_movement_transition_for_dump();
        const auto& panel = field_scene.field_interaction_panel();
        trace << stage << '\t' << frame << '\t' << input << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << position.x << '\t' << position.y << '\t'
              << field_scene.field_interaction_mode_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_runtime_state_for_dump().field_mode)
              << '\t' << field_scene.field_terrain_collision_code_for_dump()
              << '\t' << static_cast<unsigned>(
                     field_scene.field_activity_selection_for_dump())
              << '\t' << static_cast<unsigned>(movement.event_code) << '\t'
              << static_cast<unsigned>(movement.negative_probe_count) << '\t'
              << static_cast<unsigned>(movement.continuation) << '\t'
              << static_cast<unsigned>(movement.kind) << '\t'
              << field_scene.elevator_selector_open_for_dump() << '\t'
              << panel.open << '\t'
              << static_cast<unsigned>(panel.option_count) << '\t'
              << field_scene.field_entity_visible_for_dump() << '\t'
              << field_scene.field_entity_screen_x_for_dump() << '\t'
              << field_scene.field_entity_screen_y_for_dump() << '\t'
              << field_scene.state().field_scene_buffers.camera_x << '\t'
              << field_scene.state().field_scene_buffers.camera_y << '\t'
              << field_scene.field_entity_heading_for_dump() << '\t'
              << field_scene.field_entity_target_heading_for_dump() << '\t'
              << field_scene.field_camera_follow_for_dump().minimum_x << '\t'
              << field_scene.field_camera_follow_for_dump().maximum_x << '\t'
              << static_cast<int>(field_scene.field_camera_follow_for_dump()
                                      .horizontal_step) << '\t'
              << field_scene.field_camera_follow_for_dump().layer_x_dirty
              << '\t'
              << field_scene.field_camera_follow_for_dump().layer_y_dirty
              << '\t'
              << field_scene.field_camera_follow_for_dump()
                     .interaction_locked << '\t'
              << (field_audio_events.size() - audio_start) << '\n';
        trace.flush();
        return true;
    };
    const auto tick_dpad = [&](const std::uint8_t nibble,
                               const std::string_view stage,
                               const std::string_view input) {
        field_scene.set_controller_nibble(nibble);
        field_scene.advance_frame();
        ++frame;
        return capture(stage, input);
    };
    const auto finish_modal_return_transition =
        [&](const std::string_view stage) {
            const auto starting_frames =
                field_scene.field_modal_return_transition_frames_for_dump();
            if (starting_frames == 0U || starting_frames > 60U ||
                field_scene.field_palette_fade_steps_for_dump() != 9U) {
                return false;
            }
            auto previous_fade_step =
                field_scene.field_palette_fade_steps_for_dump();
            while (field_scene
                       .field_modal_return_transition_frames_for_dump() != 0U) {
                field_scene.set_controller_port_byte(0U);
                field_scene.advance_frame();
                ++frame;
                const auto fade_step =
                    field_scene.field_palette_fade_steps_for_dump();
                if (fade_step > previous_fade_step ||
                    !capture(stage, "neutral")) {
                    return false;
                }
                previous_fade_step = fade_step;
                const auto remaining = field_scene
                    .field_modal_return_transition_frames_for_dump();
                if ((remaining == 30U || remaining == 0U) &&
                    !save(remaining == 0U
                              ? std::string(stage) + "-complete"
                              : std::string(stage) + "-midpoint")) {
                    return false;
                }
            }
            return field_scene.field_palette_fade_steps_for_dump() == 0U &&
                   render() == render(true);
        };

    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!field_scene.field_entity_visible_for_dump() ||
        !capture("descriptor-spawn", "neutral") ||
        !save("scene26-descriptor-spawn") ||
        !field_hud_chrome_survives(render(), asset_root)) {
        std::cerr << "Scene-26 descriptor route QA: spawn is not a clean field "
                     "screen\n";
        return 3;
    }

    // Four ordinary Right updates turn the descriptor-spawn heading into the
    // adjacent event-0x1D elevator trigger.
    std::uint16_t right_ticks = 0U;
    while (right_ticks < 16U &&
           !field_scene.elevator_selector_open_for_dump()) {
        if (!tick_dpad(0x08U, "spawn-to-elevator", "dpad-right")) {
            return 3;
        }
        ++right_ticks;
    }
    const auto elevator =
        field_scene.last_field_movement_transition_for_dump();
    if (!field_scene.elevator_selector_open_for_dump() ||
        elevator.event_code != kElevatorEvent ||
        elevator.continuation !=
            MovementModeTransitionContinuation::event_29_world_activity ||
        elevator.kind !=
            EntityMovementModeTransitionResultKind::world_activity_started ||
        field_scene.elevator_selector_current_floor_for_dump() !=
            field_scene.elevator_selector_selected_floor_for_dump() ||
        field_scene.elevator_selector_destination_for_dump() != kScene ||
        !save("spawn-elevator-selector") ||
        !field_hud_chrome_survives(render(), asset_root)) {
        std::cerr << "Scene-26 descriptor route QA: Right input did not open "
                     "the source event-0x1D selector\n";
        return 3;
    }

    // Start keeps the current floor and returns to its field view.
    field_scene.set_controller_port_byte(0x80U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("elevator-return", "start") ||
        field_scene.elevator_selector_open_for_dump() ||
        field_scene.field_scene_reference_for_dump() != kScene ||
        field_scene.field_interaction_open() ||
        !field_hud_chrome_survives(render(), asset_root) ||
        !save("field-after-elevator")) {
        std::cerr << "Scene-26 descriptor route QA: Start did not return to "
                     "the current floor cleanly\n";
        return 3;
    }
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("field-after-elevator", "neutral")) {
        return 3;
    }

    // Turn south-east to clear the elevator trigger lane, pass east of the
    // machinery, then follow the open south corridor to the A2 door. These
    // directional phases follow the observed collision-free route.
    // Tick counts follow the same corridor at the on-screen 0xBEC2 step of 30.
    for (std::uint8_t tick = 0U; tick < 8U; ++tick) {
        if (!tick_dpad(0x02U, "clear-elevator-trigger", "dpad-down") ||
            field_scene.elevator_selector_open_for_dump() ||
            field_scene.field_interaction_open()) {
            std::cerr << "Scene-26 descriptor route QA: could not clear the "
                         "elevator trigger lane\n";
            return 3;
        }
    }
    for (std::uint8_t tick = 0U; tick < 18U; ++tick) {
        if (!tick_dpad(0x08U, "east-of-elevator", "dpad-right") ||
            field_scene.elevator_selector_open_for_dump() ||
            field_scene.field_interaction_open()) {
            std::cerr << "Scene-26 descriptor route QA: unexpected event on "
                         "the eastbound route\n";
            return 3;
        }
    }
    std::uint16_t south_ticks = 0U;
    for (; south_ticks < 155U; ++south_ticks) {
        if (!tick_dpad(0x02U, "southbound-open-corridor", "dpad-down") ||
            field_scene.elevator_selector_open_for_dump()) {
            std::cerr << "Scene-26 descriptor route QA: unexpected modal or "
                         "frame failure on southbound route\n";
            return 3;
        }
        if (!field_scene.field_entity_visible_for_dump()) {
            std::cerr << "Scene-26 descriptor route QA: runner left the "
                         "visible field before reaching A2\n";
            return 3;
        }
    }
    std::uint16_t a2_ticks = 0U;
    while (a2_ticks < 28U && !field_scene.field_interaction_open()) {
        if (!tick_dpad(0x08U, "cross-a2-passage", "dpad-right") ||
            field_scene.elevator_selector_open_for_dump()) {
            std::cerr << "Scene-26 descriptor route QA: unexpected modal or "
                         "frame failure at the A2 passage\n";
            return 3;
        }
        ++a2_ticks;
    }
    field_scene.set_controller_port_byte(0U);
    const auto& movement =
        field_scene.last_field_movement_transition_for_dump();
    const auto& panel = field_scene.field_interaction_panel();
    const bool source_a2_prompt =
        field_scene.field_scene_reference_for_dump() == kScene &&
        field_scene.field_interaction_mode_for_dump() == 2U &&
        field_scene.field_activity_selection_for_dump() ==
            kMaglockSelection &&
        field_scene.field_interaction_open() && panel.source_complete &&
        panel.actor_kind == DialoguePanelActorKind::none &&
        panel.option_count == 1U && panel.text_segment_count != 0U &&
        panel.text_segments[0].find("sturdy door") != std::string_view::npos &&
        panel.options[0U].source_label.find("MORE") != std::string_view::npos &&
        movement.event_code == kMaglockEvent &&
        movement.negative_probe_count >= 2U &&
        movement.continuation ==
            MovementModeTransitionContinuation::maglock_door_interaction &&
        movement.kind ==
            EntityMovementModeTransitionResultKind::field_dialogue_started;
    const auto modal_frame = render();
    const auto field_underlay = render(true);
    if (!source_a2_prompt || modal_frame == field_underlay ||
        field_scene.elevator_selector_open_for_dump() ||
        !capture("maglock-introduction", "neutral") ||
        !save("maglock-introduction") || !save("actual")) {
        std::cerr << "Scene-26 descriptor route QA: record 117 did not open "
                     "the generic electromagnetic-lock introduction "
                     "(event=" << static_cast<unsigned>(
                         field_collision_event_value(movement.event_code))
                  << ", selection="
                  << static_cast<unsigned>(
                         field_scene.field_activity_selection_for_dump())
                  << ", probes=" << static_cast<unsigned>(
                         movement.negative_probe_count)
                  << ", panel=" << field_scene.field_interaction_open()
                  << ")\n";
        return 3;
    }
    if (!save("maglock-field-underlay", true)) {
        return 3;
    }

    for (std::uint8_t tick = 0U; tick < 10U; ++tick) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (!capture("maglock-introduction-hold", "neutral")) {
            return 3;
        }
    }
    if (render() != modal_frame || !field_scene.field_interaction_open() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.dialogue_open() || field_scene.shop_menu_open() ||
        !save("maglock-introduction-held") || !save("actual")) {
        std::cerr << "Scene-26 descriptor route QA: lock introduction did not "
                     "remain a clean full-screen page\n";
        return 3;
    }

    // A successful passkey action makes FFE16E negative. ROM 0x2C1A..0x2C34
    // then advances the sampled FF1700 map-event counter on field return,
    // which is the source-side state that should open this A2 passage.
    const auto collision_map_before_passkey =
        field_scene.state().field_scene_buffers.source_metadata
            .terrain_collision_map;
    const auto audio_before_passkey = field_audio_events.size();
    field_scene.set_controller_port_byte(0x40U); // ordinary A: passkey action
    field_scene.advance_frame();
    ++frame;
    if (!capture("maglock-passkey-action", "a")) {
        return 3;
    }
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("maglock-passkey-result-wait-1", "neutral")) {
        return 3;
    }
    const auto& passkey_result_panel = field_scene.field_interaction_panel();
    const auto passkey_result_image = render();
    const bool passkey_result_text =
        passkey_result_panel.text_segment_count >= 3U &&
        passkey_result_panel.text_segments[0].find("Maglock Passkey") !=
            std::string_view::npos &&
        passkey_result_panel.text_segments[2].find("door has been disabled") !=
            std::string_view::npos;
    if (!field_scene.field_interaction_open() ||
        !passkey_result_panel.open || !passkey_result_panel.source_complete ||
        passkey_result_panel.kind != DialoguePanelKind::information_page ||
        passkey_result_panel.actor_kind != DialoguePanelActorKind::none ||
        passkey_result_panel.option_count != 0U || !passkey_result_text ||
        field_scene.field_activity_selection_for_dump() != 0xFFU ||
        field_audio_events.size() != audio_before_passkey + 1U ||
        field_audio_events.back() != 0x4BU ||
        passkey_result_image == modal_frame ||
        field_hud_chrome_survives(passkey_result_image, asset_root) ||
        !save("maglock-passkey-result") ||
        !save("actual")) {
        std::cerr << "Scene-26 passkey route QA: source passkey action did not "
                     "show its disabled-door result, negative selection, and "
                     "0x4B sound (selection="
                  << static_cast<unsigned>(
                         field_scene.field_activity_selection_for_dump())
                  << ", audio=" << audio_before_passkey << "->"
                  << field_audio_events.size() << ")\n";
        return 3;
    }
    for (std::uint8_t wait_frame = 2U; wait_frame <= 30U; ++wait_frame) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (!capture("maglock-passkey-result-wait", "neutral")) {
            return 3;
        }
        if (wait_frame == 15U || wait_frame == 30U) {
            const auto held_result = render();
            if (held_result != passkey_result_image ||
                !save(wait_frame == 15U
                          ? "maglock-passkey-result-wait-15"
                          : "maglock-passkey-result-wait-30")) {
                std::cerr << "Scene-26 passkey route QA: result page changed "
                             "during its source 30-frame acknowledgement wait\n";
                return 3;
            }
        }
    }
    field_scene.set_controller_port_byte(0x40U); // ordinary A: acknowledge
    field_scene.advance_frame();
    ++frame;
    if (!capture("maglock-passkey-result-acknowledged", "a")) {
        return 3;
    }
    if (field_scene.field_modal_return_transition_frames_for_dump() != 60U ||
        field_scene.field_palette_fade_steps_for_dump() != 9U) {
        std::cerr << "Scene-26 passkey route QA: A acknowledgement did not "
                     "start the 60-frame return fade\n";
        return 3;
    }
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("maglock-passkey-field-return", "neutral")) {
        return 3;
    }
    // The source field coordinator commits the negative event result after
    // the modal has released the screen. Give that ordinary field frame its
    // own capture before attempting movement.
    field_scene.advance_frame();
    ++frame;
    if (!capture("maglock-passkey-event-state-settled", "neutral")) {
        return 3;
    }
    if (!finish_modal_return_transition("maglock-passkey-field-fade")) {
        std::cerr << "Scene-26 passkey route QA: the return fade did not "
                     "finish with a clean, unobscured field\n";
        return 3;
    }
    const auto& collision_map_after_passkey =
        field_scene.state().field_scene_buffers.source_metadata
            .terrain_collision_map;
    std::vector<std::tuple<std::size_t, std::uint8_t, std::uint8_t>>
        collision_map_changes;
    const auto map_count = std::min(collision_map_before_passkey.size(),
                                    collision_map_after_passkey.size());
    for (std::size_t index = 0U; index < map_count; ++index) {
        if (collision_map_before_passkey[index] !=
            collision_map_after_passkey[index]) {
            collision_map_changes.emplace_back(
                index, collision_map_before_passkey[index],
                collision_map_after_passkey[index]);
        }
    }
    const bool one_a2_event_advanced =
        collision_map_changes.size() == 1U &&
        std::get<1>(collision_map_changes.front()) == kMaglockCollision &&
        std::get<2>(collision_map_changes.front()) == 0x00A1U;
    const auto field_after_passkey = render();
    if (field_scene.field_interaction_open() ||
        field_scene.dialogue_open() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.shop_menu_open() ||
        !field_scene.field_entity_visible_for_dump() ||
        !field_hud_chrome_survives(field_after_passkey, asset_root) ||
        field_after_passkey != render(true) ||
        !one_a2_event_advanced ||
        field_audio_events.size() != audio_before_passkey + 1U ||
        !save("field-after-passkey") ||
        !save("field-after-passkey-field-only", true)) {
        std::cerr << "Scene-26 passkey route QA: field return did not redraw "
                     "cleanly and advance exactly the sampled A2 map cell "
                     "from 0xA2 to 0xA1 (changed cells="
                  << collision_map_changes.size() << ", scene="
                  << field_scene.state().field_scene_buffers.scene_reference
                  << ", interaction=" << field_scene.field_interaction_open()
                  << ", dialogue=" << field_scene.dialogue_open()
                  << ", mode_text="
                  << field_scene.field_mode_text_open_for_dump()
                  << ", shop=" << field_scene.shop_menu_open()
                  << ", actor="
                  << field_scene.field_entity_visible_for_dump()
                  << ", hud="
                  << field_hud_chrome_survives(field_after_passkey, asset_root)
                  << ", field_only="
                  << (field_after_passkey == render(true))
                  << ", map_delta=";
        if (!collision_map_changes.empty()) {
            const auto& [index, before, after] = collision_map_changes.front();
            std::cerr << index << ":0x" << std::hex
                      << static_cast<unsigned>(before) << "->0x"
                      << static_cast<unsigned>(after) << std::dec;
        } else {
            std::cerr << "none";
        }
        std::cerr << ")\n";
        return 3;
    }
    {
        std::ofstream event_delta(output / "collision-map-delta.tsv",
                                  std::ios::trunc);
        if (!event_delta) {
            return 3;
        }
        event_delta << "map_index\tbefore\tafter\n";
        for (const auto& [index, before, after] : collision_map_changes) {
            event_delta << index << "\t0x" << std::hex
                        << static_cast<unsigned>(before) << "\t0x"
                        << static_cast<unsigned>(after) << std::dec << '\n';
        }
    }
    std::uint16_t passage_ticks = 0U;
    while (field_scene.field_entity_world_position().x < 0x1200U &&
           passage_ticks < 180U) {
        if (!tick_dpad(0x08U, "passkey-open-a2-passage", "dpad-right") ||
            field_scene.field_interaction_open() ||
            field_scene.elevator_selector_open_for_dump()) {
            std::cerr << "Scene-26 passkey route QA: ordinary Right did not "
                         "continue through the A2 passage cleanly\n";
            return 3;
        }
        ++passage_ticks;
    }
    const auto passage_position = field_scene.field_entity_world_position();
    if (passage_position.x < 0x1200U ||
        passage_position.y < 0x1600U || passage_position.y > 0x17FFU ||
        !field_scene.field_entity_visible_for_dump() ||
        !field_hud_chrome_survives(render(), asset_root) ||
        !capture("a2-passage-crossed", "neutral") ||
        !save("a2-passage-crossed") || !save("actual")) {
        std::cerr << "Scene-26 passkey route QA: runner did not cross the "
                     "A2 passage in its source lane (position="
                  << passage_position.x << ',' << passage_position.y << ")\n";
        return 3;
    }

    // ROM scene-26 record 110 is a second value-0x82 maglock. Follow the
    // clear 64x64 collision-map cells from the A2 passage to that trigger,
    // then continue via the north corridor to records 124/125 (D8). The
    // route is grounded in the extracted scene collision records and the
    // B952/B9A8 event branches; every movement step still uses the controller.
    const auto walk_to = [&](const std::uint8_t nibble,
                             const std::string_view stage,
                             const std::string_view input,
                             const auto& reached,
                             const std::uint16_t max_ticks)
        -> std::optional<std::uint16_t> {
        std::uint16_t ticks = 0U;
        while (!reached() && ticks < max_ticks) {
            if (!tick_dpad(nibble, stage, input) ||
                field_scene.field_interaction_open() ||
                field_scene.elevator_selector_open_for_dump()) {
                return std::nullopt;
            }
            ++ticks;
        }
        return reached() ? std::optional<std::uint16_t>{ticks}
                         : std::nullopt;
    };
    auto route_position = field_scene.field_entity_world_position();
    const auto east_to_secondary_lane = walk_to(
        0x08U, "route-to-secondary-maglock-east", "dpad-right",
        [&] {
            return field_scene.field_entity_world_position().x >= 0x1380U;
        },
        40U);
    const auto north_to_secondary_lane = east_to_secondary_lane
        ? walk_to(0x01U, "route-to-secondary-maglock-north", "dpad-up",
                  [&] {
                      return field_scene.field_entity_world_position().y <=
                             0x13A0U;
                  },
                  60U)
        : std::nullopt;
    const auto east_to_secondary_door = north_to_secondary_lane
        ? walk_to(0x08U, "approach-secondary-maglock", "dpad-right",
                  [&] {
                      return field_scene.field_entity_world_position().x >=
                             0x1A20U;
                  },
                  60U)
        : std::nullopt;
    if (!east_to_secondary_lane || !north_to_secondary_lane ||
        !east_to_secondary_door) {
        route_position = field_scene.field_entity_world_position();
        std::cerr << "Scene-26 descriptor route QA: collision-map route to "
                     "record 110 failed (position="
                  << route_position.x << ',' << route_position.y << ")\n";
        return 3;
    }

    std::uint16_t secondary_maglock_ticks = 0U;
    while (secondary_maglock_ticks < 32U &&
           !field_scene.field_interaction_open()) {
        if (!tick_dpad(0x01U, "enter-secondary-maglock", "dpad-up") ||
            field_scene.elevator_selector_open_for_dump()) {
            std::cerr << "Scene-26 descriptor route QA: unexpected route "
                         "transition approaching record 110\n";
            return 3;
        }
        ++secondary_maglock_ticks;
    }
    field_scene.set_controller_nibble(0U);
    const auto secondary_position =
        field_scene.field_entity_world_position();
    const auto& secondary_movement =
        field_scene.last_field_movement_transition_for_dump();
    const auto& secondary_panel = field_scene.field_interaction_panel();
    const bool source_secondary_maglock_prompt =
        field_scene.field_scene_reference_for_dump() == kScene &&
        field_scene.field_interaction_mode_for_dump() == 2U &&
        field_scene.field_activity_selection_for_dump() ==
            kMaglockSelection &&
        field_scene.field_interaction_open() && secondary_panel.source_complete &&
        secondary_panel.actor_kind == DialoguePanelActorKind::none &&
        secondary_panel.option_count == 1U &&
        secondary_panel.text_segment_count != 0U &&
        secondary_panel.text_segments[0].find("sturdy door") !=
            std::string_view::npos &&
        secondary_panel.options[0U].source_label.find("MORE") !=
            std::string_view::npos &&
        secondary_movement.event_code == kMaglockEvent &&
        secondary_movement.negative_probe_count >= 2U &&
        secondary_movement.continuation ==
            MovementModeTransitionContinuation::maglock_door_interaction &&
        secondary_movement.kind ==
            EntityMovementModeTransitionResultKind::field_dialogue_started &&
        (secondary_position.x >> 4U) >= 0x01A0U &&
        (secondary_position.x >> 4U) <= 0x01BFU &&
        (secondary_position.y >> 4U) >= 0x0120U &&
        (secondary_position.y >> 4U) <= 0x013FU;
    const auto secondary_modal_frame = render();
    if (!source_secondary_maglock_prompt ||
        secondary_modal_frame == render(true) ||
        field_hud_chrome_survives(secondary_modal_frame, asset_root) ||
        !capture("secondary-maglock-introduction", "neutral") ||
        !save("secondary-maglock-introduction") ||
        !save("actual")) {
        std::cerr << "Scene-26 descriptor route QA: record 110 did not open "
                     "the source generic maglock prompt (event="
                  << static_cast<unsigned>(field_collision_event_value(
                         secondary_movement.event_code))
                  << ", probes="
                  << static_cast<unsigned>(
                         secondary_movement.negative_probe_count)
                  << ", runner=" << secondary_position.x << ','
                  << secondary_position.y << ")\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 10U; ++tick) {
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        if (!capture("secondary-maglock-introduction-hold", "neutral")) {
            return 3;
        }
    }
    if (render() != secondary_modal_frame ||
        !save("secondary-maglock-introduction-held")) {
        std::cerr << "Scene-26 descriptor route QA: second lock prompt "
                     "changed during its source 10-frame hold\n";
        return 3;
    }

    // 0x21628 leaves the passkey in its live runner slot after the first
    // success, so the same source property is checked at record 110.
    if (field_scene.active_runner_record().inventory_item_codes[*passkey_slot] !=
            kMaglockPasskeyItem ||
        field_scene.active_runner_record().inventory_phase_bytes[*passkey_slot] !=
            kPasskeyQuality) {
        std::cerr << "Scene-26 descriptor route QA: first passkey use changed "
                     "the source inventory record\n";
        return 3;
    }
    const auto collision_map_before_secondary_passkey =
        field_scene.state().field_scene_buffers.source_metadata
            .terrain_collision_map;
    const auto audio_before_secondary_passkey = field_audio_events.size();
    field_scene.set_controller_port_byte(0x40U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("secondary-passkey-action", "a")) {
        return 3;
    }
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("secondary-passkey-result-wait-1", "neutral")) {
        return 3;
    }
    const auto& secondary_result_panel =
        field_scene.field_interaction_panel();
    const auto secondary_result_image = render();
    const bool secondary_result_text =
        secondary_result_panel.text_segment_count >= 3U &&
        secondary_result_panel.text_segments[0].find("Maglock Passkey") !=
            std::string_view::npos &&
        secondary_result_panel.text_segments[2].find("door has been disabled") !=
            std::string_view::npos;
    if (!field_scene.field_interaction_open() ||
        !secondary_result_panel.open ||
        !secondary_result_panel.source_complete ||
        secondary_result_panel.kind != DialoguePanelKind::information_page ||
        secondary_result_panel.actor_kind != DialoguePanelActorKind::none ||
        secondary_result_panel.option_count != 0U ||
        !secondary_result_text ||
        field_scene.field_activity_selection_for_dump() != 0xFFU ||
        field_audio_events.size() != audio_before_secondary_passkey + 1U ||
        field_audio_events.back() != 0x4BU ||
        secondary_result_image == secondary_modal_frame ||
        field_hud_chrome_survives(secondary_result_image, asset_root) ||
        !save("secondary-passkey-result") || !save("actual")) {
        std::cerr << "Scene-26 descriptor route QA: second passkey action "
                     "did not resolve through the shared source handler\n";
        return 3;
    }
    for (std::uint8_t wait_frame = 2U; wait_frame <= 30U; ++wait_frame) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (!capture("secondary-passkey-result-wait", "neutral")) {
            return 3;
        }
        if (wait_frame == 15U || wait_frame == 30U) {
            const auto held_result = render();
            if (held_result != secondary_result_image ||
                !save(wait_frame == 15U
                          ? "secondary-passkey-result-wait-15"
                          : "secondary-passkey-result-wait-30")) {
                std::cerr << "Scene-26 descriptor route QA: second passkey "
                             "result changed during its source 30-frame wait\n";
                return 3;
            }
        }
    }
    field_scene.set_controller_port_byte(0x40U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("secondary-passkey-result-acknowledged", "a")) {
        return 3;
    }
    if (field_scene.field_modal_return_transition_frames_for_dump() != 60U ||
        field_scene.field_palette_fade_steps_for_dump() != 9U) {
        std::cerr << "Scene-26 descriptor route QA: second A acknowledgement "
                     "did not start the 60-frame return fade\n";
        return 3;
    }
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    if (!capture("secondary-passkey-field-return", "neutral")) {
        return 3;
    }
    field_scene.advance_frame();
    ++frame;
    if (!capture("secondary-passkey-event-state-settled", "neutral")) {
        return 3;
    }
    if (!finish_modal_return_transition(
            "secondary-passkey-field-fade")) {
        std::cerr << "Scene-26 descriptor route QA: the second return fade "
                     "did not finish with a clean field\n";
        return 3;
    }
    const auto& collision_map_after_secondary_passkey =
        field_scene.state().field_scene_buffers.source_metadata
            .terrain_collision_map;
    std::vector<std::tuple<std::size_t, std::uint8_t, std::uint8_t>>
        secondary_collision_map_changes;
    const auto secondary_map_count = std::min(
        collision_map_before_secondary_passkey.size(),
        collision_map_after_secondary_passkey.size());
    for (std::size_t index = 0U; index < secondary_map_count; ++index) {
        if (collision_map_before_secondary_passkey[index] !=
            collision_map_after_secondary_passkey[index]) {
            secondary_collision_map_changes.emplace_back(
                index, collision_map_before_secondary_passkey[index],
                collision_map_after_secondary_passkey[index]);
        }
    }
    const auto secondary_map_index = static_cast<std::size_t>(
        ((((0x0100U & 0xFFE0U) << 1U) + (0x01A0U >> 5U)) & 0x0FFFU));
    const bool secondary_maglock_opened =
        secondary_collision_map_changes.size() == 1U &&
        std::get<0>(secondary_collision_map_changes.front()) ==
            secondary_map_index &&
        std::get<1>(secondary_collision_map_changes.front()) ==
            kSecondaryMaglockCollision &&
        std::get<2>(secondary_collision_map_changes.front()) == 0x0081U;
    const auto field_after_secondary_passkey = render();
    const bool secondary_field_has_no_modal =
        !field_scene.field_interaction_open() && !field_scene.dialogue_open() &&
        !field_scene.field_mode_text_open_for_dump() &&
        !field_scene.shop_menu_open();
    const bool secondary_field_entity_visible =
        field_scene.field_entity_visible_for_dump();
    const bool secondary_field_hud_survives =
        field_hud_chrome_survives(field_after_secondary_passkey, asset_root);
    const bool secondary_field_matches_field_only =
        field_after_secondary_passkey == render(true);
    const bool secondary_passkey_audio_correct =
        field_audio_events.size() == audio_before_secondary_passkey + 1U;
    const bool secondary_field_saved =
        save("field-after-secondary-passkey") &&
        save("field-after-secondary-passkey-field-only", true);
    if (!secondary_field_has_no_modal ||
        !secondary_field_entity_visible || !secondary_field_hud_survives ||
        !secondary_field_matches_field_only || !secondary_maglock_opened ||
        !secondary_passkey_audio_correct || !secondary_field_saved) {
        std::cerr << "Scene-26 descriptor route QA: second field return did "
                     "not redraw cleanly and advance record 110 from 0x82 "
                     "to 0x81 (changed cells="
                  << secondary_collision_map_changes.size()
                  << ", expected index=" << secondary_map_index
                  << ", audio=" << audio_before_secondary_passkey << "->"
                  << field_audio_events.size();
        if (!secondary_collision_map_changes.empty()) {
            const auto [index, before, after] =
                secondary_collision_map_changes.front();
            std::cerr << ", delta=" << index << ":0x" << std::hex
                      << static_cast<unsigned>(before) << "->0x"
                      << static_cast<unsigned>(after) << std::dec;
        }
        std::cerr << ", interaction="
                  << field_scene.field_interaction_open()
                  << ", visible="
                  << field_scene.field_entity_visible_for_dump()
                  << ", screen="
                  << field_scene.field_entity_screen_x_for_dump() << ','
                  << field_scene.field_entity_screen_y_for_dump()
                  << ", camera="
                  << field_scene.state().field_scene_buffers.camera_x << ','
                  << field_scene.state().field_scene_buffers.camera_y
                  << ", clean_return="
                  << secondary_field_matches_field_only
                  << ", no_modal=" << secondary_field_has_no_modal
                  << ", hud=" << secondary_field_hud_survives
                  << ", map_opened=" << secondary_maglock_opened
                  << ", audio=" << secondary_passkey_audio_correct
                  << ", saved=" << secondary_field_saved << ")\n";
        return 3;
    }
    {
        std::ofstream event_delta(
            output / "secondary-maglock-collision-map-delta.tsv",
            std::ios::trunc);
        if (!event_delta) {
            return 3;
        }
        event_delta << "map_index\tbefore\tafter\n";
        for (const auto& [index, before, after] :
             secondary_collision_map_changes) {
            event_delta << index << "\t0x" << std::hex
                        << static_cast<unsigned>(before) << "\t0x"
                        << static_cast<unsigned>(after) << std::dec << '\n';
        }
    }
    if (!dump_collision_map("terrain-collision-map-before-d8")) {
        std::cerr << "Scene-26 descriptor route QA: current collision map "
                     "could not be captured before the D8 route\n";
        return 3;
    }

    // Records 124/125 place the D8 trigger in projected-grid rows 1-2,
    // columns 12-13. The collision map routes around the 0x7E cells along
    // row 6 to column 16, north through row 2, then west to column 13. The
    // intermediate targets allow the source heading turn to finish before a
    // probe reaches the wall.
    const auto north_through_secondary_door = walk_to(
        0x01U, "north-through-secondary-maglock", "dpad-up",
        [&] {
            return field_scene.field_entity_world_position().y <= 0x0D80U;
        },
        56U);
    const auto east_to_terminal_corridor = north_through_secondary_door
        ? walk_to(0x08U, "east-corridor-to-terminal", "dpad-right",
                  [&] {
                      return field_scene.field_entity_world_position().x >=
                             0x2000U;
                  },
                  84U)
        : std::nullopt;
    const auto north_to_terminal_lane = east_to_terminal_corridor
        ? walk_to(0x01U, "north-corridor-to-terminal", "dpad-up",
                  [&] {
                      return field_scene.field_entity_world_position().y <=
                             0x0640U;
                  },
                  136U)
        : std::nullopt;
    const auto west_to_terminal_lane = north_to_terminal_lane
        ? walk_to(0x04U, "align-terminal-trigger-lane", "dpad-left",
                  [&] {
                      return field_scene.field_entity_world_position().x <=
                             0x1B80U;
                  },
                  56U)
        : std::nullopt;
    if (!north_through_secondary_door || !east_to_terminal_corridor ||
        !north_to_terminal_lane || !west_to_terminal_lane) {
        route_position = field_scene.field_entity_world_position();
        std::cerr << "Scene-26 descriptor route QA: collision-map route to "
                     "the D8 approach failed (position="
                  << route_position.x << ',' << route_position.y << ")\n";
        return 3;
    }

    std::uint16_t terminal_entry_ticks = 0U;
    while (terminal_entry_ticks < 48U &&
           !field_scene.field_interaction_open()) {
        if (!tick_dpad(0x01U, "enter-d8-security-terminal", "dpad-up") ||
            field_scene.elevator_selector_open_for_dump()) {
            std::cerr << "Scene-26 descriptor route QA: unexpected transition "
                         "approaching the D8 Security Terminal\n";
            return 3;
        }
        ++terminal_entry_ticks;
    }
    field_scene.set_controller_nibble(0U);
    route_position = field_scene.field_entity_world_position();
    const auto& terminal_movement =
        field_scene.last_field_movement_transition_for_dump();
    const auto& terminal_panel = field_scene.field_interaction_panel();
    const bool source_terminal_prompt =
        field_scene.field_scene_reference_for_dump() == kScene &&
        field_scene.field_interaction_mode_for_dump() == 2U &&
        field_scene.field_interaction_open() && terminal_panel.open &&
        terminal_panel.source_complete && terminal_panel.option_count == 2U &&
        terminal_panel.options[0U].role ==
            DialoguePanelOptionRole::field_security_access &&
        terminal_panel.options[1U].role ==
            DialoguePanelOptionRole::field_walk_away &&
        terminal_movement.event_code == FieldCollisionEventCode::event_24 &&
        terminal_movement.negative_probe_count >= 2U &&
        terminal_movement.continuation ==
            MovementModeTransitionContinuation::building_security_terminal &&
        terminal_movement.kind ==
            EntityMovementModeTransitionResultKind::building_reaction_started &&
        (route_position.x >> 4U) >= 0x01A0U &&
        (route_position.x >> 4U) <= 0x01BFU &&
        (route_position.y >> 4U) >= 0x0020U &&
        (route_position.y >> 4U) <= 0x005FU;
    const auto terminal_modal_frame = render();
    if (!source_terminal_prompt || terminal_modal_frame == render(true) ||
        field_hud_chrome_survives(terminal_modal_frame, asset_root) ||
        !save("security-terminal-from-descriptor-spawn") ||
        !capture("security-terminal-from-descriptor-spawn", "neutral") ||
        !save("actual")) {
        std::cerr << "Scene-26 descriptor route QA: normal map path did not "
                     "reach the D8 event-24 Security Terminal (event="
                  << static_cast<unsigned>(field_collision_event_value(
                         terminal_movement.event_code))
                  << ", probes="
                  << static_cast<unsigned>(
                         terminal_movement.negative_probe_count)
                  << ", runner=" << route_position.x << ','
                  << route_position.y << ")\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 10U; ++tick) {
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        if (!capture("security-terminal-introduction-hold", "neutral")) {
            return 3;
        }
    }
    if (render() != terminal_modal_frame ||
        field_scene.dialogue_open() || field_scene.shop_menu_open() ||
        !save("security-terminal-introduction-held") || !save("actual")) {
        std::cerr << "Scene-26 descriptor route QA: terminal prompt changed "
                     "during its source 10-frame hold or left stale UI\n";
        return 3;
    }

    std::ofstream audio_file(output / "audio-events.txt", std::ios::trunc);
    for (std::size_t index = audio_start;
         index < field_audio_events.size(); ++index) {
        audio_file << "0x" << std::hex << field_audio_events[index] << '\n';
    }
    std::ofstream boundary_file(output / "source-boundaries.txt",
                                std::ios::trunc);
    for (std::size_t index = boundary_start;
         index < source_boundaries.size(); ++index) {
        boundary_file << source_boundaries[index] << '\n';
    }
    if (!audio_file || !boundary_file) {
        return 3;
    }

    std::cout << "field_scene26_maglock_descriptor_route_qa=passed "
                 "scene=26 elevator_event=0x1D maglock_collision=0xA2 "
                 "maglock_event=2 passkey_item=0x14 quality="
              << static_cast<unsigned>(kPasskeyQuality)
              << " map_counter=A2->A1,82->81 right_ticks=" << right_ticks
              << " south_ticks=" << south_ticks << " a2_ticks=" << a2_ticks
              << " passage_ticks=" << passage_ticks
              << " secondary_maglock_ticks=" << secondary_maglock_ticks
              << " terminal_entry_ticks=" << terminal_entry_ticks
              << " prompt=generic_sturdy_door passkey_result=door_disabled "
                 "terminal_prompt=source_event_0x18 "
                 "frames=" << frame
              << " artifacts=" << output.string() << '\n';
    return 0;
}

int run_field_scene26_event1_terminal_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Scene-26 event-1 terminal QA: could not clear output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        return 3;
    }

    // Keep one FieldSceneRuntime alive across the normal scene-2 collision,
    // map-event selection, scene-26 route, and terminal result. Only the
    // inventory, skill, and PRNG values below are test fixtures; all map and
    // menu transitions use ordinary controller input.
    const auto entry_output = output / "scene2-event1-entry";
    if (run_field_scene26_event1_physical_entry_qa(
            field_scene, asset_root, entry_output, field_audio_events,
            source_boundaries) != 0) {
        return 3;
    }
    auto selected_floor = field_scene.security_floor_index_for_dump();
    const auto& activity = field_scene.world_activity_state_for_dump();
    if (field_scene.field_scene_reference_for_dump() != 26U ||
        !selected_floor.has_value() || *selected_floor != 0U ||
        activity.mode != WorldActivityMode::resource_activity ||
        activity.scene_id != 26U ||
        activity.resource_random_index_bound != 3U ||
        activity.selected_resource_random_index != *selected_floor ||
        field_scene.field_entity_world_position().x != 0x0A00U ||
        field_scene.field_entity_world_position().y != 0x0500U) {
        std::cerr << "Scene-26 event-1 terminal QA: ordinary entry did not "
                     "preserve the selected resource-floor state\n";
        return 3;
    }

    // Keep the physical event-31 route in the same end-to-end session, but
    // run it after the terminal result has returned to ordinary scene-26
    // movement. Its Exit choice restores the source scene captured by the
    // original scene-2 resource entry.
    const auto exercise_resource_scene_exit_menu = [&]() {
    const auto exit_render = [&field_scene](const bool field_only = false) {
        QImage frame(kSceneWidth, kSceneHeight, QImage::Format_RGB32);
        frame.fill(Qt::black);
        QPainter painter(&frame);
        if (field_only) {
            field_scene.paint_field_scene_for_dump(painter);
        } else {
            field_scene.paint(painter);
        }
        painter.end();
        return frame;
    };
    const auto save_exit_frame = [&output, &exit_render](
                                     const std::string_view name) {
        return exit_render().save(QString::fromStdWString(
            (output / (std::string(name) + ".bmp")).wstring()));
    };
    const auto menu_audio_before = field_audio_events.size();
    for (std::uint8_t warmup = 0U; warmup < 90U; ++warmup) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
    }
    // Collision records use 12.4 world coordinates after the terrain probe
    // normalizes actor positions. Seed one source pixel south of record 126:
    // x=0x0210, y=0x0230 in the record's integer coordinate space.
    field_scene.set_field_entity_world_position_for_dump(
        static_cast<std::uint16_t>(0x0210U << 4U),
        static_cast<std::uint16_t>(0x0230U << 4U));
    for (std::uint8_t input_frame = 0U;
         input_frame < 48U && !field_scene.dialogue_open(); ++input_frame) {
        field_scene.set_controller_nibble(0x01U); // Ordinary Up.
        field_scene.advance_frame();
        if (field_scene.last_field_movement_transition_for_dump().event_code ==
                FieldCollisionEventCode::event_31 &&
            field_scene.last_field_movement_transition_for_dump()
                .mode_event_code_published) {
            break;
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    for (std::uint8_t settle = 0U;
         settle < 4U && !field_scene.dialogue_open(); ++settle) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
    }
    const auto main_menu = exit_render();
    const auto& main_menu_panel = field_scene.dialogue_panel();
    const bool main_menu_content_matches =
        main_menu_panel.text_segment_count != 0U &&
        main_menu_panel.text_segments[0] == "Main Menu" &&
        main_menu_panel.option_count == 2U &&
        main_menu_panel.options[0].source_label == "Cyberspace" &&
        main_menu_panel.options[1].source_label == "Exit";
    if (!field_scene.dialogue_open() ||
        !main_menu_panel.cursor_selection ||
        main_menu_panel.option_count != 2U ||
        main_menu_panel.selected_option != 0U ||
        !main_menu_content_matches ||
        !image_has_green_ink(main_menu, 88, 16, 216, 24) ||
        field_hud_chrome_survives(main_menu, asset_root) ||
        main_menu == exit_render(true) ||
        !save_exit_frame("scene26-main-menu-cyberspace-selected")) {
        std::cerr << "Scene-26 event-31 QA: south approach did not open the "
                     "scripted Main Menu; pos="
                  << std::hex << field_scene.field_entity_world_position().x
                  << ',' << field_scene.field_entity_world_position().y
                  << " event=" << static_cast<unsigned>(
                         field_scene.last_field_movement_transition_for_dump()
                             .event_code)
                  << " continuation=" << static_cast<unsigned>(
                         field_scene.last_field_movement_transition_for_dump()
                             .continuation)
                  << " kind=" << static_cast<unsigned>(
                         field_scene.last_field_movement_transition_for_dump()
                             .kind)
                  << " terrain=0x" << field_scene
                         .field_terrain_collision_code_for_dump()
                  << " controller=0x" << field_scene
                         .controller_event_word_for_dump()
                  << " lock=" << field_scene.field_runtime_state_for_dump()
                         .field_activity_lock
                  << " active=" << field_scene.field_entity_active_for_dump()
                  << " visible=" << field_scene.field_entity_visible_for_dump()
                  << " timeout=" << static_cast<unsigned>(
                         field_scene.world_activity_request_timeout_for_dump())
                  << '\n';
        return 3;
    }
    for (std::uint8_t idle_frame = 1U; idle_frame <= 30U; ++idle_frame) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        if (exit_render() != main_menu ||
            field_scene.dialogue_panel().selected_option != 0U ||
            field_audio_events.size() != menu_audio_before) {
            std::cerr << "Scene-26 event-31 QA: the Main Menu changed or "
                         "requested audio during its 30-frame idle hold\n";
            return 3;
        }
        if ((idle_frame == 1U || idle_frame == 15U || idle_frame == 30U) &&
            !save_exit_frame(
                idle_frame == 1U ? "scene26-main-menu-hold-01"
                : idle_frame == 15U ? "scene26-main-menu-hold-15"
                                    : "scene26-main-menu-hold-30")) {
            return 3;
        }
    }
    field_scene.set_controller_nibble(0x02U); // Lua-owned Down selection.
    field_scene.advance_frame();
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    if (field_scene.dialogue_panel().selected_option != 1U ||
        field_audio_events.size() != menu_audio_before ||
        !save_exit_frame("scene26-main-menu-exit-selected")) {
        std::cerr << "Scene-26 event-31 QA: Lua Down did not select Exit "
                     "without a navigation sound\n";
        return 3;
    }
    field_scene.set_controller_port_byte(0x40U); // Confirm Exit with A.
    field_scene.advance_frame();
    field_scene.set_controller_port_byte(0U);
    if (field_scene.dialogue_open() ||
        field_scene.field_modal_return_transition_frames_for_dump() != 60U ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_audio_events.size() != menu_audio_before) {
        std::cerr << "Scene-26 event-31 QA: Exit did not restore Scene 2\n";
        return 3;
    }
    for (std::uint8_t transition_frame = 0U; transition_frame < 60U;
         ++transition_frame) {
        field_scene.advance_frame();
        if ((transition_frame == 29U || transition_frame == 59U) &&
            !save_exit_frame(transition_frame == 29U
                                 ? "resource-exit-return-midpoint"
                                 : "resource-exit-return-complete")) {
            return 3;
        }
    }
    const auto returned_source_field = exit_render();
    if (field_scene.field_palette_fade_steps_for_dump() != 0U ||
        !field_hud_chrome_survives(returned_source_field, asset_root) ||
        returned_source_field != exit_render(true) ||
        !save_exit_frame("source-field-return-after-resource-scene")) {
        std::cerr << "Scene-26 event-31 QA: completed Exit redraw is not clean\n";
        return 3;
    }

    return 0;
    };

    const auto physical_route_output = output / "scene26-physical-route";
    if (run_field_scene26_maglock_descriptor_route_qa(
            field_scene, asset_root, physical_route_output,
            field_audio_events, source_boundaries) != 0) {
        return 3;
    }
    if (!field_scene.field_interaction_open() ||
        field_scene.security_floor_index_for_dump() != selected_floor) {
        std::cerr << "Scene-26 event-1 terminal QA: physical route lost the "
                     "selected floor before the Security Terminal prompt\n";
        return 3;
    }

    const auto render = [&field_scene](const bool field_only = false) { return render_qa_field(field_scene, field_only); };
    const auto save = [&output](const std::string_view name,
                                const QImage& frame) {
        return frame.size() == QSize(kSceneWidth, kSceneHeight) &&
               frame.save(QString::fromStdWString(
                   (output / (std::string(name) + ".bmp")).wstring()));
    };

    const auto terminal_prompt = render();
    if (!save("terminal-prompt-before-electronics", terminal_prompt)) {
        return 3;
    }
    // Match the deterministic terminal-result route's explicit source inputs.
    field_scene.active_runner_record().skills[9U] = 10U;
    field_scene.set_source_random_seed_for_dump(0x1234U);
    const auto audio_before_access = field_audio_events.size();
    for (std::uint8_t wait = 1U; wait <= 10U; ++wait) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        if (render() != terminal_prompt) {
            std::cerr << "Scene-26 event-1 terminal QA: prompt changed during "
                         "its source ten-frame input delay\n";
            return 3;
        }
        if ((wait == 1U || wait == 10U) &&
            !save(wait == 1U ? "terminal-prompt-wait-1"
                             : "terminal-prompt-wait-10",
                  render())) {
            return 3;
        }
    }
    tap_qa_controller_button(field_scene, 0x40U); // ordinary A: Electronics

    const auto& result_panel = field_scene.field_interaction_panel();
    bool first_floor_visible = false;
    for (std::size_t segment = 0U;
         segment < result_panel.text_segment_count; ++segment) {
        first_floor_visible = first_floor_visible ||
            result_panel.text_segments[segment].find("first floor") !=
                std::string_view::npos;
    }
    const auto floor_result = render();
    if (!field_scene.field_interaction_open() || !result_panel.open ||
        !result_panel.source_complete ||
        result_panel.kind != DialoguePanelKind::information_page ||
        result_panel.actor_kind != DialoguePanelActorKind::none ||
        result_panel.option_count != 0U || !first_floor_visible ||
        field_audio_events.size() != audio_before_access + 1U ||
        field_audio_events.back() != 0x30U ||
        floor_result == terminal_prompt ||
        field_hud_chrome_survives(floor_result, asset_root) ||
        !save("security-terminal-first-floor-result", floor_result) ||
        !save("actual", floor_result)) {
        std::cerr << "Scene-26 event-1 terminal QA: Electronics did not use "
                     "the selected floor in its successful result (floor="
                  << static_cast<unsigned>(*selected_floor) << ", audio="
                  << audio_before_access << "->" << field_audio_events.size()
                  << ")\n";
        return 3;
    }

    for (std::uint8_t wait = 1U; wait <= 30U; ++wait) {
        field_scene.advance_frame();
        if (render() != floor_result) {
            std::cerr << "Scene-26 event-1 terminal QA: result changed during "
                         "its source 30-frame hold\n";
            return 3;
        }
        if ((wait == 1U || wait == 15U || wait == 30U) &&
            !save(wait == 1U ? "first-floor-result-wait-1"
                 : wait == 15U ? "first-floor-result-wait-15"
                               : "first-floor-result-wait-30",
                  render())) {
            return 3;
        }
    }
    field_scene.set_controller_port_byte(0x40U); // ordinary A dismisses
    field_scene.advance_frame();
    if (field_scene.field_modal_return_transition_frames_for_dump() != 60U ||
        field_scene.field_palette_fade_steps_for_dump() != 9U) {
        std::cerr << "Scene-26 event-1 terminal QA: result acknowledgement "
                     "did not start the 60-frame return fade\n";
        return 3;
    }
    field_scene.set_controller_port_byte(0U);
    for (std::uint8_t transition_frame = 0U; transition_frame < 60U;
         ++transition_frame) {
        field_scene.advance_frame();
        if ((transition_frame == 29U || transition_frame == 59U) &&
            !save(transition_frame == 29U
                      ? "scene26-terminal-return-midpoint"
                      : "scene26-terminal-return-complete",
                  render())) {
            std::cerr << "Scene-26 event-1 terminal QA: return-fade frame "
                         "could not be saved\n";
            return 3;
        }
    }
    const auto returned_field = render();
    if (field_scene.field_modal_return_transition_frames_for_dump() != 0U ||
        field_scene.field_palette_fade_steps_for_dump() != 0U ||
        field_scene.field_interaction_open() ||
        field_scene.field_scene_reference_for_dump() != 26U ||
        field_scene.security_floor_index_for_dump() != selected_floor ||
        !field_scene.field_entity_visible_for_dump() ||
        !field_hud_chrome_survives(returned_field, asset_root) ||
        returned_field != render(true) ||
        !save("scene26-return-after-terminal", returned_field)) {
        std::cerr << "Scene-26 event-1 terminal QA: acknowledgement did not "
                     "return to a clean selected scene\n";
        return 3;
    }

    if (exercise_resource_scene_exit_menu() != 0) {
        return 3;
    }

    std::ofstream route_state(output / "selected-floor-route.tsv",
                              std::ios::trunc);
    if (!route_state) {
        return 3;
    }
    route_state << "scene2_collision_event\tmap_row\tresource_scene\t"
                   "resource_bound\tselected_floor\tterminal_event\t"
                   "terminal_sound_request\tevent31_menu\treturn_scene\n"
                << "1\t1\t0x1A\t3\t"
                << static_cast<unsigned>(*selected_floor)
                 << "\t0x18\t0x30\tmain_menu_exit\t2\n";
    std::cout << "field_scene26_event1_terminal_qa=passed "
                 "collision_event=1 resource_scene=0x1A floor="
              << static_cast<unsigned>(*selected_floor)
              << " terminal_event=0x18 outcome=first-floor audio=0x30 "
                 "event31_menu=main_menu_exit return_scene=2 "
                 "passkey_and_skill=qa-seeded artifacts="
              << output.string() << '\n';
    return 0;
}

int run_field_security_terminal_physical_entry_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Security Terminal physical-entry QA: could not clear "
                     "previous captures: " << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output / "sequence", output_error);
    if (output_error) {
        std::cerr << "Security Terminal physical-entry QA: could not create "
                     "capture directory: " << output_error.message() << '\n';
        return 3;
    }

    constexpr auto kSecurityEvent = FieldCollisionEventCode::event_24;
    constexpr std::uint16_t kSecurityCollision = 0x00D8U;
    constexpr std::array<std::size_t, 2> kSecurityRecords{124U, 125U};
    const auto& metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& rectangles = metadata.terrain_collision_rectangles;
    const bool collision_records_match =
        rectangles.size() > kSecurityRecords.back() &&
        rectangles[124U].left == 0x0180U &&
        rectangles[124U].right == 0x019FU &&
        rectangles[124U].top == 0x0020U &&
        rectangles[124U].bottom == 0x003FU &&
        rectangles[124U].value == kSecurityCollision &&
        rectangles[125U].left == 0x01A0U &&
        rectangles[125U].right == 0x01BFU &&
        rectangles[125U].top == 0x0020U &&
        rectangles[125U].bottom == 0x003FU &&
        rectangles[125U].value == kSecurityCollision;
    const auto collision_cell_index = [](const std::uint16_t x,
                                         const std::uint16_t y) {
        return static_cast<std::size_t>(
            ((((static_cast<std::uint32_t>(y) & 0xFFE0U) << 1U) +
              (x >> 5U)) &
             0x0FFFU));
    };
    const auto& collision_map = metadata.terrain_collision_map;
    const bool terminal_collision_cells_match =
        collision_map[collision_cell_index(0x0180U, 0x0020U)] ==
            kSecurityCollision &&
        collision_map[collision_cell_index(0x01A0U, 0x0020U)] ==
            kSecurityCollision;
    const auto initial_position = field_scene.field_entity_world_position();
    if (field_scene.field_scene_reference_for_dump() != 26U ||
        initial_position.x != 0x1A00U || initial_position.y != 0x0500U ||
        !collision_records_match || !terminal_collision_cells_match) {
        std::cerr << "Security Terminal physical-entry QA: scene-26 pre-trigger "
                     "checkpoint or ROM event rectangles do not match (scene="
                  << field_scene.field_scene_reference_for_dump() << ", runner="
                  << initial_position.x << ',' << initial_position.y
                  << ", expected=0x1A00,0x0500, collision_count="
                  << rectangles.size() << ", record124=";
        if (rectangles.size() > kSecurityRecords.back()) {
            std::cerr << std::hex << rectangles[124U].left << ','
                      << rectangles[124U].right << ',' << rectangles[124U].top
                      << ',' << rectangles[124U].bottom << ','
                      << rectangles[124U].value << "; record125="
                      << rectangles[125U].left << ','
                      << rectangles[125U].right << ',' << rectangles[125U].top
                      << ',' << rectangles[125U].bottom << ','
                      << rectangles[125U].value << std::dec;
        }
        std::cerr << ")\n";
        return 3;
    }

    const auto render = [&field_scene](const bool scene_only) { return render_qa_field(field_scene, scene_only); };
    const auto save = [&output, &render](const std::string_view name,
                                         const bool scene_only = false) {
        const auto image = render(scene_only);
        const auto path = output / (std::string(name) + ".bmp");
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            std::cerr << "Security Terminal physical-entry QA: could not "
                         "save full frame " << name << '\n';
            return false;
        }
        return true;
    };
    std::ofstream trace(output / "route.tsv", std::ios::trunc);
    if (!trace) {
        std::cerr << "Security Terminal physical-entry QA: could not write "
                     "route trace\n";
        return 3;
    }
    trace << "stage\tframe\tscene\tx\ty\tworld_mode\tfield_mode"
             "\tcollision\tmode_event\tinteraction\tselected_option"
             "\tterrain_sample_0\tterrain_sample_1\tterrain_sample_2"
             "\tterrain_sample_3\taudio_events\ttransition_event"
             "\tnegative_probe_count\tcontinuation\ttransition_kind"
             "\tentity_visible"
             "\tscreen_x\tscreen_y\tdirection\twalking\n";
    std::uint32_t frame = 0U;
    const auto write_state = [&] (const std::string_view stage) {
        const auto position = field_scene.field_entity_world_position();
        const auto& panel = field_scene.field_interaction_panel();
        const auto& transition =
            field_scene.last_field_movement_transition_for_dump();
        trace << stage << '\t' << frame << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << position.x << '\t' << position.y << '\t'
              << field_scene.field_interaction_mode_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_runtime_state_for_dump().field_mode)
              << '\t' << field_scene.field_terrain_collision_code_for_dump()
              << '\t' << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump())
              << '\t' << field_scene.field_interaction_open() << '\t'
              << panel.selected_option;
        for (const auto sample :
             field_scene.field_terrain_sample_bytes_for_dump()) {
            trace << '\t' << static_cast<unsigned>(sample);
        }
        trace << '\t' << field_audio_events.size() << '\t'
              << static_cast<unsigned>(transition.event_code) << '\t'
              << static_cast<unsigned>(transition.negative_probe_count) << '\t'
              << static_cast<unsigned>(transition.continuation) << '\t'
              << static_cast<unsigned>(transition.kind) << '\t'
              << field_scene.field_entity_visible_for_dump() << '\t'
              << field_scene.field_entity_screen_x_for_dump() << '\t'
              << field_scene.field_entity_screen_y_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_entity_direction_for_dump())
              << '\t' << field_scene.field_entity_walking_for_dump() << '\n';
        trace.flush();
    };
    const auto save_sequence_frame = [&] {
        std::ostringstream filename;
        filename << "frame-" << std::setw(6) << std::setfill('0') << frame
                 << ".bmp";
        const auto image = render(false);
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
               image.save(QString::fromStdWString(
                   ((output / "sequence") / filename.str()).wstring()));
    };
    const auto position_in_scene_units = [&field_scene] {
        const auto position = field_scene.field_entity_world_position();
        return std::pair<std::uint16_t, std::uint16_t>{
            static_cast<std::uint16_t>(position.x >> 4U),
            static_cast<std::uint16_t>(position.y >> 4U)};
    };

    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!field_scene.field_entity_visible_for_dump()) {
        std::cerr << "Security Terminal physical-entry QA: aligned source "
                     "checkpoint does not project the runner into the field\n";
        return 3;
    }
    if (!save("scene26-entry") || !save_sequence_frame()) {
        return 3;
    }
    write_state("pre-trigger-checkpoint");

    const auto advance_input = [&](const std::uint8_t nibble) {
        field_scene.set_controller_nibble(nibble);
        field_scene.advance_frame();
        ++frame;
        return save_sequence_frame();
    };
    const auto reached_terminal_event = [&] {
        return (field_scene.field_terrain_collision_code_for_dump() & 0x001FU) ==
               field_collision_event_value(kSecurityEvent);
    };

    // Walk north into the 0xD8 collision using normal controller input. The ROM
    // gate requires two negative samples from this adjacent-record region.
    std::uint16_t entry_ticks = 0U;
    while (entry_ticks < 40U && !reached_terminal_event() &&
           !field_scene.field_interaction_open()) {
        if (!advance_input(0x01U)) {
            std::cerr << "Security Terminal physical-entry QA: frame write "
                         "failed during north approach\n";
            return 3;
        }
        ++entry_ticks;
        if (!field_scene.field_interaction_open() &&
            !field_scene.field_entity_visible_for_dump()) {
            std::cerr << "Security Terminal physical-entry QA: runner became "
                         "invisible during the terminal approach\n";
            return 3;
        }
        write_state("terminal-approach");
        if (reached_terminal_event()) {
            (void)save("terminal-contact");
        }
    }
    field_scene.set_controller_nibble(0U);
    const auto activity_started_for_entry = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.world.activity.started");
    const auto prompt_opened_for_entry = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.interaction.prompt_opened");
    const auto& movement_transition =
        field_scene.last_field_movement_transition_for_dump();
    const bool security_terminal_transition =
        movement_transition.event_code == kSecurityEvent &&
        movement_transition.negative_probe_count >= 2U &&
        movement_transition.continuation ==
            MovementModeTransitionContinuation::building_security_terminal &&
        movement_transition.kind ==
            EntityMovementModeTransitionResultKind::building_reaction_started;
    const auto& entry_panel = field_scene.field_interaction_panel();
    const bool source_terminal_prompt_open =
        entry_panel.open && entry_panel.source_complete &&
        entry_panel.option_count == 2U &&
        entry_panel.options[0U].role ==
            DialoguePanelOptionRole::field_security_access &&
        entry_panel.options[1U].role ==
            DialoguePanelOptionRole::field_walk_away &&
        activity_started_for_entry != source_boundaries.end() &&
        prompt_opened_for_entry != source_boundaries.end() &&
        security_terminal_transition;
    if (field_scene.field_interaction_open() &&
        !std::filesystem::exists(output / "terminal-contact.bmp") &&
        !save("terminal-contact")) {
        return 3;
    }
    const auto negative_sample_count = static_cast<std::size_t>(
        movement_transition.negative_probe_count);
    if (!security_terminal_transition && !source_terminal_prompt_open) {
        const auto position = position_in_scene_units();
        std::cerr << "Security Terminal physical-entry QA: normal movement "
                     "did not touch ROM event 0x18 (position="
                  << position.first << ',' << position.second
                  << ", collision=0x" << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << std::dec << ", negative_samples="
                  << negative_sample_count << ", entry_ticks=" << entry_ticks
                  << ", prompt_open=" << field_scene.field_interaction_open()
                  << ", event=0x" << std::hex
                  << static_cast<unsigned>(movement_transition.event_code)
                  << ", continuation="
                  << static_cast<unsigned>(movement_transition.continuation)
                  << std::dec
                  << ")\n";
        return 3;
    }
    const auto audio_before_prompt = field_audio_events.size();
    if (!field_scene.field_interaction_open()) {
        for (std::uint8_t wait = 0U;
             wait < 90U && !field_scene.field_interaction_open(); ++wait) {
            field_scene.advance_frame();
            ++frame;
            if (!save_sequence_frame()) {
                std::cerr << "Security Terminal physical-entry QA: frame "
                             "write failed while entering prompt\n";
                return 3;
            }
            write_state("handler-entry");
        }
    }
    if (!field_scene.field_interaction_open()) {
        const auto& samples =
            field_scene.field_terrain_sample_bytes_for_dump();
        const auto started = std::find(
            source_boundaries.begin(), source_boundaries.end(),
            "field.world.activity.started");
        std::cerr << "Security Terminal physical-entry QA: event 0x18 did "
                     "not open the source Security Terminal prompt (flags=0x"
                  << std::hex << static_cast<unsigned>(
                         field_scene.field_entity_behavior_flags_for_dump())
                  << ", mode=0x"
                  << field_scene.field_interaction_mode_for_dump()
                  << ", collision=0x"
                  << field_scene.field_terrain_collision_code_for_dump()
                  << std::dec << ", samples=0x" << std::hex
                  << static_cast<unsigned>(samples[0]) << ','
                  << static_cast<unsigned>(samples[1]) << ','
                  << static_cast<unsigned>(samples[2]) << ','
                  << static_cast<unsigned>(samples[3]) << std::dec
                  << ", activity_started="
                  << (started != source_boundaries.end())
                  << ", pending="
                  << field_scene.field_runtime_state_for_dump()
                         .pending_field_scene_handler
                  << ", transition="
                  << field_scene.field_transition_pending_for_dump()
                  << ")\n";
        return 3;
    }
    const auto prompt_underlay = render(true);
    const auto& panel = field_scene.field_interaction_panel();
    const bool prompt_matches =
        panel.open && panel.source_complete && panel.option_count == 2U &&
        panel.options[0U].role == DialoguePanelOptionRole::field_security_access &&
        panel.options[1U].role == DialoguePanelOptionRole::field_walk_away;
    const auto initial_prompt_frame = render(false);
    if (!prompt_matches || initial_prompt_frame == prompt_underlay ||
        !save("terminal-underlay", true) || !save("terminal-prompt")) {
        std::cerr << "Security Terminal physical-entry QA: source prompt "
                     "state or full-screen replacement failed\n";
        return 3;
    }
    write_state("terminal-prompt");

    // The shared prompt delays input for ten source frames. Capture every
    // frame and make sure the modal owns the whole screen without changing its
    // selected choices or drawing stale field controls over them.
    const auto prompt_frame = render(false);
    for (std::uint8_t wait = 0U; wait < 10U; ++wait) {
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        if (!save_sequence_frame()) {
            std::cerr << "Security Terminal physical-entry QA: prompt frame "
                         "write failed\n";
            return 3;
        }
        write_state("prompt-input-delay");
    }
    if (render(false) != prompt_frame || !save("terminal-prompt-held")) {
        std::cerr << "Security Terminal physical-entry QA: prompt changed "
                     "during its ten-frame source hold\n";
        return 3;
    }

    // In 0x1F3C4 the second option is selected by mask 0x10. Its terminal
    // command is Walk Away, which should close the modal and expose the field.
    const auto return_result =
        field_scene.advance_field_interaction_for_dump(0x1000U);
    ++frame;
    if (!save_sequence_frame() ||
        return_result != FieldInteractionAdvanceResult::returned_to_field ||
        field_scene.field_interaction_open() ||
        field_audio_events.size() != audio_before_prompt ||
        field_scene.field_modal_return_transition_frames_for_dump() != 60U ||
        field_scene.field_palette_fade_steps_for_dump() != 9U) {
        std::cerr << "Security Terminal physical-entry QA: Walk Away did not "
                     "return with the expected 60-frame fade and no new "
                     "sound request\n";
        return 3;
    }
    for (std::uint8_t transition_frame = 0U; transition_frame < 60U;
         ++transition_frame) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (transition_frame == 29U || transition_frame == 59U) {
            if (!save_sequence_frame()) {
                std::cerr << "Security Terminal physical-entry QA: transition checkpoint write failed\n";
                return 3;
            }
        }
    }
    const auto returned_field = render(false);
    if (field_scene.field_modal_return_transition_frames_for_dump() != 0U ||
        field_scene.field_palette_fade_steps_for_dump() != 0U ||
        !save("return-field") || returned_field != render(true) ||
        !field_hud_chrome_survives(returned_field, asset_root) ||
        !field_scene.field_entity_visible_for_dump() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.dialogue_open() || field_scene.shop_menu_open()) {
        std::cerr << "Security Terminal physical-entry QA: return retained "
                     "terminal graphics or a competing screen active\n";
        return 3;
    }
    write_state("return-field");

    const auto activity_started = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.world.activity.started");
    const auto prompt_opened = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.interaction.prompt_opened");
    if (activity_started == source_boundaries.end() ||
        prompt_opened == source_boundaries.end() ||
        activity_started > prompt_opened ||
        field_scene.field_mode_event_code_for_dump() != 0U ||
        !save("actual")) {
        std::cerr << "Security Terminal physical-entry QA: source continuation "
                     "order or early event-code behavior diverged\n";
        return 3;
    }
    std::cout << "field_security_terminal_physical_entry_qa=passed scene=26 "
                 "collision=0xD8 event=0x18 records=124,125 approach_ticks="
              << entry_ticks << " negative_samples=" << negative_sample_count
              << " prompt_options=Electronics,WalkAway prompt_hold=10 "
                 "sound_requests=0 artifacts="
              << output.string() << '\n';
    return 0;
}

int run_field_ares_collision_shop_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    // The ordinary route advances source-backed NPC and encounter timers;
    // pin its random stream so the physical doorway and menu captures repeat.
    field_scene.set_source_random_seed_for_dump(0U);
    std::filesystem::create_directories(output);
    std::error_code directory_error;
    for (std::filesystem::directory_iterator item(output, directory_error), end;
         !directory_error && item != end; item.increment(directory_error)) {
        if (!item->is_regular_file(directory_error)) {
            continue;
        }
        const auto filename = item->path().filename();
        if (item->path().extension() == ".bmp" ||
            item->path().extension() == ".tsv" ||
            filename == "source-boundaries.txt" ||
            filename == "audio-events.txt") {
            std::filesystem::remove(item->path(), directory_error);
            if (directory_error) {
                std::cerr << "Ares collision QA: could not clear old artifact "
                          << filename.string() << ": "
                          << directory_error.message() << '\n';
                return 3;
            }
        }
    }
    if (directory_error) {
        std::cerr << "Ares collision QA: could not inspect output: "
                  << directory_error.message() << '\n';
        return 3;
    }

    constexpr std::size_t ares_collision_record_index = 92U;
    constexpr std::uint32_t ares_collision_rom_address = 0x173142U;
    constexpr std::uint8_t ares_collision_value = 0xCBU;
    const auto& rectangles = field_scene.state()
                                 .field_scene_buffers.source_metadata
                                 .terrain_collision_rectangles;
    const bool source_record_matches =
        rectangles.size() > ares_collision_record_index &&
        rectangles[ares_collision_record_index].left == 0x04C0U &&
        rectangles[ares_collision_record_index].right == 0x04DFU &&
        rectangles[ares_collision_record_index].top == 0x0220U &&
        rectangles[ares_collision_record_index].bottom == 0x023FU &&
        rectangles[ares_collision_record_index].value ==
            ares_collision_value;
    const auto initial_position = field_scene.field_entity_world_position();
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        initial_position.x != 0x3CE0U || initial_position.y != 0x2D00U ||
        field_scene.field_interaction_mode_for_dump() != 0U ||
        field_scene.field_runtime_state_for_dump().field_mode != 2U ||
        !source_record_matches) {
        std::cerr << "Ares collision QA: New Game state or source record 92 "
                     "does not match the traced scene-2 route (scene="
                  << field_scene.field_scene_reference_for_dump() << ", x="
                  << initial_position.x << ", y=" << initial_position.y
                  << ", world_mode="
                  << field_scene.field_interaction_mode_for_dump()
                  << ", field_mode="
                  << static_cast<unsigned>(
                         field_scene.field_runtime_state_for_dump().field_mode)
                  << ")\n";
        return 3;
    }

    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save = [&](const std::string_view name,
                          const bool require_field_hud = false) {
        const auto image = render();
        const auto path = output / (std::string(name) + ".bmp");
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            (require_field_hud &&
             (!field_hud_chrome_survives(image, asset_root) ||
              count_playfield_lit(image) < 100U)) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            std::cerr << "Ares collision QA: full-screen dump/validation "
                         "failed for " << name << '\n';
            return false;
        }
        return true;
    };
    std::ofstream trace(output / "route.tsv", std::ios::trunc);
    if (!trace) {
        std::cerr << "Ares collision QA: could not create route.tsv\n";
        return 3;
    }
    trace << "stage\tframe\tscene\tx\ty\tworld_mode\tfield_mode\tevent"
             "\traw_collision\tprojected\tfade_timer\tpalette_steps"
             "\tmode_text\tshop\n";
    std::uint32_t frame = 0U;
    const auto write_state = [&](const std::string_view stage) {
        const auto position = field_scene.field_entity_world_position();
        trace << stage << '\t' << frame << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << position.x << '\t' << position.y << '\t'
              << field_scene.field_interaction_mode_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_runtime_state_for_dump().field_mode)
              << '\t'
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump())
              << '\t' << field_scene.field_terrain_collision_code_for_dump()
              << '\t' << field_scene.field_projected_code_for_dump() << '\t'
              << field_scene.field_interaction_transition_timer_for_dump()
              << '\t' << static_cast<unsigned>(
                     field_scene.field_palette_fade_steps_for_dump())
              << '\t' << field_scene.field_mode_text_open_for_dump() << '\t'
              << field_scene.shop_menu_open() << '\n';
        trace.flush();
    };
    const auto route_is_live = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 2U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open() &&
               !field_scene.field_interaction_transition_active_for_dump() &&
               !field_scene.field_transition_pending_for_dump();
    };
    const auto world_position = [&field_scene] {
        const auto position = field_scene.field_entity_world_position();
        return std::pair<std::uint16_t, std::uint16_t>{
            static_cast<std::uint16_t>(position.x >> 4U),
            static_cast<std::uint16_t>(position.y >> 4U)};
    };

    if (!save("spawn", true)) {
        return 3;
    }
    write_state("spawn");
    const auto& door = rectangles[ares_collision_record_index];
    // Right-to-Up heading slew moves the runner about 15 world pixels east
    // before the vertical approach settles. Start at the doorway's west edge
    // so all four expanded probes stay inside record 92's single tile.
    const auto target_world_x = door.left;
    std::uint16_t east_ticks = 0U;
    while (east_ticks < 300U && world_position().first < target_world_x &&
           route_is_live()) {
        field_scene.set_controller_nibble(0x08U); // ordinary Right hold
        field_scene.advance_frame();
        ++frame;
        ++east_ticks;
        if (east_ticks == 16U || east_ticks == 64U || east_ticks == 128U) {
            if (!save("east-" + std::to_string(east_ticks), true)) {
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    const auto east_position = world_position();
    if (!route_is_live() || east_position.first < target_world_x ||
        !save("east-waypoint", true)) {
        std::cerr << "Ares collision QA: normal Right input did not reach the "
                     "doorway's east/west coordinate (ticks=" << east_ticks
                  << ", position=" << east_position.first << ','
                  << east_position.second << ", target-x=" << target_world_x
                  << ", event=" << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ")\n";
        return 3;
    }
    write_state("east-waypoint");

    std::uint16_t north_ticks = 0U;
    while (north_ticks < 240U && route_is_live()) {
        field_scene.set_controller_nibble(0x01U); // ordinary Up hold
        field_scene.advance_frame();
        ++frame;
        ++north_ticks;
        write_state("north-step-" + std::to_string(north_ticks));
        if (north_ticks == 16U || north_ticks == 32U ||
            north_ticks == 64U || north_ticks == 128U ||
            north_ticks == 180U || north_ticks == 200U) {
            if (!save("north-" + std::to_string(north_ticks), true)) {
                return 3;
            }
        }
        if (field_scene.field_projected_code_for_dump() == 0xFFCBU ||
            field_scene.field_mode_event_code_for_dump() == 11U ||
            field_scene.field_interaction_transition_active_for_dump() ||
            field_scene.field_transition_pending_for_dump() ||
            field_scene.field_mode_text_open_for_dump() ||
            field_scene.shop_menu_open()) {
            break;
        }
    }
    const auto contact_position = world_position();
    (void)save("north-raw-contact");
    if (field_scene.field_terrain_collision_code_for_dump() != 0xFFCBU ||
        field_scene.field_projected_code_for_dump() != 0xFFCBU ||
        field_scene.field_mode_event_code_for_dump() != 11U ||
        field_scene.field_interaction_mode_for_dump() != 0U ||
        field_scene.field_runtime_state_for_dump().field_mode != 2U ||
        contact_position.first < door.left - 12U ||
        contact_position.first > door.right + 12U ||
        contact_position.second < door.top - 7U ||
        contact_position.second > door.bottom + 7U ||
        !field_scene.field_interaction_transition_active_for_dump() ||
        field_scene.dialogue_open() || field_scene.field_interaction_open() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.shop_menu_open()) {
        std::cerr << "Ares collision QA: ordinary Up contact did not publish "
                     "scene-2 record 92/event 11 (ticks=" << north_ticks
                  << ", position=" << contact_position.first << ','
                  << contact_position.second << ", raw=0x" << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << ", projected=0x"
                  << field_scene.field_projected_code_for_dump() << std::dec
                  << ", event=" << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", world_mode="
                  << field_scene.field_interaction_mode_for_dump()
                  << ", field_mode=" << static_cast<unsigned>(
                         field_scene.field_runtime_state_for_dump().field_mode)
                  << ")\n";
        std::size_t printed_boundaries = 0U;
        for (auto boundary = source_boundaries.rbegin();
             boundary != source_boundaries.rend() &&
             printed_boundaries < 24U;
             ++boundary) {
            if (boundary->find("movement") == std::string::npos &&
                boundary->find("map_event") == std::string::npos &&
                boundary->find("mode_event") == std::string::npos) {
                continue;
            }
            std::cerr << "  source_boundary=" << *boundary << '\n';
            ++printed_boundaries;
        }
        return 3;
    }
    const auto ares_trigger_position =
        field_scene.field_entity_world_position();
    const auto ares_trigger_heading =
        field_scene.field_entity_heading_for_dump();
    const auto ares_trigger_dispatches =
        field_scene.field_map_event_system_for_dump()
            .collision_dispatch_count();
    if (!save("doorway-contact")) {
        return 3;
    }
    write_state("doorway-contact");
    const auto field_audio_events_at_contact = field_audio_events.size();
    field_scene.set_controller_nibble(0U);

    const std::array<std::uint32_t, 3> fade_checkpoints{8U, 16U, 17U};
    std::uint32_t fade_updates = 0U;
    for (const auto checkpoint : fade_checkpoints) {
        while (fade_updates < checkpoint - 1U) {
            field_scene.advance_frame();
            ++frame;
            ++fade_updates;
        }
        const auto name = "fade-" +
                          (checkpoint < 10U ? std::string("0") : std::string()) +
                          std::to_string(checkpoint);
        const auto expected_timer = checkpoint == 8U ? 8 :
                                    checkpoint == 16U ? 0 : -1;
        const auto expected_palette_steps = checkpoint == 8U ? 4U :
                                            checkpoint == 16U ? 8U : 9U;
        if (!save(name) ||
            field_scene.field_interaction_transition_timer_for_dump() !=
                expected_timer ||
            field_scene.field_palette_fade_steps_for_dump() !=
                expected_palette_steps ||
            field_scene.field_transition_pending_for_dump() !=
                (checkpoint == 17U)) {
            std::cerr << "Ares collision QA: source fade state diverged at "
                         "checkpoint " << checkpoint << '\n';
            return 3;
        }
        write_state(name);
    }

    for (std::uint16_t settle = 0U;
         settle < 60U && !field_scene.field_mode_text_open_for_dump();
         ++settle) {
        field_scene.advance_frame();
        ++frame;
    }
    if (!field_scene.field_mode_text_open_for_dump() ||
        field_scene.field_transition_pending_for_dump() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_mode_event_code_for_dump() != 11U ||
        field_scene.field_runtime_state_for_dump().field_mode != 2U ||
        field_scene.dialogue_open() || field_scene.field_interaction_open()) {
        std::cerr << "Ares collision QA: the physical event did not enter the "
                     "mode-2/event-11 generic text prompt\n";
        return 3;
    }
    const auto prompt = field_scene.field_mode_text_panel_for_dump();
    const auto prompt_image = render();
    const bool prompt_source_valid =
        prompt.source_complete &&
        prompt.actor_kind == DialoguePanelActorKind::none &&
        prompt.portrait_alias == "field.mode.entry.ares.sprite" &&
        prompt.text_segment_count != 0U;
    const bool prompt_delay_valid =
        field_scene.field_mode_text_frames_remaining_for_dump() == 30U;
    const bool prompt_audio_silent =
        field_audio_events.size() == field_audio_events_at_contact;
    const bool prompt_owns_full_screen =
        !field_hud_chrome_survives(prompt_image, asset_root);
    const bool prompt_saved = save("ares-introduction");
    if (!prompt_source_valid || !prompt_delay_valid || !prompt_audio_silent ||
        !prompt_owns_full_screen || !prompt_saved) {
        std::cerr << "Ares collision QA: event-selected prompt, 30-frame delay, "
                     "audio boundary, or full-screen ownership is incorrect "
                  << "(source=" << prompt_source_valid
                  << ", delay="
                  << field_scene.field_mode_text_frames_remaining_for_dump()
                  << ", audio=" << field_audio_events.size() << '/'
                  << field_audio_events_at_contact << ", hud_visible="
                  << field_hud_chrome_survives(prompt_image, asset_root)
                  << ", saved=" << prompt_saved << ")\n";
        return 3;
    }
    write_state("ares-introduction");
    for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
        field_scene.advance_frame();
        ++frame;
    }
    const auto prompt_after_delay = render();
    if (!field_scene.field_mode_text_open_for_dump() ||
        field_scene.field_mode_text_frames_remaining_for_dump() != 0U ||
        prompt_after_delay != prompt_image ||
        !save("ares-introduction-after-30-frames")) {
        std::cerr << "Ares collision QA: Ares prompt changed during its "
                     "30-frame input delay\n";
        return 3;
    }

    field_scene.set_controller_port_byte(0x40U); // ordinary A press
    field_scene.advance_frame();
    ++frame;
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    if (field_scene.field_mode_text_open_for_dump() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        !field_scene.shop_menu_open() ||
        field_scene.shop_menu_group() != ShopActionGroup::weapons ||
        field_scene.shop_menu_offers_active()) {
        std::cerr << "Ares collision QA: ordinary A input did not open the "
                     "source Ares category screen\n";
        return 3;
    }
    const auto shop_image = render();
    const QImage service_background(QString::fromStdWString(
        (asset_root / "menu" / "field" / "service-background.bmp")
            .wstring()));
    if (service_background.isNull() ||
        !image_region_differs(shop_image, service_background, 64, 128, 144,
                              16) ||
        !image_region_differs(shop_image, service_background, 16, 168, 240,
                              24) ||
        !image_has_green_ink(shop_image, 64, 144, 160, 16) ||
        !save("ares-shop-category")) {
        std::cerr << "Ares collision QA: shop category or full-screen entry "
                     "draw is missing\n";
        return 3;
    }
    write_state("ares-shop-category");

    // Follow the same source cursor path visible in the longplay: begin on
    // Weapons, move Right to the other-items category, then Down into its
    // first stock offer (Universal Gun Clips). Capture each full screen so
    // the selected tab and detail panel can be reviewed together.
    field_scene.set_controller_port_byte(0x08U); // ordinary Right
    field_scene.advance_frame();
    ++frame;
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    const auto equipment_category_image = render();
    const auto equipment_category_saved =
        save("ares-shop-other-items-category");
    const bool equipment_category_state_valid =
        field_scene.shop_menu_open() &&
        field_scene.shop_menu_group() == ShopActionGroup::other_items &&
        field_scene.shop_menu_cursor() == 1U &&
        !field_scene.shop_menu_offers_active();
    const bool equipment_category_presentation_valid =
        equipment_category_saved &&
        image_region_differs(shop_image, equipment_category_image,
                             64, 128, 144, 16) &&
        image_region_differs(shop_image, equipment_category_image,
                             64, 144, 160, 16) &&
        !image_region_differs(shop_image, equipment_category_image,
                              16, 168, 240, 24);
    if (!equipment_category_state_valid ||
        !equipment_category_presentation_valid) {
        std::cerr << "Ares collision QA: category navigation did not keep "
                     "the source cursor and stock panel in sync (group="
                  << static_cast<int>(field_scene.shop_menu_group())
                  << ", cursor=" << static_cast<unsigned>(
                         field_scene.shop_menu_cursor())
                  << ", offers=" << field_scene.shop_menu_offers_active()
                  << ", row_preserved="
                  << !image_region_differs(shop_image,
                                           equipment_category_image,
                                           16, 168, 240, 24)
                  << ", frame_saved=" << equipment_category_saved << ")\n";
        return 3;
    }
    write_state("ares-shop-other-items-category");

    field_scene.set_controller_port_byte(0x02U); // ordinary Down
    field_scene.advance_frame();
    ++frame;
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    const auto clips_offer = render();
    if (!field_scene.shop_menu_open() ||
        field_scene.shop_menu_group() != ShopActionGroup::other_items ||
        !field_scene.shop_menu_offers_active() ||
        field_scene.shop_menu_cursor() != 0U ||
        !image_region_differs(shop_image, clips_offer, 16, 168, 240, 24) ||
        !image_has_green_ink(clips_offer, 24, 56, 224, 64) ||
        !image_has_green_ink(clips_offer, 104, 144, 64, 16) ||
        !save("ares-shop-universal-clips-detail")) {
        std::cerr << "Ares collision QA: Down did not select the first "
                     "other-items offer and redraw its detail panel\n";
        return 3;
    }
    write_state("ares-shop-universal-clips-detail");

    field_scene.set_controller_port_byte(0x80U); // ordinary Start return
    field_scene.advance_frame();
    ++frame;
    field_scene.set_controller_port_byte(0U);
    field_scene.advance_frame();
    ++frame;
    const auto returned_field = render();
    const auto repeated_return = render();
    const auto boundary_was_seen = [&](const std::string_view expected) {
        return std::find(source_boundaries.begin(), source_boundaries.end(),
                         expected) != source_boundaries.end();
    };
    if (field_scene.shop_menu_open() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        !boundary_was_seen(
            "field.mode_text_prompt.display_palette_refreshed") ||
        !boundary_was_seen("field.shop.ares.opened") ||
        !boundary_was_seen("field.shop.ares.returned_to_field") ||
        !field_hud_chrome_survives(returned_field, asset_root) ||
        count_playfield_lit(returned_field) < 100U ||
        returned_field == shop_image || returned_field != repeated_return ||
        !save("field-return", true)) {
        std::cerr << "Ares collision QA: Start did not restore a clean full "
                     "scene-2 field screen\n";
        return 3;
    }
    write_state("field-return");

    const auto ares_return_position =
        field_scene.field_entity_world_position();
    if (ares_return_position.x != ares_trigger_position.x ||
        ares_return_position.y != ares_trigger_position.y ||
        field_scene.field_entity_heading_for_dump() != ares_trigger_heading ||
        field_scene.field_map_event_system_for_dump()
                .collision_dispatch_count() != ares_trigger_dispatches ||
        (field_scene.field_movement_route_flags_for_dump() & 0x20U) == 0U) {
        std::cerr << "Ares collision QA: Start changed the source contact "
                     "position/facing or lost the one-shot retry state\n";
        return 3;
    }
    std::ofstream exit_trace(output / "ares-held-and-fresh-direction.tsv",
                             std::ios::trunc);
    if (!exit_trace) {
        std::cerr << "Ares collision QA: could not write the exit route trace\n";
        return 3;
    }
    exit_trace
        << "phase\tinput\tframe\tx\ty\theading\ttarget_heading"
           "\troute_flags\traw_collision\tevent\tdispatches"
           "\ttransition\tmode_text\tshop\taudio_events\n";
    const auto write_exit_state = [&](const std::string_view phase,
                                      const std::string_view input) {
        const auto position = field_scene.field_entity_world_position();
        exit_trace
            << phase << '\t' << input << '\t' << frame << '\t'
            << position.x << '\t' << position.y << '\t'
            << field_scene.field_entity_heading_for_dump() << '\t'
            << field_scene.field_entity_target_heading_for_dump() << '\t'
            << static_cast<unsigned>(
                   field_scene.field_movement_route_flags_for_dump())
            << '\t' << field_scene.field_terrain_collision_code_for_dump()
            << '\t' << static_cast<unsigned>(
                   field_scene.field_mode_event_code_for_dump())
            << '\t' << field_scene.field_map_event_system_for_dump()
                           .collision_dispatch_count()
            << '\t' << field_scene.field_transition_pending_for_dump()
            << '\t' << field_scene.field_mode_text_open_for_dump() << '\t'
            << field_scene.shop_menu_open() << '\t'
            << field_audio_events.size() << '\n';
        return static_cast<bool>(exit_trace);
    };
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!write_exit_state("release-after-shop", "none") ||
        !save("field-release-after-shop")) {
        return 3;
    }
    for (std::uint32_t tick = 1U; tick <= 16U; ++tick) {
        field_scene.set_controller_nibble(0x02U); // held ordinary Down
        field_scene.advance_frame();
        ++frame;
        if (!route_is_live() ||
            field_scene.field_map_event_system_for_dump()
                    .collision_dispatch_count() != ares_trigger_dispatches) {
            field_scene.set_controller_nibble(0U);
            std::cerr << "Ares collision QA: held Down reopened its source "
                         "interaction or left scene 2 at update " << tick
                      << '\n';
            return 3;
        }
        if (!write_exit_state("held-down", "Down") ||
            (tick == 1U && !save("field-held-down-01")) ||
            (tick == 4U && !save("field-held-down-04")) ||
            (tick == 8U && !save("field-held-down-08")) ||
            (tick == 16U && !save("field-held-down-16"))) {
            field_scene.set_controller_nibble(0U);
            return 3;
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    const auto ares_departure_position =
        field_scene.field_entity_world_position();
    if (!write_exit_state("release-after-held-down", "none") ||
        ares_departure_position.y <= ares_return_position.y ||
        (field_scene.field_movement_route_flags_for_dump() & 0x20U) != 0U ||
        field_scene.field_terrain_collision_code_for_dump() != 0U ||
        !route_is_live() || !save("field-clear-of-ares-trigger")) {
        std::cerr << "Ares collision QA: held Down did not clear the source "
                     "trigger and its retry bit\n";
        return 3;
    }
    for (std::uint32_t tick = 1U; tick <= 8U; ++tick) {
        field_scene.set_controller_nibble(0x08U); // fresh ordinary Right
        field_scene.advance_frame();
        ++frame;
        if (!route_is_live() ||
            field_scene.field_map_event_system_for_dump()
                    .collision_dispatch_count() != ares_trigger_dispatches) {
            field_scene.set_controller_nibble(0U);
            std::cerr << "Ares collision QA: fresh Right replayed the service "
                         "event after the runner cleared its trigger\n";
            return 3;
        }
        if (!write_exit_state("fresh-right", "Right") ||
            (tick == 1U && !save("field-fresh-right-01")) ||
            (tick == 4U && !save("field-fresh-right-04")) ||
            (tick == 8U && !save("field-fresh-right-08"))) {
            field_scene.set_controller_nibble(0U);
            return 3;
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!save("actual")) {
        return 3;
    }
    exit_trace.close();

    {
        std::ofstream boundaries(output / "source-boundaries.txt",
                                 std::ios::trunc);
        if (!boundaries) {
            std::cerr << "Ares collision QA: could not write boundary trace\n";
            return 3;
        }
        for (const auto& boundary : source_boundaries) {
            boundaries << boundary << '\n';
        }
    }
    {
        std::ofstream events(output / "audio-events.txt", std::ios::trunc);
        if (!events) {
            std::cerr << "Ares collision QA: could not write audio trace\n";
            return 3;
        }
        for (const auto event : field_audio_events) {
            events << "0x" << std::hex << event << '\n';
        }
    }

    std::cout << "field_ares_collision_shop_qa=passed scene=2 record="
              << ares_collision_record_index << " rom=0x" << std::hex
              << ares_collision_rom_address << " collision=0xFFCB" << std::dec
              << " event=11 east_ticks=" << east_ticks
              << " north_ticks=" << north_ticks
              << " prompt_delay_frames=30 audio_events="
              << field_audio_events.size() << " artifacts=" << output.string()
              << '\n';
    return 0;
}

enum class Scene20PhysicalEntryQaPath : std::uint8_t {
    c0_exit_lifetime,
    walk_away,
    grenade_unavailable,
    passkey_success,
    passkey_insufficient,
    electronics_no_skill,
    electronics_alert,
    electronics_trials,
};

int run_field_scene20_physical_entry_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries,
    const Scene20PhysicalEntryQaPath path =
        Scene20PhysicalEntryQaPath::walk_away) {
    // Stabilize random NPC/action timing across Debug and Release captures.
    field_scene.set_source_random_seed_for_dump(0U);
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Scene-20 physical-entry QA: could not clear previous "
                     "capture directory: " << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        std::cerr << "Scene-20 physical-entry QA: could not create capture "
                     "directory: " << output_error.message() << '\n';
        return 3;
    }
    constexpr std::array<std::size_t, 2> doorway_record_indices{89U, 90U};
    constexpr std::uint32_t doorway_rom_address = 0x173124U;
    constexpr std::uint8_t doorway_value = 0xC0U;
    const auto& metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& rectangles = metadata.terrain_collision_rectangles;
    const bool doorway_records_match =
        rectangles.size() > doorway_record_indices.back() &&
        rectangles[89U].left == 0x00E0U &&
        rectangles[89U].right == 0x00FFU &&
        rectangles[89U].top == 0x0260U &&
        rectangles[89U].bottom == 0x027FU &&
        rectangles[89U].value == doorway_value &&
        rectangles[90U].left == 0x0100U &&
        rectangles[90U].right == 0x011FU &&
        rectangles[90U].top == 0x0260U &&
        rectangles[90U].bottom == 0x027FU &&
        rectangles[90U].value == doorway_value &&
        metadata.event_table_available &&
        metadata.event_mode_table[0U] == 0x14U;
    const auto initial_position = field_scene.field_entity_world_position();
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        initial_position.x != 0x3CE0U || initial_position.y != 0x2D00U ||
        !doorway_records_match) {
        std::cerr << "Scene-20 physical-entry QA: New Game state, paired C0 "
                     "doorway records, or event-table destination is wrong\n";
        return 3;
    }

    std::optional<std::size_t> seeded_passkey_slot;
    constexpr std::uint8_t kPasskeyItemCode = 0x14U;
    constexpr std::uint8_t kPasskeyQuality = 2U;
    const auto seeded_passkey_quality =
        path == Scene20PhysicalEntryQaPath::passkey_insufficient
            ? static_cast<std::uint8_t>(kPasskeyQuality - 1U)
            : kPasskeyQuality;
    if (path == Scene20PhysicalEntryQaPath::passkey_success ||
        path == Scene20PhysicalEntryQaPath::passkey_insufficient) {
        const auto active_slot =
            field_scene.field_active_party_slot_for_dump();
        if (!field_scene.field_party_slot_active_for_dump(active_slot) ||
            (field_scene.active_runner_record().flags & 0x0100U) == 0U) {
            std::cerr << "Scene-20 passkey QA: active runner record is not live\n";
            return 3;
        }
        for (std::size_t runner_slot = 0U;
             runner_slot < field_scene.field_party_records_for_dump().size();
             ++runner_slot) {
            const auto& runner =
                field_scene.field_party_records_for_dump()[runner_slot];
            if (field_scene.field_party_slot_active_for_dump(runner_slot) &&
                (runner.flags & 0x0100U) != 0U &&
                std::find(runner.inventory_item_codes.begin(),
                          runner.inventory_item_codes.end(),
                          kPasskeyItemCode) !=
                    runner.inventory_item_codes.end()) {
                std::cerr << "Scene-20 passkey QA: New Game fixture already "
                             "contains a passkey\n";
                return 3;
            }
        }
        auto& active_runner = field_scene.active_runner_record();
        for (std::size_t inventory_slot = 0U;
             inventory_slot < active_runner.inventory_item_codes.size();
             ++inventory_slot) {
            if (active_runner.inventory_item_codes[inventory_slot] == 0U) {
                seeded_passkey_slot = inventory_slot;
                break;
            }
        }
        if (!seeded_passkey_slot.has_value()) {
            std::cerr << "Scene-20 passkey QA: active runner has no free "
                         "inventory slot\n";
            return 3;
        }
        active_runner.inventory_item_codes[*seeded_passkey_slot] =
            kPasskeyItemCode;
        active_runner.inventory_phase_bytes[*seeded_passkey_slot] =
            seeded_passkey_quality;
    }

    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto render_field_scene_only = [&field_scene] { return render_qa_field(field_scene, true); };
    const auto save_image = [&output](const std::string_view name,
                                      const QImage& image) {
        const auto path = output / (std::string(name) + ".bmp");
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            std::cerr << "Scene-20 physical-entry QA: could not save full "
                         "screen " << name << '\n';
            return false;
        }
        return true;
    };
    const auto save = [&render, &save_image](const std::string_view name) {
        return save_image(name, render());
    };
    std::ofstream trace(output / "route.tsv", std::ios::trunc);
    if (!trace) {
        std::cerr << "Scene-20 physical-entry QA: could not create route.tsv\n";
        return 3;
    }
    trace << "stage\tframe\tscene\tx\ty\tworld_mode\tfield_mode\tevent"
             "\traw_collision\tprojected\tfade_timer\tpalette_steps"
             "\tinteraction\tmode_text\tshop\n";
    std::uint32_t frame = 0U;
    const auto write_state = [&] (const std::string_view stage) {
        const auto position = field_scene.field_entity_world_position();
        trace << stage << '\t' << frame << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << position.x << '\t' << position.y << '\t'
              << field_scene.field_interaction_mode_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_runtime_state_for_dump().field_mode)
              << '\t'
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump())
              << '\t' << field_scene.field_terrain_collision_code_for_dump()
              << '\t' << field_scene.field_projected_code_for_dump() << '\t'
              << field_scene.field_interaction_transition_timer_for_dump()
              << '\t' << static_cast<unsigned>(
                     field_scene.field_palette_fade_steps_for_dump())
              << '\t' << field_scene.field_interaction_open() << '\t'
              << field_scene.field_mode_text_open_for_dump() << '\t'
              << field_scene.shop_menu_open() << '\n';
        trace.flush();
    };
    const auto world_position = [&field_scene] {
        const auto position = field_scene.field_entity_world_position();
        return std::pair<std::uint16_t, std::uint16_t>{
            static_cast<std::uint16_t>(position.x >> 4U),
            static_cast<std::uint16_t>(position.y >> 4U)};
    };
    const auto field_is_live = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 2U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open() &&
               !field_scene.field_transition_pending_for_dump();
    };

    if (!save("spawn")) {
        return 3;
    }
    write_state("spawn");
    const auto walk_to = [&](const bool horizontal, const bool increasing,
                             const std::uint16_t target,
                             const std::uint8_t input,
                             const std::string_view stage,
                             const std::uint16_t tolerance,
                             const auto& is_live) {
        const auto coordinate = [&] {
            const auto position = world_position();
            return horizontal ? position.first : position.second;
        };
        const auto reached = [&] {
            return increasing ? coordinate() >= target
                              : coordinate() <= target;
        };
        std::uint16_t ticks = 0U;
        while (ticks < 500U && !reached() && is_live()) {
            field_scene.set_controller_nibble(input);
            field_scene.advance_frame();
            ++frame;
            ++ticks;
            if (ticks == 32U || ticks == 96U || ticks == 160U ||
                ticks == 224U || ticks == 320U) {
                if (!save(std::string(stage) + "-" + std::to_string(ticks))) {
                    return false;
                }
                write_state(std::string(stage) + "-" +
                            std::to_string(ticks));
            }
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto settled = coordinate();
        const auto difference = settled > target ? settled - target
                                                 : target - settled;
        if (!is_live() || !reached() || difference > tolerance ||
            !save(stage)) {
            const auto position = world_position();
            std::cerr << "Scene-20 physical-entry QA: normal input did not "
                      << "reach " << stage << " (ticks=" << ticks
                      << ", position=" << position.first << ','
                      << position.second << ", target=" << target << ")\n";
            return false;
        }
        write_state(stage);
        return true;
    };

    // The straight west path is blocked by the source collision wall at
    // x=0x320. Walk through its open southern row, cross the wall, then return
    // to the north-side alley that reaches the paired C0 entrance.
    if (!walk_to(false, true, 0x0310U, 0x02U, "south-lane", 24U,
                 field_is_live) ||
        !walk_to(true, false, 0x0160U, 0x04U, "west-south-lane", 24U,
                 field_is_live) ||
        !walk_to(false, false, 0x02D0U, 0x01U, "north-alley", 24U,
                 field_is_live) ||
        !walk_to(true, false, 0x0100U, 0x04U, "doorway-lane", 24U,
                 field_is_live)) {
        return 3;
    }

    std::uint16_t north_ticks = 0U;
    while (north_ticks < 180U && field_is_live()) {
        field_scene.set_controller_nibble(0x01U); // ordinary Up hold
        field_scene.advance_frame();
        ++frame;
        ++north_ticks;
        if (north_ticks == 16U || north_ticks == 32U ||
            north_ticks == 64U || north_ticks == 96U) {
            if (!save("north-" + std::to_string(north_ticks))) {
                return 3;
            }
        }
        if (field_scene.field_terrain_collision_code_for_dump() == 0xFFC0U ||
            field_scene.field_interaction_transition_active_for_dump() ||
            field_scene.field_transition_pending_for_dump() ||
            field_scene.field_scene_reference_for_dump() != 2U) {
            break;
        }
    }
    const auto doorway_contact = world_position();
    if (field_scene.field_terrain_collision_code_for_dump() != 0xFFC0U ||
        field_scene.field_projected_code_for_dump() != 0xFFC0U ||
        field_scene.field_mode_event_code_for_dump() != 0U ||
        doorway_contact.first < 0x00D4U ||
        doorway_contact.first > 0x012BU ||
        doorway_contact.second < 0x0259U ||
        doorway_contact.second > 0x0286U ||
        !field_scene.field_interaction_transition_active_for_dump() ||
        field_scene.dialogue_open() || field_scene.field_interaction_open() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.shop_menu_open() || !save("doorway-contact")) {
        std::cerr << "Scene-20 physical-entry QA: normal Up did not contact "
                     "the paired C0 doorway records (ticks=" << north_ticks
                  << ", position=" << doorway_contact.first << ','
                  << doorway_contact.second << ", raw=0x" << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << ", projected=0x"
                  << field_scene.field_projected_code_for_dump() << std::dec
                  << ", event=" << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump()) << ")\n";
        return 3;
    }
    const auto scene2_return_position =
        field_scene.field_entity_world_position();
    const auto scene2_return_heading =
        field_scene.field_entity_heading_for_dump();
    write_state("doorway-contact");
    field_scene.set_controller_nibble(0U);

    const auto fade_start_frame = frame;
    for (const auto checkpoint : std::array<std::uint32_t, 3>{8U, 16U, 17U}) {
        const auto frame_goal = fade_start_frame + checkpoint - 1U;
        while (frame < frame_goal) {
            field_scene.advance_frame();
            ++frame;
        }
        const auto name = "fade-" +
                          (checkpoint < 10U ? std::string("0") : std::string()) +
                          std::to_string(checkpoint);
        if (!save(name) ||
            field_scene.field_interaction_transition_timer_for_dump() !=
                (checkpoint == 8U ? 8 : checkpoint == 16U ? 0 : -1)) {
            std::cerr << "Scene-20 physical-entry QA: source fade diverged at "
                         "checkpoint " << checkpoint << '\n';
            return 3;
        }
        write_state(name);
    }

    for (std::uint16_t settle = 0U;
         settle < 120U && field_scene.field_scene_reference_for_dump() == 2U;
         ++settle) {
        field_scene.advance_frame();
        ++frame;
    }
    const auto scene20_position = field_scene.field_entity_world_position();
    const auto& scene20_metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto expected_scene20_position =
        scene20_metadata.initial_field_records[0U];
    if (field_scene.default_actor_count_for_dump() != 7U ||
        field_scene.visible_default_actor_count_for_dump() != 2U) {
        std::cerr << "Scene-20 physical-entry QA: source-slot-limited default "
                     "actor population did not match (loaded="
                  << field_scene.default_actor_count_for_dump()
                  << ", on-screen="
                  << field_scene.visible_default_actor_count_for_dump()
                  << ")\n";
        return 3;
    }
    const auto scene20_image = render();
    if (field_scene.field_scene_reference_for_dump() != 0x14U ||
        scene20_metadata.terrain_collision_rectangles.size() != 132U ||
        scene20_position.x != expected_scene20_position.x ||
        scene20_position.y != expected_scene20_position.y ||
        field_scene.dialogue_open() || field_scene.field_interaction_open() ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.shop_menu_open() ||
        field_scene.field_transition_pending_for_dump() ||
        field_scene.field_interaction_transition_active_for_dump() ||
        scene20_image.size() != QSize(kSceneWidth, kSceneHeight) ||
        !field_hud_chrome_survives(scene20_image, asset_root) ||
        count_playfield_lit(scene20_image) < 100U ||
        !save("scene20-entry") || !save("actual")) {
        std::cerr << "Scene-20 physical-entry QA: event-table destination "
                     "did not replace the complete field scene (scene="
                  << field_scene.field_scene_reference_for_dump() << ", x="
                  << scene20_position.x << ", y=" << scene20_position.y
                  << ", source-x=" << expected_scene20_position.x
                  << ", source-y=" << expected_scene20_position.y << ")\n";
        return 3;
    }
    write_state("scene20-entry");
    if (seeded_passkey_slot.has_value()) {
        write_state("fixture-passkey-seeded-in-active-runner");
    }
    const auto actor_direction_order_3 =
        field_scene.default_actor_direction_for_dump(3U);
    const auto actor_direction_order_4 =
        field_scene.default_actor_direction_for_dump(4U);
    if (actor_direction_order_3 != std::optional<std::uint8_t>{2U} ||
        actor_direction_order_4 != std::optional<std::uint8_t>{6U}) {
        std::cerr << "Scene-20 physical-entry QA: source heading overrides "
                     "did not select the two directional guard poses\n";
        return 3;
    }
    std::ofstream actor_package_trace(output / "actor-packages.tsv",
                                      std::ios::trunc);
    if (!actor_package_trace) {
        std::cerr << "Scene-20 physical-entry QA: actor package trace "
                     "could not be written\n";
        return 3;
    }
    actor_package_trace
        << "source_order\trecord_slot\tprofile_id\tpackage_id\t"
           "weapon_item_id\n";
    constexpr std::array<FieldWorldActorSlot, 7> expected_actor_slots{{
        FieldWorldActorSlot::slot_3,
        FieldWorldActorSlot::slot_4,
        FieldWorldActorSlot::slot_5,
        FieldWorldActorSlot::slot_6,
        FieldWorldActorSlot::slot_7,
        FieldWorldActorSlot::slot_8,
        FieldWorldActorSlot::slot_9,
    }};
    for (std::uint16_t source_order = 0U; source_order < 8U;
         ++source_order) {
        const auto profile_id =
            field_scene.default_actor_script_profile_for_dump(source_order);
        const auto package =
            field_scene.default_actor_ai_package_for_dump(source_order);
        const auto weapon_item =
            field_scene.default_actor_weapon_item_for_dump(source_order);
        const auto record_slot =
            field_scene.default_actor_record_slot_for_dump(source_order);
        if (source_order >= expected_actor_slots.size()) {
            if (profile_id.has_value() || package.has_value() ||
                weapon_item.has_value() || record_slot.has_value()) {
                std::cerr << "Scene-20 physical-entry QA: the eighth default "
                             "list row bypassed the ROM's seven actor slots\n";
                return 3;
            }
            actor_package_trace << source_order
                                << "\tinactive\tinactive\tinactive\tnone\n";
            continue;
        }
        const auto is_guard = source_order < 5U;
        const auto expected_profile = is_guard
            ? "corp_guard_k05_item06"
            : "pedestrian_k0b_none00";
        const auto expected_package = is_guard
            ? "corp_security.max_power_heavy_pistol"
            : "pedestrian.no_active_action";
        if (!profile_id.has_value() || *profile_id != expected_profile ||
            !package.has_value() || *package != expected_package ||
            record_slot != std::optional<FieldWorldActorSlot>{
                               expected_actor_slots[source_order]} ||
            (is_guard && weapon_item != std::optional<std::uint8_t>{6U}) ||
            (!is_guard && weapon_item.has_value())) {
            std::cerr << "Scene-20 physical-entry QA: Lua actor package "
                         "did not match ROM profile/action at source order "
                      << source_order << " (package="
                      << (package.has_value() ? *package : "missing")
                      << ", profile="
                      << (profile_id.has_value() ? *profile_id : "missing")
                      << ", weapon=";
            if (weapon_item.has_value()) {
                std::cerr << static_cast<unsigned>(*weapon_item);
            } else {
                std::cerr << "none";
            }
            std::cerr << ")\n";
            return 3;
        }
        actor_package_trace << source_order << '\t'
                            << static_cast<unsigned>(*record_slot) << '\t'
                            << *profile_id << '\t' << *package << '\t';
        if (weapon_item.has_value()) {
            actor_package_trace << static_cast<unsigned>(*weapon_item);
        } else {
            actor_package_trace << "none";
        }
        actor_package_trace << '\n';
    }
    if (!actor_package_trace) {
        std::cerr << "Scene-20 physical-entry QA: actor package trace "
                     "write failed\n";
        return 3;
    }
    const auto actor_audio_event_count = [&field_audio_events](
                                             const std::uint16_t event) {
        return static_cast<std::size_t>(std::count(
            field_audio_events.begin(), field_audio_events.end(), event));
    };
    const auto actor_audio_2e_at_entry = actor_audio_event_count(0x2EU);
    const auto actor_audio_2f_at_entry = actor_audio_event_count(0x2FU);
    std::ofstream actor_animation_trace(output / "actor-animation.tsv",
                                        std::ios::trunc);
    if (!actor_animation_trace) {
        std::cerr << "Scene-20 physical-entry QA: actor animation trace "
                     "could not be written\n";
        return 3;
    }
    actor_animation_trace
        << "frame\ttransitions_started\ttransitions_complete\t"
           "order_3_direction\torder_3_frame\torder_4_direction\t"
           "order_4_frame\taudio_2e_count\taudio_2f_count\n";
    const auto record_actor_animation = [&](const std::uint16_t elapsed) {
        const auto order_3_frame =
            field_scene.default_actor_animation_frame_for_dump(3U);
        const auto order_4_frame =
            field_scene.default_actor_animation_frame_for_dump(4U);
        if (!order_3_frame.has_value() || !order_4_frame.has_value()) {
            return false;
        }
        actor_animation_trace
            << elapsed << '\t'
            << field_scene.default_actor_transition_started_count_for_dump()
            << '\t'
            << field_scene.default_actor_transition_complete_count_for_dump()
            << '\t' << static_cast<unsigned>(*actor_direction_order_3) << '\t'
            << static_cast<unsigned>(*order_3_frame) << '\t'
            << static_cast<unsigned>(*actor_direction_order_4) << '\t'
            << static_cast<unsigned>(*order_4_frame) << '\t'
            << actor_audio_event_count(0x2EU) << '\t'
            << actor_audio_event_count(0x2FU) << '\n';
        return static_cast<bool>(actor_animation_trace);
    };
    if (!record_actor_animation(0U)) {
        return 3;
    }
    QImage actor_frame_8;
    QImage actor_frame_30;
    QImage actor_frame_40;
    for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
        field_scene.advance_frame();
        ++frame;
        if (tick == 7U || tick == 29U) {
            auto& animation_frame = tick == 7U ? actor_frame_8 : actor_frame_30;
            animation_frame = render();
            if (!save_image(
                    tick == 7U ? "scene20-frame-8" : "scene20-frame-30",
                    animation_frame)) {
                return 3;
            }
            if (!record_actor_animation(
                    static_cast<std::uint16_t>(tick + 1U))) {
                return 3;
            }
        }
    }
    if (field_scene.default_actor_transition_started_count_for_dump() != 7U) {
        std::cerr << "Scene-20 physical-entry QA: the seven allocated default "
                     "actors did not enter their finite behavior animation "
                     "within 30 ticks\n";
        return 3;
    }
    for (std::uint8_t tick = 30U; tick < 40U; ++tick) {
        field_scene.advance_frame();
        ++frame;
    }
    if (field_scene.default_actor_transition_complete_count_for_dump() != 7U ||
        actor_audio_event_count(0x2EU) <= actor_audio_2e_at_entry ||
        actor_audio_event_count(0x2FU) <= actor_audio_2f_at_entry ||
        field_scene.dialogue_open() || field_scene.command_overview_open() ||
        field_scene.field_interaction_open() || field_scene.shop_menu_open() ||
        !record_actor_animation(40U)) {
        std::cerr << "Scene-20 physical-entry QA: actor transition completion, "
                     "source cue requests, or clean full-screen field state "
                     "did not hold after 40 ticks\n";
        return 3;
    }
    actor_frame_40 = render();
    if (!save_image("scene20-frame-40", actor_frame_40) ||
        actor_frame_30 == scene20_image || actor_frame_8 == actor_frame_30 ||
        actor_frame_30 != actor_frame_40) {
        std::cerr << "Scene-20 physical-entry QA: the actor pose sequence did "
                     "not change the full-screen pixels by frame 30 and then "
                     "hold its terminal frame without leaving stale graphics\n";
        return 3;
    }

    const auto actor_audio_2e_after_entry = actor_audio_event_count(0x2EU);
    const auto actor_audio_2f_after_entry = actor_audio_event_count(0x2FU);
    for (std::uint16_t elapsed = 41U; elapsed <= 82U; ++elapsed) {
        field_scene.advance_frame();
        ++frame;
        if (elapsed != 61U && elapsed != 82U) {
            continue;
        }
        const auto name = "scene20-post-entry-" + std::to_string(elapsed);
        const auto image = render();
        const auto order_3_frame =
            field_scene.default_actor_animation_frame_for_dump(3U);
        const auto order_4_frame =
            field_scene.default_actor_animation_frame_for_dump(4U);
        if (field_scene.default_actor_count_for_dump() != 7U ||
            field_scene.visible_default_actor_count_for_dump() != 2U ||
            field_scene.default_actor_transition_complete_count_for_dump() !=
                7U ||
            order_3_frame != std::optional<std::uint8_t>{1U} ||
            order_4_frame != std::optional<std::uint8_t>{1U} ||
            actor_audio_event_count(0x2EU) != actor_audio_2e_after_entry ||
            actor_audio_event_count(0x2FU) != actor_audio_2f_after_entry ||
            field_scene.dialogue_open() ||
            field_scene.command_overview_open() ||
            field_scene.field_interaction_open() ||
            field_scene.field_mode_text_open_for_dump() ||
            field_scene.shop_menu_open() ||
            image_region_differs(actor_frame_40, image, 20, 128, 60, 48) ||
            image_region_differs(actor_frame_40, image, 216, 128, 56, 48) ||
            !save_image(name, image) || !record_actor_animation(elapsed)) {
            std::cerr << "Scene-20 physical-entry QA: post-entry NPC state, "
                         "entry audio, visible guard pixels, or clean "
                         "full-screen state changed at tick "
                      << elapsed << '\n';
            return 3;
        }
    }

    constexpr std::size_t maglock_record_index = 117U;
    const auto& scene20_rectangles = field_scene.state()
                                         .field_scene_buffers.source_metadata
                                         .terrain_collision_rectangles;
    if (scene20_rectangles.size() <= maglock_record_index ||
        scene20_rectangles[maglock_record_index].left != 0x0460U ||
        scene20_rectangles[maglock_record_index].right != 0x047FU ||
        scene20_rectangles[maglock_record_index].top != 0x00E0U ||
        scene20_rectangles[maglock_record_index].bottom != 0x00FFU ||
        scene20_rectangles[maglock_record_index].value != 0x82U) {
        std::cerr << "Scene-20 physical-entry QA: the selected maglock "
                     "collision record 117 does not match its source cells\n";
        return 3;
    }
    const auto scene20_is_live = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 0x14U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open() &&
               !field_scene.field_transition_pending_for_dump() &&
               !field_scene.field_interaction_transition_active_for_dump();
    };
    const auto scene2_is_live = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 2U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open() &&
               !field_scene.field_transition_pending_for_dump() &&
               !field_scene.field_interaction_transition_active_for_dump();
    };
    if (path == Scene20PhysicalEntryQaPath::c0_exit_lifetime) {
        constexpr std::size_t kDoorRecordIndex = 110U;
        constexpr std::uint32_t kDoorRecordAddress = 0x1D96DEU;
        const auto& door_metadata =
            field_scene.state().field_scene_buffers.source_metadata;
        if (scene20_rectangles.size() <= kDoorRecordIndex ||
            scene20_rectangles[kDoorRecordIndex].left != 0x0580U ||
            scene20_rectangles[kDoorRecordIndex].right != 0x059FU ||
            scene20_rectangles[kDoorRecordIndex].top != 0x0020U ||
            scene20_rectangles[kDoorRecordIndex].bottom != 0x003FU ||
            scene20_rectangles[kDoorRecordIndex].value != 0xC0U ||
            door_metadata.event_table_available || !scene20_is_live()) {
            std::cerr << "Scene-20 C0 QA: record 110, its null event table, "
                         "or the ordinary field state differs from the ROM\n";
            return 3;
        }
        std::ofstream exit_trace(output / "scene20-c0-exit-lifetime.tsv",
                                 std::ios::trunc);
        if (!exit_trace) {
            return 3;
        }
        exit_trace
            << "phase\tinput\tframe\tx\ty\theading\ttarget_heading"
               "\troute_flags\traw_collision\tprojected\tevent"
               "\tdispatches\ttransition\tmode_text\tinteraction"
               "\tdialogue\taudio_events\n";
        const auto write_exit_state = [&](const std::string_view phase,
                                          const std::string_view input) {
            const auto position = field_scene.field_entity_world_position();
            exit_trace
                << phase << '\t' << input << '\t' << frame << '\t'
                << position.x << '\t' << position.y << '\t'
                << field_scene.field_entity_heading_for_dump() << '\t'
                << field_scene.field_entity_target_heading_for_dump() << '\t'
                << static_cast<unsigned>(
                       field_scene.field_movement_route_flags_for_dump())
                << '\t' << field_scene.field_terrain_collision_code_for_dump()
                << '\t' << field_scene.field_projected_code_for_dump()
                << '\t' << static_cast<unsigned>(
                       field_scene.field_mode_event_code_for_dump())
                << '\t' << field_scene.field_map_event_system_for_dump()
                               .collision_dispatch_count()
                << '\t' << field_scene.field_transition_pending_for_dump()
                << '\t' << field_scene.field_mode_text_open_for_dump()
                << '\t' << field_scene.field_interaction_open() << '\t'
                << field_scene.dialogue_open() << '\t'
                << field_audio_events.size() << '\n';
            return static_cast<bool>(exit_trace);
        };
        const auto dispatches_before_door =
            field_scene.field_map_event_system_for_dump()
                .collision_dispatch_count();
        if (!write_exit_state("scene20-entry", "none")) {
            return 3;
        }
        // The source spawn is directly east of record 110's open approach
        // strip. Move left around record 109's 0x7F wall, then approach the
        // C0 bounds from the south using ordinary controller input.
        constexpr std::uint16_t kLateralApproachTicks = 8U;
        for (std::uint16_t tick = 1U; tick <= kLateralApproachTicks; ++tick) {
            field_scene.set_controller_nibble(0x04U); // ordinary Left
            field_scene.advance_frame();
            ++frame;
            if (!scene20_is_live() ||
                field_scene.field_map_event_system_for_dump()
                        .collision_dispatch_count() != dispatches_before_door ||
                !write_exit_state("approach-left", "Left") ||
                (tick == 1U &&
                 (field_scene.field_terrain_collision_code_for_dump() != 0U ||
                  (field_scene.field_movement_route_flags_for_dump() &
                   0x20U) != 0U)) ||
                (tick == 4U && !save("scene20-c0-route-left-04")) ||
                (tick == 8U && !save("scene20-c0-route-left-08"))) {
                field_scene.set_controller_nibble(0U);
                std::cerr << "Scene-20 C0 QA: ordinary Left did not clear "
                             "the entry latch or stay in the source scene\n";
                return 3;
            }
        }
        const auto lateral_approach = world_position();
        if (lateral_approach.first < 0x0580U ||
            lateral_approach.first >= 0x05A0U ||
            lateral_approach.second <= 0x0040U ||
            !write_exit_state("southwest-approach", "Left")) {
            std::cerr << "Scene-20 C0 QA: ordinary Left did not reach the "
                         "open source lane west of record 109 (position="
                      << lateral_approach.first << ','
                      << lateral_approach.second << ")\n";
            return 3;
        }
        field_scene.set_terrain_probe_trace_enabled_for_dump(true);
        std::uint16_t north_ticks_to_door = 0U;
        while (north_ticks_to_door < 48U && scene20_is_live()) {
            field_scene.set_controller_nibble(0x01U); // ordinary Up
            field_scene.advance_frame();
            ++frame;
            ++north_ticks_to_door;
            if (!write_exit_state("approach-up", "Up") ||
                (north_ticks_to_door == 8U &&
                 !save("scene20-c0-route-up-08")) ||
                (north_ticks_to_door == 16U &&
                 !save("scene20-c0-route-up-16")) ||
                (north_ticks_to_door == 24U &&
                 !save("scene20-c0-route-up-24")) ||
                (north_ticks_to_door == 32U &&
                 !save("scene20-c0-route-up-32")) ||
                (north_ticks_to_door == 40U &&
                 !save("scene20-c0-route-up-40"))) {
                field_scene.set_controller_nibble(0U);
                field_scene.set_terrain_probe_trace_enabled_for_dump(false);
                return 3;
            }
            if (field_scene.field_interaction_transition_active_for_dump() ||
                field_scene.field_transition_pending_for_dump()) {
                break;
            }
        }
        field_scene.set_controller_nibble(0U);
        const auto door_contact = field_scene.field_entity_world_position();
        const auto door_contact_heading =
            field_scene.field_entity_heading_for_dump();
        const auto door_contact_world = world_position();
        const auto dispatches_at_door =
            field_scene.field_map_event_system_for_dump()
                .collision_dispatch_count();
        const auto& door_dispatch =
            field_scene.field_map_event_system_for_dump()
                .last_collision_dispatch();
        const auto& probe_history =
            field_scene.terrain_probe_trace_for_dump();
        {
            std::ofstream probe_trace(
                output / "scene20-c0-terrain-probes.tsv", std::ios::trunc);
            if (!probe_trace) {
                field_scene.set_terrain_probe_trace_enabled_for_dump(false);
                return 3;
            }
            probe_trace
                << "candidate_x_fixed\tcandidate_y_fixed\tnormalized_x\t"
                   "normalized_y\tcorner_x\tcorner_y\tterrain_byte\t"
                   "tile\traw_code\tcollision_result\texpanded\toutside\n";
            const auto begin = probe_history.size() > 64U
                                   ? probe_history.size() - 64U
                                   : 0U;
            for (std::size_t index = begin;
                 index < probe_history.size(); ++index) {
                const auto& probe = probe_history[index];
                for (std::size_t corner = 0U;
                     corner < probe.terrain_bytes.size(); ++corner) {
                    probe_trace << probe.candidate_x_fixed << '\t'
                                << probe.candidate_y_fixed << '\t'
                                << probe.normalized_x << '\t'
                                << probe.normalized_y << '\t'
                                << probe.corner_x[corner] << '\t'
                                << probe.corner_y[corner] << '\t'
                                << static_cast<unsigned>(
                                       probe.terrain_bytes[corner])
                                << '\t' << probe.selected_tile_index << '\t'
                                << probe.raw_terrain_code << '\t'
                                << probe.collision_result << '\t'
                                << probe.expanded_probe << '\t'
                                << probe.outside_bounds << '\n';
                }
            }
        }
        field_scene.set_terrain_probe_trace_enabled_for_dump(false);
        const bool contact_is_inside_source_probe_bounds =
            door_contact_world.first + 12U >= 0x0580U &&
            door_contact_world.first <= 0x059FU + 12U &&
            door_contact_world.second + 7U >= 0x0020U &&
            door_contact_world.second <= 0x003FU + 7U;
        if (field_scene.field_scene_reference_for_dump() != 0x14U ||
            field_scene.field_terrain_collision_code_for_dump() != 0xFFC0U ||
            field_scene.field_projected_code_for_dump() != 0xFFC0U ||
            field_scene.field_mode_event_code_for_dump() != 0U ||
            door_contact_heading != 0U ||
            !field_scene.field_interaction_transition_active_for_dump() ||
            !contact_is_inside_source_probe_bounds ||
            dispatches_at_door != dispatches_before_door + 1U ||
            !door_dispatch.has_value() ||
            door_dispatch->input.scene_id != 0x14U ||
            door_dispatch->input.raw_collision_code != 0xFFC0U ||
            !save("scene20-c0-doorway-contact")) {
            std::cerr << "Scene-20 C0 QA: ordinary Left/Up did not contact "
                         "ROM record 110 exactly once (left-ticks="
                      << kLateralApproachTicks << ", up-ticks="
                      << north_ticks_to_door << ", position="
                      << door_contact_world.first << ','
                      << door_contact_world.second << ", raw=0x" << std::hex
                      << field_scene.field_terrain_collision_code_for_dump()
                      << ", projected=0x"
                      << field_scene.field_projected_code_for_dump()
                      << std::dec << ", dispatches="
                      << dispatches_before_door << "->" << dispatches_at_door
                      << ")\n";
            return 3;
        }
        if (!write_exit_state("scene20-c0-contact", "Up")) {
            return 3;
        }
        const auto fade_start_frame = frame;
        for (const auto checkpoint :
             std::array<std::uint32_t, 3U>{8U, 16U, 17U}) {
            const auto target_frame = fade_start_frame + checkpoint - 1U;
            while (frame < target_frame) {
                field_scene.advance_frame();
                ++frame;
            }
            const auto expected_timer = checkpoint == 8U ? 8 :
                                        checkpoint == 16U ? 0 : -1;
            const auto expected_palette_steps = checkpoint == 8U ? 4U :
                                                checkpoint == 16U ? 8U : 9U;
            const auto name = "scene20-c0-fade-" +
                (checkpoint < 10U ? std::string("0") : std::string()) +
                std::to_string(checkpoint);
            if (field_scene.field_interaction_transition_timer_for_dump() !=
                    expected_timer ||
                field_scene.field_palette_fade_steps_for_dump() !=
                    expected_palette_steps ||
                !write_exit_state(name, "none") || !save(name)) {
                std::cerr << "Scene-20 C0 QA: source fade diverged at frame "
                          << checkpoint << '\n';
                return 3;
            }
        }
        for (std::uint16_t settle = 0U;
             settle < 120U && !scene2_is_live(); ++settle) {
            field_scene.advance_frame();
            ++frame;
        }
        const auto returned_contact =
            field_scene.field_entity_world_position();
        if (!write_exit_state("post-transition-settle", "none") ||
            !save("scene20-c0-post-transition-settle")) {
            return 3;
        }
        if (!scene2_is_live() ||
            returned_contact.x != scene2_return_position.x ||
            returned_contact.y != scene2_return_position.y ||
            field_scene.field_entity_heading_for_dump() !=
                scene2_return_heading ||
            field_scene.field_map_event_system_for_dump()
                    .collision_dispatch_count() != dispatches_at_door ||
            !field_hud_chrome_survives(render(), asset_root) ||
            count_playfield_lit(render()) < 100U ||
            !write_exit_state("scene2-return", "none") ||
            !save("scene20-c0-scene2-return")) {
            std::cerr << "Scene-20 C0 QA: event 0 did not restore the "
                         "source scene-2 contact position and facing\n";
            return 3;
        }

        const auto dispatches_after_c0 =
            field_scene.field_map_event_system_for_dump()
                .collision_dispatch_count();
        for (std::uint32_t tick = 1U; tick <= 16U; ++tick) {
            field_scene.set_controller_nibble(0x02U); // held Down, away
            field_scene.advance_frame();
            ++frame;
            if (!scene2_is_live() ||
                field_scene.field_map_event_system_for_dump()
                        .collision_dispatch_count() != dispatches_after_c0 ||
                !write_exit_state("held-down", "Down")) {
                field_scene.set_controller_nibble(0U);
                std::cerr << "Scene-20 C0 QA: held Down retriggered event 0 "
                             "or left scene 2 at update " << tick
                          << '\n';
                return 3;
            }
            if ((tick == 1U || tick == 4U || tick == 8U || tick == 16U) &&
                !save("scene20-c0-held-down-" +
                      (tick < 10U ? std::string("0") : std::string()) +
                      std::to_string(tick))) {
                field_scene.set_controller_nibble(0U);
                return 3;
            }
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto clear_position =
            field_scene.field_entity_world_position();
        if (clear_position.y <= returned_contact.y ||
            field_scene.field_terrain_collision_code_for_dump() != 0U ||
            (field_scene.field_movement_route_flags_for_dump() & 0x20U) !=
                0U ||
            !write_exit_state("released-after-down", "none") ||
            !save("scene20-c0-clear-of-trigger")) {
            std::cerr << "Scene-20 C0 QA: held Down did not clear the door "
                         "record and source retry latch\n";
            return 3;
        }
        for (std::uint32_t tick = 1U; tick <= 8U; ++tick) {
            field_scene.set_controller_nibble(0x08U); // fresh ordinary Right
            field_scene.advance_frame();
            ++frame;
            if (!scene2_is_live() ||
                field_scene.field_map_event_system_for_dump()
                        .collision_dispatch_count() != dispatches_after_c0 ||
                !write_exit_state("fresh-right", "Right")) {
                field_scene.set_controller_nibble(0U);
                std::cerr << "Scene-20 C0 QA: fresh Right retriggered event 0 "
                             "after clearing its record\n";
                return 3;
            }
            if ((tick == 1U || tick == 4U || tick == 8U) &&
                !save("scene20-c0-fresh-right-" +
                      (tick < 10U ? std::string("0") : std::string()) +
                      std::to_string(tick))) {
                field_scene.set_controller_nibble(0U);
                return 3;
            }
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto actual = render();
        if (!scene2_is_live() ||
            !field_hud_chrome_survives(actual, asset_root) ||
            count_playfield_lit(actual) < 100U || !save("actual")) {
            return 3;
        }
        exit_trace.close();
        std::cout << "scene20_c0_return_lifetime_qa=passed record=110 rom=0x"
                  << std::hex << kDoorRecordAddress << std::dec
                  << " event=0 destination=source-scene="
                  << field_scene.field_scene_reference_for_dump()
                  << " scene20_contact=" << door_contact.x << ','
                  << door_contact.y << " source_return="
                  << scene2_return_position.x << ','
                  << scene2_return_position.y << " dispatches="
                  << dispatches_before_door << "->" << dispatches_at_door
                  << " held_down=16 fresh_right=8"
                  << " artifacts=" << output.string() << '\n';
        return 0;
    }
    // The source collision cells describe a narrow path around the central
    // wall before record 117's physical maglock. Stay in cell centers so the
    // player's four probes follow clear cells through the scene.
    for (std::uint8_t tick = 0U; tick < 12U; ++tick) {
        field_scene.set_controller_nibble(0x06U); // ordinary Down + Left
        field_scene.advance_frame();
        ++frame;
        if (tick == 3U || tick == 7U) {
            if (!save("interior-diagonal-entry-" +
                      std::to_string(static_cast<unsigned>(tick + 1U)))) {
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!save("interior-diagonal-entry-12")) {
        return 3;
    }
    write_state("interior-diagonal-entry-12");
    std::uint16_t south_corridor_ticks = 0U;
    while (south_corridor_ticks < 500U && scene20_is_live() &&
           world_position().second < 0x0230U) {
        const auto position = world_position();
        const auto input = position.first < 0x058CU
                               ? 0x0AU // Down + Right: correct west drift
                               : position.first > 0x0594U
                                     ? 0x06U // Down + Left: correct east drift
                                     : 0x02U; // Down through the lane center
        field_scene.set_controller_nibble(input);
        field_scene.advance_frame();
        ++frame;
        ++south_corridor_ticks;
        if (south_corridor_ticks == 32U || south_corridor_ticks == 96U ||
            south_corridor_ticks == 160U || south_corridor_ticks == 224U ||
            south_corridor_ticks == 320U) {
            if (!save("interior-east-hall-" +
                      std::to_string(south_corridor_ticks))) {
                return 3;
            }
            write_state("interior-east-hall-" +
                        std::to_string(south_corridor_ticks));
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    const auto south_corridor_position = world_position();
    if (!scene20_is_live() || south_corridor_position.second < 0x0230U ||
        south_corridor_position.first < 0x057FU ||
        south_corridor_position.first > 0x059FU ||
        !save("interior-east-hall")) {
        std::cerr << "Scene-20 physical-entry QA: normal steering did not "
                  << "follow the narrow south corridor (ticks="
                  << south_corridor_ticks << ", position="
                  << south_corridor_position.first << ','
                  << south_corridor_position.second << ")\n";
        return 3;
    }
    write_state("interior-east-hall");
    if (!walk_to(true, false, 0x0528U, 0x04U, "interior-south-turn", 16U,
                 scene20_is_live) ||
        !walk_to(false, false, 0x011CU, 0x01U, "interior-north-hall", 16U,
                 scene20_is_live) ||
        !walk_to(true, false, 0x047CU, 0x04U, "maglock-approach", 16U,
                 scene20_is_live)) {
        return 3;
    }

    std::uint16_t maglock_ticks = 0U;
    while (maglock_ticks < 120U && scene20_is_live()) {
        field_scene.set_controller_nibble(0x01U); // ordinary Up hold
        field_scene.advance_frame();
        ++frame;
        ++maglock_ticks;
        if (maglock_ticks == 16U || maglock_ticks == 32U ||
            maglock_ticks == 64U) {
            if (!save("maglock-north-" +
                      std::to_string(maglock_ticks))) {
                return 3;
            }
        }
        if ((field_scene.field_terrain_collision_code_for_dump() & 0x001FU) ==
                2U ||
            field_scene.field_interaction_open() ||
            field_scene.field_transition_pending_for_dump()) {
            break;
        }
    }
    const auto maglock_contact = world_position();
    const auto maglock_contact_projected_code =
        field_scene.field_projected_code_for_dump();
    const auto maglock_contact_terrain_code =
        field_scene.field_terrain_collision_code_for_dump();
    const auto maglock_contact_activity =
        field_scene.field_activity_selection_for_dump();
    // The converted 0xB7B8 route emits FF82 at y=0x0107. Keep the exact
    // projected-event/activity checks and allow the runner center one map
    // unit below record 117's last coordinate.
    const bool maglock_contact_is_valid =
        maglock_contact_projected_code == 0xFF82U &&
        maglock_contact_activity == 2U &&
        maglock_contact.first >= 0x0454U &&
        maglock_contact.first <= 0x048BU &&
        maglock_contact.second >= 0x00D9U &&
        maglock_contact.second <= 0x0107U;
    write_state("maglock-contact");
    if (maglock_contact_is_valid && !save("maglock-contact")) {
        return 3;
    }
    field_scene.set_controller_nibble(0U);
    for (std::uint16_t settle = 0U;
         settle < 120U && !field_scene.field_interaction_open(); ++settle) {
        field_scene.advance_frame();
        ++frame;
        if (settle == 7U || settle == 15U || settle == 31U ||
            settle == 63U) {
            if (!save("maglock-intro-wait-" +
                      std::to_string(static_cast<unsigned>(settle + 1U)))) {
                return 3;
            }
        }
    }
    const auto& maglock_panel = field_scene.field_interaction_panel();
    if (!maglock_contact_is_valid ||
        !field_scene.field_interaction_open() ||
        !maglock_panel.open || !maglock_panel.source_complete ||
        maglock_panel.actor_kind != DialoguePanelActorKind::none ||
        maglock_panel.text_segment_count == 0U ||
        field_scene.field_scene_reference_for_dump() != 0x14U ||
        field_scene.field_mode_text_open_for_dump() ||
        field_scene.shop_menu_open() || !save("maglock-introduction")) {
        std::cerr << "Scene-20 physical-entry QA: ordinary Up did not open "
                     "the event-2 maglock prompt (ticks=" << maglock_ticks
                  << ", position=" << maglock_contact.first << ','
                  << maglock_contact.second << ", contact-projected=0x"
                  << std::hex << maglock_contact_projected_code
                  << ", terrain=0x" << maglock_contact_terrain_code << std::dec
                  << ", contact-activity=" << static_cast<unsigned>(
                         maglock_contact_activity)
                  << ", contact-valid=" << maglock_contact_is_valid
                  << ", panel=" << maglock_panel.open
                  << ", complete=" << maglock_panel.source_complete
                  << ", actor=" << static_cast<unsigned>(
                         maglock_panel.actor_kind)
                  << ", text-segments=" << static_cast<unsigned>(
                         maglock_panel.text_segment_count)
                  << ", panel-reason=" << maglock_panel.source_boundary_reason
                  << ", scene=" << field_scene.field_scene_reference_for_dump()
                  << ", mode-text=" << field_scene.field_mode_text_open_for_dump()
                  << ", shop=" << field_scene.shop_menu_open()
                  << ", pending-handler="
                  << field_scene.field_runtime_state_for_dump()
                         .pending_field_scene_handler
                  << ")\n";
        std::ofstream boundary_log(output / "source-boundaries.txt",
                                   std::ios::trunc);
        if (boundary_log) {
            for (const auto& boundary : source_boundaries) {
                boundary_log << boundary << '\n';
            }
        }
        return 3;
    }
    write_state("maglock-introduction");
    for (std::uint8_t tick = 0U; tick < 10U; ++tick) {
        field_scene.advance_frame();
        ++frame;
    }
    const auto maglock_introduction = render();
    if (maglock_introduction.size() != QSize(kSceneWidth, kSceneHeight) ||
        field_hud_chrome_survives(maglock_introduction, asset_root) ||
        !save("maglock-introduction-after-10-frames")) {
        return 3;
    }
    std::array<std::uint8_t, 4096U>
        insufficient_passkey_collision_map_before{};
    std::size_t insufficient_passkey_audio_count = 0U;
    std::array<std::uint8_t, 4096U>
        electronics_no_skill_collision_map_before{};
    std::optional<std::array<std::uint8_t, kRunnerRecordInventorySlots>>
        electronics_no_skill_inventory_items_before;
    std::optional<std::array<std::uint8_t, kRunnerRecordInventorySlots>>
        electronics_no_skill_inventory_phase_before;
    std::size_t electronics_no_skill_audio_count = 0U;
    if (path == Scene20PhysicalEntryQaPath::passkey_success) {
        const auto collision_map_before = field_scene.state()
                                              .field_scene_buffers
                                              .source_metadata
                                              .terrain_collision_map;
        const auto audio_count_before = field_audio_events.size();
        field_scene.set_controller_port_byte(0x40U); // ordinary A: <MORE>
        field_scene.advance_frame();
        ++frame;
        const auto passkey_action_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        const auto& result_panel = field_scene.field_interaction_panel();
        const auto result_image = render();
        const bool result_text_matches =
            result_panel.text_segment_count == 3U &&
            result_panel.text_segments[0].find("Your Maglock Passkey") !=
                std::string_view::npos &&
            result_panel.text_segments[2].find("door has been disabled") !=
                std::string_view::npos;
        if ((passkey_action_event & 0xFF00U) != 0x4000U ||
            !field_scene.field_interaction_open() || !result_panel.open ||
            !result_panel.source_complete ||
            result_panel.kind != DialoguePanelKind::information_page ||
            result_panel.actor_kind != DialoguePanelActorKind::none ||
            result_panel.option_count != 0U || !result_text_matches ||
            field_scene.field_activity_selection_for_dump() != 0xFFU ||
            field_audio_events.size() != audio_count_before + 1U ||
            field_audio_events.back() != 0x4BU ||
            result_image == maglock_introduction ||
            field_hud_chrome_survives(result_image, asset_root) ||
            !save("maglock-passkey-result") || !save("actual")) {
            std::cerr << "Scene-20 passkey QA: normal A did not produce the "
                         "ROM passkey result (event=0x" << std::hex
                      << passkey_action_event << std::dec << ", selection="
                      << static_cast<unsigned>(
                             field_scene.field_activity_selection_for_dump())
                      << ", audio=" << audio_count_before << "->"
                      << field_audio_events.size() << ")\n";
            return 3;
        }
        write_state("maglock-passkey-result");
        if (!save("maglock-passkey-result-wait-1")) {
            return 3;
        }
        for (std::uint8_t wait_frame = 2U; wait_frame <= 30U; ++wait_frame) {
            field_scene.advance_frame();
            ++frame;
            if (wait_frame == 15U || wait_frame == 30U) {
                const auto held_result = render();
                if (held_result != result_image ||
                    !save(wait_frame == 15U
                              ? "maglock-passkey-result-wait-15"
                              : "maglock-passkey-result-wait-30")) {
                    std::cerr << "Scene-20 passkey QA: result changed during "
                                 "the source 30-frame wait\n";
                    return 3;
                }
            }
        }
        field_scene.set_controller_port_byte(0x40U); // ordinary A dismisses
        field_scene.advance_frame();
        ++frame;
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        field_scene.advance_frame();
        ++frame;

        if (!finish_field_modal_return_transition(field_scene)) {
            std::cerr << "Scene-20 passkey QA: field return fade did not complete\n";
            return 3;
        }

        const auto collision_map_after = field_scene.state()
                                             .field_scene_buffers
                                             .source_metadata
                                             .terrain_collision_map;
        std::vector<std::tuple<std::size_t, std::uint8_t, std::uint8_t>>
            collision_map_changes;
        if (collision_map_before.size() == collision_map_after.size()) {
            for (std::size_t index = 0U; index < collision_map_before.size();
                 ++index) {
                if (collision_map_before[index] != collision_map_after[index]) {
                    collision_map_changes.emplace_back(
                        index, collision_map_before[index],
                        collision_map_after[index]);
                }
            }
        }
        const bool one_passkey_marker_advanced =
            collision_map_before.size() == collision_map_after.size() &&
            collision_map_changes.size() == 1U &&
            std::get<1>(collision_map_changes.front()) == 0x82U &&
            std::get<2>(collision_map_changes.front()) == 0x81U;
        const auto returned_scene20 = render();
        const auto returned_field_only = render_field_scene_only();
        const auto& active_runner = field_scene.active_runner_record();
        const bool passkey_remains_in_live_inventory =
            seeded_passkey_slot.has_value() &&
            active_runner.inventory_item_codes[*seeded_passkey_slot] ==
                kPasskeyItemCode &&
            active_runner.inventory_phase_bytes[*seeded_passkey_slot] ==
                kPasskeyQuality;
        const bool returned_cleanly =
            !field_scene.field_interaction_open() &&
            !field_scene.dialogue_open() &&
            !field_scene.field_mode_text_open_for_dump() &&
            !field_scene.shop_menu_open() &&
            field_scene.field_scene_reference_for_dump() == 0x14U &&
            field_scene.field_entity_visible_for_dump() &&
            field_hud_chrome_survives(returned_scene20, asset_root) &&
            count_playfield_lit(returned_scene20) >= 100U &&
            returned_scene20 == returned_field_only;
        write_state("scene20-return-after-passkey");
        if (!returned_cleanly || !one_passkey_marker_advanced ||
            !passkey_remains_in_live_inventory ||
            field_audio_events.size() != audio_count_before + 1U ||
            !returned_scene20.save(QString::fromStdWString(
                (output / "scene20-after-passkey.bmp").wstring())) ||
            !returned_field_only.save(QString::fromStdWString(
                (output / "scene20-field-only-after-passkey.bmp").wstring())) ||
            !save("scene20-return-after-passkey")) {
            std::cerr << "Scene-20 passkey QA: acknowledgement did not "
                         "return to a clean field and advance one 0x82->0x81 "
                         "collision cell (changes="
                      << collision_map_changes.size() << ", clean="
                      << returned_cleanly << ", inventory="
                      << passkey_remains_in_live_inventory << ", audio="
                      << field_audio_events.size() << ")\n";
            return 3;
        }
        {
            std::ofstream event_delta(
                output / "passkey-collision-map-delta.tsv", std::ios::trunc);
            if (!event_delta) {
                return 3;
            }
            event_delta << "map_index\tbefore\tafter\n";
            for (const auto& [index, before, after] : collision_map_changes) {
                event_delta << index << "\t0x" << std::hex
                            << static_cast<unsigned>(before) << "\t0x"
                            << static_cast<unsigned>(after) << std::dec << '\n';
            }
        }
        {
            std::ofstream boundaries(output / "source-boundaries.txt",
                                     std::ios::trunc);
            if (!boundaries) {
                return 3;
            }
            for (const auto& boundary : source_boundaries) {
                boundaries << boundary << '\n';
            }
        }
        {
            std::ofstream events(output / "audio-events.txt", std::ios::trunc);
            if (!events) {
                return 3;
            }
            for (const auto event : field_audio_events) {
                events << "0x" << std::hex << event << '\n';
            }
        }
        std::cout << "field_scene20_physical_entry_qa=passed records=89,90 "
                     "rom=0x"
                  << std::hex << doorway_rom_address << " destination=0x14"
                  << std::dec << " route_frames=" << frame
                  << " north_ticks=" << north_ticks
                  << " raw=0xFFC0 event=0 audio_events="
                  << field_audio_events.size()
                  << " choice=passkey-success artifacts=" << output.string()
                  << '\n';
        return 0;
    }
    if (path == Scene20PhysicalEntryQaPath::passkey_insufficient) {
        const auto audio_before_insufficient_passkey =
            field_audio_events.size();
        insufficient_passkey_audio_count = audio_before_insufficient_passkey;
        insufficient_passkey_collision_map_before = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        field_scene.set_controller_port_byte(0x40U); // ordinary A: <MORE>
        field_scene.advance_frame();
        ++frame;
        const auto passkey_action_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        const auto& insufficient_panel = field_scene.field_interaction_panel();
        const auto insufficient_image = render();
        const auto& active_runner = field_scene.active_runner_record();
        const bool insufficient_quality_text =
            insufficient_panel.text_segment_count == 1U &&
            insufficient_panel.text_segments[0].find(
                "not sophisticated enough") != std::string_view::npos;
        const bool live_passkey_unchanged =
            seeded_passkey_slot.has_value() &&
            active_runner.inventory_item_codes[*seeded_passkey_slot] ==
                kPasskeyItemCode &&
            active_runner.inventory_phase_bytes[*seeded_passkey_slot] ==
                seeded_passkey_quality;
        if ((passkey_action_event & 0xFF00U) != 0x4000U ||
            !field_scene.field_interaction_open() ||
            !insufficient_panel.open || !insufficient_panel.source_complete ||
            insufficient_panel.option_count != 3U ||
            !insufficient_quality_text ||
            field_scene.field_activity_selection_for_dump() != 2U ||
            !live_passkey_unchanged ||
            field_audio_events.size() != audio_before_insufficient_passkey ||
            field_hud_chrome_survives(insufficient_image, asset_root) ||
            insufficient_image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !save("maglock-insufficient-passkey-choices") ||
            !save("actual")) {
            std::cerr << "Scene-20 insufficient-passkey QA: normal A did not "
                         "retain the source three-choice prompt for a "
                         "quality-1 key against selection 2 (event=0x"
                      << std::hex << passkey_action_event << std::dec
                      << ", open=" << field_scene.field_interaction_open()
                      << ", options=" << insufficient_panel.option_count
                      << ", segments="
                      << insufficient_panel.text_segment_count
                      << ", selection=" << static_cast<unsigned>(
                             field_scene.field_activity_selection_for_dump())
                      << ", inventory=" << live_passkey_unchanged
                      << ", audio=" << audio_before_insufficient_passkey
                      << "->" << field_audio_events.size() << ")\n";
            return 3;
        }
        write_state("maglock-insufficient-passkey-choices");
    } else {
        field_scene.set_controller_port_byte(0x40U); // ordinary A: <MORE>
        field_scene.advance_frame();
        ++frame;
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
    }
    const auto& maglock_choices = field_scene.field_interaction_panel();
    const auto maglock_choices_image = render();
    bool no_passkey_choices_text = false;
    for (std::size_t segment = 0U;
         segment < maglock_choices.text_segment_count; ++segment) {
        no_passkey_choices_text = no_passkey_choices_text ||
            maglock_choices.text_segments[segment].find(
                "Since you do not have a Maglock Passkey") !=
                std::string_view::npos;
    }
    const bool choices_are_source_complete =
        field_scene.field_interaction_open() &&
        maglock_choices.source_complete &&
        maglock_choices.option_count == 3U &&
        maglock_choices.options[0].source_label.find("Electronics") !=
            std::string::npos &&
        maglock_choices.options[1].source_label.find("Frag") !=
            std::string::npos &&
        maglock_choices.options[2].source_label.find("Walk") !=
            std::string::npos &&
        ((path != Scene20PhysicalEntryQaPath::electronics_no_skill &&
          path != Scene20PhysicalEntryQaPath::electronics_alert &&
          path != Scene20PhysicalEntryQaPath::electronics_trials) ||
         no_passkey_choices_text);
    if (!choices_are_source_complete ||
        field_hud_chrome_survives(maglock_choices_image, asset_root) ||
        maglock_choices_image.size() != QSize(kSceneWidth, kSceneHeight) ||
        !save("maglock-choices")) {
        std::cerr << "Scene-20 physical-entry QA: ordinary A did not replace "
                     "the doorway page with its complete three-choice screen\n";
        return 3;
    }
    write_state("maglock-choices");
    // The release sample after A is already the first source wait frame.
    // Eight idle frames plus the selected-input frame complete the ten-frame
    // delay exactly.
    for (std::uint8_t tick = 0U; tick < 8U; ++tick) {
        field_scene.advance_frame();
        ++frame;
    }
    if (path == Scene20PhysicalEntryQaPath::passkey_insufficient) {
        const auto held_choices_image = render();
        if (held_choices_image != maglock_choices_image ||
            field_audio_events.size() != insufficient_passkey_audio_count ||
            !save("maglock-insufficient-passkey-choices-after-8-frames")) {
            std::cerr << "Scene-20 insufficient-passkey QA: the generic "
                         "three-choice prompt changed during its idle hold "
                         "or emitted an action sound\n";
            return 3;
        }
    }
    if (path == Scene20PhysicalEntryQaPath::electronics_no_skill) {
        const auto& party = field_scene.field_party_records_for_dump();
        bool active_party_member_found = false;
        bool active_party_has_electronics_skill = false;
        for (std::size_t slot = 0U; slot < party.size(); ++slot) {
            const auto& runner = party[slot];
            if (!field_scene.field_party_slot_active_for_dump(slot) ||
                (runner.flags & 0x0100U) == 0U) {
                continue;
            }
            active_party_member_found = true;
            active_party_has_electronics_skill =
                active_party_has_electronics_skill || runner.skills[9] != 0U;
        }
        const auto& active_runner = field_scene.active_runner_record();
        if (!active_party_member_found || active_party_has_electronics_skill ||
            active_runner.archetype_index != 2U ||
            active_runner.skills[9] != 0U ||
            field_scene.field_activity_selection_for_dump() != 2U) {
            std::cerr << "Scene-20 Electronics QA: expected the source "
                         "Samurai class-2 record with no active Electronics skill "
                         "against selection 2 (archetype="
                      << static_cast<unsigned>(active_runner.archetype_index)
                      << ", skill=" << static_cast<unsigned>(
                             active_runner.skills[9])
                      << ", selection=" << static_cast<unsigned>(
                             field_scene.field_activity_selection_for_dump())
                      << ")\n";
            return 3;
        }
        electronics_no_skill_inventory_items_before =
            active_runner.inventory_item_codes;
        electronics_no_skill_inventory_phase_before =
            active_runner.inventory_phase_bytes;
        electronics_no_skill_collision_map_before = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        electronics_no_skill_audio_count = field_audio_events.size();

        field_scene.set_controller_port_byte(0x40U); // ordinary A: Electronics
        field_scene.advance_frame();
        ++frame;
        const auto electronics_choice_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        const auto& no_skill_panel = field_scene.field_interaction_panel();
        const auto no_skill_image = render();
        const auto& no_skill_runner = field_scene.active_runner_record();
        const bool no_skill_text_matches =
            no_skill_panel.text_segment_count == 1U &&
            no_skill_panel.text_segments[0].find(
                "not skilled in Electronics") != std::string_view::npos;
        const bool no_skill_inventory_unchanged =
            electronics_no_skill_inventory_items_before.has_value() &&
            electronics_no_skill_inventory_phase_before.has_value() &&
            no_skill_runner.inventory_item_codes ==
                *electronics_no_skill_inventory_items_before &&
            no_skill_runner.inventory_phase_bytes ==
                *electronics_no_skill_inventory_phase_before;
        const auto& no_skill_collision_map_after_action = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const bool no_skill_world_unchanged =
            no_skill_collision_map_after_action ==
                electronics_no_skill_collision_map_before &&
            field_scene.field_activity_selection_for_dump() == 2U;
        const bool no_skill_action_silent =
            field_audio_events.size() == electronics_no_skill_audio_count;
        if ((electronics_choice_event & 0xFF00U) != 0x4000U ||
            !field_scene.field_interaction_open() || !no_skill_panel.open ||
            !no_skill_panel.source_complete ||
            no_skill_panel.kind != DialoguePanelKind::information_page ||
            no_skill_panel.actor_kind != DialoguePanelActorKind::none ||
            no_skill_panel.option_count != 0U || !no_skill_text_matches ||
            !no_skill_inventory_unchanged || !no_skill_world_unchanged ||
            !no_skill_action_silent ||
            field_hud_chrome_survives(no_skill_image, asset_root) ||
            no_skill_image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !save("maglock-electronics-no-skill") || !save("actual")) {
            std::cerr << "Scene-20 Electronics QA: ordinary A did not show "
                         "the source no-skill information page without "
                         "mutating the runner/map or adding a sound (event=0x"
                      << std::hex << electronics_choice_event << std::dec
                      << ", open=" << field_scene.field_interaction_open()
                      << ", options=" << no_skill_panel.option_count
                      << ", text='"
                      << (no_skill_panel.text_segment_count == 0U
                              ? std::string_view{}
                              : no_skill_panel.text_segments[0])
                      << "', inventory=" << no_skill_inventory_unchanged
                      << ", map=" << no_skill_world_unchanged
                      << ", audio=" << electronics_no_skill_audio_count
                      << "->" << field_audio_events.size() << ")\n";
            return 3;
        }
        write_state("maglock-electronics-no-skill");
        if (!save("maglock-electronics-no-skill-wait-1")) {
            return 3;
        }
        for (std::uint8_t tick = 1U; tick < 30U; ++tick) {
            field_scene.advance_frame();
            ++frame;
            if (tick == 14U || tick == 29U) {
                if (!save("maglock-electronics-no-skill-wait-" +
                          std::to_string(static_cast<unsigned>(tick + 1U)))) {
                    return 3;
                }
            }
        }
        const auto held_no_skill_image = render();
        const auto& no_skill_collision_map_after_wait = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const auto& no_skill_runner_after_wait =
            field_scene.active_runner_record();
        if (held_no_skill_image != no_skill_image ||
            field_audio_events.size() != electronics_no_skill_audio_count ||
            no_skill_collision_map_after_wait !=
                electronics_no_skill_collision_map_before ||
            !electronics_no_skill_inventory_items_before.has_value() ||
            !electronics_no_skill_inventory_phase_before.has_value() ||
            no_skill_runner_after_wait.inventory_item_codes !=
                *electronics_no_skill_inventory_items_before ||
            no_skill_runner_after_wait.inventory_phase_bytes !=
                *electronics_no_skill_inventory_phase_before ||
            !save("maglock-electronics-no-skill-held")) {
            std::cerr << "Scene-20 Electronics QA: source no-skill result "
                         "changed during its 30-frame wait or mutated world "
                         "state\n";
            return 3;
        }
        write_state("maglock-electronics-no-skill-held");

        field_scene.set_controller_port_byte(0x40U); // ordinary A acknowledges
        field_scene.advance_frame();
        ++frame;
        const auto acknowledgement_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (!finish_field_modal_return_transition(field_scene)) {
            std::cerr << "Scene-20 Electronics QA: field return fade did not complete\n";
            return 3;
        }
        const auto returned_scene20 = render();
        const auto returned_field_only = render_field_scene_only();
        const auto& acknowledgement_panel =
            field_scene.field_interaction_panel();
        const auto& returned_runner = field_scene.active_runner_record();
        const auto& returned_collision_map = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const bool result_closed_cleanly =
            controller_event_contains_a(acknowledgement_event) &&
            !field_scene.field_interaction_open() &&
            !field_scene.dialogue_open() &&
            !field_scene.field_mode_text_open_for_dump() &&
            !field_scene.shop_menu_open() &&
            field_scene.field_scene_reference_for_dump() == 0x14U &&
            !acknowledgement_panel.open &&
            field_hud_chrome_survives(returned_scene20, asset_root) &&
            count_playfield_lit(returned_scene20) >= 100U &&
            returned_scene20 == returned_field_only &&
            returned_runner.inventory_item_codes ==
                *electronics_no_skill_inventory_items_before &&
            returned_runner.inventory_phase_bytes ==
                *electronics_no_skill_inventory_phase_before &&
            returned_runner.skills[9] == 0U &&
            returned_collision_map == electronics_no_skill_collision_map_before &&
            field_scene.field_activity_selection_for_dump() == 2U &&
            field_audio_events.size() == electronics_no_skill_audio_count;
        write_state("after-electronics-no-skill-acknowledgement");
        if (!result_closed_cleanly ||
            !returned_scene20.save(QString::fromStdWString(
                (output /
                 "scene20-after-electronics-no-skill-acknowledgement.bmp")
                    .wstring())) ||
            !returned_field_only.save(QString::fromStdWString(
                (output / "scene20-field-only-after-electronics-no-skill.bmp")
                    .wstring())) ||
            !save("scene20-return-after-electronics-no-skill")) {
            std::cerr << "Scene-20 Electronics QA: ordinary A did not close "
                         "the generic result page and restore a clean field "
                         "screen (event=0x"
                      << std::hex << acknowledgement_event << std::dec
                      << ", closed=" << !field_scene.field_interaction_open()
                      << ", scene="
                      << field_scene.field_scene_reference_for_dump()
                      << ", clean-frame="
                      << (returned_scene20 == returned_field_only)
                      << ", audio=" << electronics_no_skill_audio_count
                      << "->" << field_audio_events.size() << ")\n";
            return 3;
        }
        write_state("scene20-return-after-electronics-no-skill");
    } else if (path == Scene20PhysicalEntryQaPath::electronics_alert) {
        constexpr std::uint8_t electronics_kit_code = 0x15U;
        constexpr std::uint8_t maglock_passkey_code = 0x14U;
        const auto& party = field_scene.field_party_records_for_dump();
        bool active_party_has_kit = false;
        bool active_party_has_passkey = false;
        for (std::size_t slot = 0U; slot < party.size(); ++slot) {
            if (!field_scene.field_party_slot_active_for_dump(slot) ||
                (party[slot].flags & 0x0100U) == 0U) {
                continue;
            }
            active_party_has_kit = active_party_has_kit ||
                std::find(party[slot].inventory_item_codes.begin(),
                          party[slot].inventory_item_codes.end(),
                          electronics_kit_code) !=
                    party[slot].inventory_item_codes.end();
            active_party_has_passkey = active_party_has_passkey ||
                std::find(party[slot].inventory_item_codes.begin(),
                          party[slot].inventory_item_codes.end(),
                          maglock_passkey_code) !=
                    party[slot].inventory_item_codes.end();
        }
        const auto& decker_before = field_scene.active_runner_record();
        const auto inventory_before = decker_before.inventory_item_codes;
        const auto inventory_phase_before = decker_before.inventory_phase_bytes;
        const auto collision_map_before = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const auto audio_before = field_audio_events.size();
        const auto& timeout_before =
            field_scene.world_activity_timeout_for_dump();
        if (decker_before.archetype_index != 3U ||
            decker_before.skills[9] != 1U || active_party_has_kit ||
            active_party_has_passkey ||
            field_scene.field_activity_selection_for_dump() != 2U ||
            timeout_before.timeout_marker != 0 ||
            timeout_before.timeout_frames != 0U) {
            std::cerr << "Scene-20 Electronics alert QA: expected a clean "
                         "skill-1 Decker with no kit/passkey and no prior "
                         "world timeout\n";
            return 3;
        }

        // ROM 0x0D44/0x0D3A/0x0DBA: seed 0 produces a face below target 5,
        // so the sole no-kit trial reaches the zero-success alert branch.
        field_scene.set_source_random_seed_for_dump(0U);
        field_scene.set_controller_port_byte(0x40U); // ordinary A: Electronics
        field_scene.advance_frame();
        ++frame;
        const auto action_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;

        const auto& alert_panel = field_scene.field_interaction_panel();
        const auto alert_image = render();
        bool mentions_failed_attempt = false;
        bool mentions_alert_klaxon = false;
        for (std::size_t segment = 0U;
             segment < alert_panel.text_segment_count; ++segment) {
            mentions_failed_attempt = mentions_failed_attempt ||
                alert_panel.text_segments[segment].find("fragged this attempt") !=
                    std::string_view::npos;
            mentions_alert_klaxon = mentions_alert_klaxon ||
                alert_panel.text_segments[segment].find("alert klaxon") !=
                    std::string_view::npos;
        }
        const auto& alert_runner = field_scene.active_runner_record();
        const auto& alert_map = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const auto& alert_timeout =
            field_scene.world_activity_timeout_for_dump();
        const bool alert_state_correct =
            alert_timeout.scene_id == 0x14U &&
            alert_timeout.timeout_marker == -1 &&
            alert_timeout.timeout_frames == 0x78U;
        const bool alert_result_correct =
            (action_event & 0xFF00U) == 0x4000U &&
            field_scene.field_interaction_open() && alert_panel.open &&
            alert_panel.source_complete &&
            alert_panel.kind == DialoguePanelKind::information_page &&
            alert_panel.actor_kind == DialoguePanelActorKind::none &&
            alert_panel.option_count == 0U && mentions_failed_attempt &&
            mentions_alert_klaxon &&
            field_scene.field_activity_selection_for_dump() == 2U &&
            alert_runner.inventory_item_codes == inventory_before &&
            alert_runner.inventory_phase_bytes == inventory_phase_before &&
            alert_runner.skills[9] == 1U && alert_map == collision_map_before &&
            alert_state_correct && field_audio_events.size() == audio_before &&
            !field_hud_chrome_survives(alert_image, asset_root) &&
            alert_image.size() == QSize(kSceneWidth, kSceneHeight);
        if (!alert_result_correct || !save("maglock-electronics-alert") ||
            !save("actual")) {
            std::cerr << "Scene-20 Electronics alert QA: the zero-success "
                         "trial did not show the alert page with the source "
                         "timeout and unchanged map/inventory (event=0x"
                      << std::hex << action_event << std::dec
                      << ", text-segments=" << alert_panel.text_segment_count
                      << ", timeout=" << alert_state_correct
                      << ", audio=" << audio_before << "->"
                      << field_audio_events.size() << ")\n";
            return 3;
        }
        write_state("maglock-electronics-alert");

        std::ofstream alert_trace(output / "electronics-alert-state.tsv",
                                  std::ios::trunc);
        if (!alert_trace) {
            std::cerr << "Scene-20 Electronics alert QA: could not write "
                         "alert state trace\n";
            return 3;
        }
        alert_trace << "stage\tscene\ttimeout_marker\ttimeout_frames"
                       "\tworld_active\tcleanup_countdown"
                       "\ttarget_selection_requested\taudio_events\n";
        const auto write_alert_state = [&] (const std::string_view stage) {
            const auto& timeout =
                field_scene.world_activity_timeout_for_dump();
            const auto& world = field_scene.world_frame_logic_for_dump();
            alert_trace << stage << '\t' << timeout.scene_id << '\t'
                        << timeout.timeout_marker << '\t'
                        << timeout.timeout_frames << '\t'
                        << world.world_active << '\t'
                        << world.cleanup_countdown << '\t'
                        << world.target_selection_requested << '\t'
                        << field_audio_events.size() << '\n';
            alert_trace.flush();
        };
        write_alert_state("result-open");

        if (!save("maglock-electronics-alert-wait-1")) {
            return 3;
        }
        for (std::uint8_t tick = 1U; tick < 30U; ++tick) {
            field_scene.advance_frame();
            ++frame;
            if (tick == 14U || tick == 29U) {
                if (!save("maglock-electronics-alert-wait-" +
                          std::to_string(static_cast<unsigned>(tick + 1U)))) {
                    return 3;
                }
            }
        }
        const auto held_alert_image = render();
        const auto& held_alert_timeout =
            field_scene.world_activity_timeout_for_dump();
        if (held_alert_image != alert_image ||
            held_alert_timeout.timeout_marker != -1 ||
            held_alert_timeout.timeout_frames != 0x78U ||
            field_audio_events.size() != audio_before ||
            !save("maglock-electronics-alert-held")) {
            std::cerr << "Scene-20 Electronics alert QA: result or scheduled "
                         "timeout changed during the 30-frame modal wait\n";
            return 3;
        }
        write_state("maglock-electronics-alert-held");
        write_alert_state("result-held-30");

        const auto target_service_before = static_cast<std::size_t>(
            std::count(source_boundaries.begin(), source_boundaries.end(),
                       "field.world_logic.select_entity_service_target"));
        field_scene.set_controller_port_byte(0x40U); // ordinary A acknowledges
        field_scene.advance_frame();
        ++frame;
        const auto acknowledgement_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame(); // next field frame runs world logic
        ++frame;
        if (!finish_field_modal_return_transition(field_scene)) {
            std::cerr << "Scene-20 Electronics alert QA: field return fade did not complete\n";
            return 3;
        }
        field_scene.advance_frame(); // resume the source world-service pass
        ++frame;

        const auto returned_scene20 = render();
        const auto returned_field_only = render_field_scene_only();
        const auto& returned_timeout =
            field_scene.world_activity_timeout_for_dump();
        const auto& returned_world = field_scene.world_frame_logic_for_dump();
        const auto& returned_runner = field_scene.active_runner_record();
        const auto& returned_map = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const auto target_service_after = static_cast<std::size_t>(
            std::count(source_boundaries.begin(), source_boundaries.end(),
                       "field.world_logic.select_entity_service_target"));
        const bool alert_return_correct =
            controller_event_contains_a(acknowledgement_event) &&
            !field_scene.field_interaction_open() &&
            !field_scene.dialogue_open() &&
            !field_scene.field_mode_text_open_for_dump() &&
            !field_scene.shop_menu_open() &&
            field_scene.field_scene_reference_for_dump() == 0x14U &&
            returned_timeout.timeout_marker == -1 &&
            returned_timeout.timeout_frames == 0x78U &&
            returned_world.world_active == 0xFFFFU &&
            returned_world.cleanup_countdown == 0x78 &&
            returned_world.target_selection_requested &&
            target_service_after > target_service_before &&
            returned_runner.inventory_item_codes == inventory_before &&
            returned_runner.inventory_phase_bytes == inventory_phase_before &&
            returned_map == collision_map_before &&
            field_scene.field_activity_selection_for_dump() == 2U &&
            field_audio_events.size() == audio_before &&
            field_hud_chrome_survives(returned_scene20, asset_root) &&
            count_playfield_lit(returned_scene20) >= 100U &&
            returned_scene20 == returned_field_only;
        if (!alert_return_correct ||
            !returned_scene20.save(QString::fromStdWString(
                (output / "scene20-after-electronics-alert.bmp").wstring())) ||
            !returned_field_only.save(QString::fromStdWString(
                (output / "scene20-field-only-after-electronics-alert.bmp")
                    .wstring())) ||
            !save("scene20-return-after-electronics-alert")) {
            std::cerr << "Scene-20 Electronics alert QA: A did not clear "
                         "the full-screen result while preserving the live "
                         "timeout state (closed="
                      << !field_scene.field_interaction_open()
                      << ", world-active=" << returned_world.world_active
                      << ", timeout=" << returned_timeout.timeout_frames
                      << ", target-service=" << target_service_before << "->"
                      << target_service_after << ", clean-frame="
                      << (returned_scene20 == returned_field_only) << ")\n";
            return 3;
        }
        write_state("scene20-return-after-electronics-alert");
        write_alert_state("first-field-frame-after-acknowledgement");
    } else if (path ==
               Scene20PhysicalEntryQaPath::electronics_trials) {
        constexpr std::uint8_t electronics_kit_code = 0x15U;
        constexpr std::uint8_t maglock_passkey_code = 0x14U;
        const auto& party = field_scene.field_party_records_for_dump();
        bool active_party_member_found = false;
        bool active_party_has_kit = false;
        bool active_party_has_passkey = false;
        std::uint8_t best_electronics_skill = 0U;
        for (std::size_t slot = 0U; slot < party.size(); ++slot) {
            const auto& runner = party[slot];
            if (!field_scene.field_party_slot_active_for_dump(slot) ||
                (runner.flags & 0x0100U) == 0U) {
                continue;
            }
            active_party_member_found = true;
            best_electronics_skill = std::max(
                best_electronics_skill, runner.skills[9]);
            active_party_has_kit = active_party_has_kit ||
                std::find(runner.inventory_item_codes.begin(),
                          runner.inventory_item_codes.end(),
                          electronics_kit_code) !=
                    runner.inventory_item_codes.end();
            active_party_has_passkey = active_party_has_passkey ||
                std::find(runner.inventory_item_codes.begin(),
                          runner.inventory_item_codes.end(),
                          maglock_passkey_code) !=
                    runner.inventory_item_codes.end();
        }
        const auto& decker = field_scene.active_runner_record();
        if (!active_party_member_found || decker.archetype_index != 3U ||
            decker.skills[9] != 1U || best_electronics_skill != 1U ||
            active_party_has_kit || active_party_has_passkey ||
            field_scene.field_activity_selection_for_dump() != 2U) {
            std::cerr << "Scene-20 Electronics trials QA: expected the "
                         "ordinary Decker class-3 record with skill 1, no "
                         "Electronics Kit/passkey, and selection 2 (class="
                      << static_cast<unsigned>(decker.archetype_index)
                      << ", skill="
                      << static_cast<unsigned>(decker.skills[9])
                      << ", best="
                      << static_cast<unsigned>(best_electronics_skill)
                      << ", kit=" << active_party_has_kit
                      << ", passkey=" << active_party_has_passkey
                      << ", selection=" << static_cast<unsigned>(
                             field_scene.field_activity_selection_for_dump())
                      << ")\n";
            return 3;
        }

        const auto count_audio = [&field_audio_events](
                                     const std::uint16_t event) {
            return static_cast<std::size_t>(std::count(
                field_audio_events.begin(), field_audio_events.end(), event));
        };
        const auto& live_decker = field_scene.active_runner_record();
        auto expected_inventory = live_decker.inventory_item_codes;
        auto expected_inventory_phase = live_decker.inventory_phase_bytes;

        const auto run_trial = [&](const std::string_view stage,
                                   const bool unlocks,
                                   const std::uint8_t selection_before,
                                   const std::uint16_t random_seed) {
            const auto map_before = field_scene.state()
                .field_scene_buffers.source_metadata.terrain_collision_map;
            const auto sound_4b_before = count_audio(0x4BU);
            const auto sound_30_before = count_audio(0x30U);

            // ROM 0x0D44/0x0D3A/0x0DBA: seed 6 yields one no-kit face 5,
            // meeting target 5; seed 4 yields kit faces 4, 2, 4, so two of
            // three trials meet target 3. Pin only action boundaries.
            field_scene.set_source_random_seed_for_dump(random_seed);
            field_scene.set_controller_port_byte(0x40U); // ordinary A
            field_scene.advance_frame();
            ++frame;
            const auto action_event =
                field_scene.controller_event_word_for_dump();
            field_scene.set_controller_port_byte(0U);
            field_scene.advance_frame();
            ++frame;

            const auto& result_panel = field_scene.field_interaction_panel();
            const auto result_image = render();
            const auto trial_map = field_scene.state()
                .field_scene_buffers.source_metadata.terrain_collision_map;
            const auto& trial_runner = field_scene.active_runner_record();
            const auto expected_selection = unlocks
                ? static_cast<std::uint8_t>(0xFFU)
                : static_cast<std::uint8_t>(selection_before - 1U);
            const auto expected_text = unlocks
                ? std::string_view("quick work of the lock")
                : std::string_view("This attempt at the lock eludes you");
            // ROM 0x2BD2 applies a negative lock result to the sampled map
            // counter only after the generic result page returns to field.
            const bool map_state_correct = trial_map == map_before;
            const bool action_sound_correct =
                count_audio(0x4BU) == sound_4b_before +
                    (unlocks ? 1U : 0U) &&
                count_audio(0x30U) == sound_30_before;
            const bool result_state_correct =
                (action_event & 0xFF00U) == 0x4000U &&
                field_scene.field_interaction_open() && result_panel.open &&
                result_panel.source_complete &&
                result_panel.kind == DialoguePanelKind::information_page &&
                result_panel.actor_kind == DialoguePanelActorKind::none &&
                result_panel.option_count == 0U &&
                result_panel.text_segment_count == 1U &&
                result_panel.text_segments[0].find(expected_text) !=
                    std::string_view::npos &&
                field_scene.field_activity_selection_for_dump() ==
                    expected_selection &&
                trial_runner.inventory_item_codes == expected_inventory &&
                trial_runner.inventory_phase_bytes ==
                    expected_inventory_phase &&
                trial_runner.skills[9] == 1U && map_state_correct &&
                action_sound_correct &&
                !field_hud_chrome_survives(result_image, asset_root) &&
                result_image.size() == QSize(kSceneWidth, kSceneHeight);
            const auto result_stage = std::string(stage) + "-result";
            if (!result_state_correct || !save(result_stage) ||
                (unlocks && !save("actual"))) {
                std::cerr << "Scene-20 Electronics trials QA: ROM trial "
                             "did not produce the expected "
                          << (unlocks ? "unlock" : "partial-progress")
                          << " page (selection="
                          << static_cast<unsigned>(
                                 field_scene.field_activity_selection_for_dump())
                          << ", text='"
                          << (result_panel.text_segment_count == 0U
                                  ? std::string_view{}
                                  : result_panel.text_segments[0])
                          << "', map=" << map_state_correct
                          << " (cell483="
                          << (map_before.size() > 483U
                                  ? static_cast<unsigned>(map_before[483U])
                                  : 999U)
                          << "->"
                          << (trial_map.size() > 483U
                                  ? static_cast<unsigned>(trial_map[483U])
                                  : 999U)
                          << ", sizes=" << map_before.size() << '/'
                          << trial_map.size() << ')'
                          << ", 0x4B=" << sound_4b_before << "->"
                          << count_audio(0x4BU) << ")\n";
                return false;
            }
            write_state(result_stage);

            const auto wait_one = std::string(stage) + "-wait-1";
            if (!save(wait_one)) {
                return false;
            }
            for (std::uint8_t tick = 1U; tick < 30U; ++tick) {
                field_scene.advance_frame();
                ++frame;
                if (tick == 14U || tick == 29U) {
                    const auto wait_name = std::string(stage) + "-wait-" +
                        std::to_string(static_cast<unsigned>(tick + 1U));
                    if (!save(wait_name)) {
                        return false;
                    }
                }
            }
            const auto held_result_image = render();
            const auto& held_map = field_scene.state()
                .field_scene_buffers.source_metadata.terrain_collision_map;
            const auto& held_runner = field_scene.active_runner_record();
            if (held_result_image != result_image || held_map != trial_map ||
                held_runner.inventory_item_codes != expected_inventory ||
                held_runner.inventory_phase_bytes !=
                    expected_inventory_phase ||
                held_runner.skills[9] != 1U ||
                field_scene.field_activity_selection_for_dump() !=
                    expected_selection ||
                count_audio(0x4BU) != sound_4b_before +
                    (unlocks ? 1U : 0U) ||
                count_audio(0x30U) != sound_30_before ||
                !save(std::string(stage) + "-held")) {
                std::cerr << "Scene-20 Electronics trials QA: the generic "
                             "trial result changed or mutated state during "
                             "its 30-frame hold\n";
                return false;
            }
            write_state(std::string(stage) + "-held");

            field_scene.set_controller_port_byte(0x40U); // ordinary A
            field_scene.advance_frame();
            ++frame;
            const auto acknowledgement_event =
                field_scene.controller_event_word_for_dump();
            field_scene.set_controller_port_byte(0U);
            field_scene.advance_frame();
            ++frame;
            if (!finish_field_modal_return_transition(field_scene)) {
                std::cerr << "Scene-20 Electronics trials QA: field return fade did not complete\n";
                return false;
            }
            const auto returned_scene20 = render();
            const auto returned_field_only = render_field_scene_only();
            const auto& return_runner = field_scene.active_runner_record();
            const auto& return_map = field_scene.state()
                .field_scene_buffers.source_metadata.terrain_collision_map;
            bool return_map_state_correct = return_map == trial_map;
            if (unlocks) {
                return_map_state_correct = trial_map.size() > 483U &&
                    return_map.size() == trial_map.size() &&
                    trial_map[483U] == 0x82U && return_map[483U] == 0x81U;
                for (std::size_t cell = 0U;
                     return_map_state_correct && cell < trial_map.size();
                     ++cell) {
                    if (cell != 483U && return_map[cell] != trial_map[cell]) {
                        return_map_state_correct = false;
                    }
                }
            }
            const bool returned_cleanly =
                controller_event_contains_a(acknowledgement_event) &&
                !field_scene.field_interaction_open() &&
                !field_scene.dialogue_open() &&
                !field_scene.field_mode_text_open_for_dump() &&
                !field_scene.shop_menu_open() &&
                field_scene.field_scene_reference_for_dump() == 0x14U &&
                field_hud_chrome_survives(returned_scene20, asset_root) &&
                count_playfield_lit(returned_scene20) >= 100U &&
                returned_scene20 == returned_field_only &&
                return_runner.inventory_item_codes == expected_inventory &&
                return_runner.inventory_phase_bytes ==
                    expected_inventory_phase &&
                return_runner.skills[9] == 1U &&
                return_map_state_correct &&
                field_scene.field_activity_selection_for_dump() ==
                    expected_selection &&
                count_audio(0x4BU) == sound_4b_before +
                    (unlocks ? 1U : 0U) &&
                count_audio(0x30U) == sound_30_before;
            const auto return_stage = std::string(stage) + "-return";
            const auto return_full_name = return_stage + ".bmp";
            const auto return_field_name = return_stage + "-field-only.bmp";
            write_state(return_stage);
            if (!returned_cleanly ||
                !returned_scene20.save(QString::fromStdWString(
                    (output / return_full_name).wstring())) ||
                !returned_field_only.save(QString::fromStdWString(
                    (output / return_field_name).wstring())) ||
                !save(return_stage)) {
                std::cerr << "Scene-20 Electronics trials QA: A did not "
                             "restore a clean full-screen field after "
                             "the " << (unlocks ? "unlock" : "partial")
                          << " result (ack="
                          << controller_event_contains_a(acknowledgement_event)
                          << ", interaction=" << field_scene.field_interaction_open()
                          << ", scene=" << field_scene.field_scene_reference_for_dump()
                          << ", hud=" << field_hud_chrome_survives(
                                 returned_scene20, asset_root)
                          << ", lit=" << count_playfield_lit(returned_scene20)
                          << ", clean-pixels="
                          << (returned_scene20 == returned_field_only)
                          << ", map=" << return_map_state_correct
                          << ", selection=" << static_cast<unsigned>(
                                 field_scene.field_activity_selection_for_dump())
                          << ", inventory="
                          << (return_runner.inventory_item_codes ==
                              expected_inventory)
                          << ", audio4b=" << count_audio(0x4BU)
                          << ", audio30=" << count_audio(0x30U)
                          << ", cell483="
                          << (trial_map.size() > 483U
                                  ? static_cast<unsigned>(trial_map[483U])
                                  : 999U)
                          << "->"
                          << (return_map.size() > 483U
                                  ? static_cast<unsigned>(return_map[483U])
                                  : 999U) << ")\n";
                return false;
            }
            write_state(return_stage);
            return true;
        };

        if (!run_trial("electronics-no-kit-partial", false, 2U, 0x0006U)) {
            return 3;
        }

        // The field collision dispatcher restores FFE16E from the event code
        // on a fresh contact (ROM 0xB994); partial progress is only the current
        // interaction's value. Seed the kit in the live QA runner record so
        // the second physical action exercises the source's kit success path.
        auto& decker_with_kit = field_scene.active_runner_record();
        std::optional<std::size_t> electronics_kit_slot;
        for (std::size_t slot = 0U;
             slot < decker_with_kit.inventory_item_codes.size(); ++slot) {
            if (decker_with_kit.inventory_item_codes[slot] == 0U) {
                electronics_kit_slot = slot;
                break;
            }
        }
        if (!electronics_kit_slot.has_value()) {
            std::cerr << "Scene-20 Electronics trials QA: Decker inventory "
                         "has no slot for the QA Electronics Kit\n";
            return 3;
        }
        decker_with_kit.inventory_item_codes[*electronics_kit_slot] =
            electronics_kit_code;
        decker_with_kit.inventory_phase_bytes[*electronics_kit_slot] = 0U;
        expected_inventory = decker_with_kit.inventory_item_codes;
        expected_inventory_phase = decker_with_kit.inventory_phase_bytes;

        // The partial result returns Joshua to the contact edge. Holding Up
        // there does not create a new ROM collision: the Lua movement policy
        // routes along the lock face (the old QA stopped at x=0x46A,y=0x107).
        // First clear the source contact envelope, then use ordinary
        // Up+Right input to return to the documented approach lane so B7B8
        // receives a fresh blocked probe from the south.
        const auto partial_return_position = world_position();
        std::uint16_t retry_backoff_ticks = 0U;
        for (; retry_backoff_ticks < 120U &&
               world_position().second <= 0x0107U &&
               !field_scene.field_interaction_open(); ++retry_backoff_ticks) {
            field_scene.set_controller_nibble(0x02U); // ordinary Down
            field_scene.advance_frame();
            ++frame;
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto retry_backoff_position = world_position();
        if (field_scene.field_interaction_open() ||
            field_scene.field_scene_reference_for_dump() != 0x14U ||
            retry_backoff_position.second <= 0x0107U ||
            retry_backoff_position.second <= partial_return_position.second ||
            !save("electronics-retry-backoff")) {
            std::cerr << "Scene-20 Electronics trials QA: ordinary Down did "
                         "not clear the maglock contact before retry "
                         "(ticks=" << retry_backoff_ticks << ", position="
                      << retry_backoff_position.first << ','
                      << retry_backoff_position.second << ")\n";
            return 3;
        }
        write_state("electronics-retry-backoff");

        std::uint16_t retry_lane_ticks = 0U;
        for (; retry_lane_ticks < 120U &&
               world_position().first < 0x047CU &&
               !field_scene.field_interaction_open(); ++retry_lane_ticks) {
            field_scene.set_controller_nibble(0x09U); // ordinary Up + Right
            field_scene.advance_frame();
            ++frame;
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto retry_lane_position = world_position();
        if (field_scene.field_scene_reference_for_dump() != 0x14U ||
            (!field_scene.field_interaction_open() &&
             retry_lane_position.first < 0x047CU) ||
            !save("electronics-retry-approach-lane")) {
            std::cerr << "Scene-20 Electronics trials QA: ordinary Up+Right "
                         "did not return to the clear maglock approach lane "
                         "(ticks=" << retry_lane_ticks << ", position="
                      << retry_lane_position.first << ','
                      << retry_lane_position.second << ")\n";
            return 3;
        }
        write_state("electronics-retry-approach-lane");

        std::uint16_t retry_south_edge_ticks = 0U;
        for (; retry_south_edge_ticks < 16U &&
               world_position().second < 0x010CU &&
               !field_scene.field_interaction_open();
             ++retry_south_edge_ticks) {
            field_scene.set_controller_nibble(0x06U); // ordinary Down + Left
            field_scene.advance_frame();
            ++frame;
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto retry_south_edge_position = world_position();
        if (field_scene.field_scene_reference_for_dump() != 0x14U ||
            (!field_scene.field_interaction_open() &&
             (retry_south_edge_position.second < 0x010CU ||
              retry_south_edge_position.first < 0x0454U ||
              retry_south_edge_position.first > 0x0494U)) ||
            !save("electronics-retry-south-edge")) {
            std::cerr << "Scene-20 Electronics trials QA: ordinary Down+Left "
                         "did not reach the clear south edge of record 117 "
                         "(ticks=" << retry_south_edge_ticks << ", position="
                      << retry_south_edge_position.first << ','
                      << retry_south_edge_position.second << ")\n";
            return 3;
        }
        write_state("electronics-retry-south-edge");

        std::uint16_t retry_heading_alignment_ticks = 0U;
        for (; retry_heading_alignment_ticks < 16U &&
               world_position().first > 0x047CU &&
               world_position().second >= 0x010CU &&
               !field_scene.field_interaction_open();
             ++retry_heading_alignment_ticks) {
            field_scene.set_controller_nibble(0x04U); // ordinary Left
            field_scene.advance_frame();
            ++frame;
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto retry_approach_position = world_position();
        if (field_scene.field_scene_reference_for_dump() != 0x14U ||
            (!field_scene.field_interaction_open() &&
             (retry_approach_position.first > 0x047CU ||
              retry_approach_position.second < 0x010CU)) ||
            !save("electronics-retry-northbound-approach")) {
            std::cerr << "Scene-20 Electronics trials QA: ordinary Left did "
                         "not align with the source maglock approach lane "
                         "(ticks=" << retry_heading_alignment_ticks
                      << ", position=" << retry_approach_position.first
                      << ',' << retry_approach_position.second << ")\n";
            return 3;
        }
        write_state("electronics-retry-northbound-approach");

        std::uint16_t retry_contact_ticks = 0U;
        for (; retry_contact_ticks < 120U &&
               !field_scene.field_interaction_open(); ++retry_contact_ticks) {
            field_scene.set_controller_nibble(0x01U); // ordinary Up
            field_scene.advance_frame();
            ++frame;
        }
        field_scene.set_controller_nibble(0U);
        field_scene.advance_frame();
        ++frame;
        const auto retry_position = world_position();
        const auto retry_projected_code =
            field_scene.field_projected_code_for_dump();
        const auto retry_activity_selection =
            field_scene.field_activity_selection_for_dump();
        const auto& retry_intro_panel = field_scene.field_interaction_panel();
        const auto retry_intro_image = render();
        if (!field_scene.field_interaction_open() ||
            field_scene.field_scene_reference_for_dump() != 0x14U ||
            retry_projected_code != 0xFF82U ||
            retry_activity_selection != 2U ||
            retry_intro_panel.actor_kind != DialoguePanelActorKind::none ||
            field_hud_chrome_survives(retry_intro_image, asset_root) ||
            !save("electronics-retry-introduction")) {
            std::cerr << "Scene-20 Electronics trials QA: after a clear "
                         "south-corridor retreat, ordinary Up did not "
                         "reopen the physical lock with collision selection "
                         "2 (backoff=" << retry_backoff_ticks << ", ticks="
                      << retry_contact_ticks
                      << ", position=" << retry_position.first << ','
                      << retry_position.second << ", projected=0x"
                      << std::hex << retry_projected_code << std::dec
                      << ", selection=" << static_cast<unsigned>(
                             retry_activity_selection) << ")\n";
            return 3;
        }
        write_state("electronics-retry-introduction");
        for (std::uint8_t tick = 0U; tick < 10U; ++tick) {
            field_scene.advance_frame();
            ++frame;
        }
        field_scene.set_controller_port_byte(0x40U); // ordinary A: <MORE>
        field_scene.advance_frame();
        ++frame;
        const auto retry_more_event =
            field_scene.controller_event_word_for_dump();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        for (std::uint8_t tick = 0U; tick < 8U; ++tick) {
            field_scene.advance_frame();
            ++frame;
        }
        const auto& retry_choices = field_scene.field_interaction_panel();
        const auto retry_choices_image = render();
        if ((retry_more_event & 0xFF00U) != 0x4000U ||
            !field_scene.field_interaction_open() ||
            retry_activity_selection != 2U ||
            retry_choices.option_count != 3U ||
            retry_choices.options[0].source_label.find("Electronics") ==
                std::string_view::npos ||
            retry_choices.options[2].source_label.find("Walk") ==
                std::string_view::npos ||
            field_hud_chrome_survives(retry_choices_image, asset_root) ||
            !save("electronics-retry-choices-after-8-frames")) {
            std::cerr << "Scene-20 Electronics trials QA: retry prompt did "
                         "not retain the source Electronics/Frag/Walk rows\n";
            return 3;
        }
        write_state("electronics-retry-choices");
        if (!run_trial("electronics-kit-success", true, 2U, 0x0004U)) {
            return 3;
        }
    } else if (path == Scene20PhysicalEntryQaPath::grenade_unavailable) {
        constexpr std::uint8_t frag_grenade_code = 0x0DU;
        const auto& party = field_scene.field_party_records_for_dump();
        bool active_party_has_grenade = false;
        for (std::size_t slot = 0U; slot < party.size(); ++slot) {
            const auto& runner = party[slot];
            if (!field_scene.field_party_slot_active_for_dump(slot) ||
                (runner.flags & 0x0100U) == 0U) {
                continue;
            }
            active_party_has_grenade = active_party_has_grenade ||
                std::find(runner.inventory_item_codes.begin(),
                          runner.inventory_item_codes.end(),
                          frag_grenade_code) !=
                    runner.inventory_item_codes.end();
        }
        if (active_party_has_grenade) {
            std::cerr << "Scene-20 grenade QA: New Game party unexpectedly "
                         "contains a Frag Grenade\n";
            return 3;
        }

        const auto audio_count_before_action = field_audio_events.size();
        field_scene.set_controller_port_byte(0x10U); // ordinary B: Frag Grenade
        field_scene.advance_frame();
        ++frame;
        const auto grenade_choice_event =
            field_scene.controller_event_word_for_dump();
        const bool grenade_choice_was_a_new_b_press =
            (grenade_choice_event & 0xFF00U) == 0x1000U;
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        const auto& unavailable_panel = field_scene.field_interaction_panel();
        const auto unavailable_image = render();
        const bool unavailable_text_matches =
            unavailable_panel.text_segment_count == 1U &&
            unavailable_panel.text_segments[0].find("Frag Grenade") !=
                std::string_view::npos &&
            unavailable_panel.text_segments[0].find("available to you") !=
                std::string_view::npos;
        const bool result_page_open = field_scene.field_interaction_open();
        const bool generic_result_page =
            unavailable_panel.kind == DialoguePanelKind::information_page &&
            unavailable_panel.actor_kind == DialoguePanelActorKind::none;
        const bool result_hud_hidden =
            !field_hud_chrome_survives(unavailable_image, asset_root);
        const bool result_audio_silent =
            field_audio_events.size() == audio_count_before_action;
        if (!grenade_choice_was_a_new_b_press || !result_page_open ||
            !generic_result_page ||
            !unavailable_panel.source_complete ||
            unavailable_panel.option_count != 0U ||
            !unavailable_text_matches || !result_hud_hidden ||
            unavailable_image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !result_audio_silent ||
            !save("maglock-grenade-unavailable") || !save("actual")) {
            std::cerr << "Scene-20 grenade QA: ordinary B did not show the "
                         "source no-item result as a generic information "
                         "page without an extra sound (open="
                      << result_page_open << ", kind="
                      << static_cast<unsigned>(unavailable_panel.kind)
                      << ", actor=" << static_cast<unsigned>(
                             unavailable_panel.actor_kind)
                      << ", complete=" << unavailable_panel.source_complete
                      << ", options=" << unavailable_panel.option_count
                      << ", segments="
                      << unavailable_panel.text_segment_count << ", text='"
                      << (unavailable_panel.text_segment_count == 0U
                              ? std::string_view{}
                              : unavailable_panel.text_segments[0])
                      << "', hud-hidden=" << result_hud_hidden
                      << ", sampled-event=0x" << std::hex
                      << grenade_choice_event << std::dec
                      << ", size=" << unavailable_image.width() << 'x'
                      << unavailable_image.height() << ", audio="
                      << audio_count_before_action << "->"
                      << field_audio_events.size() << ")\n";
            return 3;
        }
        write_state("maglock-grenade-unavailable");
        if (!save("maglock-grenade-result-wait-1")) {
            return 3;
        }
        for (std::uint8_t tick = 1U; tick < 30U; ++tick) {
            field_scene.advance_frame();
            ++frame;
            if (tick == 14U || tick == 29U) {
                if (!save("maglock-grenade-result-wait-" +
                          std::to_string(static_cast<unsigned>(tick + 1U)))) {
                    return 3;
                }
            }
        }
        const auto held_unavailable_image = render();
        if (held_unavailable_image != unavailable_image ||
            field_audio_events.size() != audio_count_before_action ||
            !save("maglock-grenade-result-held")) {
            std::cerr << "Scene-20 grenade QA: source result changed during "
                         "its 30-frame wait\n";
            return 3;
        }
        write_state("maglock-grenade-result-held");

        field_scene.set_controller_port_byte(0x40U); // ordinary A dismisses
        field_scene.advance_frame();
        ++frame;
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (!finish_field_modal_return_transition(field_scene)) {
            std::cerr << "Scene-20 grenade QA: field return fade did not complete\n";
            return 3;
        }
        const auto returned_scene20 = render();
        const auto returned_field_only = render_field_scene_only();
        const bool returned_cleanly =
            !field_scene.field_interaction_open() &&
            !field_scene.dialogue_open() &&
            !field_scene.field_mode_text_open_for_dump() &&
            !field_scene.shop_menu_open() &&
            field_scene.field_scene_reference_for_dump() == 0x14U &&
            field_hud_chrome_survives(returned_scene20, asset_root) &&
            count_playfield_lit(returned_scene20) >= 100U &&
            returned_scene20 == returned_field_only &&
            field_audio_events.size() == audio_count_before_action;
        write_state("scene20-return-after-grenade-unavailable");
        if (!returned_cleanly ||
            !returned_scene20.save(QString::fromStdWString(
                (output / "scene20-after-grenade-unavailable.bmp").wstring())) ||
            !returned_field_only.save(QString::fromStdWString(
                (output / "scene20-field-only-after-grenade-unavailable.bmp")
                    .wstring())) ||
            !save("scene20-return-after-grenade-unavailable")) {
            std::cerr << "Scene-20 grenade QA: A did not dismiss the result "
                         "to the clean current field image\n";
            return 3;
        }
    } else {
        field_scene.set_controller_port_byte(0x20U); // ordinary C: Walk Away
        field_scene.advance_frame();
        ++frame;
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        ++frame;
        if (!finish_field_modal_return_transition(field_scene)) {
            std::cerr << "Scene-20 walk-away QA: field return fade did not complete\n";
            return 3;
        }
        const auto returned_scene20 = render();
        const auto returned_field_only = render_field_scene_only();
        const auto& walk_away_panel = field_scene.field_interaction_panel();
        const bool walk_away_closed = !field_scene.field_interaction_open();
        const bool walk_away_same_scene =
            field_scene.field_scene_reference_for_dump() == 0x14U;
        const bool walk_away_hud_clean =
            field_hud_chrome_survives(returned_scene20, asset_root);
        const bool walk_away_playfield_visible =
            count_playfield_lit(returned_scene20) >= 100U;
        const bool walk_away_matches_field_only =
            returned_scene20 == returned_field_only;
        const auto& active_runner = field_scene.active_runner_record();
        const bool insufficient_passkey_remains_unchanged =
            path != Scene20PhysicalEntryQaPath::passkey_insufficient ||
            (seeded_passkey_slot.has_value() &&
             active_runner.inventory_item_codes[*seeded_passkey_slot] ==
                 kPasskeyItemCode &&
             active_runner.inventory_phase_bytes[*seeded_passkey_slot] ==
                 seeded_passkey_quality);
        const auto& collision_map_after_walk_away = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_map;
        const bool insufficient_passkey_left_world_unchanged =
            path != Scene20PhysicalEntryQaPath::passkey_insufficient ||
            (collision_map_after_walk_away ==
                 insufficient_passkey_collision_map_before &&
             field_audio_events.size() == insufficient_passkey_audio_count);
        write_state("after-walk-away-input");
        if (!returned_scene20.save(QString::fromStdWString(
                (output / "scene20-after-walk-away-input.bmp").wstring())) ||
            !returned_field_only.save(QString::fromStdWString(
                (output / "scene20-field-only-after-walk-away.bmp")
                    .wstring()))) {
            std::cerr << "Scene-20 physical-entry QA: could not save "
                         "post-choice full-screen frame\n";
            return 3;
        }
        if (!walk_away_closed || !walk_away_same_scene ||
            !walk_away_hud_clean || !walk_away_playfield_visible ||
            !walk_away_matches_field_only ||
            !insufficient_passkey_remains_unchanged ||
            !insufficient_passkey_left_world_unchanged ||
            !save("scene20-return-after-walk-away")) {
            std::cerr << "Scene-20 physical-entry QA: normal exit input did "
                         "not close the maglock page and restore a clean "
                         "interior screen (open=" << !walk_away_closed << ", scene="
                      << field_scene.field_scene_reference_for_dump()
                      << ", selected=" << walk_away_panel.selected_option
                      << ", hud=" << walk_away_hud_clean
                      << ", playfield=" << walk_away_playfield_visible
                      << ", field-only-pixels="
                      << walk_away_matches_field_only << ")\n";
            return 3;
        }
        write_state("scene20-return-after-walk-away");
    }

    {
        std::ofstream boundaries(output / "source-boundaries.txt",
                                 std::ios::trunc);
        if (!boundaries) {
            std::cerr << "Scene-20 physical-entry QA: could not write "
                         "source boundaries\n";
            return 3;
        }
        for (const auto& boundary : source_boundaries) {
            boundaries << boundary << '\n';
        }
    }
    {
        std::ofstream events(output / "audio-events.txt", std::ios::trunc);
        if (!events) {
            std::cerr << "Scene-20 physical-entry QA: could not write audio "
                         "events\n";
            return 3;
        }
        for (const auto event : field_audio_events) {
            events << "0x" << std::hex << event << '\n';
        }
    }
    std::cout << "field_scene20_physical_entry_qa=passed records=89,90 rom=0x"
              << std::hex << doorway_rom_address << " destination=0x14"
              << std::dec << " route_frames=" << frame
              << " north_ticks=" << north_ticks << " raw=0xFFC0 event=0"
              << " entry-x=" << scene20_position.x
              << " entry-y=" << scene20_position.y
              << " audio_events=" << field_audio_events.size()
              << " choice=" << (path ==
                                        Scene20PhysicalEntryQaPath::grenade_unavailable
                                    ? "frag-grenade-unavailable"
                                    : path == Scene20PhysicalEntryQaPath::
                                                 passkey_insufficient
                                          ? "insufficient-passkey-walk-away"
                                          : path == Scene20PhysicalEntryQaPath::
                                                       electronics_no_skill
                                                ? "electronics-no-skill"
                                          : path == Scene20PhysicalEntryQaPath::
                                                       electronics_alert
                                                ? "electronics-alert"
                                          : path == Scene20PhysicalEntryQaPath::
                                                       electronics_trials
                                                ? "electronics-trials"
                                          : path == Scene20PhysicalEntryQaPath::
                                                       passkey_success
                                                ? "passkey-success"
                                                : "walk-away")
              << " artifacts=" << output.string() << '\n';
    return 0;
}

int run_field_scene26_event1_physical_entry_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    // The real runtime seeds from its own startup entropy. Pin the source PRNG
    // only for this screenshot route so Debug and Release capture the same
    // resource variant.
    field_scene.set_source_random_seed_for_dump(0U);
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Scene-26 event-1 entry QA: could not clear prior output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        std::cerr << "Scene-26 event-1 entry QA: could not create output: "
                  << output_error.message() << '\n';
        return 3;
    }

    constexpr std::size_t kEntryRecord = 93U;
    constexpr std::uint32_t kEntryRecordAddress = 0x17314CU;
    constexpr std::uint8_t kEntryCollision = 0xC1U;
    constexpr std::uint8_t kEntryEventIndex = 1U;
    constexpr auto kEntryEventCode = FieldCollisionEventCode::event_1;
    constexpr std::uint8_t kDestinationScene = 0x1AU;
    const auto& entry_metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& entry_records = entry_metadata.terrain_collision_rectangles;
    const auto initial_position = field_scene.field_entity_world_position();
    const bool source_entry_matches =
        entry_records.size() > kEntryRecord &&
        entry_records[kEntryRecord].left == 0x06E0U &&
        entry_records[kEntryRecord].right == 0x06FFU &&
        entry_records[kEntryRecord].top == 0x0220U &&
        entry_records[kEntryRecord].bottom == 0x023FU &&
        entry_records[kEntryRecord].value == kEntryCollision &&
        entry_metadata.event_table_available &&
        entry_metadata.event_mode_table[kEntryEventIndex] == kDestinationScene &&
        field_scene.field_scene_reference_for_dump() == 2U &&
        initial_position.x == 0x3CE0U && initial_position.y == 0x2D00U;
    if (!source_entry_matches) {
        std::cerr << "Scene-26 event-1 entry QA: New Game source position, "
                     "scene-2 collision record 93, or event-table row 1 "
                     "does not match (scene="
                  << field_scene.field_scene_reference_for_dump()
                  << ", position=" << initial_position.x << ','
                  << initial_position.y << ", records="
                  << entry_records.size() << ")\n";
        return 3;
    }

    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save = [&render, &output](const std::string_view name) {
        const auto image = render();
        const auto path = output / (std::string(name) + ".bmp");
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            std::cerr << "Scene-26 event-1 entry QA: could not save full "
                         "screen " << name << '\n';
            return false;
        }
        return true;
    };
    std::ofstream trace(output / "route.tsv", std::ios::trunc);
    if (!trace) {
        std::cerr << "Scene-26 event-1 entry QA: could not create route.tsv\n";
        return 3;
    }
    trace << "stage\tframe\tscene\tx\ty\tcollision\tmode_event"
             "\ttransition_event\tnegative_probe_count\ttransition_kind"
             "\tactivity_scene\tactivity_mode\tresource_bound"
             "\tresource_index\tinteraction\tdialogue\tshop"
             "\tentity_visible\tscreen_x\tscreen_y\tcamera_x"
             "\tcamera_y\taudio_events\n";
    std::uint32_t frame = 0U;
    const auto write_state = [&] (const std::string_view stage) {
        const auto position = field_scene.field_entity_world_position();
        const auto& transition =
            field_scene.last_field_movement_transition_for_dump();
        const auto& activity = field_scene.world_activity_state_for_dump();
        trace << stage << '\t' << frame << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << position.x << '\t' << position.y << '\t'
              << field_scene.field_terrain_collision_code_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump()) << '\t'
              << static_cast<unsigned>(transition.event_code) << '\t'
              << static_cast<unsigned>(transition.negative_probe_count) << '\t'
              << static_cast<unsigned>(transition.kind) << '\t'
              << activity.scene_id << '\t'
              << static_cast<unsigned>(activity.mode) << '\t'
              << activity.resource_random_index_bound << '\t'
              << activity.selected_resource_random_index << '\t'
              << field_scene.field_interaction_open() << '\t'
              << field_scene.dialogue_open() << '\t'
              << field_scene.shop_menu_open() << '\t'
              << field_scene.field_entity_visible_for_dump() << '\t'
              << field_scene.field_entity_screen_x_for_dump() << '\t'
              << field_scene.field_entity_screen_y_for_dump() << '\t'
              << field_scene.state().field_scene_buffers.camera_x << '\t'
              << field_scene.state().field_scene_buffers.camera_y << '\t'
              << field_audio_events.size() << '\n';
        trace.flush();
    };
    const auto world_position = [&field_scene] {
        const auto position = field_scene.field_entity_world_position();
        return std::pair<std::uint16_t, std::uint16_t>{
            static_cast<std::uint16_t>(position.x >> 4U),
            static_cast<std::uint16_t>(position.y >> 4U)};
    };
    const auto field_is_live = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 2U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open() &&
               !field_scene.field_transition_pending_for_dump() &&
               !field_scene.field_interaction_transition_active_for_dump();
    };
    const auto step = [&](const std::uint8_t input) {
        field_scene.set_controller_nibble(input);
        field_scene.advance_frame();
        ++frame;
    };

    if (!save("scene2-spawn")) {
        return 3;
    }
    write_state("scene2-spawn");

    // Source collision geometry leaves a clear eastbound lane from the New
    // Game spawn through x=0x650. The northeast approach then reaches the
    // open south lane below record 93 without crossing other entry records.
    std::uint16_t east_ticks = 0U;
    while (east_ticks < 1200U && field_is_live() &&
           world_position().first < 0x0650U) {
        step(0x08U); // ordinary Right
        ++east_ticks;
        if (east_ticks == 128U || east_ticks == 256U ||
            east_ticks == 512U || east_ticks == 768U) {
            if (!save("east-" + std::to_string(east_ticks))) {
                return 3;
            }
        }
        write_state("east-lane");
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    const auto east_position = world_position();
    if (!field_is_live() || east_position.first < 0x0640U ||
        east_position.first > 0x0668U || east_position.second < 0x02B0U ||
        east_position.second > 0x02F0U || !save("east-lane-end")) {
        std::cerr << "Scene-26 event-1 entry QA: normal Right did not reach "
                     "the source eastbound lane (ticks=" << east_ticks
                  << ", position=" << east_position.first << ','
                  << east_position.second << ")\n";
        return 3;
    }
    write_state("east-lane-end");

    std::uint16_t northeast_ticks = 0U;
    while (northeast_ticks < 160U && field_is_live() &&
           world_position().second > 0x025CU) {
        step(0x09U); // ordinary Up + Right
        ++northeast_ticks;
        if (northeast_ticks == 32U || northeast_ticks == 64U) {
            if (!save("northeast-" + std::to_string(northeast_ticks))) {
                return 3;
            }
        }
        write_state("northeast-entry-approach");
    }
    field_scene.set_controller_nibble(0U);
    const auto south_doorway_position = world_position();
    if (!field_is_live() || south_doorway_position.second < 0x0248U ||
        south_doorway_position.second > 0x0260U ||
        !save("south-of-event-wall")) {
        std::cerr << "Scene-26 event-1 entry QA: normal diagonal approach "
                     "did not reach the south side of record 93 (ticks="
                  << northeast_ticks << ", position="
                  << south_doorway_position.first << ','
                  << south_doorway_position.second << ")\n";
        return 3;
    }
    write_state("south-of-event-wall");

    // Record 47 is a 0x7F wall spanning the event-1 doorway row. Record 93's
    // narrow C1 rectangle replaces only its doorway cell. Follow the open
    // southern lane east first, then approach north through that cell.
    std::uint16_t doorway_lane_ticks = 0U;
    while (doorway_lane_ticks < 120U && field_is_live() &&
           world_position().first < 0x06E2U) {
        step(0x08U); // ordinary Right along the south side of the wall
        ++doorway_lane_ticks;
        if (doorway_lane_ticks == 16U || doorway_lane_ticks == 32U) {
            if (!save("doorway-lane-" +
                      std::to_string(doorway_lane_ticks))) {
                return 3;
            }
        }
        write_state("south-doorway-lane");
    }
    field_scene.set_controller_nibble(0U);
    const auto doorway_lane_position = world_position();
    if (!field_is_live() || doorway_lane_position.first < 0x06E0U ||
        doorway_lane_position.first > 0x06F0U ||
        doorway_lane_position.second < 0x0248U ||
        doorway_lane_position.second > 0x0260U ||
        !save("event1-south-doorway-lane")) {
        std::cerr << "Scene-26 event-1 entry QA: source south doorway lane "
                     "was blocked (ticks=" << doorway_lane_ticks
                  << ", position=" << doorway_lane_position.first << ','
                  << doorway_lane_position.second << ")\n";
        return 3;
    }
    write_state("event1-south-doorway-lane");

    std::uint16_t north_ticks = 0U;
    while (north_ticks < 100U && field_is_live()) {
        step(0x01U); // ordinary Up through the C1 doorway cell
        ++north_ticks;
        const auto& transition =
            field_scene.last_field_movement_transition_for_dump();
        const bool entry_touched =
            (field_scene.field_terrain_collision_code_for_dump() & 0x001FU) ==
                field_collision_event_value(kEntryEventCode) ||
            (transition.event_code == kEntryEventCode &&
             transition.mode_event_code_published) ||
            field_scene.field_mode_event_code_for_dump() ==
                field_collision_event_value(kEntryEventCode);
        if (north_ticks == 16U || north_ticks == 32U) {
            if (!save("north-doorway-" + std::to_string(north_ticks))) {
                return 3;
            }
        }
        write_state("north-entry-approach");
        if (entry_touched) {
            break;
        }
    }
    field_scene.set_controller_nibble(0U);
    const auto& movement_transition =
        field_scene.last_field_movement_transition_for_dump();
    const bool published_event_one =
        movement_transition.event_code == kEntryEventCode &&
        movement_transition.mode_event_code_published &&
        movement_transition.negative_probe_count >= 2U &&
        field_scene.field_mode_event_code_for_dump() ==
            field_collision_event_value(kEntryEventCode);
    if (!published_event_one || !save("scene2-event1-contact")) {
        const auto position = world_position();
        std::cerr << "Scene-26 event-1 entry QA: normal Up did not publish "
                     "scene-2 record-93 event 1 (northeast_ticks="
                  << northeast_ticks << ", doorway_ticks="
                  << doorway_lane_ticks << ", north_ticks=" << north_ticks
                  << ", position=" << position.first
                  << ',' << position.second << ", collision=0x" << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << std::dec << ", event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ")\n";
        return 3;
    }
    write_state("scene2-event1-contact");

    const auto contact_frame = frame;
    for (const auto checkpoint :
         std::array<std::uint32_t, 3>{8U, 16U, 17U}) {
        const auto target_frame = contact_frame + checkpoint - 1U;
        while (frame < target_frame) {
            step(0U);
        }
        const auto name = std::string("fade-") +
                          (checkpoint < 10U ? "0" : "") +
                          std::to_string(checkpoint);
        if (!save(name)) {
            return 3;
        }
        write_state(name);
    }

    for (std::uint16_t settle = 0U;
         settle < 180U &&
         field_scene.field_scene_reference_for_dump() == 2U &&
         !field_scene.field_mode_text_open_for_dump();
         ++settle) {
        step(0U);
    }
    const auto& entry_panel =
        field_scene.field_mode_text_panel_for_dump();
    const bool little_chiba_entry_text =
        entry_panel.open &&
        entry_panel.portrait_alias ==
            "field.mode.entry.little.chiba.sprite" &&
        entry_panel.text_segment_count >= 3U &&
        entry_panel.text_segments[0].find("Little Chiba's Chop Shop") !=
            std::string_view::npos &&
        entry_panel.text_segments[2].find("install powerful cyberware") !=
            std::string_view::npos &&
        entry_panel.option_count == 0U;
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        !field_scene.field_mode_text_open_for_dump() ||
        !little_chiba_entry_text ||
        field_scene.field_mode_text_frames_remaining_for_dump() != 30U ||
        !save("little-chiba-entry")) {
        std::cerr << "Scene-26 event-1 entry QA: source-selected Little Chiba "
                     "mode text did not replace the whole field screen "
                     "before the destination route (scene="
                  << field_scene.field_scene_reference_for_dump()
                  << ", mode_text="
                  << field_scene.field_mode_text_open_for_dump()
                  << ", frames="
                  << field_scene.field_mode_text_frames_remaining_for_dump()
                  << ", portrait=" << entry_panel.portrait_alias << ")\n";
        for (std::size_t segment = 0U;
             segment < entry_panel.text_segment_count; ++segment) {
            std::cerr << "  text[" << segment << "]: "
                      << entry_panel.text_segments[segment] << '\n';
        }
        return 3;
    }
    write_state("little-chiba-entry");

    const auto mode_text_audio_count = field_audio_events.size();
    field_scene.set_controller_port_byte(0x40U); // early A is ignored
    field_scene.advance_frame();
    ++frame;
    field_scene.set_controller_port_byte(0U);
    for (std::uint8_t delay = 0U; delay < 29U; ++delay) {
        field_scene.advance_frame();
        ++frame;
    }
    if (!field_scene.field_mode_text_open_for_dump() ||
        field_scene.field_mode_text_frames_remaining_for_dump() != 0U ||
        field_audio_events.size() != mode_text_audio_count ||
        !save("little-chiba-entry-delay-30")) {
        std::cerr << "Scene-26 event-1 entry QA: early input dismissed the "
                     "30-frame source prompt or unexpected audio played\n";
        return 3;
    }
    field_scene.set_controller_port_byte(0x40U); // fresh A after delay
    field_scene.advance_frame();
    ++frame;
    field_scene.set_controller_port_byte(0U);
    for (std::uint16_t settle = 0U;
         settle < 180U &&
         (field_scene.field_scene_reference_for_dump() == 2U ||
          field_scene.field_transition_pending_for_dump() ||
          field_scene.field_interaction_transition_active_for_dump() ||
          field_scene.field_modal_return_transition_frames_for_dump() != 0U);
         ++settle) {
        field_scene.advance_frame();
        ++frame;
    }
    const auto& destination_metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& activity = field_scene.world_activity_state_for_dump();
    const auto& destination_position =
        field_scene.field_entity_world_position();
    const auto expected_destination_position =
        destination_metadata.initial_field_records[0U];
    const bool destination_loaded =
        field_scene.field_scene_reference_for_dump() == kDestinationScene &&
        activity.scene_id == kDestinationScene &&
        activity.mode == WorldActivityMode::resource_activity &&
        activity.resource_random_index_bound > 0U &&
        activity.selected_resource_random_index <
            activity.resource_random_index_bound &&
        field_scene.security_floor_index_for_dump() ==
            std::optional<std::uint8_t>{static_cast<std::uint8_t>(
                activity.selected_resource_random_index)} &&
        destination_metadata.terrain_collision_rectangles.size() == 133U &&
        !destination_metadata.event_table_available &&
        destination_position.x == expected_destination_position.x &&
        destination_position.y == expected_destination_position.y &&
        field_scene.field_entity_visible_for_dump() &&
        !field_scene.dialogue_open() && !field_scene.field_interaction_open() &&
        !field_scene.field_mode_text_open_for_dump() &&
        !field_scene.shop_menu_open() &&
        !field_scene.field_transition_pending_for_dump() &&
        !field_scene.field_interaction_transition_active_for_dump();
    const auto scene26_entry = render();
    if (!destination_loaded ||
        !field_hud_chrome_survives(scene26_entry, asset_root) ||
        count_playfield_lit(scene26_entry) < 100U ||
        !save("scene26-entry")) {
        std::cerr << "Scene-26 event-1 entry QA: event-table target, typed "
                     "resource selection, field spawn, or full screen did not "
                     "load (scene="
                  << field_scene.field_scene_reference_for_dump()
                  << ", activity_scene=" << activity.scene_id
                  << ", activity_mode="
                  << static_cast<unsigned>(activity.mode)
                  << ", resource_index="
                  << activity.selected_resource_random_index << '/'
                  << activity.resource_random_index_bound << ")\n";
        return 3;
    }
    write_state("scene26-entry");

    for (std::uint8_t idle = 0U; idle < 30U; ++idle) {
        step(0U);
        if (field_scene.field_scene_reference_for_dump() != kDestinationScene ||
            field_scene.dialogue_open() || field_scene.field_interaction_open() ||
            field_scene.shop_menu_open()) {
            std::cerr << "Scene-26 event-1 entry QA: destination scene or "
                         "screen owner changed during the 30-frame hold\n";
            return 3;
        }
        if (idle == 9U || idle == 29U) {
            const auto name = std::string("scene26-hold-") +
                              std::to_string(idle + 1U);
            if (!save(name)) {
                return 3;
            }
            write_state(name);
        }
    }
    if (!save("actual")) {
        return 3;
    }

    const auto entry_page_opened = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.mode_text.area_event_entry_opened");
    const auto resumed_route = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.mode_text.area_event_scene_entered");
    const auto scene_prepared = std::find(
        source_boundaries.begin(), source_boundaries.end(),
        "field.world_activity.scene_prepared");
    if (entry_page_opened == source_boundaries.end() ||
        resumed_route == source_boundaries.end() ||
        scene_prepared == source_boundaries.end()) {
        std::cerr << "Scene-26 event-1 entry QA: source entry page, resumed "
                     "area-table route, or destination preparation boundary "
                     "was not reached\n";
        return 3;
    }
    {
        std::ofstream boundaries(output / "source-boundaries.txt",
                                 std::ios::trunc);
        if (!boundaries) {
            std::cerr << "Scene-26 event-1 entry QA: could not write source "
                         "boundary trace\n";
            return 3;
        }
        std::vector<std::string> unique_boundaries;
        unique_boundaries.reserve(source_boundaries.size());
        for (const auto& boundary : source_boundaries) {
            if (std::find(unique_boundaries.begin(), unique_boundaries.end(),
                          boundary) == unique_boundaries.end()) {
                unique_boundaries.push_back(boundary);
                boundaries << boundary << '\n';
            }
        }
    }
    {
        std::ofstream events(output / "audio-events.txt", std::ios::trunc);
        if (!events) {
            std::cerr << "Scene-26 event-1 entry QA: could not write audio "
                         "trace\n";
            return 3;
        }
        events << "runtime_audio_event_count=" << field_audio_events.size()
               << '\n';
        for (const auto event : field_audio_events) {
            events << "0x" << std::hex << event << '\n';
        }
    }
    std::cout << "field_scene26_event1_route_behavior=passed "
                 "visual_review=partial "
                 "scene2_record=93 rom=0x"
              << std::hex << kEntryRecordAddress << " collision=0xC1 "
                 "event=1 destination=0x1A"
              << std::dec << " east_ticks=" << east_ticks
              << " northeast_ticks=" << northeast_ticks
              << " doorway_lane_ticks=" << doorway_lane_ticks
              << " north_ticks=" << north_ticks
              << " resource_index="
              << activity.selected_resource_random_index << '/'
              << activity.resource_random_index_bound << " audio_events="
              << field_audio_events.size() << " artifacts="
              << output.string() << '\n';
    return 0;
}

int run_scene26_table_corner_fallback_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    std::vector<std::uint16_t>& field_audio_events) {
    constexpr std::size_t kTableRecordIndex = 70U;
    constexpr std::uint32_t kTableRecordAddress = 0x1D9C2AU;
    constexpr std::uint8_t kTableCollisionValue = 0x7EU;
    const auto& metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    if (field_scene.field_scene_reference_for_dump() != 26U ||
        metadata.terrain_collision_rectangles.size() <= kTableRecordIndex) {
        std::cerr << "Scene-26 diagonal table QA: scene or ROM record is "
                     "unavailable\n";
        return 3;
    }
    const auto& record = metadata.terrain_collision_rectangles[
        kTableRecordIndex];
    if (record.left != 96U || record.right != 191U || record.top != 224U ||
        record.bottom != 255U || record.value != kTableCollisionValue) {
        std::cerr << "Scene-26 diagonal table QA: ROM record 70 at 0x1D9C2A "
                     "changed\n";
        return 3;
    }
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Scene-26 diagonal table QA: cannot clear output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        return 3;
    }
    const auto audio_count_before = field_audio_events.size();
    bool source_heading_aligned = false;
    constexpr std::uint8_t kDownRightInput = 0x0AU;
    for (std::uint8_t tick = 0U; tick < 32U; ++tick) {
        field_scene.set_controller_nibble(kDownRightInput);
        field_scene.advance_frame();
        if (field_scene.field_entity_heading_for_dump() ==
            field_scene.field_entity_target_heading_for_dump()) {
            source_heading_aligned = true;
            break;
        }
        if (field_scene.field_scene_reference_for_dump() != 26U ||
            field_scene.dialogue_open() || field_scene.field_interaction_open() ||
            field_scene.shop_menu_open()) {
            break;
        }
    }
    field_scene.set_controller_nibble(0U);
    for (std::uint8_t tick = 0U; tick < 24U; ++tick) {
        field_scene.advance_frame();
    }
    if (!source_heading_aligned ||
        field_scene.field_scene_reference_for_dump() != 26U ||
        field_scene.dialogue_open() || field_scene.field_interaction_open() ||
        field_scene.shop_menu_open()) {
        std::cerr << "Scene-26 diagonal table QA: could not establish the ROM "
                     "Down+Right heading\n";
        return 3;
    }

    // Record 70 is a real Scene-26 0x7E rectangle. With the four source
    // offsets, center (87,217) samples only corner 3 in its first 32x32 cell.
    // Start at (70,200) on that diagonal, where the ordinary field map is
    // clear, then use the normal controller and Lua movement route.
    field_scene.set_field_entity_world_position_for_dump(70U * 16U,
                                                          200U * 16U);
    field_scene.set_field_camera_world_position_for_dump(0U, 80U * 16U);
    field_scene.set_terrain_probe_trace_enabled_for_dump(true);
    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save = [&](const std::filesystem::path& path,
                          const QImage& image) {
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
               field_hud_chrome_survives(image, asset_root) &&
               image.save(QString::fromStdWString(path.wstring()));
    };
    if (!save(output / "entry.bmp", render())) {
        field_scene.set_terrain_probe_trace_enabled_for_dump(false);
        std::cerr << "Scene-26 diagonal table QA: entry frame failed\n";
        return 3;
    }
    std::ofstream trace(output / "movement.tsv", std::ios::trunc);
    if (!trace) {
        field_scene.set_terrain_probe_trace_enabled_for_dump(false);
        return 3;
    }
    trace << "tick\tbefore_x_fixed\tbefore_y_fixed\tafter_x_fixed"
             "\tafter_y_fixed\tcandidate_x_fixed\tcandidate_y_fixed"
             "\tnormalized_x\tnormalized_y\tcorner0\tcorner1\tcorner2"
             "\tcorner3\traw_terrain\tcollision_result\twalking"
             "\tselector\tanimation_frame\n";
    bool contact_found = false;
    std::uint16_t contact_tick = 0U;
    SceneRunnerPosition before_contact{};
    SceneRunnerPosition after_contact{};
    FieldTerrainProbeTrace contact_probe{};
    constexpr std::array<std::uint8_t, 4U> kOneBlockedCorner{
        0U, 0U, 0U, kTableCollisionValue};
    for (std::uint16_t tick = 1U; tick <= 80U && !contact_found; ++tick) {
        const auto before = field_scene.field_entity_world_position();
        const auto before_frame = render();
        field_scene.set_controller_nibble(kDownRightInput);
        field_scene.advance_frame();
        const auto after = field_scene.field_entity_world_position();
        const auto after_frame = render();
        for (const auto& probe : field_scene.terrain_probe_trace_for_dump()) {
            trace << tick << '\t' << before.x << '\t' << before.y << '\t'
                  << after.x << '\t' << after.y << '\t'
                  << probe.candidate_x_fixed << '\t'
                  << probe.candidate_y_fixed << '\t' << probe.normalized_x
                  << '\t' << probe.normalized_y;
            for (const auto value : probe.terrain_bytes) {
                trace << "\t0x" << std::hex << static_cast<unsigned>(value)
                      << std::dec;
            }
            trace << "\t0x" << std::hex
                  << static_cast<unsigned>(static_cast<std::uint8_t>(
                         probe.raw_terrain_code))
                  << "\t0x" << static_cast<unsigned>(
                         static_cast<std::uint16_t>(probe.collision_result))
                  << std::dec << '\t'
                  << field_scene.field_entity_walking_for_dump() << '\t'
                  << field_scene.field_entity_animation_selector_for_dump()
                  << '\t'
                  << field_scene.field_entity_animation_frame_for_dump()
                  << '\n';
            if (probe.outside_bounds || !probe.expanded_probe ||
                probe.raw_terrain_code != kTableCollisionValue ||
                probe.collision_result != 0x7F ||
                probe.terrain_bytes != kOneBlockedCorner) {
                continue;
            }
            contact_found = true;
            contact_tick = tick;
            before_contact = before;
            after_contact = after;
            contact_probe = probe;
            if (!save(output / "contact-before.bmp", before_frame) ||
                !save(output / "contact-after.bmp", after_frame)) {
                field_scene.set_controller_nibble(0U);
                field_scene.set_terrain_probe_trace_enabled_for_dump(false);
                return 3;
            }
            break;
        }
        if (field_scene.field_scene_reference_for_dump() != 26U ||
            field_scene.dialogue_open() || field_scene.field_interaction_open() ||
            field_scene.shop_menu_open()) {
            field_scene.set_controller_nibble(0U);
            field_scene.set_terrain_probe_trace_enabled_for_dump(false);
            std::cerr << "Scene-26 diagonal table QA: a modal or scene change "
                         "interrupted the furniture approach\n";
            return 3;
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.set_terrain_probe_trace_enabled_for_dump(false);
    if (!contact_found ||
        (after_contact.x == contact_probe.candidate_x_fixed &&
         after_contact.y == contact_probe.candidate_y_fixed) ||
        field_scene.field_scene_reference_for_dump() != 26U) {
        std::cerr << "Scene-26 diagonal table QA: the one-corner ROM block "
                     "did not retain/fallback from the rejected candidate "
                     "(found=" << contact_found << ", before="
                  << before_contact.x << ',' << before_contact.y
                  << ", candidate=" << contact_probe.candidate_x_fixed << ','
                  << contact_probe.candidate_y_fixed << ", after="
                  << after_contact.x << ',' << after_contact.y << ")\n";
        return 3;
    }
    std::ofstream contact(output / "contact.tsv", std::ios::trunc);
    if (!contact) {
        return 3;
    }
    contact << "scene\trom_record\trom_address\tinput\ttick"
               "\tbefore_x_fixed\tbefore_y_fixed\tcandidate_x_fixed"
               "\tcandidate_y_fixed\tafter_x_fixed\tafter_y_fixed"
               "\tcorner0\tcorner1\tcorner2\tcorner3\traw_terrain"
               "\tcollision_result\tlongplay_frame\n";
    contact << "26\t70\t0x" << std::hex << kTableRecordAddress << std::dec
            << "\tDown+Right(0x0A)\t" << contact_tick << '\t'
            << before_contact.x << '\t' << before_contact.y << '\t'
            << contact_probe.candidate_x_fixed << '\t'
            << contact_probe.candidate_y_fixed << '\t' << after_contact.x
            << '\t' << after_contact.y;
    for (const auto value : contact_probe.terrain_bytes) {
        contact << "\t0x" << std::hex << static_cast<unsigned>(value)
                << std::dec;
    }
    contact << "\t0x" << std::hex
            << static_cast<unsigned>(static_cast<std::uint8_t>(
                   contact_probe.raw_terrain_code))
            << "\t0x" << static_cast<unsigned>(
                   static_cast<std::uint16_t>(contact_probe.collision_result))
            << std::dec << "\tno exact longplay contact\n";

    std::ofstream idle_trace(output / "neutral.tsv", std::ios::trunc);
    if (!idle_trace) {
        return 3;
    }
    idle_trace << "tick\tx_fixed\ty_fixed\theading\twalking\tselector"
                  "\tanimation_frame\taudio_event_count\n";
    SceneRunnerPosition neutral_tail_position{};
    bool neutral_tail_stable = true;
    for (std::uint8_t tick = 1U; tick <= 30U; ++tick) {
        field_scene.advance_frame();
        const auto position = field_scene.field_entity_world_position();
        if (tick == 24U) {
            neutral_tail_position = position;
        } else if (tick > 24U &&
                   (position.x != neutral_tail_position.x ||
                    position.y != neutral_tail_position.y)) {
            neutral_tail_stable = false;
        }
        idle_trace << static_cast<unsigned>(tick) << '\t' << position.x << '\t'
                   << position.y << '\t'
                   << field_scene.field_entity_heading_for_dump() << '\t'
                   << field_scene.field_entity_walking_for_dump() << '\t'
                   << field_scene.field_entity_animation_selector_for_dump()
                   << '\t'
                   << field_scene.field_entity_animation_frame_for_dump()
                   << '\t' << field_audio_events.size() << '\n';
        if (!save(output / ("neutral-" +
                            (tick < 10U ? std::string("0") : std::string()) +
                            std::to_string(tick) + ".bmp"), render())) {
            return 3;
        }
    }
    if (!neutral_tail_stable || field_audio_events.size() != audio_count_before ||
        field_scene.dialogue_open() || field_scene.field_interaction_open() ||
        field_scene.shop_menu_open() ||
        !save(output / "actual.bmp", render())) {
        std::cerr << "Scene-26 diagonal table QA: neutral state, modal layer, "
                     "or audio differs (stable=" << neutral_tail_stable
                  << ", audio_before=" << audio_count_before
                  << ", audio_after=" << field_audio_events.size() << ")\n";
        return 3;
    }
    std::cout << "scene26_table_diagonal_corner_qa=passed scene=26 record=70 "
                 "contact_tick=" << contact_tick << " before="
              << before_contact.x << ',' << before_contact.y << " candidate="
              << contact_probe.candidate_x_fixed << ','
              << contact_probe.candidate_y_fixed << " after=" << after_contact.x
              << ',' << after_contact.y << " corners=0,0,0,0x7E artifacts="
              << output.string() << '\n';
    return 0;
}

int run_scene26_table_collision_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    std::vector<std::uint16_t>& field_audio_events) {
    constexpr std::size_t kTableRecordIndex = 70U;
    constexpr std::uint32_t kTableRecordAddress = 0x1D9C2AU;
    constexpr std::uint8_t kTableCollisionValue = 0x7EU;
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Scene-26 table collision QA: could not clear prior output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        std::cerr << "Scene-26 table collision QA: could not create output: "
                  << output_error.message() << '\n';
        return 3;
    }

    const auto& metadata = field_scene.state().field_scene_buffers.source_metadata;
    if (field_scene.field_scene_reference_for_dump() != 26U ||
        field_scene.field_entity_world_position().x != 0x0A00U ||
        field_scene.field_entity_world_position().y != 0x0500U ||
        metadata.terrain_collision_rectangles.size() <= kTableRecordIndex) {
        std::cerr << "Scene-26 table collision QA: event-1 route did not leave "
                     "the runner at the ROM scene-26 spawn\n";
        return 3;
    }
    const auto& table_record =
        metadata.terrain_collision_rectangles[kTableRecordIndex];
    if (table_record.left != 0x0060U || table_record.right != 0x00BFU ||
        table_record.top != 0x00E0U || table_record.bottom != 0x00FFU ||
        table_record.value != kTableCollisionValue) {
        std::cerr << "Scene-26 table collision QA: ROM record 70 changed: "
                     "address=0x1D9C2A bounds=("
                  << table_record.left << ',' << table_record.top << ")..("
                  << table_record.right << ',' << table_record.bottom
                  << ") value=0x" << std::hex
                  << static_cast<unsigned>(table_record.value) << std::dec
                  << '\n';
        return 3;
    }

    // Seed the runner into the clear lane north of record 70. This keeps the
    // contact and actor visible together in the full-screen route capture.
    field_scene.set_field_entity_world_position_for_dump(0x0800U, 0x0C00U);

    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save_image = [&](const std::filesystem::path& path,
                                const QImage& image) {
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
            field_hud_chrome_survives(image, asset_root) &&
            image.save(QString::fromStdWString(path.wstring()));
    };
    const auto initial_position = field_scene.field_entity_world_position();
    const auto initial_frame = render();
    if (!save_image(output / "table-approach-start.bmp", initial_frame)) {
        std::cerr << "Scene-26 table collision QA: initial full-screen dump failed\n";
        return 3;
    }

    std::ofstream trace(output / "terrain-probes.tsv", std::ios::trunc);
    if (!trace) {
        std::cerr << "Scene-26 table collision QA: could not create probe trace\n";
        return 3;
    }
    trace << "tick\tbefore_x_fixed\tbefore_y_fixed\tafter_x_fixed"
             "\tafter_y_fixed\tcandidate_x_fixed\tcandidate_y_fixed"
             "\tnormalized_x\tnormalized_y\texpanded\tcorner0_x"
             "\tcorner0_y\tcorner0_byte\tcorner1_x\tcorner1_y"
             "\tcorner1_byte\tcorner2_x\tcorner2_y\tcorner2_byte"
             "\tcorner3_x\tcorner3_y\tcorner3_byte\tselected_tile_index"
             "\traw_terrain\tcollision_result\toutside_bounds\n";
    field_scene.set_terrain_probe_trace_enabled_for_dump(true);
    auto previous_accepted_step = std::uint16_t{0U};
    auto contact_tick = std::uint16_t{0U};
    SceneRunnerPosition before_contact{};
    SceneRunnerPosition after_contact{};
    FieldTerrainProbeTrace contact_probe{};
    bool contact_found = false;
    constexpr std::uint16_t kMaximumApproachSteps = 160U;
    for (std::uint16_t tick = 1U; tick <= kMaximumApproachSteps; ++tick) {
        const auto before = field_scene.field_entity_world_position();
        const auto before_image = render();
        field_scene.set_controller_nibble(0x02U); // ROM D-pad Down
        field_scene.advance_frame();
        const auto after = field_scene.field_entity_world_position();
        const auto& probes = field_scene.terrain_probe_trace_for_dump();
        for (const auto& probe : probes) {
            const auto& corners_x = probe.corner_x;
            const auto& corners_y = probe.corner_y;
            const auto& bytes = probe.terrain_bytes;
            trace << tick << '\t' << before.x << '\t' << before.y << '\t'
                  << after.x << '\t' << after.y << '\t'
                  << probe.candidate_x_fixed << '\t'
                  << probe.candidate_y_fixed << '\t'
                  << probe.normalized_x << '\t' << probe.normalized_y << '\t'
                  << probe.expanded_probe;
            for (std::size_t corner = 0U; corner < bytes.size(); ++corner) {
                trace << '\t' << corners_x[corner] << '\t'
                      << corners_y[corner] << "\t0x" << std::hex
                      << static_cast<unsigned>(bytes[corner]) << std::dec;
            }
            trace << '\t' << probe.selected_tile_index << "\t0x" << std::hex
                  << static_cast<unsigned>(static_cast<std::uint8_t>(
                         probe.raw_terrain_code))
                  << "\t0x" << static_cast<unsigned>(
                         static_cast<std::uint16_t>(probe.collision_result))
                  << std::dec << '\t' << probe.outside_bounds << '\n';
            const bool table_record_sample =
                !probe.outside_bounds && probe.expanded_probe &&
                probe.normalized_x >= 0x0060U &&
                probe.normalized_x <= 0x00BFU &&
                probe.normalized_y >= 0x00D0U &&
                probe.normalized_y <= 0x0110U &&
                std::any_of(bytes.begin(), bytes.end(),
                            [](const std::uint8_t value) {
                                return value == kTableCollisionValue;
                            }) &&
                probe.raw_terrain_code == kTableCollisionValue &&
                probe.collision_result == 0x7F;
            if (!table_record_sample || contact_found) {
                continue;
            }
            before_contact = before;
            after_contact = after;
            contact_probe = probe;
            contact_tick = tick;
            contact_found = true;
            if (!save_image(output / "table-contact-before.bmp",
                            before_image) ||
                !save_image(output / "table-contact-after.bmp", render())) {
                field_scene.set_controller_nibble(0U);
                field_scene.set_terrain_probe_trace_enabled_for_dump(false);
                std::cerr << "Scene-26 table collision QA: contact full-screen "
                             "dump failed\n";
                return 3;
            }
        }
        if (contact_found) {
            break;
        }
        const auto moved_y = static_cast<std::int32_t>(after.y) -
                             static_cast<std::int32_t>(before.y);
        if (moved_y != 0 && moved_y >= -0x7FFF && moved_y <= 0x7FFF) {
            previous_accepted_step = static_cast<std::uint16_t>(
                moved_y < 0 ? -moved_y : moved_y);
        }
        if (field_scene.field_scene_reference_for_dump() != 26U ||
            field_scene.dialogue_open() ||
            field_scene.field_interaction_open() ||
            field_scene.shop_menu_open()) {
            field_scene.set_controller_nibble(0U);
            field_scene.set_terrain_probe_trace_enabled_for_dump(false);
            std::cerr << "Scene-26 table collision QA: another scene or modal "
                         "interrupted the table approach\n";
            return 3;
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.set_terrain_probe_trace_enabled_for_dump(false);
    if (!contact_found) {
        std::cerr << "Scene-26 table collision QA: the visible north approach did not sample "
                     "record 70 (ROM 0x1D9C2A, value 0x7E); start="
                  << initial_position.x << ',' << initial_position.y
                  << " end=" << field_scene.field_entity_world_position().x
                  << ',' << field_scene.field_entity_world_position().y
                  << " last_step=" << previous_accepted_step << '\n';
        return 3;
    }

    std::ofstream report(output / "table-contact.tsv", std::ios::trunc);
    if (!report) {
        std::cerr << "Scene-26 table collision QA: could not create contact report\n";
        return 3;
    }
    report << "scene\tstart_x_fixed\tstart_y_fixed\tinput\ttick"
              "\tcommitted_before_x\tcommitted_before_y"
              "\tcommitted_after_x\tcommitted_after_y"
              "\tlast_accepted_step\trom_record_index\trom_record_address"
              "\trom_value\trom_left\trom_right\trom_top\trom_bottom"
              "\tcandidate_x_fixed\tcandidate_y_fixed\tnormalized_x"
              "\tnormalized_y\tcorner0_x\tcorner0_y\tcorner0_byte"
              "\tcorner1_x\tcorner1_y\tcorner1_byte"
              "\tcorner2_x\tcorner2_y\tcorner2_byte"
              "\tcorner3_x\tcorner3_y\tcorner3_byte"
              "\tselected_tile_index\traw_terrain\tcollision_result\n";
    report << 26U << '\t' << initial_position.x << '\t'
           << initial_position.y << "\tDown(0x02)\t" << contact_tick << '\t'
           << before_contact.x << '\t' << before_contact.y << '\t'
           << after_contact.x << '\t' << after_contact.y << '\t'
           << previous_accepted_step << '\t' << kTableRecordIndex << "\t0x"
           << std::hex << kTableRecordAddress << "\t0x"
           << static_cast<unsigned>(table_record.value) << std::dec << '\t'
           << table_record.left << '\t' << table_record.right << '\t'
           << table_record.top << '\t' << table_record.bottom << '\t'
           << contact_probe.candidate_x_fixed << '\t'
           << contact_probe.candidate_y_fixed << '\t'
           << contact_probe.normalized_x << '\t'
           << contact_probe.normalized_y;
    for (std::size_t corner = 0U;
         corner < contact_probe.terrain_bytes.size(); ++corner) {
        report << '\t' << contact_probe.corner_x[corner] << '\t'
               << contact_probe.corner_y[corner] << "\t0x" << std::hex
               << static_cast<unsigned>(
                      contact_probe.terrain_bytes[corner]) << std::dec;
    }
    report << '\t' << contact_probe.selected_tile_index << "\t0x" << std::hex
           << static_cast<unsigned>(static_cast<std::uint8_t>(
                  contact_probe.raw_terrain_code))
           << "\t0x" << static_cast<unsigned>(
                  static_cast<std::uint16_t>(contact_probe.collision_result))
           << '\n';
    report.flush();

    // ROM 0xE8A0 samples (-12,-7), (+12,-7), (-12,+7), (+12,+7) in
    // this order. Record 70's lower two samples are inside its inclusive
    // 0x7E cell; 0xE7C8 returns 0x7F. The captured route retains its prior
    // position after its movement policy handles this blocked candidate.
    constexpr std::array<std::uint16_t, 4U> kExpectedCornerX{
        138U, 162U, 138U, 162U};
    constexpr std::array<std::uint16_t, 4U> kExpectedCornerY{
        211U, 211U, 225U, 225U};
    constexpr std::array<std::uint8_t, 4U> kExpectedTerrainBytes{
        0U, 0U, kTableCollisionValue, kTableCollisionValue};
    const bool expected_contact_matches =
        initial_position.x == 2048U && initial_position.y == 3072U &&
        before_contact.x == 2408U && before_contact.y == 3462U &&
        after_contact.x == before_contact.x &&
        after_contact.y == before_contact.y &&
        previous_accepted_step == 30U &&
        contact_probe.candidate_x_fixed == 2408U &&
        contact_probe.candidate_y_fixed == 3492U &&
        contact_probe.normalized_x == 150U &&
        contact_probe.normalized_y == 218U &&
        contact_probe.corner_x == kExpectedCornerX &&
        contact_probe.corner_y == kExpectedCornerY &&
        contact_probe.terrain_bytes == kExpectedTerrainBytes &&
        contact_probe.selected_tile_index == 453U &&
        contact_probe.raw_terrain_code == kTableCollisionValue &&
        contact_probe.collision_result == 0x7F &&
        contact_probe.expanded_probe && !contact_probe.outside_bounds;
    if (!expected_contact_matches) {
        std::cerr << "Scene-26 table collision QA: movement result differs "
                     "from the expected route/source-collision trace; "
                     "expected committed "
                     "(2408,3462), candidate (2408,3492), samples "
                     "0,0,0x7E,0x7E, result 0x7F; got before=("
                  << before_contact.x << ',' << before_contact.y << ") after=("
                  << after_contact.x << ',' << after_contact.y
                  << ") candidate=(" << contact_probe.candidate_x_fixed
                  << ',' << contact_probe.candidate_y_fixed << ") samples=";
        for (std::size_t corner = 0U;
             corner < contact_probe.terrain_bytes.size(); ++corner) {
            std::cerr << (corner == 0U ? "" : ",") << "0x" << std::hex
                      << static_cast<unsigned>(
                             contact_probe.terrain_bytes[corner]);
        }
        std::cerr << std::dec << " result=0x"
                  << std::hex << static_cast<unsigned>(
                         static_cast<std::uint16_t>(
                             contact_probe.collision_result))
                  << std::dec << '\n';
        return 3;
    }

    const auto after_image = render();
    if (!save_image(output / "actual.bmp", after_image)) {
        std::cerr << "Scene-26 table collision QA: actual full-screen dump failed\n";
        return 3;
    }
    if (run_scene26_table_corner_fallback_qa(
            field_scene, asset_root, output / "diagonal-corner",
            field_audio_events) != 0) {
        return 3;
    }
    std::cout << "scene26_table_collision_qa=observed scene=26 record="
              << kTableRecordIndex << " rom=0x" << std::hex
              << kTableRecordAddress << " value=0x"
              << static_cast<unsigned>(table_record.value) << std::dec
              << " tick=" << contact_tick << " before=" << before_contact.x
              << ',' << before_contact.y << " after=" << after_contact.x
              << ',' << after_contact.y << " candidate="
              << contact_probe.candidate_x_fixed << ','
              << contact_probe.candidate_y_fixed << " normalized="
              << contact_probe.normalized_x << ','
              << contact_probe.normalized_y << " corners="
              << static_cast<unsigned>(contact_probe.terrain_bytes[0]) << ','
              << static_cast<unsigned>(contact_probe.terrain_bytes[1]) << ','
              << static_cast<unsigned>(contact_probe.terrain_bytes[2]) << ','
              << static_cast<unsigned>(contact_probe.terrain_bytes[3])
              << " selected_tile=" << contact_probe.selected_tile_index
              << " output=" << output.string() << '\n';
    return 0;
}

int run_scene19_table_collision_qa(
    const StartupIntegrationState& startup_state,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output) {
    struct ContactRoute {
        enum class Side { west, east, north, south };
        std::string_view name;
        std::uint16_t start_x;
        std::uint16_t start_y;
        std::uint8_t input_nibble;
        std::size_t record_index;
        std::uint32_t record_address;
        Side side;
    };
    constexpr std::array<ContactRoute, 5U> kRoutes{{
        {"record-8-west", 48U * 16U, 140U * 16U, 0x08U, 8U,
         0x1D5F28U, ContactRoute::Side::west},
        {"record-8-east", 144U * 16U, 140U * 16U, 0x04U, 8U,
         0x1D5F28U, ContactRoute::Side::east},
        {"record-8-north", 96U * 16U, 112U * 16U, 0x02U, 8U,
         0x1D5F28U, ContactRoute::Side::north},
        {"record-8-south", 96U * 16U, 176U * 16U, 0x01U, 8U,
         0x1D5F28U, ContactRoute::Side::south},
        {"record-9-west", 144U * 16U, 140U * 16U, 0x08U, 9U,
         0x1D5F32U, ContactRoute::Side::west},
    }};
    struct ExpectedContact {
        SceneRunnerPosition start;
        SceneRunnerPosition before;
        SceneRunnerPosition candidate;
        SceneRunnerPosition after;
        std::array<std::uint8_t, 4U> terrain_bytes;
    };
    // These values are the source-route samples recorded from the ROM terrain
    // map (0xFF1700) after 0xE8A0's four +/-12,+/-7 corner probes.  Pin each
    // contact so this route cannot silently stop testing a different edge.
    constexpr std::array<ExpectedContact, 5U> kExpectedContacts{{
        {{768U, 2240U}, {828U, 2150U}, {858U, 2120U}, {828U, 2120U},
         {0U, 0U, 0U, 0x7EU}},
        {{2304U, 2240U}, {2244U, 2120U}, {2214U, 2090U}, {2244U, 2090U},
         {0U, 0U, 0x7EU, 0U}},
        {{1536U, 1792U}, {1896U, 1912U}, {1896U, 1942U}, {1926U, 1882U},
         {0U, 0U, 0x7EU, 0U}},
        {{1536U, 2816U}, {1536U, 2696U}, {1536U, 2666U}, {1536U, 2696U},
         {0x7EU, 0x7EU, 0U, 0U}},
        {{2304U, 2240U}, {2364U, 2150U}, {2394U, 2120U}, {2364U, 2120U},
         {0U, 0U, 0U, 0x7EU}},
    }};
    constexpr std::array<TerrainCollisionRectangle, 2U> kRomTableRecords{{
        {64U, 127U, 128U, 159U, 0x7EU},
        {160U, 223U, 128U, 159U, 0x7EU},
    }};
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Scene-19 table collision QA: could not clear prior "
                     "output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        std::cerr << "Scene-19 table collision QA: could not create output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::ofstream contacts(output / "contacts.tsv", std::ios::trunc);
    if (!contacts) {
        std::cerr << "Scene-19 table collision QA: contact report could not "
                     "be written\n";
        return 3;
    }
    contacts << "scene\trecord_index\trecord_address\tvalue\tleft\tright"
                "\ttop\tbottom\tinput_nibble\ttick\tstart_x_fixed"
                "\tstart_y_fixed\tbefore_x_fixed\tbefore_y_fixed"
                "\tcandidate_x_fixed\tcandidate_y_fixed\tafter_x_fixed"
                "\tafter_y_fixed\tnormalized_x\tnormalized_y"
                "\tcorner0_x\tcorner0_y\tcorner0_byte\tcorner1_x"
                "\tcorner1_y\tcorner1_byte\tcorner2_x\tcorner2_y"
                "\tcorner2_byte\tcorner3_x\tcorner3_y\tcorner3_byte"
                "\traw_terrain\tcollision_result\tlongplay_frames\n";

    for (std::size_t route_index = 0U; route_index < kRoutes.size();
         ++route_index) {
        const auto& route = kRoutes[route_index];
        const auto& expected = kExpectedContacts[route_index];
        const auto route_output = output / std::string(route.name);
        std::filesystem::create_directories(route_output, output_error);
        if (output_error) {
            std::cerr << "Scene-19 table collision QA: route directory "
                         "could not be created: "
                      << output_error.message() << '\n';
            return 3;
        }
        std::vector<std::string> source_boundaries;
        std::vector<std::uint16_t> audio_events;
        FieldSceneRuntime field_scene(
            [&source_boundaries](const std::string_view boundary) {
                source_boundaries.emplace_back(boundary);
            },
            [&audio_events](const std::uint16_t event) {
                audio_events.push_back(event);
            });
        field_scene.set_source_random_seed_for_dump(0x4000U);
        field_scene.set_field_world_frame_counter_for_dump(0x0200U);
        if (!field_scene.bootstrap_for_scene_dump(startup_state, 19U)) {
            std::cerr << "Scene-19 table collision QA: bootstrap failed: "
                      << field_scene.failure() << '\n';
            return 3;
        }
        const auto& source_records = field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_rectangles;
        const auto rom_record_index = route.record_index == 8U ? 0U : 1U;
        if (field_scene.field_scene_reference_for_dump() != 19U ||
            source_records.size() <= route.record_index ||
            source_records[route.record_index].left !=
                kRomTableRecords[rom_record_index].left ||
            source_records[route.record_index].right !=
                kRomTableRecords[rom_record_index].right ||
            source_records[route.record_index].top !=
                kRomTableRecords[rom_record_index].top ||
            source_records[route.record_index].bottom !=
                kRomTableRecords[rom_record_index].bottom ||
            source_records[route.record_index].value !=
                kRomTableRecords[rom_record_index].value) {
            std::cerr << "Scene-19 table collision QA: ROM record "
                      << route.record_index << " at 0x" << std::hex
                      << route.record_address << std::dec
                      << " differs from the active field record\n";
            return 3;
        }
        const auto& record = source_records[route.record_index];
        field_scene.set_field_entity_world_position_for_dump(
            route.start_x, route.start_y);
        field_scene.set_terrain_probe_trace_enabled_for_dump(true);
        const auto render = [&field_scene] { return render_qa_field(field_scene); };
        const auto save = [&](const std::filesystem::path& path,
                              const QImage& image) {
            return image.size() == QSize(kSceneWidth, kSceneHeight) &&
                   field_hud_chrome_survives(image, asset_root) &&
                   image.save(QString::fromStdWString(path.wstring()));
        };
        const auto start = field_scene.field_entity_world_position();
        if (!save(route_output / "entry.bmp", render())) {
            field_scene.set_terrain_probe_trace_enabled_for_dump(false);
            std::cerr << "Scene-19 table collision QA: entry frame failed for "
                      << route.name << '\n';
            return 3;
        }
        std::ofstream trace(route_output / "terrain-probes.tsv",
                            std::ios::trunc);
        if (!trace) {
            field_scene.set_terrain_probe_trace_enabled_for_dump(false);
            std::cerr << "Scene-19 table collision QA: probe trace failed for "
                      << route.name << '\n';
            return 3;
        }
        trace << "tick\tbefore_x_fixed\tbefore_y_fixed\tafter_x_fixed"
                 "\tafter_y_fixed\tcandidate_x_fixed\tcandidate_y_fixed"
                 "\tnormalized_x\tnormalized_y\tcorner0_x\tcorner0_y"
                 "\tcorner0_byte\tcorner1_x\tcorner1_y\tcorner1_byte"
                 "\tcorner2_x\tcorner2_y\tcorner2_byte\tcorner3_x"
                 "\tcorner3_y\tcorner3_byte\tselected_tile\traw_terrain"
                 "\tcollision_result\toutside_bounds\n";
        bool contact_found = false;
        bool contact_position_keeps_approach_side = false;
        std::uint16_t contact_tick = 0U;
        SceneRunnerPosition before_contact{};
        SceneRunnerPosition after_contact{};
        FieldTerrainProbeTrace contact_probe{};
        for (std::uint16_t tick = 1U; tick <= 80U && !contact_found; ++tick) {
            const auto before = field_scene.field_entity_world_position();
            const auto before_frame = render();
            field_scene.set_controller_nibble(route.input_nibble);
            field_scene.advance_frame();
            const auto after = field_scene.field_entity_world_position();
            const auto after_frame = render();
            std::ostringstream frame_name;
            frame_name << "step-" << std::setw(3) << std::setfill('0')
                       << tick << ".bmp";
            if (!save(route_output / frame_name.str(), after_frame)) {
                field_scene.set_controller_nibble(0U);
                field_scene.set_terrain_probe_trace_enabled_for_dump(false);
                std::cerr << "Scene-19 table collision QA: full frame failed "
                          << "for " << route.name << " tick " << tick << '\n';
                return 3;
            }
            for (const auto& probe : field_scene.terrain_probe_trace_for_dump()) {
                trace << tick << '\t' << before.x << '\t' << before.y << '\t'
                      << after.x << '\t' << after.y << '\t'
                      << probe.candidate_x_fixed << '\t'
                      << probe.candidate_y_fixed << '\t'
                      << probe.normalized_x << '\t' << probe.normalized_y;
                for (std::size_t corner = 0U;
                     corner < probe.terrain_bytes.size(); ++corner) {
                    trace << '\t' << probe.corner_x[corner] << '\t'
                          << probe.corner_y[corner] << "\t0x" << std::hex
                          << static_cast<unsigned>(probe.terrain_bytes[corner])
                          << std::dec;
                }
                trace << '\t' << probe.selected_tile_index << "\t0x" << std::hex
                      << static_cast<unsigned>(static_cast<std::uint8_t>(
                             probe.raw_terrain_code))
                      << "\t0x" << static_cast<unsigned>(
                             static_cast<std::uint16_t>(
                                 probe.collision_result))
                      << std::dec << '\t' << probe.outside_bounds << '\n';
                if (!probe.outside_bounds && probe.raw_terrain_code == 0x7E &&
                    probe.collision_result == 0x7F) {
                    contact_found = true;
                    const auto after_x = static_cast<std::uint16_t>(
                        after.x >> 4U);
                    const auto after_y = static_cast<std::uint16_t>(
                        after.y >> 4U);
                    switch (route.side) {
                    case ContactRoute::Side::west:
                        contact_position_keeps_approach_side =
                            after_x < record.left;
                        break;
                    case ContactRoute::Side::east:
                        contact_position_keeps_approach_side =
                            after_x > record.right;
                        break;
                    case ContactRoute::Side::north:
                        contact_position_keeps_approach_side =
                            after_y < record.top;
                        break;
                    case ContactRoute::Side::south:
                        contact_position_keeps_approach_side =
                            after_y > record.bottom;
                        break;
                    }
                    contact_tick = tick;
                    before_contact = before;
                    after_contact = after;
                    contact_probe = probe;
                    if (!save(route_output / "contact-before.bmp",
                              before_frame) ||
                        !save(route_output / "contact-after.bmp", after_frame)) {
                        field_scene.set_controller_nibble(0U);
                        field_scene.set_terrain_probe_trace_enabled_for_dump(
                            false);
                        std::cerr << "Scene-19 table collision QA: contact "
                                     "frames failed for " << route.name << '\n';
                        return 3;
                    }
                    break;
                }
            }
        }
        field_scene.set_controller_nibble(0U);
        field_scene.set_terrain_probe_trace_enabled_for_dump(false);
        const auto actual_frame = render();
        if (!save(route_output / "actual.bmp", actual_frame)) {
            std::cerr << "Scene-19 table collision QA: settled frame failed "
                      << "for " << route.name << '\n';
            return 3;
        }
        const bool center_within_rom_extent =
            contact_probe.normalized_x >=
                static_cast<std::uint16_t>(record.left - 12U) &&
            contact_probe.normalized_x <= record.right + 12U &&
            contact_probe.normalized_y >=
                static_cast<std::uint16_t>(record.top - 7U) &&
            contact_probe.normalized_y <= record.bottom + 7U;
        const bool exact_rom_contact_matches =
            start.x == expected.start.x && start.y == expected.start.y &&
            before_contact.x == expected.before.x &&
            before_contact.y == expected.before.y &&
            contact_probe.candidate_x_fixed == expected.candidate.x &&
            contact_probe.candidate_y_fixed == expected.candidate.y &&
            after_contact.x == expected.after.x &&
            after_contact.y == expected.after.y &&
            contact_probe.terrain_bytes == expected.terrain_bytes;
        if (!contact_found || !contact_position_keeps_approach_side ||
            !exact_rom_contact_matches ||
            !center_within_rom_extent ||
            field_scene.field_scene_reference_for_dump() != 19U ||
            !audio_events.empty()) {
            const auto& metadata =
                field_scene.state().field_scene_buffers.source_metadata;
            std::cerr << "Scene-19 table collision QA: host stop disagrees "
                         "with ROM record " << route.record_index
                      << " (route=" << route.name << ", found="
                      << contact_found << ", retained_approach_side="
                      << contact_position_keeps_approach_side
                      << ", exact_rom_sample=" << exact_rom_contact_matches
                      << ", center_in_extent=" << center_within_rom_extent
                      << ", before=" << before_contact.x << ','
                      << before_contact.y << ", after=" << after_contact.x
                      << ',' << after_contact.y << ", candidate="
                      << contact_probe.candidate_x_fixed << ','
                      << contact_probe.candidate_y_fixed
                      << ", bounds=" << metadata.terrain_x_inclusive_lower
                      << ".." << metadata.terrain_x_exclusive_upper << ','
                      << metadata.terrain_y_inclusive_lower << ".."
                      << metadata.terrain_y_exclusive_upper
                      << ", spawn="
                      << metadata.initial_field_records[0].x << ','
                      << metadata.initial_field_records[0].y
                      << ", outside=" << contact_probe.outside_bounds
                      << ")\n";
            return 3;
        }
        contacts << 19U << '\t' << route.record_index << "\t0x" << std::hex
                 << route.record_address << "\t0x"
                 << static_cast<unsigned>(record.value) << std::dec << '\t'
                 << record.left << '\t' << record.right << '\t' << record.top
                 << '\t' << record.bottom << "\t0x" << std::hex
                 << static_cast<unsigned>(route.input_nibble) << std::dec << '\t'
                 << contact_tick << '\t' << start.x << '\t' << start.y << '\t'
                 << before_contact.x << '\t' << before_contact.y << '\t'
                 << contact_probe.candidate_x_fixed << '\t'
                 << contact_probe.candidate_y_fixed << '\t' << after_contact.x
                 << '\t' << after_contact.y << '\t'
                 << contact_probe.normalized_x << '\t'
                 << contact_probe.normalized_y;
        for (std::size_t corner = 0U;
             corner < contact_probe.terrain_bytes.size(); ++corner) {
            contacts << '\t' << contact_probe.corner_x[corner] << '\t'
                     << contact_probe.corner_y[corner] << "\t0x" << std::hex
                     << static_cast<unsigned>(contact_probe.terrain_bytes[corner])
                     << std::dec;
        }
        contacts << "\t0x" << std::hex
                 << static_cast<unsigned>(static_cast<std::uint8_t>(
                        contact_probe.raw_terrain_code))
                 << "\t0x" << static_cast<unsigned>(
                        static_cast<std::uint16_t>(contact_probe.collision_result))
                 << std::dec << "\tsection_09:006990,007035\n";
        contacts.flush();
    }
    std::cout << "scene19_table_collision_qa=passed routes=" << kRoutes.size()
              << " records=8,9 rom=0x1D5F28,0x1D5F32 longplay="
                 "section_09:006990,007035 artifacts="
              << output.string() << '\n';
    return 0;
}

bool run_scene2_object_bounds_four_side_lookup_qa(
    const FieldSceneSourceMetadata& metadata,
    const std::filesystem::path& output) {
    struct ProbeCase {
        std::string_view side;
        std::uint8_t direction_ordinal;
        SceneRunnerPosition candidate;
        std::array<std::uint8_t, 4U> expected_bytes;
    };
    constexpr std::array<ProbeCase, 4U> kCases{{
        {"west", 2U, {580U * 16U, 1288U * 16U}, {0U, 1U, 0U, 1U}},
        {"east", 6U, {619U * 16U, 1288U * 16U}, {1U, 0U, 1U, 0U}},
        {"north", 4U, {600U * 16U, 1241U * 16U}, {0U, 0U, 1U, 0U}},
        {"south", 0U, {600U * 16U, 1318U * 16U}, {1U, 0U, 0U, 0U}},
    }};
    if (metadata.terrain_collision_rectangles.size() <= 1U ||
        metadata.terrain_collision_map.empty()) {
        return false;
    }
    const auto& object_record = metadata.terrain_collision_rectangles[1U];
    if (object_record.left != 592U || object_record.right != 607U ||
        object_record.top != 1248U || object_record.bottom != 1311U ||
        object_record.value != 1U) {
        return false;
    }
    std::array<MovementOffset, 8U> movement_offsets{};
    for (std::size_t direction = 0U; direction < movement_offsets.size();
         ++direction) {
        movement_offsets[direction] = MovementOffset{
            kFieldMovementDirectionTableWords[direction * 2U],
            kFieldMovementDirectionTableWords[direction * 2U + 1U]};
    }
    const auto sample_tiles = [&metadata](
                                  const std::uint16_t x,
                                  const std::uint16_t y,
                                  const bool expanded_probe) {
        return sample_terrain_collision_tiles(
            x, y, expanded_probe,
            [&metadata](const std::uint16_t index) {
                const auto& map = metadata.terrain_collision_map;
                return index < map.size() ? map[index] : 0x7FU;
            });
    };
    const TerrainCollisionBounds isolated_object_bounds{
        0U, 4096U, 0U, 4096U};
    const TerrainCollisionCallbacks collision_callbacks{
        sample_tiles,
        [&metadata](const std::uint8_t object_id,
                    const std::int16_t x,
                    const std::int16_t y) {
            const auto& records = metadata.terrain_collision_rectangles;
            if (object_id >= records.size()) {
                return true;
            }
            const auto lookup = [&records](const std::uint16_t index) {
                if (index >= records.size()) {
                    return TerrainObjectBounds{};
                }
                const auto& record = records[index];
                return TerrainObjectBounds{
                    static_cast<std::int16_t>(record.left),
                    static_cast<std::int16_t>(record.right),
                    static_cast<std::int16_t>(record.top),
                    static_cast<std::int16_t>(record.bottom)};
            };
            return contains_terrain_object_bounds(object_id, x, y, lookup);
        },
        {}};

    std::ofstream trace(output, std::ios::trunc);
    if (!trace) {
        return false;
    }
    trace << "scene\trom_object_record\trom_address\tside"
             "\tdirection_ordinal\tstart_x_fixed\tstart_y_fixed"
             "\tcandidate_x_fixed\tcandidate_y_fixed\tretained_x_fixed"
             "\tretained_y_fixed\tcorner0\tcorner1\tcorner2\tcorner3"
             "\traw_terrain\tcollision_result\tinside_scene_bounds\n";

    for (const auto& test_case : kCases) {
        const auto& offset = movement_offsets[test_case.direction_ordinal];
        const SceneRunnerPosition start{
            static_cast<std::uint16_t>(
                static_cast<std::int32_t>(test_case.candidate.x) - offset.x),
            static_cast<std::uint16_t>(
                static_cast<std::int32_t>(test_case.candidate.y) - offset.y)};
        EntityMovementStepState entity{};
        entity.position_x = start.x;
        entity.position_y = start.y;
        entity.heading = static_cast<std::uint16_t>(
            test_case.direction_ordinal << 13U);
        auto last_probe = MovementProbeResult{};
        auto last_collision = TerrainCollisionResult{};
        const auto movement_probe = [&](const std::uint16_t direction_slot) {
            const auto direction = static_cast<std::uint8_t>(
                (direction_slot >> 1U) & 0x07U);
            last_probe = probe_entity_directional_collision(
                MovementProbeInput{entity.position_x, entity.position_y,
                                   direction, 0x04U},
                movement_offsets,
                [&](const std::uint16_t candidate_x,
                    const std::uint16_t candidate_y) {
                    last_collision = evaluate_terrain_collision(
                        TerrainCollisionInput{
                            candidate_x, candidate_y, 0x04U,
                            isolated_object_bounds, {}},
                        collision_callbacks);
                    return last_collision.code;
                });
            return last_probe;
        };
        std::uint8_t reset_count = 0U;
        const auto direction_slot = static_cast<std::uint16_t>(
            test_case.direction_ordinal * 2U);
        advance_entity_movement_step(
            entity, field_movement_step_context_word(direction_slot),
            direction_slot, {}, movement_probe,
            [] { return false; },
            [] { return MovementRouteResult{false, std::nullopt}; },
            movement_probe, [&reset_count] { ++reset_count; });

        const auto normalized_x =
            static_cast<std::uint16_t>(test_case.candidate.x >> 4U);
        const auto normalized_y =
            static_cast<std::uint16_t>(test_case.candidate.y >> 4U);
        const bool inside_scene_bounds =
            normalized_x >= metadata.terrain_x_inclusive_lower &&
            normalized_x < metadata.terrain_x_exclusive_upper &&
            normalized_y >= metadata.terrain_y_inclusive_lower &&
            normalized_y < metadata.terrain_y_exclusive_upper;
        const bool exact_source_probe =
            last_probe.candidate_x == test_case.candidate.x &&
            last_probe.candidate_y == test_case.candidate.y &&
            last_collision.state.sample.values == test_case.expected_bytes &&
            last_collision.state.raw_terrain_code == 1 &&
            last_collision.code == 0x7F && reset_count == 1U &&
            entity.position_x == start.x && entity.position_y == start.y;
        if (!exact_source_probe) {
            std::cerr << "Object-bounds four-side lookup QA: ROM record 1 "
                         "probe differs on " << test_case.side
                      << " (candidate=" << last_probe.candidate_x << ','
                      << last_probe.candidate_y << ", expected="
                      << test_case.candidate.x << ','
                      << test_case.candidate.y << ", raw="
                      << last_collision.state.raw_terrain_code << ", result="
                      << last_collision.code << ", retained="
                      << entity.position_x << ',' << entity.position_y
                      << ", reset=" << static_cast<unsigned>(reset_count)
                      << ")\n";
            return false;
        }
        trace << 2U << '\t' << 1U << "\t0x172DB4\t" << test_case.side
              << '\t' << static_cast<unsigned>(test_case.direction_ordinal)
              << '\t' << start.x << '\t' << start.y << '\t'
              << last_probe.candidate_x << '\t' << last_probe.candidate_y
              << '\t' << entity.position_x << '\t' << entity.position_y;
        for (const auto value : last_collision.state.sample.values) {
            trace << "\t0x" << std::hex << static_cast<unsigned>(value)
                  << std::dec;
        }
        trace << "\t0x" << std::hex
              << static_cast<unsigned>(static_cast<std::uint8_t>(
                     last_collision.state.raw_terrain_code))
              << "\t0x" << static_cast<unsigned>(
                     static_cast<std::uint16_t>(last_collision.code))
              << std::dec << '\t' << inside_scene_bounds << '\n';
        if (test_case.direction_ordinal != 0U && !inside_scene_bounds) {
            return false;
        }
        if (test_case.direction_ordinal == 0U && inside_scene_bounds) {
            return false;
        }
    }
    return true;
}

int run_low_code_object_bounds_census_qa(
    const StartupIntegrationState& startup_state,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output) {
    enum class Side { west, east, north, south };
    struct CollisionRoute {
        std::string_view name;
        std::uint16_t scene;
        std::uint16_t start_x;
        std::uint16_t start_y;
        std::uint8_t input_nibble;
        std::size_t region_record_index;
        std::uint32_t region_record_address;
        TerrainCollisionRectangle region;
        std::size_t lookup_record_index;
        std::uint32_t lookup_record_address;
        TerrainCollisionRectangle lookup;
        bool expect_blocked;
        Side side;
        bool prealign_heading = false;
    };
    constexpr std::array<CollisionRoute, 10U> kRoutes{{
        {"scene-02-record-1", 2U, 528U * 16U, 1288U * 16U, 0x08U,
         1U, 0x172DB4U, {592U, 607U, 1248U, 1311U, 1U},
         1U, 0x172DB4U, {592U, 607U, 1248U, 1311U, 1U}, true,
         Side::west},
        {"scene-02-record-1-east", 2U, 672U * 16U, 1288U * 16U, 0x04U,
         1U, 0x172DB4U, {592U, 607U, 1248U, 1311U, 1U},
         1U, 0x172DB4U, {592U, 607U, 1248U, 1311U, 1U}, true,
         Side::east, true},
        {"scene-02-record-1-north", 2U, 600U * 16U, 1224U * 16U, 0x02U,
         1U, 0x172DB4U, {592U, 607U, 1248U, 1311U, 1U},
         1U, 0x172DB4U, {592U, 607U, 1248U, 1311U, 1U}, true,
         Side::north, true},
        {"scene-02-record-2", 2U, 1472U * 16U, 848U * 16U, 0x04U,
         2U, 0x172DBEU, {1376U, 1407U, 832U, 847U, 2U},
         2U, 0x172DBEU, {1376U, 1407U, 832U, 847U, 2U}, true,
         Side::east},
        {"scene-02-record-3", 2U, 944U * 16U, 960U * 16U, 0x01U,
         3U, 0x172DC8U, {928U, 959U, 928U, 943U, 3U},
         3U, 0x172DC8U, {928U, 959U, 928U, 943U, 3U}, true,
         Side::south},
        {"scene-07-record-1", 7U, 832U * 16U, 1152U * 16U, 0x08U,
         1U, 0x1B3D90U, {896U, 927U, 1136U, 1151U, 1U},
         1U, 0x1B3D90U, {896U, 927U, 1136U, 1151U, 1U}, true,
         Side::west},
        {"scene-07-record-2", 7U, 1216U * 16U, 1504U * 16U, 0x08U,
         2U, 0x1B3D9AU, {1280U, 1311U, 1488U, 1503U, 2U},
         2U, 0x1B3D9AU, {1280U, 1311U, 1488U, 1503U, 2U}, true,
         Side::west},
        {"scene-08-record-1", 8U, 1216U * 16U, 1056U * 16U, 0x08U,
         1U, 0x1B463EU, {1280U, 1311U, 1040U, 1055U, 1U},
         1U, 0x1B463EU, {1280U, 1311U, 1040U, 1055U, 1U}, true,
         Side::west},
        {"scene-31-record-102-code-4", 31U, 128U * 16U, 280U * 16U, 0x08U,
         102U, 0x1DB9F4U, {192U, 223U, 264U, 295U, 4U},
         4U, 0x1DB620U, {640U, 671U, 1120U, 1247U, 0x7FU}, false,
         Side::west},
        {"scene-34-record-102-code-4", 34U, 128U * 16U, 280U * 16U, 0x08U,
         102U, 0x1DB9F4U, {192U, 223U, 264U, 295U, 4U},
         4U, 0x1DB620U, {640U, 671U, 1120U, 1247U, 0x7FU}, false,
         Side::west},
    }};
    struct ExpectedContact {
        SceneRunnerPosition before;
        SceneRunnerPosition candidate;
        SceneRunnerPosition after;
        std::array<std::uint8_t, 4U> stop_corners;
        bool has_lookup_probe = false;
        SceneRunnerPosition lookup_candidate;
        std::array<std::uint8_t, 4U> lookup_corners{};
        bool pin_exact = true;
    };
    constexpr std::array<ExpectedContact, 10U> kExpectedContacts{{
        {{9258U, 20608U}, {9288U, 20608U}, {9258U, 20608U},
         {0U, 1U, 0U, 1U}},
        {{9942U, 20608U}, {9912U, 20608U}, {9942U, 20608U},
         {1U, 0U, 1U, 0U}},
        {{9600U, 19854U}, {9600U, 19884U}, {9630U, 19824U},
         {0U, 0U, 1U, 0U}},
        {{22742U, 13448U}, {22712U, 13448U}, {22742U, 13448U},
         {2U, 0U, 2U, 0U}},
        {{15104U, 15240U}, {15104U, 15210U}, {15104U, 15240U},
         {3U, 3U, 3U, 3U}},
        {{14122U, 18282U}, {14152U, 18282U}, {14122U, 18282U},
         {0U, 1U, 0U, 1U}},
        {{20266U, 23914U}, {20296U, 23914U}, {20266U, 23914U},
         {0U, 2U, 0U, 2U}},
        {{20266U, 16746U}, {20296U, 16746U}, {20266U, 16746U},
         {0U, 1U, 0U, 1U}},
        {{3368U, 4330U}, {3398U, 4330U}, {3368U, 4330U},
         {4U, 0x7FU, 4U, 0x7FU}, true, {2888U, 4330U},
         {0U, 4U, 0U, 4U}},
        {{3368U, 4330U}, {3398U, 4330U}, {3368U, 4330U},
         {4U, 0x7FU, 4U, 0x7FU}, true, {2888U, 4330U},
         {0U, 4U, 0U, 4U}},
    }};
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Object-bounds census QA: could not clear prior output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        std::cerr << "Object-bounds census QA: could not create output: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::ofstream census(output / "contacts.tsv", std::ios::trunc);
    if (!census) {
        std::cerr << "Object-bounds census QA: could not write contacts.tsv\n";
        return 3;
    }
    census << "scene\tregion_record_index\tregion_record_address"
              "\tterrain_code\tregion_left\tregion_right\tregion_top"
              "\tregion_bottom\tlookup_record_index\tlookup_record_address"
              "\tlookup_left\tlookup_right\tlookup_top\tlookup_bottom"
              "\tinput_nibble\ttick\tstart_x_fixed\tstart_y_fixed"
              "\tbefore_x_fixed\tbefore_y_fixed\tcandidate_x_fixed"
              "\tcandidate_y_fixed\tafter_x_fixed\tafter_y_fixed"
              "\tlookup_candidate_x_fixed\tlookup_candidate_y_fixed"
              "\tlookup_result\tstop_record_index\tstop_record_address"
              "\tcorner0\tcorner1\tcorner2\tcorner3\traw_terrain"
              "\tcollision_result\tbehavior\trunner_active\trunner_visible"
              "\tcamera_x_fixed\tcamera_y_fixed\trunner_screen_x"
              "\trunner_screen_y\tlongplay_frame\n";

    bool four_side_object_lookup_passed = false;
    for (std::size_t route_index = 0U; route_index < kRoutes.size();
         ++route_index) {
        const auto& route = kRoutes[route_index];
        const auto& expected = kExpectedContacts[route_index];
        const auto route_output = output / std::string(route.name);
        std::filesystem::create_directories(route_output, output_error);
        if (output_error) {
            std::cerr << "Object-bounds census QA: route directory could not "
                         "be created: " << output_error.message() << '\n';
            return 3;
        }
        std::vector<std::string> source_boundaries;
        std::vector<std::uint16_t> audio_events;
        FieldSceneRuntime field_scene(
            [&source_boundaries](const std::string_view boundary) {
                source_boundaries.emplace_back(boundary);
            },
            [&audio_events](const std::uint16_t event) {
                audio_events.push_back(event);
            });
        field_scene.set_source_random_seed_for_dump(0x4000U);
        field_scene.set_field_world_frame_counter_for_dump(0x0200U);
        if (!field_scene.bootstrap_for_scene_dump(startup_state,
                                                  route.scene)) {
            std::cerr << "Object-bounds census QA: scene " << route.scene
                      << " bootstrap failed: " << field_scene.failure()
                      << '\n';
            return 3;
        }
        const auto& metadata =
            field_scene.state().field_scene_buffers.source_metadata;
        const auto& records = metadata.terrain_collision_rectangles;
        const auto matches = [](const TerrainCollisionRectangle& actual,
                                const TerrainCollisionRectangle& expected) {
            return actual.left == expected.left &&
                   actual.right == expected.right &&
                   actual.top == expected.top &&
                   actual.bottom == expected.bottom &&
                   actual.value == expected.value;
        };
        if (field_scene.field_scene_reference_for_dump() != route.scene ||
            records.size() <= route.region_record_index ||
            records.size() <= route.lookup_record_index ||
            !matches(records[route.region_record_index], route.region) ||
            !matches(records[route.lookup_record_index], route.lookup)) {
            std::cerr << "Object-bounds census QA: ROM collision records do "
                         "not match Scene " << route.scene << " route "
                      << route.name << '\n';
            return 3;
        }
        constexpr TerrainCollisionRectangle kScene31AdjacentBlocker{
            224U, 255U, 256U, 351U, 0x7FU};
        if (!route.expect_blocked &&
            (route.scene != 31U && route.scene != 34U)) {
            std::cerr << "Object-bounds census QA: clear lookup route is "
                         "not a profiled shared scene\n";
            return 3;
        }
        if (!route.expect_blocked &&
            (records.size() <= 20U ||
             !matches(records[20U], kScene31AdjacentBlocker))) {
            std::cerr << "Object-bounds census QA: adjacent ROM 0x7F "
                         "record does not match Scene " << route.scene
                      << '\n';
            return 3;
        }
        if (!four_side_object_lookup_passed && route.scene == 2U &&
            route.region_record_index == 1U) {
            if (!run_scene2_object_bounds_four_side_lookup_qa(
                    metadata,
                    output / "scene-02-record-1-four-side-lookup.tsv")) {
                std::cerr << "Object-bounds census QA: four-side ROM lookup "
                             "did not match record 1\n";
                return 3;
            }
            four_side_object_lookup_passed = true;
        }
        if (route.prealign_heading) {
            bool source_heading_aligned = false;
            for (std::uint16_t tick = 0U; tick < 32U; ++tick) {
                field_scene.set_controller_nibble(route.input_nibble);
                field_scene.advance_frame();
                if (field_scene.field_entity_heading_for_dump() ==
                    field_scene.field_entity_target_heading_for_dump()) {
                    source_heading_aligned = true;
                    break;
                }
                if (field_scene.field_scene_reference_for_dump() !=
                        route.scene || field_scene.dialogue_open() ||
                    field_scene.field_interaction_open()) {
                    break;
                }
            }
            field_scene.set_controller_nibble(0U);
            for (std::uint8_t settle = 0U; settle < 24U; ++settle) {
                field_scene.advance_frame();
            }
            if (!source_heading_aligned ||
                field_scene.field_scene_reference_for_dump() != route.scene ||
                field_scene.dialogue_open() ||
                field_scene.field_interaction_open()) {
                std::cerr << "Object-bounds census QA: source heading could "
                             "not be aligned for " << route.name << '\n';
                return 3;
            }
        }
        const auto center_view_on = [&field_scene](
                                        const SceneRunnerPosition position) {
            field_scene.set_field_entity_world_position_for_dump(
                position.x, position.y);
            field_scene.set_field_camera_world_position_for_dump(
                position.x > 160U * 16U
                    ? static_cast<std::uint16_t>(position.x - 160U * 16U)
                    : 0U,
                position.y > 112U * 16U
                    ? static_cast<std::uint16_t>(position.y - 112U * 16U)
                    : 0U);
        };
        center_view_on(SceneRunnerPosition{route.start_x, route.start_y});
        field_scene.set_terrain_probe_trace_enabled_for_dump(true);
        const auto render = [&field_scene] { return render_qa_field(field_scene); };
        const auto save = [&](const std::filesystem::path& path,
                              const QImage& image) {
            return field_scene.field_entity_active_for_dump() &&
                   field_scene.field_entity_visible_for_dump() &&
                   image.size() == QSize(kSceneWidth, kSceneHeight) &&
                   field_hud_chrome_survives(image, asset_root) &&
                   image.save(QString::fromStdWString(path.wstring()));
        };
        const auto start = field_scene.field_entity_world_position();
        if (!save(route_output / "entry.bmp", render())) {
            field_scene.set_terrain_probe_trace_enabled_for_dump(false);
            std::cerr << "Object-bounds census QA: entry frame failed for "
                      << route.name << '\n';
            return 3;
        }
        std::ofstream trace(route_output / "terrain-probes.tsv",
                            std::ios::trunc);
        if (!trace) {
            field_scene.set_terrain_probe_trace_enabled_for_dump(false);
            std::cerr << "Object-bounds census QA: trace could not be written "
                      << "for " << route.name << '\n';
            return 3;
        }
        trace << "tick\tbefore_x_fixed\tbefore_y_fixed\tafter_x_fixed"
                "\tafter_y_fixed\tcandidate_x_fixed\tcandidate_y_fixed"
                "\tnormalized_x\tnormalized_y\tcorner0_x\tcorner0_y"
                "\tcorner0_byte\tcorner1_x\tcorner1_y\tcorner1_byte"
                "\tcorner2_x\tcorner2_y\tcorner2_byte\tcorner3_x"
                "\tcorner3_y\tcorner3_byte\traw_terrain"
                "\tcollision_result\toutside_bounds\n";
        field_scene.set_controller_nibble(route.input_nibble);
        bool behavior_observed = false;
        bool lookup_clear_observed = false;
        bool entered_source_region = false;
        bool source_stop_observed = false;
        bool retained_approach_side = false;
        std::uint16_t contact_tick = 0U;
        SceneRunnerPosition before_contact{};
        SceneRunnerPosition after_contact{};
        FieldTerrainProbeTrace contact_probe{};
        FieldTerrainProbeTrace lookup_probe{};
        for (std::uint16_t tick = 1U; tick <= 120U; ++tick) {
            const auto before = field_scene.field_entity_world_position();
            center_view_on(before);
            const auto before_frame = render();
            field_scene.advance_frame();
            const auto after = field_scene.field_entity_world_position();
            center_view_on(after);
            const auto after_frame = render();
            for (const auto& probe : field_scene.terrain_probe_trace_for_dump()) {
                trace << tick << '\t' << before.x << '\t' << before.y << '\t'
                      << after.x << '\t' << after.y << '\t'
                      << probe.candidate_x_fixed << '\t'
                      << probe.candidate_y_fixed << '\t'
                      << probe.normalized_x << '\t' << probe.normalized_y;
                for (std::size_t corner = 0U;
                     corner < probe.terrain_bytes.size(); ++corner) {
                    trace << '\t' << probe.corner_x[corner] << '\t'
                          << probe.corner_y[corner] << "\t0x" << std::hex
                          << static_cast<unsigned>(probe.terrain_bytes[corner])
                          << std::dec;
                }
                trace << "\t0x" << std::hex
                      << static_cast<unsigned>(static_cast<std::uint8_t>(
                             probe.raw_terrain_code))
                      << "\t0x" << static_cast<unsigned>(
                             static_cast<std::uint16_t>(probe.collision_result))
                      << std::dec << '\t' << probe.outside_bounds << '\n';
                if (probe.outside_bounds) {
                    continue;
                }
                if (route.expect_blocked &&
                    probe.raw_terrain_code == route.region.value &&
                    probe.collision_result == 0x7F) {
                    behavior_observed = true;
                    contact_tick = tick;
                    before_contact = before;
                    after_contact = after;
                    contact_probe = probe;
                    const auto after_x = static_cast<std::uint16_t>(
                        after.x >> 4U);
                    const auto after_y = static_cast<std::uint16_t>(
                        after.y >> 4U);
                    switch (route.side) {
                    case Side::west:
                        retained_approach_side = after_x < route.region.left;
                        break;
                    case Side::east:
                        retained_approach_side = after_x > route.region.right;
                        break;
                    case Side::north:
                        retained_approach_side = after_y < route.region.top;
                        break;
                    case Side::south:
                        retained_approach_side = after_y > route.region.bottom;
                        break;
                    }
                    if (!save(route_output / "contact-before.bmp",
                              before_frame) ||
                        !save(route_output / "contact-after.bmp",
                              after_frame)) {
                        field_scene.set_controller_nibble(0U);
                        field_scene.set_terrain_probe_trace_enabled_for_dump(
                            false);
                        std::cerr << "Object-bounds census QA: contact frame "
                                     "failed for " << route.name << '\n';
                        return 3;
                    }
                    break;
                }
                if (!route.expect_blocked &&
                    probe.raw_terrain_code == route.region.value &&
                    probe.collision_result == 0) {
                    behavior_observed = true;
                    if (!lookup_clear_observed) {
                        lookup_clear_observed = true;
                        lookup_probe = probe;
                        if (!save(route_output / "terrain-code-clear.bmp",
                                  after_frame)) {
                            field_scene.set_controller_nibble(0U);
                            field_scene.set_terrain_probe_trace_enabled_for_dump(
                                false);
                            std::cerr
                                << "Object-bounds census QA: clear-code frame "
                                   "failed for " << route.name << '\n';
                            return 3;
                        }
                    }
                    entered_source_region = entered_source_region ||
                        static_cast<std::uint16_t>(after.x >> 4U) >=
                            route.region.left;
                }
                if (!route.expect_blocked && !probe.outside_bounds &&
                    probe.raw_terrain_code == 0x7F &&
                    probe.collision_result == 0x7F) {
                    source_stop_observed = true;
                    contact_tick = tick;
                    before_contact = before;
                    after_contact = after;
                    contact_probe = probe;
                    if (!save(route_output / "contact-before.bmp",
                              before_frame) ||
                        !save(route_output / "contact-after.bmp",
                              after_frame)) {
                        field_scene.set_controller_nibble(0U);
                        field_scene.set_terrain_probe_trace_enabled_for_dump(
                            false);
                        std::cerr << "Object-bounds census QA: neighboring "
                                     "blocker frame failed for " << route.name
                                  << '\n';
                        return 3;
                    }
                }
            }
            if ((route.expect_blocked && behavior_observed) ||
                (!route.expect_blocked && source_stop_observed)) {
                break;
            }
        }
        field_scene.set_controller_nibble(0U);
        field_scene.set_terrain_probe_trace_enabled_for_dump(false);
        center_view_on(field_scene.field_entity_world_position());
        const auto actual = render();
        if (actual.size() != QSize(kSceneWidth, kSceneHeight) ||
            !field_hud_chrome_survives(actual, asset_root) ||
            !actual.save(QString::fromStdWString(
                (route_output / "actual.bmp").wstring()))) {
            std::cerr << "Object-bounds census QA: settled frame failed for "
                      << route.name << '\n';
            return 3;
        }
        const auto position_matches = [](const SceneRunnerPosition actual,
                                         const SceneRunnerPosition expected) {
            return actual.x == expected.x && actual.y == expected.y;
        };
        const bool stop_evidence_matches =
            !expected.pin_exact ||
            (position_matches(before_contact, expected.before) &&
            position_matches(
                SceneRunnerPosition{contact_probe.candidate_x_fixed,
                                    contact_probe.candidate_y_fixed},
                expected.candidate) &&
            position_matches(after_contact, expected.after) &&
            contact_probe.terrain_bytes == expected.stop_corners);
        const bool lookup_evidence_matches = !expected.has_lookup_probe ||
            (position_matches(
                 SceneRunnerPosition{lookup_probe.candidate_x_fixed,
                                     lookup_probe.candidate_y_fixed},
                 expected.lookup_candidate) &&
             lookup_probe.terrain_bytes == expected.lookup_corners);
        const bool result_matches = route.expect_blocked
            ? behavior_observed && retained_approach_side &&
                  contact_probe.collision_result == 0x7F &&
                  stop_evidence_matches
            : lookup_clear_observed && entered_source_region &&
                  source_stop_observed && lookup_probe.collision_result == 0 &&
                  lookup_probe.raw_terrain_code == route.region.value &&
                  contact_probe.raw_terrain_code == 0x7F &&
                  contact_probe.collision_result == 0x7F &&
                  static_cast<std::uint16_t>(after_contact.x >> 4U) >=
                      route.region.left && stop_evidence_matches &&
                  lookup_evidence_matches;
        if (!result_matches || field_scene.field_scene_reference_for_dump() !=
                route.scene || !audio_events.empty()) {
            std::cerr << "Object-bounds census QA: host result differs from "
                         "ROM for " << route.name << " (observed="
                      << behavior_observed << ", retained_side="
                      << retained_approach_side << ", crossed="
                      << entered_source_region << ", lookup_clear="
                      << lookup_clear_observed << ", source_stop="
                      << source_stop_observed << ", expected_blocked="
                      << route.expect_blocked << ", before="
                      << before_contact.x << ',' << before_contact.y
                      << ", after=" << after_contact.x << ','
                      << after_contact.y << ", candidate="
                      << contact_probe.candidate_x_fixed << ','
                      << contact_probe.candidate_y_fixed
                      << ", stop_evidence_matches="
                      << stop_evidence_matches
                      << ", lookup_evidence_matches="
                      << lookup_evidence_matches << ")\n";
            return 3;
        }
        census << route.scene << '\t' << route.region_record_index << "\t0x"
               << std::hex << route.region_record_address << std::dec << '\t'
               << static_cast<unsigned>(route.region.value) << '\t'
               << route.region.left << '\t' << route.region.right << '\t'
               << route.region.top << '\t' << route.region.bottom << '\t'
               << route.lookup_record_index << "\t0x" << std::hex
               << route.lookup_record_address << std::dec << '\t'
               << route.lookup.left << '\t' << route.lookup.right << '\t'
               << route.lookup.top << '\t' << route.lookup.bottom << "\t0x"
               << std::hex << static_cast<unsigned>(route.input_nibble)
               << std::dec << '\t' << contact_tick << '\t' << start.x << '\t'
               << start.y << '\t' << before_contact.x << '\t'
               << before_contact.y << '\t'
               << contact_probe.candidate_x_fixed << '\t'
               << contact_probe.candidate_y_fixed << '\t' << after_contact.x
               << '\t' << after_contact.y << '\t'
               << (route.expect_blocked
                       ? contact_probe.candidate_x_fixed
                       : lookup_probe.candidate_x_fixed)
               << '\t'
               << (route.expect_blocked
                       ? contact_probe.candidate_y_fixed
                       : lookup_probe.candidate_y_fixed)
               << "\t0x" << std::hex << static_cast<unsigned>(
                      route.expect_blocked
                          ? static_cast<std::uint16_t>(
                                contact_probe.collision_result)
                          : static_cast<std::uint16_t>(
                                lookup_probe.collision_result))
               << std::dec << '\t'
               << (route.expect_blocked ? route.region_record_index : 20U)
               << "\t0x" << std::hex
               << (route.expect_blocked
                       ? route.region_record_address
                       : 0x1DB6C0U)
               << std::dec;
        for (const auto value : contact_probe.terrain_bytes) {
            census << "\t0x" << std::hex << static_cast<unsigned>(value)
                   << std::dec;
        }
        census << "\t0x" << std::hex
               << static_cast<unsigned>(static_cast<std::uint8_t>(
                      contact_probe.raw_terrain_code))
               << "\t0x" << static_cast<unsigned>(
                      static_cast<std::uint16_t>(contact_probe.collision_result))
               << std::dec << '\t'
               << (route.expect_blocked
                       ? "blocked-at-object-lookup"
                       : "code-clear-entry-then-neighboring-0x7F")
               << '\t' << field_scene.field_entity_active_for_dump() << '\t'
               << field_scene.field_entity_visible_for_dump() << '\t'
               << field_scene.field_camera_follow_for_dump().camera_x << '\t'
               << field_scene.field_camera_follow_for_dump().camera_y << '\t'
               << field_scene.field_entity_screen_x_for_dump() << '\t'
               << field_scene.field_entity_screen_y_for_dump()
               << "\tno exact longplay contact\n";
    }
    if (!four_side_object_lookup_passed) {
        std::cerr << "Object-bounds census QA: four-side lookup was not run\n";
        return 3;
    }
    std::cout << "low_code_object_bounds_census_qa=passed routes="
              << kRoutes.size() << " blocked=" << (kRoutes.size() - 2U)
              << " lookup_clear=2 four_side_lookup=record-1 artifacts="
              << output.string() << '\n';
    return 0;
}

int run_field_elevator_physical_entry_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    const auto route_output = output / "scene2-event1-route";
    if (run_field_scene26_event1_physical_entry_qa(
            field_scene, asset_root, route_output, field_audio_events,
            source_boundaries) != 0) {
        return 3;
    }

    const auto selector_output = output / "scene26-event29-elevator";
    std::error_code output_error;
    std::filesystem::remove_all(selector_output, output_error);
    if (output_error) {
        std::cerr << "Elevator physical-entry QA: could not clear captures: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(selector_output, output_error);
    if (output_error) {
        std::cerr << "Elevator physical-entry QA: could not create captures: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::ofstream manifest(selector_output / "frames.tsv", std::ios::trunc);
    if (!manifest) {
        std::cerr << "Elevator physical-entry QA: could not write frames.tsv\n";
        return 3;
    }
    manifest << "stage\tframe\tscene\tselector_open\tcurrent_floor"
                "\tselected_floor\tfeedback\tfeedback_frames_remaining"
                "\tanimation\tanimation_frame\taudio_event_count"
                "\ttransition_phase\ttransition_palette_step"
                "\ttransition_vblanks_in_step\ttransition_alpha\timage\n";

    std::error_code timeline_directory_error;
    std::filesystem::create_directories(selector_output / "timeline",
                                        timeline_directory_error);
    if (timeline_directory_error) {
        std::cerr << "Elevator physical-entry QA: could not create complete "
                     "frame capture: "
                  << timeline_directory_error.message() << '\n';
        return 3;
    }
    std::ofstream timeline_manifest(selector_output / "timeline.tsv",
                                    std::ios::trunc);
    if (!timeline_manifest) {
        std::cerr << "Elevator physical-entry QA: could not write complete "
                     "frame manifest\n";
        return 3;
    }
    timeline_manifest
        << "frame\tscene\tselector_open\tcurrent_floor\tselected_floor"
           "\tfeedback\tfeedback_frames_remaining\tanimation"
           "\tanimation_frame\taudio_event_count\ttransition_phase"
           "\ttransition_palette_step\ttransition_vblanks_in_step"
           "\ttransition_alpha\tinput\timage\n";
    bool timeline_capture_ok = true;
    std::uint32_t timeline_frame_count = 0U;
    auto timeline_input = std::string("neutral");

    std::uint32_t frame = 0U;
    const auto render = [&field_scene] { return render_qa_field(field_scene, false, QImage::Format_ARGB32); };
    const auto capture_timeline_frame = [&] {
        if (!timeline_capture_ok) {
            return;
        }
        const auto image = render();
        const auto name = std::string("timeline/frame-") +
                          std::to_string(frame) + ".png";
        const auto path = selector_output / name;
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            timeline_capture_ok = false;
            return;
        }
        timeline_manifest
            << frame << '\t'
            << field_scene.field_scene_reference_for_dump() << '\t'
            << field_scene.elevator_selector_open_for_dump() << '\t'
            << static_cast<unsigned>(
                   field_scene.elevator_selector_current_floor_for_dump())
            << '\t'
            << static_cast<unsigned>(
                   field_scene.elevator_selector_selected_floor_for_dump())
            << '\t'
            << static_cast<unsigned>(field_scene
                                         .elevator_selector_navigation_feedback_for_dump())
            << '\t'
            << static_cast<unsigned>(field_scene
                                         .elevator_selector_navigation_feedback_frames_remaining_for_dump())
            << '\t' << field_scene.elevator_selector_animating_for_dump()
            << '\t'
            << static_cast<unsigned>(
                   field_scene.elevator_selector_animation_frame_for_dump())
            << '\t' << field_audio_events.size() << '\t'
            << static_cast<unsigned>(field_scene
                                         .elevator_scene_transition_phase_for_dump())
            << '\t' << static_cast<unsigned>(field_scene
                                                 .elevator_scene_transition_palette_step_for_dump())
            << '\t' << static_cast<unsigned>(field_scene
                                                 .elevator_scene_transition_vblanks_for_dump())
            << '\t' << static_cast<unsigned>(field_scene
                                                 .elevator_scene_transition_fade_alpha_for_dump())
            << '\t' << timeline_input << '\t' << name << '\n';
        ++timeline_frame_count;
    };
    const auto tick_frame = [&] {
        field_scene.advance_frame();
        ++frame;
        capture_timeline_frame();
    };
    const auto save = [&](const std::string_view stage) {
        const auto image = render();
        const auto name = std::string(stage) + ".bmp";
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(
                (selector_output / name).wstring()))) {
            return QImage{};
        }
        manifest << stage << '\t' << frame << '\t'
                 << field_scene.field_scene_reference_for_dump() << '\t'
                 << field_scene.elevator_selector_open_for_dump() << '\t'
                 << static_cast<unsigned>(
                        field_scene.elevator_selector_current_floor_for_dump())
                 << '\t'
                 << static_cast<unsigned>(
                        field_scene.elevator_selector_selected_floor_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_selector_navigation_feedback_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_selector_navigation_feedback_frames_remaining_for_dump())
                 << '\t'
                 << field_scene.elevator_selector_animating_for_dump() << '\t'
                 << static_cast<unsigned>(
                        field_scene.elevator_selector_animation_frame_for_dump())
                 << '\t' << field_audio_events.size() << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_scene_transition_phase_for_dump())
                 << '\t' << static_cast<unsigned>(field_scene
                                                      .elevator_scene_transition_palette_step_for_dump())
                 << '\t' << static_cast<unsigned>(field_scene
                                                      .elevator_scene_transition_vblanks_for_dump())
                 << '\t' << static_cast<unsigned>(field_scene
                                                      .elevator_scene_transition_fade_alpha_for_dump())
                 << '\t' << name << '\n';
        manifest.flush();
        return image;
    };
    const auto tap_dpad = [&](const std::uint8_t nibble) {
        timeline_input = nibble == 0x01U ? "dpad-up"
                         : nibble == 0x02U ? "dpad-down"
                                           : "dpad-other";
        field_scene.set_controller_nibble(nibble);
        tick_frame();
        timeline_input = "neutral";
        field_scene.set_controller_nibble(0U);
        tick_frame();
    };
    const auto tap_button = [&](const std::uint8_t port_byte) {
        timeline_input = port_byte == 0x20U ? "B"
                         : port_byte == 0x40U ? "A"
                         : port_byte == 0x80U ? "Start"
                                              : "button-other";
        field_scene.set_controller_port_byte(port_byte);
        tick_frame();
        timeline_input = "neutral";
        field_scene.set_controller_port_byte(0U);
        tick_frame();
    };
    const auto no_modal_screen = [&field_scene] {
        return !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open();
    };
    const auto scene26 = field_scene.field_scene_reference_for_dump() == 26U;
    if (!scene26 || field_scene.elevator_selector_open_for_dump() ||
        !no_modal_screen()) {
        std::cerr << "Elevator physical-entry QA: scene-26 event route did not "
                     "leave a live field before the elevator trigger\n";
        return 3;
    }
    capture_timeline_frame();
    const auto& source_metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& rectangles = source_metadata.terrain_collision_rectangles;
    if (rectangles.size() <= 103U ||
        rectangles[102U].left != 0x0080U ||
        rectangles[102U].top != 0x0020U ||
        rectangles[102U].right != 0x009FU ||
        rectangles[102U].bottom != 0x003FU ||
        rectangles[102U].value != 0x00DDU ||
        rectangles[103U].value != 0x00DDU) {
        std::cerr << "Elevator physical-entry QA: scene-26 event-29 source "
                     "rectangles do not match ROM records 102-103\n";
        return 3;
    }

    const auto activity_boundary_count_before = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.world.activity.started"));
    std::uint16_t trigger_ticks = 0U;
    while (trigger_ticks < 120U &&
           !field_scene.elevator_selector_open_for_dump() &&
           field_scene.field_scene_reference_for_dump() == 26U) {
        timeline_input = "dpad-up";
        field_scene.set_controller_nibble(0x01U); // ordinary Up into 0xDD
        tick_frame();
        ++trigger_ticks;
    }
    timeline_input = "neutral";
    field_scene.set_controller_nibble(0U);
    if (field_scene.elevator_selector_open_for_dump()) {
        tick_frame();
    }
    const auto& movement_transition =
        field_scene.last_field_movement_transition_for_dump();
    const auto scene26_map = [&] {
        QImage image(kSceneWidth, kSceneHeight, QImage::Format_ARGB32);
        image.fill(Qt::black);
        QPainter painter(&image);
        field_scene.paint_field_scene_for_dump(painter);
        painter.end();
        return image;
    }();
    if (!field_scene.elevator_selector_open_for_dump() ||
        movement_transition.event_code != FieldCollisionEventCode::event_29 ||
        movement_transition.continuation !=
            MovementModeTransitionContinuation::event_29_world_activity ||
        movement_transition.kind !=
            EntityMovementModeTransitionResultKind::world_activity_started ||
        !no_modal_screen() ||
        field_scene.field_scene_reference_for_dump() != 26U ||
        field_scene.elevator_selector_current_floor_for_dump() != 0U ||
        field_scene.elevator_selector_selected_floor_for_dump() != 0U) {
        std::cerr << "Elevator physical-entry QA: normal Up did not open the "
                     "event-29 selector (ticks=" << trigger_ticks
                  << ", scene=" << field_scene.field_scene_reference_for_dump()
                  << ", open="
                  << field_scene.elevator_selector_open_for_dump()
                  << ", event="
                  << static_cast<unsigned>(movement_transition.event_code)
                  << ", continuation="
                  << static_cast<unsigned>(movement_transition.continuation)
                  << ")\n";
        return 3;
    }
    const auto opening = save("selector-current-1-selected-1");
    if (opening.isNull() ||
        !field_hud_chrome_survives(opening, asset_root) ||
        count_playfield_lit(opening) < 100U || opening == scene26_map) {
        std::cerr << "Elevator physical-entry QA: full-screen selector did not "
                     "replace the field scene cleanly\n";
        return 3;
    }
    const auto steady = [&] {
        for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
            tick_frame();
        }
        return save("selector-current-1-selected-1-held");
    }();
    if (steady.isNull() || steady != opening) {
        std::cerr << "Elevator physical-entry QA: idle selector frame changed "
                     "or retained a prior page\n";
        return 3;
    }

    const auto audio_before_b = field_audio_events.size();
    tap_button(0x20U); // source B handler 0x391A requests audio event 0x25
    if (field_audio_events.size() != audio_before_b + 1U ||
        field_audio_events.back() != 0x25U) {
        std::cerr << "Elevator physical-entry QA: B did not request source "
                     "sound event 0x25\n";
        return 3;
    }
    tap_dpad(0x01U); // source event bit 8 advances one floor
    const auto selection_feedback_active =
        save("selector-current-1-selected-2-feedback-active");
    if (selection_feedback_active.isNull() ||
        field_scene.elevator_selector_navigation_feedback_for_dump() !=
            ElevatorSelectorNavigationFeedback::next_floor_active) {
        std::cerr << "Elevator physical-entry QA: source next-floor button "
                     "feedback did not appear on selection\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 6U; ++tick) {
        tick_frame();
    }
    const auto selection_feedback_last_active =
        save("selector-current-1-selected-2-feedback-tick-7");
    if (selection_feedback_last_active.isNull() ||
        field_scene.elevator_selector_navigation_feedback_for_dump() !=
            ElevatorSelectorNavigationFeedback::next_floor_active ||
        field_scene.elevator_selector_navigation_feedback_frames_remaining_for_dump() !=
            1U) {
        std::cerr << "Elevator physical-entry QA: navigation feedback did not "
                     "hold for its source eight-VBlank window\n";
        return 3;
    }
    tick_frame();
    if (field_scene.elevator_selector_navigation_feedback_for_dump() !=
        ElevatorSelectorNavigationFeedback::next_floor_rest) {
        std::cerr << "Elevator physical-entry QA: navigation feedback did not "
                     "restore the source arrow state after eight VBlanks\n";
        return 3;
    }
    const auto current_one_selected_two =
        save("selector-current-1-selected-2");
    if (current_one_selected_two.isNull() ||
        field_scene.elevator_selector_current_floor_for_dump() != 0U ||
        field_scene.elevator_selector_selected_floor_for_dump() != 1U) {
        std::cerr << "Elevator physical-entry QA: selected floor label did "
                     "not change independently of current floor\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
        tick_frame();
    }
    const auto current_one_selected_two_held =
        save("selector-current-1-selected-2-held");
    if (current_one_selected_two_held.isNull() ||
        current_one_selected_two_held != current_one_selected_two) {
        std::cerr << "Elevator physical-entry QA: resting arrow feedback or "
                     "floor labels changed during a 30-frame hold\n";
        return 3;
    }
    const QRect current_floor_label_region(220, 24, 40, 40);
    const QRect selected_floor_label_region(220, 88, 40, 48);
    if (opening.copy(current_floor_label_region) !=
            current_one_selected_two.copy(current_floor_label_region) ||
        opening.copy(selected_floor_label_region) ==
            current_one_selected_two.copy(selected_floor_label_region) ||
        !image_region_has_color(current_one_selected_two, 220, 88, 40, 48,
                                QColor(255, 219, 0))) {
        std::cerr << "Elevator physical-entry QA: selection changed the "
                     "current-floor label or left the selected-floor label "
                     "unchanged\n";
        return 3;
    }

    timeline_input = "A";
    field_scene.set_controller_port_byte(0x40U); // source A starts 0x58FF8
    tick_frame();
    if (!field_scene.elevator_selector_animating_for_dump() ||
        field_scene.elevator_selector_animation_frame_for_dump() != 16U) {
        std::cerr << "Elevator physical-entry QA: A did not start the source "
                     "17-frame elevator sequence\n";
        return 3;
    }
    timeline_input = "neutral";
    field_scene.set_controller_port_byte(0U);
    tick_frame(); // first of eight source VBlanks on frame 16
    const auto animation_start = save("animation-frame-16");
    if (animation_start.isNull()) {
        return 3;
    }
    for (std::size_t tick = 2U;
         tick <= kElevatorSelectorAnimationFrameCount *
                     kElevatorSelectorAnimationFrameDelay;
         ++tick) {
        tick_frame();
        if (tick == 8U || tick == 40U || tick == 80U || tick == 128U ||
            tick == kElevatorSelectorAnimationFrameCount *
                       kElevatorSelectorAnimationFrameDelay) {
            const auto checkpoint =
                std::string("animation-tick-") + std::to_string(tick);
            if (save(checkpoint).isNull()) {
                return 3;
            }
        }
    }
    if (field_scene.elevator_selector_animating_for_dump() ||
        field_scene.elevator_selector_current_floor_for_dump() != 1U ||
        field_scene.elevator_selector_selected_floor_for_dump() != 1U) {
        std::cerr << "Elevator physical-entry QA: one floor did not advance "
                     "after 17 frames x 8 VBlanks\n";
        return 3;
    }
    const auto current_two_selected_two =
        save("selector-current-2-selected-2");
    if (current_two_selected_two.isNull() ||
        current_one_selected_two.copy(current_floor_label_region) ==
            current_two_selected_two.copy(current_floor_label_region) ||
        current_one_selected_two.copy(selected_floor_label_region) !=
            current_two_selected_two.copy(selected_floor_label_region)) {
        std::cerr << "Elevator physical-entry QA: completed lift travel did "
                     "not update only the current-floor label\n";
        return 3;
    }
    tap_dpad(0x01U);
    const auto current_two_selected_three_feedback_active =
        save("selector-current-2-selected-3-feedback-active");
    if (current_two_selected_three_feedback_active.isNull() ||
        field_scene.elevator_selector_current_floor_for_dump() != 1U ||
        field_scene.elevator_selector_selected_floor_for_dump() != 2U ||
        field_scene.elevator_selector_navigation_feedback_for_dump() !=
            ElevatorSelectorNavigationFeedback::next_floor_active) {
        std::cerr << "Elevator physical-entry QA: independently selected "
                     "third-floor label is missing\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 7U; ++tick) {
        tick_frame();
    }
    if (field_scene.elevator_selector_navigation_feedback_for_dump() !=
        ElevatorSelectorNavigationFeedback::next_floor_rest) {
        std::cerr << "Elevator physical-entry QA: second arrow response did "
                     "not finish after the source wait\n";
        return 3;
    }
    const auto current_two_selected_three_rest =
        save("selector-current-2-selected-3");
    if (current_two_selected_three_rest.isNull() ||
        current_two_selected_three_rest ==
            current_two_selected_three_feedback_active ||
        !image_region_has_color(current_two_selected_three_rest, 220, 24, 40,
                                40, QColor(255, 219, 0)) ||
        !image_region_has_color(current_two_selected_three_rest, 220, 88, 40,
                                48, QColor(255, 219, 0))) {
        std::cerr << "Elevator physical-entry QA: current and selected floor "
                     "digits were not both visible over resting arrows\n";
        return 3;
    }
    const auto actual = save("actual");
    if (actual.isNull() || actual != current_two_selected_three_rest) {
        std::cerr << "Elevator physical-entry QA: CLI actual.bmp did not capture "
                     "the stable selector scene\n";
        return 3;
    }
    timeline_input = "A";
    field_scene.set_controller_port_byte(0x40U);
    tick_frame();
    if (!field_scene.elevator_selector_animating_for_dump() ||
        field_scene.elevator_selector_animation_frame_for_dump() != 16U) {
        return 3;
    }
    timeline_input = "neutral";
    field_scene.set_controller_port_byte(0U);
    tick_frame();
    for (std::size_t tick = 2U;
         tick <= kElevatorSelectorAnimationFrameCount *
                     kElevatorSelectorAnimationFrameDelay;
         ++tick) {
        tick_frame();
    }
    if (field_scene.elevator_selector_current_floor_for_dump() != 2U ||
        field_scene.elevator_selector_selected_floor_for_dump() != 2U ||
        field_scene.elevator_selector_animating_for_dump()) {
        std::cerr << "Elevator physical-entry QA: third-floor preview did not "
                     "settle at source cadence\n";
        return 3;
    }
    const auto third_floor_preview = save("selector-current-3-selected-3");
    if (third_floor_preview.isNull()) {
        return 3;
    }
    tap_dpad(0x02U); // highlight the previous floor without moving the lift
    for (std::uint8_t tick = 0U;
         field_scene
                 .elevator_selector_navigation_feedback_frames_remaining_for_dump() !=
             0U &&
         tick < kElevatorSelectorNavigationFeedbackFrameCount;
         ++tick) {
        tick_frame();
    }
    const auto current_three_selected_two =
        save("selector-current-3-selected-2-unconfirmed");
    if (current_three_selected_two.isNull() ||
        field_scene.elevator_selector_current_floor_for_dump() != 2U ||
        field_scene.elevator_selector_selected_floor_for_dump() != 1U ||
        field_scene.elevator_selector_animating_for_dump()) {
        std::cerr << "Elevator physical-entry QA: moving the highlight after "
                     "A changed the lift floor without another A press\n";
        return 3;
    }
    tap_button(0x80U); // Start begins the source 0x131C palette fade.
    if (!field_scene.elevator_selector_open_for_dump() ||
        field_scene.elevator_scene_transition_phase_for_dump() !=
            ElevatorSceneTransitionPhase::fading_to_black ||
        field_scene.elevator_scene_transition_palette_step_for_dump() != 0U ||
        field_scene.elevator_scene_transition_vblanks_for_dump() != 1U) {
        std::cerr << "Elevator physical-entry QA: Start did not enter the "
                     "source-timed destination fade\n";
        return 3;
    }
    for (std::uint8_t palette_step = 1U;
         palette_step <= kElevatorSceneTransitionPaletteStepCount;
         ++palette_step) {
        if (palette_step != 1U) {
            tick_frame(); // first of the two source VBlanks for this pass
        }
        tick_frame(); // second VBlank advances one source palette pass
        const auto final_fade_out =
            palette_step == kElevatorSceneTransitionPaletteStepCount;
        const auto transition_state_matches = final_fade_out
            ? field_scene.field_scene_reference_for_dump() == 28U &&
                  field_scene.elevator_scene_transition_phase_for_dump() ==
                      ElevatorSceneTransitionPhase::fading_from_black &&
                  field_scene.elevator_scene_transition_palette_step_for_dump() ==
                      0U &&
                  field_scene.elevator_scene_transition_fade_alpha_for_dump() ==
                      255U
            : field_scene.field_scene_reference_for_dump() == 26U &&
                  field_scene.elevator_scene_transition_phase_for_dump() ==
                      ElevatorSceneTransitionPhase::fading_to_black &&
                  field_scene.elevator_scene_transition_palette_step_for_dump() ==
                      palette_step &&
                  field_scene.elevator_scene_transition_fade_alpha_for_dump() !=
                      0U;
        if (!transition_state_matches) {
            std::cerr << "Elevator physical-entry QA: fade-out palette pass "
                         "did not advance at the source cadence\n";
            return 3;
        }
        const auto checkpoint = std::string("destination-fade-out-step-") +
                                std::to_string(palette_step);
        if (save(checkpoint).isNull()) {
            return 3;
        }
    }
    const auto black_handoff = save("destination-black-handoff");
    QImage expected_black(kSceneWidth, kSceneHeight, QImage::Format_ARGB32);
    expected_black.fill(Qt::black);
    if (black_handoff.isNull() || black_handoff != expected_black ||
        field_scene.field_scene_reference_for_dump() != 28U ||
        field_scene.elevator_selector_open_for_dump() ||
        field_scene.elevator_scene_transition_phase_for_dump() !=
            ElevatorSceneTransitionPhase::fading_from_black ||
        field_scene.elevator_scene_transition_fade_alpha_for_dump() != 255U) {
        std::cerr << "Elevator physical-entry QA: scene handoff did not replace "
                     "the selector at full black\n";
        return 3;
    }
    for (std::uint8_t palette_step = 1U;
         palette_step <= kElevatorSceneTransitionPaletteStepCount;
         ++palette_step) {
        tick_frame(); // first source VBlank in the palette step wait
        if (palette_step == 9U) {
            const auto midpoint = save("destination-fade-in-midpoint");
            if (midpoint.isNull() ||
                field_scene.elevator_scene_transition_fade_alpha_for_dump() <
                    100U ||
                field_scene.elevator_scene_transition_fade_alpha_for_dump() >
                    155U) {
                std::cerr << "Elevator physical-entry QA: destination fade "
                             "midpoint is outside the expected palette range\n";
                return 3;
            }
        }
        tick_frame(); // second VBlank advances one source palette pass
        if (field_scene.elevator_scene_transition_palette_step_for_dump() !=
            palette_step) {
            std::cerr << "Elevator physical-entry QA: fade-in palette pass "
                         "did not advance at the source cadence\n";
            return 3;
        }
        const auto checkpoint = std::string("destination-fade-in-step-") +
                                std::to_string(palette_step);
        if (save(checkpoint).isNull()) {
            return 3;
        }
    }
    const auto destination_position =
        field_scene.field_entity_world_position();
    const auto destination_landing_position =
        field_scene.state().field_scene_buffers.source_metadata
            .initial_field_records[0U];
    const auto destination = save("scene28-entry");
    if (destination.isNull() ||
        field_scene.field_scene_reference_for_dump() != 28U ||
        field_scene.elevator_selector_open_for_dump() ||
        field_scene.elevator_scene_transition_phase_for_dump() !=
            ElevatorSceneTransitionPhase::idle ||
        field_scene.elevator_scene_transition_fade_alpha_for_dump() != 0U ||
        destination_position.x != destination_landing_position.x ||
        destination_position.y != destination_landing_position.y ||
        !field_scene.field_entity_visible_for_dump() ||
        !field_hud_chrome_survives(destination, asset_root) ||
        destination == third_floor_preview || !no_modal_screen()) {
        std::cerr << "Elevator physical-entry QA: selected child scene did not "
                     "use its ROM profile lift landing\n";
        return 3;
    }
    const auto activity_boundary_count_after = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.world.activity.started"));
    if (activity_boundary_count_after <= activity_boundary_count_before ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.selector.opened") == source_boundaries.end() ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.destination_loaded") ==
            source_boundaries.end() ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.destination_fade_out_started") ==
            source_boundaries.end() ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.destination_fade_in_started") ==
            source_boundaries.end() ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.destination_fade_finished") ==
            source_boundaries.end()) {
        std::cerr << "Elevator physical-entry QA: source activity or native "
                     "destination transition boundary is missing\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
        tick_frame();
    }
    const auto destination_held = save("scene28-held-30-frames");
    if (destination_held.isNull() || destination_held != destination) {
        std::cerr << "Elevator physical-entry QA: destination frame retained "
                     "selector graphics or changed during idle hold\n";
        return 3;
    }
    timeline_manifest.flush();
    if (!timeline_capture_ok || timeline_frame_count != frame + 1U) {
        std::cerr << "Elevator physical-entry QA: complete timeline capture "
                     "did not include every update (captured="
                  << timeline_frame_count << ", expected=" << frame + 1U
                  << ")\n";
        return 3;
    }
    if (run_field_elevator_floor_group_roundtrip_qa(
            field_scene, asset_root, output / "floor-group-roundtrip",
            field_audio_events, source_boundaries) != 0) {
        return 3;
    }
    std::cout << "field_elevator_physical_entry_qa=passed trigger=scene26/event29 "
                 "records=102,103 selector_frames=17 delay=8 "
                 "destination=28 timeline_frames="
              << timeline_frame_count << " audio_events="
              << field_audio_events.size() << " artifacts="
              << selector_output.string() << '\n';
    return 0;
}

int run_field_elevator_group_route_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::uint16_t scene_id,
    const FieldElevatorSceneGroupSourceRecord& source_group,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries,
    const std::optional<std::uint8_t> destination_floor_override) {
    const auto activity_start_count = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.world.activity.started"));
    const auto collision_dispatch_count = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.map_event.collision_dispatched"));
    const auto selector_open_count = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.elevator.selector.opened"));
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Elevator group route QA: could not clear captures: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output / "timeline", output_error);
    if (output_error) {
        std::cerr << "Elevator group route QA: could not create captures: "
                  << output_error.message() << '\n';
        return 3;
    }

    const auto& metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& rectangles = metadata.terrain_collision_rectangles;
    struct RouteSourceExpectation {
        std::uint16_t scene_id;
        std::uint8_t current_floor;
        RestoredRunnerPosition spawn;
        std::size_t first_trigger_record;
        std::uint16_t first_trigger_x;
        std::uint16_t second_trigger_x;
        std::uint16_t trigger_y;
        std::uint8_t group_count;
        std::array<std::uint16_t, kFieldElevatorSceneGroupMemberCount>
            group_scene_ids;
    };
    const std::array<RouteSourceExpectation, 20U> route_expectations{{
        {21U, 0U, {0x3000U, 0x0600U}, 100U, 0x02E0U, 0x0300U, 0x0020U, 4U,
         {21U, 22U, 23U, 24U, 0U}},
        {22U, 1U, {0x3000U, 0x0600U}, 113U, 0x02E0U, 0x0300U, 0x0020U, 4U,
         {21U, 22U, 23U, 24U, 0U}},
        {23U, 2U, {0x3000U, 0x0600U}, 133U, 0x02E0U, 0x0300U, 0x0020U, 4U,
         {21U, 22U, 23U, 24U, 0U}},
        {24U, 3U, {0x3000U, 0x0600U}, 113U, 0x02E0U, 0x0300U, 0x0020U, 4U,
         {21U, 22U, 23U, 24U, 0U}},
        {25U, 0U, {0x3000U, 0x0600U}, 102U, 0x02E0U, 0x0300U, 0x0020U, 4U,
         {21U, 22U, 23U, 24U, 0U}},
        {29U, 0U, {0x0A00U, 0x0500U}, 112U, 0x0080U, 0x00A0U, 0x0020U, 3U,
         {26U, 27U, 28U, 0U, 0U}},
        {30U, 0U, {0x3A00U, 0x0600U}, 82U, 0x0380U, 0x03A0U, 0x0020U, 4U,
         {30U, 31U, 32U, 33U, 0U}},
        {31U, 1U, {0x3800U, 0x0600U}, 85U, 0x0380U, 0x03A0U, 0x0020U, 4U,
         {30U, 31U, 32U, 33U, 0U}},
        {32U, 2U, {0x3800U, 0x0600U}, 97U, 0x0380U, 0x03A0U, 0x0020U, 4U,
         {30U, 31U, 32U, 33U, 0U}},
        {33U, 3U, {0x3800U, 0x0600U}, 97U, 0x0380U, 0x03A0U, 0x0020U, 4U,
         {30U, 31U, 32U, 33U, 0U}},
        {34U, 0U, {0x3800U, 0x0600U}, 85U, 0x0380U, 0x03A0U, 0x0020U, 4U,
         {30U, 31U, 32U, 33U, 0U}},
        {40U, 0U, {0x1600U, 0x0500U}, 70U, 0x0140U, 0x0160U, 0x0020U, 5U,
         {35U, 36U, 37U, 38U, 39U}},
        {35U, 0U, {0x2800U, 0x1580U}, 117U, 0x0260U, 0x0280U, 0x0120U, 5U,
         {35U, 36U, 37U, 38U, 39U}},
        {36U, 1U, {0x2800U, 0x1580U}, 109U, 0x0260U, 0x0280U, 0x0120U, 5U,
         {35U, 36U, 37U, 38U, 39U}},
        {37U, 2U, {0x2800U, 0x1580U}, 109U, 0x0260U, 0x0280U, 0x0120U, 5U,
         {35U, 36U, 37U, 38U, 39U}},
        {38U, 3U, {0x2800U, 0x1580U}, 112U, 0x0260U, 0x0280U, 0x0120U, 5U,
         {35U, 36U, 37U, 38U, 39U}},
        {39U, 4U, {0x1600U, 0x0500U}, 58U, 0x0140U, 0x0160U, 0x0020U, 5U,
         {35U, 36U, 37U, 38U, 39U}},
        {41U, 0U, {0x0500U, 0x2300U}, 79U, 0x0020U, 0x0040U, 0x01C0U, 2U,
         {41U, 42U, 0U, 0U, 0U}},
        {42U, 1U, {0x0500U, 0x2300U}, 76U, 0x0020U, 0x0040U, 0x01E0U, 2U,
         {41U, 42U, 0U, 0U, 0U}},
        {43U, 0U, {0x0500U, 0x2300U}, 76U, 0x0020U, 0x0040U, 0x01E0U, 2U,
         {41U, 42U, 0U, 0U, 0U}},
    }};
    const auto route_expectation = std::find_if(
        route_expectations.begin(), route_expectations.end(),
        [scene_id](const RouteSourceExpectation& expectation) {
            return expectation.scene_id == scene_id;
        });
    if (route_expectation == route_expectations.end()) {
        std::cerr << "Elevator group route QA: no source route expectation for "
                     "scene "
                  << scene_id << '\n';
        return 3;
    }
    const auto& expected = *route_expectation;
    if (field_scene.field_scene_reference_for_dump() != scene_id ||
        metadata.initial_field_records[0U].x != expected.spawn.x ||
        metadata.initial_field_records[0U].y != expected.spawn.y ||
        source_group.count != expected.group_count ||
        !std::equal(expected.group_scene_ids.begin(),
                    expected.group_scene_ids.begin() + expected.group_count,
                    source_group.scene_ids.begin()) ||
        rectangles.size() <= expected.first_trigger_record + 1U ||
        rectangles[expected.first_trigger_record].left !=
            expected.first_trigger_x ||
        rectangles[expected.first_trigger_record].right !=
            expected.first_trigger_x + 0x001FU ||
        rectangles[expected.first_trigger_record].top != expected.trigger_y ||
        rectangles[expected.first_trigger_record].bottom !=
            expected.trigger_y + 0x001FU ||
        rectangles[expected.first_trigger_record].value != 0x00DDU ||
        rectangles[expected.first_trigger_record + 1U].left !=
            expected.second_trigger_x ||
        rectangles[expected.first_trigger_record + 1U].right !=
            expected.second_trigger_x + 0x001FU ||
        rectangles[expected.first_trigger_record + 1U].top !=
            expected.trigger_y ||
        rectangles[expected.first_trigger_record + 1U].bottom !=
            expected.trigger_y + 0x001FU ||
        rectangles[expected.first_trigger_record + 1U].value != 0x00DDU) {
        std::cerr << "Elevator group route QA: scene " << scene_id
                  << " descriptor spawn, group, or paired event-29 collision "
                     "records do not match the extracted source data\n";
        return 3;
    }
    const auto scene_label = std::to_string(scene_id);

    const auto no_modal_screen = [&field_scene] {
        return !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open();
    };
    const auto render = [&field_scene] { return render_qa_field(field_scene, false, QImage::Format_ARGB32); };
    std::ofstream timeline(output / "timeline.tsv", std::ios::trunc);
    if (!timeline) {
        std::cerr << "Elevator group route QA: could not write timeline.tsv\n";
        return 3;
    }
    timeline << "frame\tscene\tx\ty\tcamera_x\tcamera_y\tmode"
                "\tterrain_code\tprobe_0\tprobe_1\tprobe_2\tprobe_3\tevent"
                "\theading\ttarget_heading\tanimation_heading"
                "\tselector_open"
                "\tcurrent_floor\tselected_floor\tdestination\tfeedback"
                "\tanimation\tanimation_frame\ttransition_phase"
                "\tpalette_step\talpha"
                "\tinput\timage\n";

    std::uint32_t frame = 0U;
    std::uint32_t timeline_frame_count = 0U;
    std::string input_label = "neutral";
    const auto capture = [&]() {
        const auto image = render();
        const auto name = std::string("timeline/frame-") +
                          std::to_string(frame) + ".png";
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(
                (output / name).wstring()))) {
            return false;
        }
        const auto position = field_scene.field_entity_world_position();
        const auto& probe_samples =
            field_scene.field_terrain_sample_bytes_for_dump();
        timeline << frame << '\t'
                 << field_scene.field_scene_reference_for_dump() << '\t'
                 << position.x << '\t' << position.y << '\t'
                 << field_scene.state().field_scene_buffers.camera_x << '\t'
                 << field_scene.state().field_scene_buffers.camera_y << '\t'
                 << field_scene.field_interaction_mode_for_dump() << '\t'
                 << field_scene.field_terrain_collision_code_for_dump() << '\t'
                 << static_cast<unsigned>(probe_samples[0U]) << '\t'
                 << static_cast<unsigned>(probe_samples[1U]) << '\t'
                 << static_cast<unsigned>(probe_samples[2U]) << '\t'
                 << static_cast<unsigned>(probe_samples[3U]) << '\t'
                 << static_cast<unsigned>(
                        field_scene.field_mode_event_code_for_dump())
                 << '\t' << field_scene.field_entity_heading_for_dump()
                 << '\t' << field_scene.field_entity_target_heading_for_dump()
                 << '\t' << field_scene.field_entity_animation_heading_for_dump()
                 << '\t' << field_scene.elevator_selector_open_for_dump()
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_selector_current_floor_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_selector_selected_floor_for_dump())
                 << '\t'
                 << field_scene.elevator_selector_destination_for_dump()
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_selector_navigation_feedback_for_dump())
                 << '\t' << field_scene.elevator_selector_animating_for_dump()
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_selector_animation_frame_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_scene_transition_phase_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_scene_transition_palette_step_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_scene_transition_fade_alpha_for_dump())
                 << '\t' << input_label << '\t' << name << '\n';
        ++timeline_frame_count;
        return true;
    };
    const auto advance = [&]() {
        field_scene.advance_frame();
        ++frame;
        return capture();
    };
    const auto save = [&](const std::string_view name) {
        const auto image = render();
        const auto path = output / (std::string(name) + ".bmp");
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
               image.save(QString::fromStdWString(path.wstring()));
    };
    const auto tap_dpad = [&](const std::uint8_t nibble,
                              const std::string_view label) {
        input_label = label;
        field_scene.set_controller_nibble(nibble);
        const auto input_saved = advance();
        input_label = "neutral";
        field_scene.set_controller_nibble(0U);
        return input_saved && advance();
    };

    const auto initial_position = field_scene.field_entity_world_position();
    if (initial_position.x != expected.spawn.x ||
        initial_position.y != expected.spawn.y ||
        field_scene.field_interaction_mode_for_dump() != 2U ||
        field_scene.field_transition_pending_for_dump() ||
        !no_modal_screen() || !field_hud_chrome_survives(render(), asset_root) ||
        !save("scene" + scene_label + "-descriptor-spawn") || !capture()) {
        std::cerr << "Elevator group route QA: scene " << scene_id
                  << " source descriptor spawn did not produce a clean field "
                     "screen\n";
        return 3;
    }

    std::uint8_t activity_cooldown_frames = 0U;
    while (field_scene.world_activity_request_timeout_for_dump() != 0U &&
           activity_cooldown_frames < 60U) {
        input_label = "activity-cooldown";
        field_scene.set_controller_nibble(0U);
        if (!advance()) {
            return 3;
        }
        ++activity_cooldown_frames;
    }
    if (field_scene.world_activity_request_timeout_for_dump() != 0U) {
        std::cerr << "Elevator group route QA: previous world activity did "
                     "not release after its 60 field frames\n";
        return 3;
    }

    std::uint16_t trigger_frames = 0U;
    while (trigger_frames < 120U &&
           !field_scene.elevator_selector_open_for_dump() &&
           field_scene.field_scene_reference_for_dump() == scene_id) {
        // Scenes 31-34 spawn at x=0x380, on the west edge of the paired
        // event-29 lane. Their ROM collision rectangles place a 0x7F wall
        // immediately west of that lane and another along its east edge; six
        // ordinary Right updates move the runner's collision probes into the
        // open center before the northbound approach. Scene 30's descriptor
        // spawn is already centered at x=0x3A0.
        const bool align_with_elevator_lane =
            scene_id >= 31U && scene_id <= 34U && trigger_frames < 6U;
        input_label = align_with_elevator_lane ? "dpad-right" : "dpad-up";
        field_scene.set_controller_nibble(
            align_with_elevator_lane ? 0x08U : 0x01U);
        if (!advance()) {
            return 3;
        }
        ++trigger_frames;
    }
    input_label = "neutral";
    field_scene.set_controller_nibble(0U);
    if (field_scene.elevator_selector_open_for_dump() && !advance()) {
        return 3;
    }
    const auto& movement =
        field_scene.last_field_movement_transition_for_dump();
    const auto field_only = [&field_scene] {
        QImage image(kSceneWidth, kSceneHeight, QImage::Format_ARGB32);
        image.fill(Qt::black);
        QPainter painter(&image);
        field_scene.paint_field_scene_for_dump(painter);
        painter.end();
        return image;
    }();
    const auto selector_open = render();
    if (!field_scene.elevator_selector_open_for_dump() ||
        movement.event_code != FieldCollisionEventCode::event_29 ||
        movement.continuation !=
            MovementModeTransitionContinuation::event_29_world_activity ||
        movement.kind !=
            EntityMovementModeTransitionResultKind::world_activity_started ||
        field_scene.elevator_selector_current_floor_for_dump() !=
            expected.current_floor ||
        field_scene.elevator_selector_selected_floor_for_dump() !=
            expected.current_floor ||
        field_scene.elevator_selector_destination_for_dump() !=
            source_group.scene_ids[expected.current_floor] ||
        !no_modal_screen() || selector_open == field_only ||
        !field_hud_chrome_survives(selector_open, asset_root) ||
        !save("selector-from-scene" + scene_label)) {
        std::cerr << "Elevator group route QA: physical input from scene "
                  << scene_id << " descriptor spawn did not open the event-29 selector at group "
                     "entry floor "
                  << static_cast<unsigned>(expected.current_floor)
                  << " (frames=" << trigger_frames
                  << ", event=" << static_cast<unsigned>(movement.event_code)
                  << ", field_event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", entity_flags="
                  << static_cast<unsigned>(
                         field_scene.field_entity_behavior_flags_for_dump())
                  << ", terrain_code="
                  << field_scene.field_terrain_collision_code_for_dump()
                  << ", transition_kind="
                  << static_cast<unsigned>(movement.kind)
                  << ", continuation="
                  << static_cast<unsigned>(movement.continuation)
                  << ", activity_starts="
                  << (static_cast<std::size_t>(std::count(
                          source_boundaries.begin(), source_boundaries.end(),
                          "field.world.activity.started")) -
                      activity_start_count)
                  << ", collision_dispatches="
                  << (static_cast<std::size_t>(std::count(
                          source_boundaries.begin(), source_boundaries.end(),
                          "field.map_event.collision_dispatched")) -
                      collision_dispatch_count)
                  << ", selector_open_events="
                  << (static_cast<std::size_t>(std::count(
                          source_boundaries.begin(), source_boundaries.end(),
                          "field.elevator.selector.opened")) -
                      selector_open_count)
                  << ", position="
                  << field_scene.field_entity_world_position().x << ','
                  << field_scene.field_entity_world_position().y
                  << ", resource_countdown="
                  << field_scene.world_frame_logic_for_dump()
                         .resource_countdown
                  << ", activity_timer="
                  << static_cast<unsigned>(
                         field_scene.world_activity_request_timeout_for_dump())
                  << ", activity_countdown="
                  << field_scene.world_frame_logic_for_dump()
                         .activity_countdown
                  << ", selector_open="
                  << field_scene.elevator_selector_open_for_dump()
                  << ", current_floor="
                  << static_cast<unsigned>(field_scene
                                               .elevator_selector_current_floor_for_dump())
                  << ", selected_floor="
                  << static_cast<unsigned>(field_scene
                                               .elevator_selector_selected_floor_for_dump())
                  << ", destination="
                  << field_scene.elevator_selector_destination_for_dump()
                  << ", failure=" << field_scene.failure()
                  << ")\n";
        return 3;
    }

    for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
        if (!advance()) {
            return 3;
        }
    }
    const auto held_selector = render();
    if (held_selector != selector_open || !save("selector-held-30")) {
        std::cerr << "Elevator group route QA: selector changed during its "
                     "neutral hold\n";
        return 3;
    }

    const auto audio_before = field_audio_events.size();
    input_label = "B";
    field_scene.set_controller_port_byte(0x20U);
    const auto b_frame_saved = advance();
    input_label = "neutral";
    field_scene.set_controller_port_byte(0U);
    if (!b_frame_saved || !advance() ||
        field_audio_events.size() != audio_before + 1U ||
        field_audio_events.back() != 0x25U) {
        std::cerr << "Elevator group route QA: B did not request source audio "
                     "event 0x25\n";
        return 3;
    }
    QImage first_selected_floor;
    std::uint8_t selected_floor_index = expected.current_floor;
    const auto navigate_to_floor = [&](const std::uint8_t target_floor) {
        if (target_floor >= source_group.count ||
            target_floor == selected_floor_index) {
            return false;
        }
        while (selected_floor_index != target_floor) {
            const bool moving_up = selected_floor_index < target_floor;
            selected_floor_index = static_cast<std::uint8_t>(
                moving_up ? selected_floor_index + 1U
                          : selected_floor_index - 1U);
            const auto direction_button =
                static_cast<std::uint8_t>(moving_up ? 0x01U : 0x02U);
            const auto direction_label =
                moving_up ? std::string_view("dpad-up")
                          : std::string_view("dpad-down");
            const auto active_feedback =
                moving_up
                    ? ElevatorSelectorNavigationFeedback::next_floor_active
                    : ElevatorSelectorNavigationFeedback::previous_floor_active;
            const auto resting_feedback =
                moving_up
                    ? ElevatorSelectorNavigationFeedback::next_floor_rest
                    : ElevatorSelectorNavigationFeedback::previous_floor_rest;
            if (!tap_dpad(direction_button, direction_label) ||
                field_scene.elevator_selector_current_floor_for_dump() !=
                    expected.current_floor ||
                field_scene.elevator_selector_selected_floor_for_dump() !=
                    selected_floor_index ||
                field_scene.elevator_selector_destination_for_dump() !=
                    source_group.scene_ids[selected_floor_index] ||
                field_scene.elevator_selector_navigation_feedback_for_dump() !=
                    active_feedback) {
                std::cerr << "Elevator group route QA: navigation failed for "
                          << direction_label << " to group index "
                          << static_cast<unsigned>(selected_floor_index)
                          << " in scene "
                          << scene_id << '\n';
                return false;
            }
            if (first_selected_floor.isNull()) {
                first_selected_floor = render();
            }
            const auto destination_label =
                std::to_string(source_group.scene_ids[selected_floor_index]);
            const auto checkpoint_prefix =
                "selector-destination-" + destination_label;
            if (!save(checkpoint_prefix + "-feedback")) {
                return false;
            }
            for (std::uint8_t tick = 0U; tick < 6U; ++tick) {
                if (!advance()) {
                    return false;
                }
            }
            if (field_scene.elevator_selector_navigation_feedback_frames_remaining_for_dump() !=
                    1U ||
                !save(checkpoint_prefix + "-feedback-last") || !advance() ||
                field_scene.elevator_selector_navigation_feedback_for_dump() !=
                    resting_feedback ||
                field_scene.elevator_selector_current_floor_for_dump() !=
                    expected.current_floor ||
                field_scene.elevator_selector_selected_floor_for_dump() !=
                    selected_floor_index ||
                !save(checkpoint_prefix + "-selected")) {
                std::cerr << "Elevator group route QA: " << direction_label
                          << " feedback did not retire after eight VBlanks\n";
                return false;
            }
        }
        return true;
    };

    if (destination_floor_override.has_value()) {
        if (*destination_floor_override >= source_group.count ||
            !navigate_to_floor(*destination_floor_override)) {
            std::cerr << "Elevator group route QA: requested destination floor "
                      << static_cast<unsigned>(*destination_floor_override)
                      << " is invalid or could not be selected in scene "
                      << scene_id << '\n';
            return 3;
        }
    } else if (expected.current_floor == 0U) {
        for (std::uint8_t floor = 1U; floor < source_group.count; ++floor) {
            if (!navigate_to_floor(floor)) {
                return 3;
            }
        }
        for (std::uint8_t floor = static_cast<std::uint8_t>(source_group.count - 1U);
             floor > 1U; --floor) {
            if (!navigate_to_floor(static_cast<std::uint8_t>(floor - 1U))) {
                return 3;
            }
        }
    } else {
        for (std::uint8_t floor = expected.current_floor; floor > 0U; --floor) {
            if (!navigate_to_floor(static_cast<std::uint8_t>(floor - 1U))) {
                return 3;
            }
        }
    }

    const auto current_floor_label_region = QRect(220, 24, 40, 40);
    const auto selected_floor_label_region = QRect(220, 88, 40, 48);
    const auto selected_floor = render();
    if (selector_open.copy(current_floor_label_region) !=
            selected_floor.copy(current_floor_label_region) ||
        first_selected_floor.isNull() ||
        selector_open.copy(selected_floor_label_region) ==
            first_selected_floor.copy(selected_floor_label_region) ||
        !image_region_has_color(first_selected_floor, 220, 88, 40, 48,
                                QColor(255, 219, 0))) {
        std::cerr << "Elevator group route QA: navigation changed the current "
                     "floor label or failed to show the selected floor\n";
        return 3;
    }

    const auto destination_floor = destination_floor_override.value_or(
        static_cast<std::uint8_t>(expected.current_floor == 0U ? 1U : 0U));
    const auto initial_lift_animation_frame = static_cast<std::uint8_t>(
        destination_floor > expected.current_floor ? 16U : 0U);
    input_label = "A";
    field_scene.set_controller_port_byte(0x40U);
    if (!advance() || !field_scene.elevator_selector_animating_for_dump() ||
        field_scene.elevator_selector_animation_frame_for_dump() !=
            initial_lift_animation_frame) {
        std::cerr << "Elevator group route QA: A did not start the 17-frame "
                     "lift sequence at the source-direction frame "
                  << static_cast<unsigned>(initial_lift_animation_frame)
                  << '\n';
        return 3;
    }
    input_label = "neutral";
    field_scene.set_controller_port_byte(0U);
    if (!advance() ||
        field_scene.elevator_selector_animation_frame_for_dump() !=
            initial_lift_animation_frame ||
        !save("lift-animation-start")) {
        return 3;
    }
    auto previous_lift_image = render();
    auto previous_lift_animation_frame = initial_lift_animation_frame;
    constexpr std::uint16_t kLiftAnimationFramesPerFloor = 17U * 8U;
    const auto travel_steps = static_cast<std::uint16_t>(
        destination_floor > expected.current_floor
            ? destination_floor - expected.current_floor
            : expected.current_floor - destination_floor);
    const auto lift_frame_limit = static_cast<std::uint16_t>(
        travel_steps * kLiftAnimationFramesPerFloor + 1U);
    const auto floor_step_direction = static_cast<std::int8_t>(
        destination_floor > expected.current_floor ? 1 : -1);
    std::uint16_t lift_frames = 0U;
    std::uint16_t frames_in_floor_step = 1U;
    auto observed_current_floor = expected.current_floor;
    while (lift_frames < lift_frame_limit &&
           field_scene.elevator_selector_animating_for_dump()) {
        if (!advance()) {
            return 3;
        }
        ++lift_frames;
        ++frames_in_floor_step;
        const auto current_floor =
            field_scene.elevator_selector_current_floor_for_dump();
        const auto animation_frame =
            field_scene.elevator_selector_animation_frame_for_dump();
        const auto lift_image = render();
        if (current_floor == observed_current_floor &&
            animation_frame != previous_lift_animation_frame &&
            lift_image.copy(QRect(32, 32, 1, 192)) ==
                previous_lift_image.copy(QRect(32, 32, 1, 192))) {
            std::cerr << "Elevator group route QA: visible lift rail did not "
                         "change when the source animation frame advanced\n";
            return 3;
        }
        if (current_floor != observed_current_floor) {
            const auto expected_next_floor = static_cast<std::uint8_t>(
                static_cast<std::int16_t>(observed_current_floor) +
                floor_step_direction);
            if (current_floor != expected_next_floor ||
                frames_in_floor_step != kLiftAnimationFramesPerFloor) {
                std::cerr << "Elevator group route QA: source lift stepped from "
                          << static_cast<unsigned>(observed_current_floor)
                          << " to " << static_cast<unsigned>(current_floor)
                          << " after " << frames_in_floor_step
                          << " animation VBlanks\n";
                return 3;
            }
            if (lift_image.copy(current_floor_label_region) ==
                    previous_lift_image.copy(current_floor_label_region) ||
                !image_region_has_color(lift_image, 220, 24, 40, 40,
                                        QColor(255, 219, 0)) ||
                lift_image.copy(selected_floor_label_region) !=
                    selected_floor.copy(selected_floor_label_region)) {
                std::cerr << "Elevator group route QA: floor stop did not "
                             "redraw only the current-floor display\n";
                return 3;
            }
            observed_current_floor = current_floor;
            frames_in_floor_step = 0U;
            if (current_floor == destination_floor) {
                if (field_scene.elevator_selector_animating_for_dump()) {
                    std::cerr << "Elevator group route QA: lift continued past "
                                 "its selected floor\n";
                    return 3;
                }
            } else if (!field_scene.elevator_selector_animating_for_dump() ||
                       field_scene.elevator_selector_animation_frame_for_dump() !=
                           initial_lift_animation_frame) {
                std::cerr << "Elevator group route QA: lift did not restart its "
                             "17-frame step between floors\n";
                return 3;
            }
            if (!save("lift-arrived-floor-" +
                      std::to_string(source_group.scene_ids[current_floor]))) {
                return 3;
            }
        }
        previous_lift_image = lift_image;
        previous_lift_animation_frame = animation_frame;
    }
    if (lift_frames >= lift_frame_limit ||
        field_scene.elevator_selector_animating_for_dump() ||
        observed_current_floor != destination_floor ||
        field_scene.elevator_selector_current_floor_for_dump() != destination_floor ||
        field_scene.elevator_selector_selected_floor_for_dump() !=
            destination_floor ||
        field_scene.elevator_selector_destination_for_dump() !=
            source_group.scene_ids[destination_floor] ||
        !save("selector-arrived-at-selected-floor")) {
        std::cerr << "Elevator group route QA: lift animation did not settle "
                     "on selected floor index "
                  << static_cast<unsigned>(destination_floor) << '\n';
        return 3;
    }

    input_label = "Start";
    field_scene.set_controller_port_byte(0x80U);
    const auto start_saved = advance();
    input_label = "neutral";
    field_scene.set_controller_port_byte(0U);
    if (!start_saved || !advance() ||
        field_scene.elevator_scene_transition_phase_for_dump() !=
            ElevatorSceneTransitionPhase::fading_to_black) {
        std::cerr << "Elevator group route QA: Start did not begin the "
                     "source-timed fade after the lift arrived\n";
        return 3;
    }

    bool black_handoff_captured = false;
    std::uint16_t transition_frames = 0U;
    const auto destination_scene = source_group.scene_ids[destination_floor];
    while (transition_frames < 500U &&
           (field_scene.field_scene_reference_for_dump() != destination_scene ||
            field_scene.elevator_scene_transition_phase_for_dump() !=
                ElevatorSceneTransitionPhase::idle)) {
        if (!advance()) {
            return 3;
        }
        ++transition_frames;
        if (!black_handoff_captured &&
            field_scene.field_scene_reference_for_dump() == destination_scene &&
            field_scene.elevator_scene_transition_phase_for_dump() ==
                ElevatorSceneTransitionPhase::fading_from_black &&
            field_scene.elevator_scene_transition_fade_alpha_for_dump() ==
                255U) {
            QImage black(kSceneWidth, kSceneHeight, QImage::Format_ARGB32);
            black.fill(Qt::black);
            if (render() != black ||
                !save("destination-black-handoff")) {
                std::cerr << "Elevator group route QA: scene change did not "
                             "replace the selector at full black\n";
                return 3;
            }
            black_handoff_captured = true;
        }
    }
    const auto destination_position = field_scene.field_entity_world_position();
    const auto destination_landing_position =
        field_scene.state().field_scene_buffers.source_metadata
            .initial_field_records[0U];
    const auto entry_after_fade = render();
    if (transition_frames >= 500U || !black_handoff_captured ||
        field_scene.field_scene_reference_for_dump() != destination_scene ||
        field_scene.elevator_selector_open_for_dump() || !no_modal_screen() ||
        field_scene.elevator_scene_transition_phase_for_dump() !=
            ElevatorSceneTransitionPhase::idle ||
        field_scene.elevator_scene_transition_fade_alpha_for_dump() != 0U ||
        destination_position.x != destination_landing_position.x ||
        destination_position.y != destination_landing_position.y ||
        !field_scene.field_entity_visible_for_dump() ||
        !field_hud_chrome_survives(entry_after_fade, asset_root) ||
        entry_after_fade == selector_open ||
        !save("scene" + std::to_string(destination_scene) +
              "-entry-after-fade")) {
        std::cerr << "Elevator group route QA: selected scene "
                  << destination_scene
                  << " did not place the runner at its ROM profile lift "
                     "landing\n";
        return 3;
    }

    auto camera_x =
        field_scene.state().field_scene_buffers.camera_x;
    auto camera_y =
        field_scene.state().field_scene_buffers.camera_y;
    std::uint8_t stable_camera_frames = 0U;
    std::uint16_t camera_settle_frames = 0U;
    // A destination can enter with its descriptor camera offset from the
    // ordinary 0x3C0 lookahead target. At the slow camera rate of 0x10 units
    // per update, allow up to 0x3C0 / 0x10 updates, plus three stable samples.
    constexpr std::uint16_t kCameraSettleFrameLimit = 0x03C0U / 0x0010U + 3U;
    while (camera_settle_frames < kCameraSettleFrameLimit &&
           stable_camera_frames < 3U) {
        if (!advance()) {
            return 3;
        }
        ++camera_settle_frames;
        const auto next_camera_x =
            field_scene.state().field_scene_buffers.camera_x;
        const auto next_camera_y =
            field_scene.state().field_scene_buffers.camera_y;
        if (next_camera_x == camera_x && next_camera_y == camera_y) {
            ++stable_camera_frames;
        } else {
            stable_camera_frames = 0U;
        }
        camera_x = next_camera_x;
        camera_y = next_camera_y;
    }
    const auto destination = render();
    if (stable_camera_frames != 3U ||
        field_scene.field_scene_reference_for_dump() != destination_scene ||
        field_scene.field_entity_world_position().x !=
            destination_landing_position.x ||
        field_scene.field_entity_world_position().y !=
            destination_landing_position.y ||
        !no_modal_screen() || !field_hud_chrome_survives(destination, asset_root) ||
        !save("scene" + std::to_string(destination_scene) + "-destination")) {
        std::cerr << "Elevator group route QA: destination camera did not settle "
                     "to a clean, stable field screen\n";
        return 3;
    }
    for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
        if (!advance()) {
            return 3;
        }
    }
    if (render() != destination ||
        !save("scene" + std::to_string(destination_scene) + "-held-30")) {
        std::cerr << "Elevator group route QA: destination retained stale "
                     "selector graphics or changed during idle\n";
        return 3;
    }
    if (!save("actual")) {
        std::cerr << "Elevator group route QA: could not write actual.bmp\n";
        return 3;
    }
    timeline.flush();
    if (timeline_frame_count != frame + 1U ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.selector.opened") ==
            source_boundaries.end() ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.destination_loaded") ==
            source_boundaries.end() ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.elevator.destination_fade_finished") ==
            source_boundaries.end()) {
        std::cerr << "Elevator group route QA: complete timeline or source "
                     "transition boundary was not recorded\n";
        return 3;
    }
    std::cout << "field_elevator_group_route_qa=passed scene="
              << scene_id << " trigger=event29 records="
              << expected.first_trigger_record << ','
              << expected.first_trigger_record + 1U
              << " current_floor="
              << static_cast<unsigned>(expected.current_floor)
              << " destination=" << destination_scene
              << " audio_event=0x25 frames="
              << timeline_frame_count << " artifacts=" << output.string()
              << '\n';
    return 0;
}

int run_field_elevator_floor_group_roundtrip_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    const auto activity_start_count = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.world.activity.started"));
    const auto collision_dispatch_count = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.map_event.collision_dispatched"));
    const auto selector_open_count = static_cast<std::size_t>(
        std::count(source_boundaries.begin(), source_boundaries.end(),
                   "field.elevator.selector.opened"));
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Elevator floor-group QA: could not clear captures: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output / "timeline", output_error);
    if (output_error) {
        std::cerr << "Elevator floor-group QA: could not create captures: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::ofstream manifest(output / "frames.tsv", std::ios::trunc);
    std::ofstream timeline_manifest(output / "timeline.tsv", std::ios::trunc);
    if (!manifest || !timeline_manifest) {
        std::cerr << "Elevator floor-group QA: could not create manifests\n";
        return 3;
    }
    manifest << "stage\tframe\tscene\tselector_open\tcurrent_floor"
                "\tselected_floor\tanimation\tanimation_frame"
                "\ttransition_phase\ttransition_step\ttransition_alpha"
                "\taudio_event_count\timage\n";
    timeline_manifest
        << "frame\tscene\tx\ty\theading\ttarget_heading\tselector_open"
           "\tcurrent_floor\tselected_floor"
           "\tanimation\tanimation_frame\ttransition_phase"
           "\ttransition_step\ttransition_vblanks\ttransition_alpha"
           "\tinput\timage\n";

    std::uint32_t frame = 0U;
    std::uint32_t timeline_frame_count = 0U;
    bool timeline_capture_ok = true;
    auto timeline_input = std::string("neutral");
    const auto render = [&field_scene] { return render_qa_field(field_scene, false, QImage::Format_ARGB32); };
    const auto capture_timeline_frame = [&] {
        if (!timeline_capture_ok) {
            return;
        }
        const auto name = std::string("timeline/frame-") +
                          std::to_string(frame) + ".png";
        const auto path = output / name;
        const auto image = render();
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            timeline_capture_ok = false;
            return;
        }
        timeline_manifest
            << frame << '\t'
            << field_scene.field_scene_reference_for_dump() << '\t'
            << field_scene.field_entity_world_position().x << '\t'
            << field_scene.field_entity_world_position().y << '\t'
            << field_scene.field_entity_heading_for_dump() << '\t'
            << field_scene.field_entity_target_heading_for_dump() << '\t'
            << field_scene.elevator_selector_open_for_dump() << '\t'
            << static_cast<unsigned>(
                   field_scene.elevator_selector_current_floor_for_dump())
            << '\t'
            << static_cast<unsigned>(
                   field_scene.elevator_selector_selected_floor_for_dump())
            << '\t' << field_scene.elevator_selector_animating_for_dump()
            << '\t'
            << static_cast<unsigned>(
                   field_scene.elevator_selector_animation_frame_for_dump())
            << '\t' << static_cast<unsigned>(
                           field_scene.elevator_scene_transition_phase_for_dump())
            << '\t'
            << static_cast<unsigned>(field_scene
                                         .elevator_scene_transition_palette_step_for_dump())
            << '\t'
            << static_cast<unsigned>(field_scene
                                         .elevator_scene_transition_vblanks_for_dump())
            << '\t'
            << static_cast<unsigned>(field_scene
                                         .elevator_scene_transition_fade_alpha_for_dump())
            << '\t' << timeline_input << '\t' << name << '\n';
        ++timeline_frame_count;
    };
    const auto tick_frame = [&] {
        field_scene.advance_frame();
        ++frame;
        capture_timeline_frame();
    };
    const auto save = [&](const std::string_view stage) {
        const auto image = render();
        const auto name = std::string(stage) + ".bmp";
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(
                (output / name).wstring()))) {
            return QImage{};
        }
        manifest << stage << '\t' << frame << '\t'
                 << field_scene.field_scene_reference_for_dump() << '\t'
                 << field_scene.elevator_selector_open_for_dump() << '\t'
                 << static_cast<unsigned>(
                        field_scene.elevator_selector_current_floor_for_dump())
                 << '\t'
                 << static_cast<unsigned>(
                        field_scene.elevator_selector_selected_floor_for_dump())
                 << '\t' << field_scene.elevator_selector_animating_for_dump()
                 << '\t'
                 << static_cast<unsigned>(
                        field_scene.elevator_selector_animation_frame_for_dump())
                 << '\t' << static_cast<unsigned>(field_scene
                                                      .elevator_scene_transition_phase_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_scene_transition_palette_step_for_dump())
                 << '\t'
                 << static_cast<unsigned>(field_scene
                                              .elevator_scene_transition_fade_alpha_for_dump())
                 << '\t' << field_audio_events.size() << '\t' << name << '\n';
        manifest.flush();
        return image;
    };
    const auto tap_dpad = [&](const std::uint8_t nibble) {
        timeline_input = nibble == 0x01U ? "dpad-up" : "dpad-down";
        field_scene.set_controller_nibble(nibble);
        tick_frame();
        timeline_input = "neutral";
        field_scene.set_controller_nibble(0U);
        tick_frame();
    };
    const auto tap_button = [&](const std::uint8_t port_byte) {
        timeline_input = port_byte == 0x40U ? "A" : "Start";
        field_scene.set_controller_port_byte(port_byte);
        tick_frame();
        timeline_input = "neutral";
        field_scene.set_controller_port_byte(0U);
        tick_frame();
    };
    const auto no_modal_screen = [&field_scene] {
        return !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_mode_text_open_for_dump() &&
               !field_scene.shop_menu_open();
    };

    if (field_scene.field_scene_reference_for_dump() != 28U ||
        field_scene.elevator_selector_open_for_dump() ||
        field_scene.elevator_scene_transition_phase_for_dump() !=
            ElevatorSceneTransitionPhase::idle ||
        !no_modal_screen()) {
        std::cerr << "Elevator floor-group QA: first route did not leave a "
                     "stable scene-28 field\n";
        return 3;
    }
    capture_timeline_frame();
    auto stable_field = save("scene28-initial");
    if (stable_field.isNull() ||
        !field_hud_chrome_survives(stable_field, asset_root)) {
        std::cerr << "Elevator floor-group QA: scene-28 starting frame is "
                     "missing or lacks its HUD\n";
        return 3;
    }

    const auto enter_selector = [&](const std::uint16_t scene,
                                    const std::size_t first_record,
                                    const std::uint8_t floor,
                                    const std::string& label,
                                    const QImage& parent_field) {
        const auto& rectangles = field_scene.state()
                                     .field_scene_buffers.source_metadata
                                     .terrain_collision_rectangles;
        if (field_scene.field_scene_reference_for_dump() != scene ||
            rectangles.size() <= first_record + 1U) {
            std::cerr << "Elevator floor-group QA: scene/record mismatch scene="
                      << field_scene.field_scene_reference_for_dump()
                      << " expected=" << scene
                      << " records=" << rectangles.size()
                      << " first_record=" << first_record << '\n';
            return QImage{};
        }
        for (const auto record : {first_record, first_record + 1U}) {
            const auto& rectangle = rectangles[record];
            const auto offset = record == first_record ? 0U : 0x20U;
            if (rectangle.left != 0x0080U + offset ||
                rectangle.right != 0x009FU + offset ||
                rectangle.top != 0x0020U || rectangle.bottom != 0x003FU ||
                rectangle.value != 0x00DDU) {
                std::cerr << "Elevator floor-group QA: event-29 collision "
                             "record mismatch scene="
                          << scene << " record=" << record << " rect="
                          << rectangle.left << ',' << rectangle.top << ".."
                          << rectangle.right << ',' << rectangle.bottom
                          << " value=0x" << std::hex
                          << static_cast<unsigned>(rectangle.value) << std::dec
                          << '\n';
                return QImage{};
            }
        }
        std::uint8_t activity_cooldown_frames = 0U;
        while (field_scene.world_activity_request_timeout_for_dump() != 0U &&
               activity_cooldown_frames < 60U) {
            timeline_input = "activity-cooldown";
            field_scene.set_controller_nibble(0U);
            tick_frame();
            ++activity_cooldown_frames;
        }
        if (field_scene.world_activity_request_timeout_for_dump() != 0U) {
            std::cerr << "Elevator floor-group QA: previous world activity "
                         "did not release after its 60 field frames\n";
            return QImage{};
        }

        const auto activity_before = static_cast<std::size_t>(std::count(
            source_boundaries.begin(), source_boundaries.end(),
            "field.world.activity.started"));
        std::uint16_t movement_ticks = 0U;
        while (movement_ticks < 120U &&
               !field_scene.elevator_selector_open_for_dump() &&
               field_scene.field_scene_reference_for_dump() == scene) {
            timeline_input = "dpad-up";
            field_scene.set_controller_nibble(0x01U);
            tick_frame();
            ++movement_ticks;
        }
        timeline_input = "neutral";
        field_scene.set_controller_nibble(0U);
        if (field_scene.elevator_selector_open_for_dump()) {
            tick_frame();
        }
        const auto& transition =
            field_scene.last_field_movement_transition_for_dump();
        const auto activity_after = static_cast<std::size_t>(std::count(
            source_boundaries.begin(), source_boundaries.end(),
            "field.world.activity.started"));
        if (!field_scene.elevator_selector_open_for_dump() ||
        transition.event_code != FieldCollisionEventCode::event_29 ||
            transition.continuation !=
                MovementModeTransitionContinuation::event_29_world_activity ||
            transition.kind !=
                EntityMovementModeTransitionResultKind::world_activity_started ||
            field_scene.field_scene_reference_for_dump() != scene ||
            field_scene.elevator_selector_current_floor_for_dump() != floor ||
            field_scene.elevator_selector_selected_floor_for_dump() != floor ||
            activity_after <= activity_before || !no_modal_screen()) {
        const auto& last_dispatch =
            field_scene.field_map_event_system_for_dump()
                .last_collision_dispatch();
        if (last_dispatch.has_value()) {
            std::cerr << "Elevator approach last collision: scene="
                      << last_dispatch->input.scene_id
                      << " event="
                      << static_cast<unsigned>(field_collision_event_value(
                             last_dispatch->decision.source_event_code))
                      << " selected_event="
                      << static_cast<unsigned>(field_collision_event_value(
                             last_dispatch->decision.event_code))
                      << " raw_collision="
                      << last_dispatch->input.raw_collision_code
                      << " candidate=" << last_dispatch->input.world_x << ','
                      << last_dispatch->input.world_y
                      << " action=" << static_cast<unsigned>(
                             last_dispatch->decision.action)
                      << '\n';
        }
            return QImage{};
        }
        const auto selector = save(label + "-selector-open");
        if (selector.isNull() || selector == parent_field ||
            !field_hud_chrome_survives(selector, asset_root) ||
            !image_region_has_color(selector, 220, 88, 40, 48,
                                    QColor(255, 219, 0))) {
            return QImage{};
        }
        return selector;
    };

    const auto transition_down_one_floor =
        [&](const std::uint16_t source_scene,
            const std::uint16_t destination_scene,
            const std::uint8_t current_floor, const std::string& label,
            const QImage& selector_frame) {
            if (current_floor == 0U) {
                return QImage{};
            }
            tap_dpad(0x02U);
            const auto selected_floor = static_cast<std::uint8_t>(
                current_floor - 1U);
            const auto feedback = save(label + "-previous-floor-feedback");
            if (feedback.isNull() ||
                field_scene.elevator_selector_current_floor_for_dump() !=
                    current_floor ||
                field_scene.elevator_selector_selected_floor_for_dump() !=
                    selected_floor ||
                field_scene.elevator_selector_destination_for_dump() !=
                    destination_scene ||
                field_scene.elevator_selector_navigation_feedback_for_dump() !=
                    ElevatorSelectorNavigationFeedback::previous_floor_active ||
                feedback == selector_frame) {
                return QImage{};
            }
            std::uint8_t feedback_ticks = 0U;
            while (field_scene
                           .elevator_selector_navigation_feedback_frames_remaining_for_dump() !=
                       0U &&
                   feedback_ticks < kElevatorSelectorNavigationFeedbackFrameCount) {
                tick_frame();
                ++feedback_ticks;
            }
            if (field_scene.elevator_selector_navigation_feedback_for_dump() !=
                ElevatorSelectorNavigationFeedback::previous_floor_rest) {
                return QImage{};
            }
            const auto feedback_rest = save(label + "-previous-floor-rest");
            if (feedback_rest.isNull()) {
                return QImage{};
            }
            tap_button(0x40U);
            if (!field_scene.elevator_selector_animating_for_dump() ||
                field_scene.elevator_selector_animation_frame_for_dump() != 0U) {
                return QImage{};
            }
            for (std::size_t tick = 2U;
                 tick <= kElevatorSelectorAnimationFrameCount *
                             kElevatorSelectorAnimationFrameDelay;
                 ++tick) {
                tick_frame();
            }
            const auto settled = save(label + "-floor-animation-settled");
            if (settled.isNull() ||
                field_scene.elevator_selector_current_floor_for_dump() !=
                    selected_floor ||
                field_scene.elevator_selector_selected_floor_for_dump() !=
                    selected_floor ||
                field_scene.elevator_selector_animating_for_dump()) {
                return QImage{};
            }
            tap_button(0x80U);
            if (!field_scene.elevator_selector_open_for_dump() ||
                field_scene.elevator_scene_transition_phase_for_dump() !=
                    ElevatorSceneTransitionPhase::fading_to_black ||
                field_scene.elevator_scene_transition_palette_step_for_dump() !=
                    0U ||
                field_scene.elevator_scene_transition_vblanks_for_dump() != 1U) {
                return QImage{};
            }
            for (std::uint8_t palette_step = 1U;
                 palette_step <= kElevatorSceneTransitionPaletteStepCount;
                 ++palette_step) {
                if (palette_step != 1U) {
                    tick_frame();
                }
                tick_frame();
                const auto last_step =
                    palette_step == kElevatorSceneTransitionPaletteStepCount;
                const auto transition_matches = last_step
                    ? field_scene.field_scene_reference_for_dump() ==
                              destination_scene &&
                          field_scene.elevator_scene_transition_phase_for_dump() ==
                              ElevatorSceneTransitionPhase::fading_from_black &&
                          field_scene.elevator_scene_transition_palette_step_for_dump() ==
                              0U &&
                          field_scene.elevator_scene_transition_fade_alpha_for_dump() ==
                              255U
                    : field_scene.field_scene_reference_for_dump() == source_scene &&
                          field_scene.elevator_scene_transition_phase_for_dump() ==
                              ElevatorSceneTransitionPhase::fading_to_black &&
                          field_scene.elevator_scene_transition_palette_step_for_dump() ==
                              palette_step &&
                          field_scene.elevator_scene_transition_fade_alpha_for_dump() !=
                              0U;
                if (!transition_matches ||
                    save(label + "-fade-out-step-" +
                         std::to_string(palette_step))
                        .isNull()) {
                    return QImage{};
                }
            }
            QImage expected_black(kSceneWidth, kSceneHeight,
                                  QImage::Format_ARGB32);
            expected_black.fill(Qt::black);
            const auto black_handoff = save(label + "-black-handoff");
            if (black_handoff.isNull() || black_handoff != expected_black ||
                field_scene.field_scene_reference_for_dump() !=
                    destination_scene ||
                field_scene.elevator_selector_open_for_dump()) {
                return QImage{};
            }
            for (std::uint8_t palette_step = 1U;
                 palette_step <= kElevatorSceneTransitionPaletteStepCount;
                 ++palette_step) {
                tick_frame();
                if (palette_step == 9U &&
                    save(label + "-fade-in-midpoint").isNull()) {
                    return QImage{};
                }
                tick_frame();
                if (field_scene.elevator_scene_transition_palette_step_for_dump() !=
                        palette_step ||
                    save(label + "-fade-in-step-" +
                         std::to_string(palette_step))
                        .isNull()) {
                    return QImage{};
                }
            }
            const auto destination = save(label + "-entry");
            const auto destination_position =
                field_scene.field_entity_world_position();
            const auto destination_landing_position =
                field_scene.state().field_scene_buffers.source_metadata
                    .initial_field_records[0U];
            if (destination.isNull() ||
                field_scene.field_scene_reference_for_dump() !=
                    destination_scene ||
                field_scene.elevator_selector_open_for_dump() ||
                field_scene.elevator_scene_transition_phase_for_dump() !=
                    ElevatorSceneTransitionPhase::idle ||
                field_scene.elevator_scene_transition_fade_alpha_for_dump() !=
                    0U ||
                destination_position.x != destination_landing_position.x ||
                destination_position.y != destination_landing_position.y ||
                !field_scene.field_entity_visible_for_dump() ||
                !field_hud_chrome_survives(destination, asset_root) ||
                destination == selector_frame || !no_modal_screen()) {
                return QImage{};
            }
            for (std::uint8_t tick = 0U; tick < 30U; ++tick) {
                tick_frame();
            }
            const auto held = save(label + "-held-30-frames");
            return !held.isNull() && held == destination ? held : QImage{};
        };

    struct ElevatorRoute final {
        std::uint16_t source_scene;
        std::size_t first_collision_record;
        std::uint8_t current_floor;
        std::uint16_t destination_scene;
        std::string label;
    };
    const std::array<ElevatorRoute, 2> return_routes{{
        {28U, 112U, 2U, 27U, "scene28-to-scene27"},
        {27U, 131U, 1U, 26U, "scene27-to-scene26"},
    }};
    for (const auto& route : return_routes) {
        const auto selector = enter_selector(
            route.source_scene, route.first_collision_record,
            route.current_floor, route.label, stable_field);
        if (selector.isNull()) {
            const auto& movement =
                field_scene.last_field_movement_transition_for_dump();
            const auto& last_dispatch =
                field_scene.field_map_event_system_for_dump()
                    .last_collision_dispatch();
            std::cerr << "Elevator floor-group QA: scene "
                      << route.source_scene
                      << " collision did not open its current floor selector"
                      << " (selector_open="
                      << field_scene.elevator_selector_open_for_dump()
                      << ", current_floor="
                      << static_cast<unsigned>(field_scene
                                                   .elevator_selector_current_floor_for_dump())
                      << ", selected_floor="
                      << static_cast<unsigned>(field_scene
                                                   .elevator_selector_selected_floor_for_dump())
                      << ", event="
                      << static_cast<unsigned>(field_scene
                                                   .field_mode_event_code_for_dump())
                      << ", entity_flags="
                      << static_cast<unsigned>(
                             field_scene.field_entity_behavior_flags_for_dump())
                      << ", terrain_code="
                      << field_scene.field_terrain_collision_code_for_dump()
                      << ", transition_kind="
                      << static_cast<unsigned>(movement.kind)
                      << ", continuation="
                      << static_cast<unsigned>(movement.continuation)
                      << ", activity_starts="
                      << (static_cast<std::size_t>(std::count(
                              source_boundaries.begin(),
                              source_boundaries.end(),
                              "field.world.activity.started")) -
                          activity_start_count)
                      << ", collision_dispatches="
                      << (static_cast<std::size_t>(std::count(
                              source_boundaries.begin(),
                              source_boundaries.end(),
                              "field.map_event.collision_dispatched")) -
                          collision_dispatch_count)
                      << ", selector_open_events="
                      << (static_cast<std::size_t>(std::count(
                              source_boundaries.begin(),
                              source_boundaries.end(),
                              "field.elevator.selector.opened")) -
                          selector_open_count)
                      << ", position="
                      << field_scene.field_entity_world_position().x << ','
                      << field_scene.field_entity_world_position().y
                      << ", resource_countdown="
                      << field_scene.world_frame_logic_for_dump()
                             .resource_countdown
                      << ", activity_timer="
                      << static_cast<unsigned>(
                             field_scene
                                 .world_activity_request_timeout_for_dump())
                      << ", activity_countdown="
                      << field_scene.world_frame_logic_for_dump()
                             .activity_countdown
                      << ", failure=" << field_scene.failure() << ")\n";
            if (last_dispatch.has_value()) {
                std::cerr << "Elevator approach last collision: scene="
                          << last_dispatch->input.scene_id
                          << " event="
                          << static_cast<unsigned>(field_collision_event_value(
                                 last_dispatch->decision.source_event_code))
                          << " selected_event="
                          << static_cast<unsigned>(field_collision_event_value(
                                 last_dispatch->decision.event_code))
                          << " raw_collision="
                          << last_dispatch->input.raw_collision_code
                          << " candidate="
                          << last_dispatch->input.world_x << ','
                          << last_dispatch->input.world_y
                          << " action=" << static_cast<unsigned>(
                                 last_dispatch->decision.action)
                          << '\n';
            }
            return 3;
        }
        const auto destination = transition_down_one_floor(
            route.source_scene, route.destination_scene,
            route.current_floor, route.label, selector);
        if (destination.isNull()) {
            std::cerr << "Elevator floor-group QA: scene "
                      << route.source_scene << " did not transition to scene "
                      << route.destination_scene << " at source cadence\n";
            return 3;
        }
        stable_field = destination;
    }
    const auto actual = save("actual");
    if (actual.isNull() || actual != stable_field ||
        field_scene.field_scene_reference_for_dump() != 26U) {
        std::cerr << "Elevator floor-group QA: final scene-26 field does not "
                     "match the settled return state\n";
        return 3;
    }
    manifest.flush();
    timeline_manifest.flush();
    if (!timeline_capture_ok || timeline_frame_count != frame + 1U) {
        std::cerr << "Elevator floor-group QA: timeline missed an update (captured="
                  << timeline_frame_count << ", expected=" << frame + 1U
                  << ")\n";
        return 3;
    }
    std::cout << "field_elevator_floor_group_roundtrip_qa=passed "
                 "routes=scene28-to-scene27,scene27-to-scene26 "
                 "timeline_frames="
              << timeline_frame_count << " artifacts=" << output.string()
              << '\n';
    return 0;
}

int run_field_stoker_collision_to_dialogue_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::filesystem::create_directories(output);
    constexpr std::array<std::string_view, 42> stale_or_current_frames{
        "actual.bmp",
        "destination-entry.bmp",
        "destination-idle-01.bmp",
        "destination-idle-08.bmp",
        "destination-idle-30.bmp",
        "destination-settled.bmp",
        "doorway-trigger.bmp",
        "fade-01.bmp",
        "fade-08.bmp",
        "fade-16.bmp",
        "fade-17.bmp",
        "leave-walk-01.bmp",
        "leave-walk-02.bmp",
        "leave-walk-04.bmp",
        "leave-walk-08.bmp",
        "leave-walk-16.bmp",
        "leave-release-before-fresh-direction.bmp",
        "leave-fresh-right-01.bmp",
        "leave-fresh-right-04.bmp",
        "leave-fresh-right-08.bmp",
        "movement-8.bmp",
        "movement-16.bmp",
        "movement-32.bmp",
        "movement-64.bmp",
        "movement-128.bmp",
        "spawn.bmp",
        "stoker-arrival-dialogue.bmp",
        "stoker-debt-question.bmp",
        "stoker-leave-dialogue.bmp",
        "stoker-jump-house-referral.bmp",
        "stoker-manager-greeting.bmp",
        "stoker-manager-ordinary.bmp",
        "stoker-manager-package-offer.bmp",
        "stoker-leave-notice.bmp",
        "stoker-package-handoff.bmp",
        "stoker-ordinary-motel.bmp",
        "stoker-package-returned-field.bmp",
        "stoker-repeat-manager-package-offer.bmp",
        "stoker-leave-returned-to-field.bmp",
        "stoker-unpaid-walk-away.bmp",
        "stoker-post-payment-walk-away.bmp",
        "returned-to-field.bmp"};
    for (const auto name : stale_or_current_frames) {
        std::error_code remove_error;
        std::filesystem::remove(output / name, remove_error);
        if (remove_error) {
            std::cerr << "Stoker collision QA: could not remove prior frame "
                      << name << ": " << remove_error.message() << '\n';
            return 3;
        }
    }
    const auto mode_entry_commands_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.command"));
    const auto mode_entry_waits_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.wait"));
    const auto mode_entry_flushes_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.flush"));
    const auto mode_entry_ticks_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.service"));
    const auto auto_walk_armed_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.opening_auto_walk.armed"));
    const auto opening_event_started_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.map_event.new_game_opening_walk_started"));
    const auto lua_handler_completed_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.map_event.lua_handler_completed"));
    const auto auto_walk_consumed_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.opening_auto_walk.consumed"));
    if (auto_walk_armed_before != 1 || opening_event_started_before != 1 ||
        lua_handler_completed_before != 0 || auto_walk_consumed_before != 0) {
        std::cerr << "Stoker collision QA: New Game opening event was not "
                     "dispatched and armed exactly once before the field route\n";
        return 3;
    }
    const auto render_field = [&field_scene] { return render_qa_field(field_scene); };
    const auto save_frame = [&] (const std::string_view name,
                                 const bool expect_field_hud) {
        const auto image = render_field();
        const auto path = output / (std::string(name) + ".bmp");
        if (!image.save(QString::fromStdWString(path.wstring()))) {
            std::cerr << "Stoker collision QA: dump failed for " << name
                      << '\n';
            return false;
        }
        if (image.width() != kSceneWidth || image.height() != kSceneHeight ||
            (expect_field_hud &&
             (!field_hud_chrome_survives(image, asset_root) ||
              count_playfield_lit(image) < 100U))) {
            std::cerr << "Stoker collision QA: full-frame validation failed for "
                      << name << '\n';
            return false;
        }
        return true;
    };

    const auto start_position = field_scene.field_entity_world_position();
    const auto& collision_rectangles = field_scene.state()
                                           .field_scene_buffers.source_metadata
                                           .terrain_collision_rectangles;
    const bool source_doorway_record_matches =
        collision_rectangles.size() > 91U &&
        collision_rectangles[91U].left == 0x03C0U &&
        collision_rectangles[91U].right == 0x03DFU &&
        collision_rectangles[91U].top == 0x0280U &&
        collision_rectangles[91U].bottom == 0x029FU &&
        collision_rectangles[91U].value == 0xC2U;
    const auto spawn_image = render_field();
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        start_position.x != 0x3CE0U || start_position.y != 0x2D00U ||
        !field_scene.opening_auto_walk_active_for_dump() ||
        field_scene.field_controller_nibble_for_dump() != 0U ||
        !source_doorway_record_matches ||
        (field_scene.field_entity_behavior_flags_for_dump() & 0x02U) == 0U ||
        spawn_image.size() != QSize(kSceneWidth, kSceneHeight) ||
        !field_hud_chrome_survives(spawn_image, asset_root) ||
        count_playfield_lit(spawn_image) < 100U ||
        !spawn_image.save(QString::fromStdWString(
            (output / "spawn.bmp").wstring()))) {
        std::cerr << "Stoker collision QA: New Game did not start from the "
                     "source scene-2 runner state (scene="
                  << field_scene.field_scene_reference_for_dump() << ", x="
                  << start_position.x << ", y=" << start_position.y
                  << ", behavior="
                  << static_cast<unsigned>(
                         field_scene.field_entity_behavior_flags_for_dump())
                  << ")\n";
        return 3;
    }

    bool position_changed = false;
    bool transition_started = false;
    bool fade_started = false;
    std::uint32_t transition_start_frame = 0U;
    std::uint16_t transition_position_x = 0U;
    std::uint16_t transition_position_y = 0U;
    std::int32_t transition_camera_x = 0;
    std::uint8_t transition_event_code = 0U;
    std::uint16_t transition_projected_code = 0U;
    std::uint8_t transition_cell_status = 0U;
    bool controller_stayed_released = true;
    std::uint32_t frame = 0U;
    for (; frame < 256U; ++frame) {
        field_scene.advance_frame();
        controller_stayed_released = controller_stayed_released &&
                                     field_scene.field_controller_nibble_for_dump() ==
                                         0U;
        const auto position = field_scene.field_entity_world_position();
        position_changed = position_changed ||
                           position.x != start_position.x ||
                           position.y != start_position.y;
        if (frame == 7U || frame == 15U || frame == 31U ||
            frame == 63U || frame == 127U) {
            if (!save_frame("movement-" + std::to_string(frame + 1U), true)) {
                return 3;
            }
        }

        fade_started = fade_started ||
                       field_scene.field_interaction_transition_active_for_dump();
        if (field_scene.field_interaction_transition_active_for_dump() ||
            field_scene.field_transition_pending_for_dump() ||
            field_scene.field_scene_reference_for_dump() != 2U ||
            field_scene.field_interaction_open() ||
            field_scene.dialogue_open()) {
            transition_started = true;
            transition_start_frame = frame + 1U;
            transition_position_x = position.x;
            transition_position_y = position.y;
            transition_camera_x = static_cast<std::int32_t>(
                field_scene.state().field_scene_buffers.camera_x);
            transition_event_code =
                field_scene.field_mode_event_code_for_dump();
            transition_projected_code =
                field_scene.field_projected_code_for_dump();
            const auto cell_x = static_cast<std::size_t>(position.x >> 9U);
            const auto cell_y = static_cast<std::size_t>(position.y >> 9U);
            const auto cell_index = cell_y * 64U + cell_x;
            const auto& collision_map = field_scene.state()
                                            .field_scene_buffers
                                            .source_metadata
                                            .terrain_collision_map;
            if (cell_index < collision_map.size()) {
                transition_cell_status = collision_map[cell_index];
            }
            if (!save_frame("doorway-trigger", false)) {
                return 3;
            }
            field_scene.set_controller_nibble(0U);
            break;
        }
    }

    if (!position_changed || !transition_started ||
        !controller_stayed_released) {
        const auto position = field_scene.field_entity_world_position();
        std::cerr << "Stoker collision QA: automatic opening walk did not reach a "
                     "source transition within 256 frames (scene="
                  << field_scene.field_scene_reference_for_dump() << ", x="
                  << position.x << ", y=" << position.y << ", heading="
                  << field_scene.field_entity_heading_for_dump() << ", moved="
                     << (position_changed ? "yes" : "no")
                     << ", raw_collision=0x" << std::hex
                     << field_scene.field_terrain_collision_code_for_dump()
                     << ", projected=0x"
                     << field_scene.field_projected_code_for_dump() << std::dec
                     << ", event="
                     << static_cast<unsigned>(
                            field_scene.field_mode_event_code_for_dump())
                     << ", activity="
                     << static_cast<unsigned>(
                            field_scene.field_activity_selection_for_dump())
                     << ", interaction="
                     << (field_scene.field_interaction_open() ? "open"
                                                              : "closed")
                     << ", dialogue="
                     << (field_scene.dialogue_open() ? "open" : "closed")
                     << ")\n";
        return 3;
    }
    const auto& doorway = collision_rectangles[91U];
    const auto doorway_world_x = static_cast<std::uint16_t>(
        transition_position_x >> 4U);
    const auto doorway_world_y = static_cast<std::uint16_t>(
        transition_position_y >> 4U);
    const auto& route_state = field_scene.field_runtime_state_for_dump();
    if (!source_doorway_record_matches ||
        transition_event_code != 2U ||
        field_scene.field_terrain_collision_code_for_dump() != 0xFFC2U ||
        transition_projected_code != 0xFFC2U ||
        field_scene.field_interaction_mode_for_dump() != 0U ||
        route_state.field_mode != 2U ||
        doorway_world_x < doorway.left - 12U ||
        doorway_world_x > doorway.right + 12U ||
        doorway_world_y < doorway.top - 7U ||
        doorway_world_y > doorway.bottom + 7U ||
        field_scene.dialogue_open() || field_scene.field_interaction_open()) {
        std::cerr << "Stoker collision QA: normal contact did not publish the "
                     "source doorway's raw C2/event-2 state (collision=0x"
                  << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << ", projected=0x" << transition_projected_code
                  << std::dec << ", event="
                  << static_cast<unsigned>(transition_event_code)
                  << ", world_mode="
                  << field_scene.field_interaction_mode_for_dump()
                  << ", field_mode=" << static_cast<unsigned>(route_state.field_mode)
                  << ", contact=" << doorway_world_x << ',' << doorway_world_y
                  << ")\n";
        return 3;
    }
    if (!fade_started) {
        std::cerr << "Stoker collision QA: physical contact bypassed the "
                     "source fade timer\n";
        return 3;
    }
    if (!field_scene.field_interaction_transition_active_for_dump() ||
        field_scene.field_interaction_transition_timer_for_dump() != 15 ||
        field_scene.field_palette_fade_steps_for_dump() != 1U) {
        std::cerr << "Stoker collision QA: collision-frame fade state is "
                     "unexpected (timer="
                  << field_scene.field_interaction_transition_timer_for_dump()
                  << ", palette_steps="
                  << static_cast<unsigned>(
                         field_scene.field_palette_fade_steps_for_dump())
                  << ")\n";
        return 3;
    }

    const std::array<std::uint32_t, 3> fade_checkpoints{8U, 16U, 17U};
    for (const auto checkpoint : fade_checkpoints) {
        const auto target_frame = transition_start_frame + checkpoint - 1U;
        while (frame + 1U < target_frame) {
            field_scene.advance_frame();
            ++frame;
        }
        const auto name = "fade-" +
                          (checkpoint < 10U ? std::string("0") : std::string()) +
                          std::to_string(checkpoint);
        if (!save_frame(name, false)) {
            return 3;
        }
        const auto expected_timer = checkpoint == 8U ? 8 :
                                    checkpoint == 16U ? 0 : -1;
        const auto expected_palette_steps = checkpoint == 8U ? 4U :
                                            checkpoint == 16U ? 8U : 9U;
        if (field_scene.field_interaction_transition_timer_for_dump() !=
                expected_timer ||
            field_scene.field_palette_fade_steps_for_dump() !=
                expected_palette_steps ||
            field_scene.field_transition_pending_for_dump() !=
                (checkpoint == 17U)) {
            std::cerr << "Stoker collision QA: source fade counter diverged "
                         "at frame " << checkpoint << " (timer="
                      << field_scene.field_interaction_transition_timer_for_dump()
                      << ", palette_steps="
                      << static_cast<unsigned>(
                             field_scene.field_palette_fade_steps_for_dump())
                      << ", pending="
                      << (field_scene.field_transition_pending_for_dump()
                              ? "yes"
                              : "no")
                      << ")\n";
            return 3;
        }
    }

    field_scene.set_controller_nibble(0U);
    for (std::uint16_t settle = 0U;
         settle < 60U && !field_scene.dialogue_open(); ++settle) {
        field_scene.advance_frame();
        ++frame;
    }
    if (!field_scene.dialogue_open()) {
        const auto position = field_scene.field_entity_world_position();
        std::cerr << "Stoker collision QA: source mode/event did not open its "
                     "dialogue after the fade (scene="
                  << field_scene.field_scene_reference_for_dump() << ", x="
                  << position.x << ", y=" << position.y << ", mode="
                  << field_scene.field_interaction_mode_for_dump()
                  << ", event=" << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", transition_pending="
                  << (field_scene.field_transition_pending_for_dump()
                          ? "yes"
                          : "no")
                  << ")\n";
        return 3;
    }
    const auto auto_walk_consumed_after = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.opening_auto_walk.consumed"));
    const auto lua_handler_completed_after = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.map_event.lua_handler_completed"));
    const auto& map_event_system =
        field_scene.field_map_event_system_for_dump();
    const auto& last_map_event =
        map_event_system.last_collision_dispatch();
    if (field_scene.opening_auto_walk_active_for_dump() ||
        auto_walk_consumed_after != auto_walk_consumed_before + 1 ||
        lua_handler_completed_after != lua_handler_completed_before + 1 ||
        map_event_system.collision_dispatch_count() == 0U ||
        !last_map_event.has_value() ||
        last_map_event->input.scene_id != 2U ||
        (last_map_event->input.raw_collision_code & 0x001FU) != 2U ||
        last_map_event->decision.action !=
            FieldMapEventAction::project_world_interaction) {
        std::cerr << "Stoker collision QA: first field-exit dispatch did not "
                     "consume the New Game auto-walk state exactly once or "
                     "route its C2 contact through the map-event system\n";
        return 3;
    }
    if (field_scene.field_transition_pending_for_dump()) {
        std::cerr << "Stoker collision QA: coordinator left its field "
                     "transition request armed while the dialogue owns the screen\n";
        return 3;
    }

    {
        std::ofstream boundaries(output / "source-boundaries.txt",
                                 std::ios::trunc);
        if (boundaries) {
            for (const auto& boundary : source_boundaries) {
                boundaries << boundary << '\n';
            }
        }
    }

    std::ofstream trace(output / "route.tsv", std::ios::trunc);
    if (!trace) {
        std::cerr << "Stoker collision QA: could not create route.tsv\n";
        return 3;
    }
    trace << "stage\tframe\tscene\tx\ty\tworld_mode\tfield_mode\tevent"
             "\traw_collision\tprojected\tactivity\ttransition_pending"
             "\tdialogue\tpalette_steps\tcontroller_nibble"
             "\topening_auto_walk\tmap_event_dispatches"
             "\tlast_event_scene\tlast_event_raw\tlast_event_action\n";
    const auto write_state = [&] (const std::string_view stage) {
        const auto position = field_scene.field_entity_world_position();
        const auto& runtime = field_scene.field_runtime_state_for_dump();
        trace << stage << '\t' << frame << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << position.x << '\t' << position.y << '\t'
              << field_scene.field_interaction_mode_for_dump() << '\t'
              << static_cast<unsigned>(runtime.field_mode) << '\t'
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump()) << '\t'
              << field_scene.field_terrain_collision_code_for_dump() << '\t'
              << field_scene.field_projected_code_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_activity_selection_for_dump()) << '\t'
              << (field_scene.field_transition_pending_for_dump() ? 1 : 0)
              << '\t' << (field_scene.dialogue_open() ? 1 : 0) << '\t'
              << static_cast<unsigned>(
                     field_scene.field_palette_fade_steps_for_dump()) << '\t'
              << static_cast<unsigned>(
                     field_scene.field_controller_nibble_for_dump()) << '\t'
              << (field_scene.opening_auto_walk_active_for_dump() ? 1 : 0)
              << '\t' << field_scene.field_map_event_system_for_dump()
                                .collision_dispatch_count();
        const auto& last = field_scene.field_map_event_system_for_dump()
                               .last_collision_dispatch();
        if (last.has_value()) {
            trace << '\t' << last->input.scene_id << '\t'
                  << last->input.raw_collision_code << '\t'
                  << static_cast<unsigned>(last->decision.action);
        } else {
            trace << "\t-\t-\t-";
        }
        trace
              << '\n';
        trace.flush();
    };
    write_state("stoker-arrival-dialogue");
    const auto stoker_trigger_position =
        field_scene.field_entity_world_position();
    const auto stoker_trigger_heading =
        field_scene.field_entity_heading_for_dump();

    const auto& arrival = field_scene.dialogue_panel();
    const auto arrival_text_present = [&arrival] {
        for (std::size_t index = 0; index < arrival.text_segment_count; ++index) {
            if (arrival.text_segments[index].find("battered sign") !=
                std::string_view::npos) {
                return true;
            }
        }
        return false;
    };
    if (!arrival.open || !arrival.source_complete ||
        arrival.actor_kind != DialoguePanelActorKind::field_npc ||
        arrival.actor_name != "Stoker" ||
        arrival.portrait_alias != "dialogue.portraits.stoker.motel" ||
        !arrival_text_present() || !arrival.has_more ||
        arrival.option_count != 1U ||
        !field_scene.stoker_motel_story_state_for_dump()
             .opening_dialogue_seen ||
        arrival.continuation_label.find("< MORE >") == std::string_view::npos ||
        !save_frame("stoker-arrival-dialogue", false)) {
        std::cerr << "Stoker collision QA: normal contact did not select the "
                     "source Stoker arrival record in the shared dialogue panel\n";
        return 3;
    }
    const auto arrival_image = render_field();
    if (arrival_image.size() != QSize(kSceneWidth, kSceneHeight) ||
        field_hud_chrome_survives(arrival_image, asset_root) ||
        !image_has_green_ink(arrival_image, 88, 16, 216, 120)) {
        std::cerr << "Stoker collision QA: dialogue does not replace the field "
                     "HUD cleanly or its text is not visible\n";
        return 3;
    }

    // Use ordinary controller bytes through the field runtime. The indexed
    // Stoker title service supplies the first-visit page and package offer;
    // no mode/event tuple or dialogue record is injected.
    const auto press_button = [&field_scene](const std::uint8_t port_byte) {
        field_scene.set_controller_port_byte(port_byte);
        field_scene.advance_frame();
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
    };
    press_button(0x40U);
    if (!field_scene.dialogue_open() ||
        field_scene.dialogue_panel().actor_name != "Stoker" ||
        field_scene.dialogue_panel().option_count != 3U ||
        field_scene.dialogue_panel().has_more ||
        !save_frame("stoker-manager-package-offer", false)) {
        std::cerr << "Stoker collision QA: A did not advance the arrival page "
                     "to the three-choice manager offer\n";
        return 3;
    }
    write_state("stoker-manager-package-offer");
    const auto& manager = field_scene.dialogue_panel();
    if (manager.options[1].source_label.find("I'll talk to you later") ==
            std::string_view::npos ||
        manager.options[2].source_label.find("Michael's stuff") ==
            std::string_view::npos) {
        std::cerr << "Stoker collision QA: manager package offer lacks its "
                     "source Leave or Michael's-stuff choice\n";
        return 3;
    }

    // QA fixture for the paid source branch; this does not claim an in-game
    // funds-acquisition route.
    field_scene.set_field_funds_for_dump(250U);
    press_button(0x20U);
    const auto& debt_question = field_scene.dialogue_panel();
    if (!field_scene.dialogue_open() ||
        debt_question.actor_name != "Stoker" ||
        debt_question.option_count != 2U ||
        debt_question.text_segment_count == 0U ||
        debt_question.text_segments[0].find("Michael's brother") ==
            std::string_view::npos ||
        !save_frame("stoker-debt-question", false)) {
        std::cerr << "Stoker collision QA: C did not open the source debt "
                     "question from the live three-choice offer\n";
        return 3;
    }
    write_state("stoker-debt-question");

    press_button(0x40U);
    const auto& package_handoff = field_scene.dialogue_panel();
    bool package_text_present = false;
    for (std::size_t index = 0;
         index < package_handoff.text_segment_count; ++index) {
        package_text_present = package_text_present ||
            package_handoff.text_segments[index].find("Here's the package") !=
                std::string_view::npos;
    }
    if (!field_scene.dialogue_open() ||
        field_scene.field_funds_for_dump() !=
            std::optional<std::uint32_t>{500U} ||
        !field_scene.stoker_motel_story_state_for_dump().michael_debt_paid ||
        !field_scene.stoker_motel_story_state_for_dump()
             .michael_package_collected ||
        package_handoff.actor_name != "Stoker" ||
        package_handoff.option_count != 0U ||
        !package_text_present ||
        !save_frame("stoker-package-handoff", false)) {
        std::cerr << "Stoker collision QA: successful payment did not update "
                     "the wallet and show the source package handoff\n";
        return 3;
    }
    write_state("paid-package-handoff");

    press_button(0x40U);
    field_scene.advance_frame();
    const bool modal_return_completed =
        finish_field_modal_return_transition(field_scene);
    if (field_scene.dialogue_open() ||
        !modal_return_completed ||
        field_scene.field_transition_pending_for_dump() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_palette_fade_steps_for_dump() != 0U) {
        std::cerr << "Stoker collision QA: dialogue return did not resume a "
                     "clear scene-2 field frame (dialogue="
                  << (field_scene.dialogue_open() ? "open" : "closed")
                  << ", transition_pending="
                  << (field_scene.field_transition_pending_for_dump()
                          ? "yes"
                          : "no")
                  << ", scene="
                  << field_scene.field_scene_reference_for_dump()
                  << ", palette_steps=" << static_cast<unsigned>(
                         field_scene.field_palette_fade_steps_for_dump())
                  << ")\n";
        return 3;
    }
    const auto returned_position = field_scene.field_entity_world_position();
    const auto returned_image = render_field();
    if (returned_position.x != stoker_trigger_position.x ||
        returned_position.y != stoker_trigger_position.y ||
        field_scene.field_entity_heading_for_dump() !=
            stoker_trigger_heading ||
        !save_frame("returned-to-field", true) ||
        !returned_image.save(QString::fromStdWString(
            (output / "actual.bmp").wstring())) ||
        !field_hud_chrome_survives(returned_image, asset_root) ||
        count_playfield_lit(returned_image) < 100U ||
        field_scene.field_controller_nibble_for_dump() != 0U) {
        std::cerr << "Stoker collision QA: return frame is incomplete or still "
                     "contains a dialogue overlay\n";
        return 3;
    }
    write_state("returned-to-field");

    // Reopen the shared motel manager with completed-story state. The Leave
    // choice must yield location-profile dialogue through Lua, replace the
    // manager rows cleanly, then return to the field.
    if (!field_scene.open_stoker_dialogue_for_dump(
            StokerMotelPromptId::manager_greeting) ||
        !field_scene.dialogue_open() ||
        field_scene.dialogue_panel().option_count != 2U ||
        !save_frame("stoker-manager-ordinary", false)) {
        std::cerr << "Stoker collision QA: ordinary motel manager did not "
                     "reopen through the shared script flow\n";
        return 3;
    }
    write_state("ordinary-motel-manager");

    press_button(0x10U);
    const auto& leave_dialogue = field_scene.dialogue_panel();
    bool leave_text_present = false;
    for (std::size_t index = 0; index < leave_dialogue.text_segment_count;
         ++index) {
        leave_text_present = leave_text_present ||
            leave_dialogue.text_segments[index].find("seeing you") !=
                std::string_view::npos;
    }
    const auto leave_image = render_field();
    if (!field_scene.dialogue_open() || leave_dialogue.actor_name != "Stoker" ||
        !leave_text_present || leave_dialogue.option_count != 0U ||
        leave_dialogue.has_more ||
        field_hud_chrome_survives(leave_image, asset_root) ||
        !image_has_green_ink(leave_image, 88, 16, 216, 120) ||
        image_has_green_ink(leave_image, 48, 152, 240, 48) ||
        !save_frame("stoker-leave-dialogue", false)) {
        std::cerr << "Stoker collision QA: scripted Leave did not replace "
                     "the menu with a clean title-only farewell page\n";
        return 3;
    }
    write_state("motel-leave-dialogue");

    press_button(0x10U);
    const bool farewell_return_completed =
        finish_field_modal_return_transition(field_scene);
    if (!farewell_return_completed || field_scene.dialogue_open() ||
        field_scene.field_transition_pending_for_dump() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_controller_nibble_for_dump() != 0U ||
        !save_frame("stoker-leave-returned-to-field", true) ||
        !save_frame("actual", true)) {
        std::cerr << "Stoker collision QA: dismissing the scripted farewell "
                     "did not restore the clean field scene\n";
        return 3;
    }
    write_state("leave-returned-to-field");

    // ROM 0xAC5E releases B7B8's one-shot retry bit only after FFDF64 reports
    // clear terrain. Check the first player-controlled movement after the
    // same-scene modal return: the runner should step out of the C2 bounds,
    // not immediately dispatch the Stoker interaction again.
    const auto departure_start = field_scene.field_entity_world_position();
    const auto dispatches_before_departure =
        field_scene.field_map_event_system_for_dump().collision_dispatch_count();
    const auto audio_events_before_departure = field_audio_events.size();
    if (departure_start.x != stoker_trigger_position.x ||
        departure_start.y != stoker_trigger_position.y ||
        field_scene.field_entity_heading_for_dump() !=
            stoker_trigger_heading) {
        std::cerr << "Stoker collision QA: same-scene Leave changed the ROM "
                     "contact coordinate or facing (contact="
                  << stoker_trigger_position.x << ','
                  << stoker_trigger_position.y << ", return="
                  << departure_start.x << ',' << departure_start.y
                  << ", contact_heading=" << stoker_trigger_heading
                  << ", return_heading="
                  << field_scene.field_entity_heading_for_dump() << ")\n";
        return 3;
    }
    if ((field_scene.field_movement_route_flags_for_dump() & 0x20U) == 0U) {
        std::cerr << "Stoker collision QA: B7B8 retry bit was lost across "
                     "the same-scene dialogue return\n";
        return 3;
    }
    std::ofstream departure_trace(output / "stoker-field-exit-movement.tsv");
    if (!departure_trace) {
        std::cerr << "Stoker collision QA: could not write departure trace\n";
        return 3;
    }
    departure_trace
        << "frame\tx\ty\theading\ttarget_heading\tanimation_heading"
           "\tselector\tanimation_frame\twalking\troute_flags"
           "\traw_collision\tevent\ttransition\tinteraction\tdialogue"
           "\tdispatches\taudio_events\n";
    constexpr std::array<std::uint32_t, 5> departure_checkpoints{
        1U, 2U, 4U, 8U, 16U};
    bool departure_moved_south = false;
    field_scene.set_controller_nibble(0x02U); // ordinary Down hold
    for (std::uint32_t departure_frame = 1U;
         departure_frame <= departure_checkpoints.back();
         ++departure_frame) {
        field_scene.advance_frame();
        const auto position = field_scene.field_entity_world_position();
        departure_moved_south = departure_moved_south ||
                                position.y > departure_start.y;
        const auto collision_code =
            field_scene.field_terrain_collision_code_for_dump();
        const auto route_flags =
            field_scene.field_movement_route_flags_for_dump();
        const bool retry_bit_is_set = (route_flags & 0x20U) != 0U;
        departure_trace
            << departure_frame << '\t' << position.x << '\t' << position.y
            << '\t' << field_scene.field_entity_heading_for_dump()
            << '\t' << field_scene.field_entity_target_heading_for_dump()
            << '\t' << field_scene.field_entity_animation_heading_for_dump()
            << '\t' << field_scene.field_entity_animation_selector_for_dump()
            << '\t' << field_scene.field_entity_animation_frame_for_dump()
            << '\t' << (field_scene.field_entity_walking_for_dump() ? 1 : 0)
            << '\t' << static_cast<unsigned>(route_flags)
            << '\t' << collision_code
            << '\t' << static_cast<unsigned>(
                   field_scene.field_mode_event_code_for_dump())
            << '\t' << (field_scene.field_transition_pending_for_dump() ? 1 : 0)
            << '\t' << (field_scene.field_interaction_open() ? 1 : 0)
            << '\t' << (field_scene.dialogue_open() ? 1 : 0)
            << '\t' << field_scene.field_map_event_system_for_dump()
                                .collision_dispatch_count()
            << '\t' << field_audio_events.size()
            << '\n';
        if ((collision_code == 0U && retry_bit_is_set) ||
            (collision_code != 0U && !retry_bit_is_set)) {
            field_scene.set_controller_nibble(0U);
            departure_trace.close();
            std::cerr << "Stoker collision QA: 0xAC5E retry-bit lifetime "
                         "did not match its terrain sample at frame "
                      << departure_frame << " (terrain=0x" << std::hex
                      << collision_code << ", route_flags=0x"
                      << static_cast<unsigned>(route_flags) << ")\n";
            return 3;
        }
        if (field_scene.field_transition_pending_for_dump() ||
            field_scene.field_interaction_transition_active_for_dump() ||
            field_scene.field_interaction_open() ||
            field_scene.dialogue_open() ||
            field_scene.field_scene_reference_for_dump() != 2U) {
            field_scene.set_controller_nibble(0U);
            departure_trace.close();
            std::cerr << "Stoker collision QA: Down after the farewell "
                         "re-entered a modal/scene transition at frame "
                      << departure_frame << " (scene="
                      << field_scene.field_scene_reference_for_dump()
                      << ", x=" << position.x << ", y=" << position.y
                      << ", event="
                      << static_cast<unsigned>(
                             field_scene.field_mode_event_code_for_dump())
                      << ", dispatches="
                      << field_scene.field_map_event_system_for_dump()
                             .collision_dispatch_count()
                      << ")\n";
            return 3;
        }
        if (std::find(departure_checkpoints.begin(),
                      departure_checkpoints.end(), departure_frame) !=
            departure_checkpoints.end()) {
            const auto frame_name = std::string("leave-walk-") +
                (departure_frame < 10U ? "0" : "") +
                std::to_string(departure_frame);
            if (!save_frame(frame_name, true)) {
                field_scene.set_controller_nibble(0U);
                departure_trace.close();
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    departure_trace.close();
    const auto departure_end = field_scene.field_entity_world_position();
    const auto dispatches_after_departure =
        field_scene.field_map_event_system_for_dump().collision_dispatch_count();
    if (!departure_moved_south ||
        departure_end.y <= departure_start.y ||
        (field_scene.field_movement_route_flags_for_dump() & 0x20U) != 0U ||
        field_scene.field_terrain_collision_code_for_dump() != 0U ||
        dispatches_after_departure != dispatches_before_departure ||
        field_audio_events.size() != audio_events_before_departure ||
        !save_frame("actual", true)) {
        std::cerr << "Stoker collision QA: ordinary Down did not leave the "
                     "doorway cleanly (start="
                  << departure_start.x << ',' << departure_start.y
                  << ", end=" << departure_end.x << ',' << departure_end.y
                  << ", dispatches=" << dispatches_before_departure << "->"
                  << dispatches_after_departure << ", audio="
                  << audio_events_before_departure << "->"
                  << field_audio_events.size() << ")\n";
        return 3;
    }
    write_state("leave-walk-16");

    std::ofstream fresh_direction_trace(
        output / "stoker-fresh-direction.tsv", std::ios::trunc);
    if (!fresh_direction_trace) {
        std::cerr << "Stoker collision QA: could not write the fresh-direction "
                     "trace\n";
        return 3;
    }
    fresh_direction_trace
        << "phase\tinput\tframe\tx\ty\theading\troute_flags"
           "\traw_collision\tevent\tdispatches\ttransition"
           "\tinteraction\tdialogue\taudio_events\n";
    const auto fresh_direction_dispatches =
        field_scene.field_map_event_system_for_dump()
            .collision_dispatch_count();
    const auto trace_fresh_direction = [&](const std::string_view phase,
                                           const std::string_view input) {
        const auto position = field_scene.field_entity_world_position();
        fresh_direction_trace
            << phase << '\t' << input << '\t' << frame << '\t'
            << position.x << '\t' << position.y << '\t'
            << field_scene.field_entity_heading_for_dump() << '\t'
            << static_cast<unsigned>(
                   field_scene.field_movement_route_flags_for_dump())
            << '\t' << field_scene.field_terrain_collision_code_for_dump()
            << '\t' << static_cast<unsigned>(
                   field_scene.field_mode_event_code_for_dump())
            << '\t' << field_scene.field_map_event_system_for_dump()
                           .collision_dispatch_count()
            << '\t' << field_scene.field_transition_pending_for_dump()
            << '\t' << field_scene.field_interaction_open() << '\t'
            << field_scene.dialogue_open() << '\t'
            << field_audio_events.size() << '\n';
        return static_cast<bool>(fresh_direction_trace);
    };
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!trace_fresh_direction("release-between-directions", "none") ||
        !save_frame("leave-release-before-fresh-direction", true)) {
        return 3;
    }
    bool fresh_direction_moved_east = false;
    constexpr std::array<std::uint32_t, 3> fresh_direction_checkpoints{
        1U, 4U, 8U};
    for (std::uint32_t tick = 1U; tick <= 8U; ++tick) {
        field_scene.set_controller_nibble(0x08U); // fresh ordinary Right
        field_scene.advance_frame();
        ++frame;
        const auto position = field_scene.field_entity_world_position();
        fresh_direction_moved_east =
            fresh_direction_moved_east || position.x > departure_end.x;
        if (!trace_fresh_direction("fresh-right", "Right") ||
            field_scene.field_scene_reference_for_dump() != 2U ||
            field_scene.dialogue_open() || field_scene.field_interaction_open() ||
            field_scene.shop_menu_open() ||
            field_scene.field_transition_pending_for_dump() ||
            field_scene.field_map_event_system_for_dump()
                    .collision_dispatch_count() != fresh_direction_dispatches) {
            field_scene.set_controller_nibble(0U);
            std::cerr << "Stoker collision QA: a fresh direction retriggered "
                         "or left the field after the runner cleared the C2 "
                         "trigger\n";
            return 3;
        }
        if (std::find(fresh_direction_checkpoints.begin(),
                      fresh_direction_checkpoints.end(), tick) !=
            fresh_direction_checkpoints.end()) {
            const auto name = "leave-fresh-right-" +
                (tick < 10U ? std::string("0") : std::string()) +
                std::to_string(tick);
            if (!save_frame(name, true)) {
                field_scene.set_controller_nibble(0U);
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    ++frame;
    if (!fresh_direction_moved_east ||
        field_scene.field_map_event_system_for_dump()
                .collision_dispatch_count() != fresh_direction_dispatches ||
        !save_frame("actual", true)) {
        std::cerr << "Stoker collision QA: releasing Down and pressing fresh "
                     "Right did not stay on the field without replaying the "
                     "Stoker event\n";
        return 3;
    }
    fresh_direction_trace.close();

    trace.close();

    const auto mode_entry_commands_after = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.command"));
    const auto mode_entry_waits_after = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.wait"));
    const auto mode_entry_flushes_after = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.flush"));
    const auto mode_entry_ticks_after = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.audio.mode_entry.service"));
    const auto mode_event_publications = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.world.activity.mode_event_published"));
    const auto transition_projection_resets = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.entities.transition_projection_invalidated"));
    const auto transition_anchor_snapshots = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.entities.transition_anchor_snapshotted"));
    if (mode_entry_commands_after - mode_entry_commands_before != 6 ||
        mode_entry_waits_after - mode_entry_waits_before != 6 ||
        mode_entry_flushes_after - mode_entry_flushes_before != 1 ||
        mode_entry_ticks_after - mode_entry_ticks_before != 1 ||
        mode_event_publications != 1 || transition_projection_resets != 1 ||
        transition_anchor_snapshots != 1) {
        std::cerr << "Stoker collision QA: source transition service order "
                     "was incomplete (commands="
                  << mode_entry_commands_after - mode_entry_commands_before
                  << ", waits="
                  << mode_entry_waits_after - mode_entry_waits_before
                  << ", flushes="
                  << mode_entry_flushes_after - mode_entry_flushes_before
                  << ", ticks="
                  << mode_entry_ticks_after - mode_entry_ticks_before
                  << ", events=" << mode_event_publications
                  << ", projection_resets=" << transition_projection_resets
                  << ", anchor_snapshots=" << transition_anchor_snapshots
                  << ")\n";
        return 3;
    }
    const auto expected_bmp_names = std::vector<std::string>{
        "actual.bmp",
        "doorway-trigger.bmp",
        "fade-08.bmp",
        "fade-16.bmp",
        "fade-17.bmp",
        "leave-fresh-right-01.bmp",
        "leave-fresh-right-04.bmp",
        "leave-fresh-right-08.bmp",
        "leave-release-before-fresh-direction.bmp",
        "leave-walk-01.bmp",
        "leave-walk-02.bmp",
        "leave-walk-04.bmp",
        "leave-walk-08.bmp",
        "leave-walk-16.bmp",
        "movement-16.bmp",
        "movement-8.bmp",
        "returned-to-field.bmp",
        "spawn.bmp",
        "stoker-arrival-dialogue.bmp",
        "stoker-debt-question.bmp",
        "stoker-leave-dialogue.bmp",
        "stoker-leave-returned-to-field.bmp",
        "stoker-manager-ordinary.bmp",
        "stoker-manager-package-offer.bmp",
        "stoker-package-handoff.bmp"};
    std::vector<std::string> actual_bmp_names;
    std::error_code directory_error;
    for (std::filesystem::directory_iterator item(output, directory_error), end;
         !directory_error && item != end; item.increment(directory_error)) {
        if (item->is_regular_file(directory_error) &&
            item->path().extension() == ".bmp") {
            actual_bmp_names.push_back(item->path().filename().string());
        }
    }
    if (directory_error) {
        std::cerr << "Stoker collision QA: could not inspect output set: "
                  << directory_error.message() << '\n';
        return 3;
    }
    std::sort(actual_bmp_names.begin(), actual_bmp_names.end());
    if (actual_bmp_names != expected_bmp_names) {
        std::cerr << "Stoker collision QA: expected 25 full-screen checkpoints, "
                     "found " << actual_bmp_names.size() << '\n';
        for (const auto& name : actual_bmp_names) {
            std::cerr << "  frame: " << name << '\n';
        }
        return 3;
    }

    const auto position = field_scene.field_entity_world_position();
    std::cout << "field_stoker_collision_to_dialogue_qa=passed "
              << "movement=automatic controller=none,a,b,a scene="
              << field_scene.field_scene_reference_for_dump()
              << " collision=0x" << std::hex
              << field_scene.field_terrain_collision_code_for_dump()
              << " projected=0x" << field_scene.field_projected_code_for_dump()
              << std::dec << " event="
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump())
              << " world_mode_after_return="
              << field_scene.field_interaction_mode_for_dump()
              << " position=" << position.x << ',' << position.y
              << " returned_position=" << returned_position.x << ','
              << returned_position.y
              << " dialogue=opening->manager-package->debt->paid-handoff->field"
                 "->motel-leave->field"
              << " mode_entry_commands="
              << mode_entry_commands_after - mode_entry_commands_before
              << " mode_entry_waits="
              << mode_entry_waits_after - mode_entry_waits_before
              << " mode_entry_vblank_waits="
              << (mode_entry_waits_after - mode_entry_waits_before) * 3
              << " event_publications=" << mode_event_publications
              << " discrete_sfx_events=" << field_audio_events.size()
              << " artifacts=" << output.string() << '\n';
    return 0;
}
int run_field_stoker_collision_candidate_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::filesystem::create_directories(output);
    std::error_code directory_error;
    for (std::filesystem::directory_iterator item(output, directory_error), end;
         !directory_error && item != end; item.increment(directory_error)) {
        if (item->is_regular_file(directory_error) &&
            item->path().extension() == ".bmp") {
            std::filesystem::remove(item->path(), directory_error);
            if (directory_error) {
                std::cerr << "field Stoker-property QA: could not clear old "
                          << item->path().filename().string() << ": "
                          << directory_error.message() << '\n';
                return 3;
            }
        }
    }
    if (directory_error) {
        std::cerr << "field Stoker-property QA: could not inspect output: "
                  << directory_error.message() << '\n';
        return 3;
    }
    // Stabilize all source-PRNG-driven actor delays during this route so the
    // collision path and its full-screen captures are repeatable.
    // Keep the source PRNG repeatable for actor delays while the fixed world
    // tick offset above keeps the encounter cadence out of this route.
    field_scene.set_source_random_seed_for_dump(0x4000U);

    std::vector<std::string> saved_bmp_names;
    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save_frame = [&](const std::string_view name,
                                const QImage& image) {
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            !image.save(QString::fromStdWString(
                (output / std::string(name)).wstring()))) {
            return false;
        }
        saved_bmp_names.emplace_back(name);
        return true;
    };
    const auto save = [&](const std::string_view name) {
        return save_frame(name, render());
    };
    const auto route_active = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 2U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_interaction_transition_active_for_dump() &&
               !field_scene.field_transition_pending_for_dump();
    };

    const auto start = field_scene.field_entity_world_position();
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        start.x != 0x3CE0U || start.y != 0x2D00U ||
        field_scene.field_mode_event_code_for_dump() != 0U ||
        !save("spawn.bmp")) {
        std::cerr << "field Stoker-property QA: New Game field did not start "
                     "from the traced scene-2 state (scene="
                  << field_scene.field_scene_reference_for_dump()
                  << ", position=" << start.x << ',' << start.y
                  << ", event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ")\n";
        return 3;
    }

    // Scene-2 record 2 at ROM 0x172DBE is a type-2 collision object in the
    // east/south street, not an NPC/event identity. Follow ordinary D-pad
    // movement to its boundary and record the projected event and dialogue
    // state. This checks that the nearby object is not mislabeled as Stoker;
    // the actual mode-2/event-2 trigger remains a separate unresolved route.
    constexpr std::uint16_t east_waypoint_x = 0x5500U; // world x=0x550
    constexpr std::uint16_t south_waypoint_y = 0x3520U; // world y=0x352
    constexpr std::uint16_t property_approach_x = 0x5540U; // world x=0x554
    std::uint16_t east_ticks = 0U;
    while (east_ticks < 240U &&
           field_scene.field_entity_world_position().x < east_waypoint_x &&
           route_active()) {
        field_scene.set_controller_nibble(0x08U);
        field_scene.advance_frame();
        ++east_ticks;
        if (east_ticks == 16U || east_ticks == 64U || east_ticks == 128U) {
            const auto name = "east-" + std::to_string(east_ticks) + ".bmp";
            if (!save(name)) {
                std::cerr << "field Stoker-property QA: east-route dump failed\n";
                return 3;
            }
        }
    }
    const auto east_position = field_scene.field_entity_world_position();
    if (!save("east-waypoint.bmp") || east_position.x < east_waypoint_x ||
        !route_active()) {
        std::cerr << "field Stoker-property QA: east street waypoint was not "
                     "reached (ticks="
                  << east_ticks << ", position=" << east_position.x << ','
                  << east_position.y << ", event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", scene=" << field_scene.field_scene_reference_for_dump()
                  << ")\n";
        return 3;
    }

    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    std::uint16_t south_ticks = 0U;
    while (south_ticks < 120U &&
           field_scene.field_entity_world_position().y < south_waypoint_y &&
           route_active()) {
        field_scene.set_controller_nibble(0x02U);
        field_scene.advance_frame();
        ++south_ticks;
        if (south_ticks == 16U || south_ticks == 32U ||
            south_ticks == 48U) {
            const auto name = "south-" + std::to_string(south_ticks) + ".bmp";
            if (!save(name)) {
                std::cerr << "field Stoker-property QA: south-route dump failed\n";
                return 3;
            }
        }
    }
    const auto wall_position = field_scene.field_entity_world_position();
    const auto wall_animation_selector =
        field_scene.field_entity_animation_selector_for_dump();
    const bool blocked_animation_resets_to_idle =
        !field_scene.field_entity_walking_for_dump() &&
        field_scene.field_entity_animation_frame_for_dump() == 0U &&
        wall_animation_selector <= 0x001CU &&
        (wall_animation_selector & 0x0003U) == 0U;
    // Record 76 is the source wall across this street. 0xE7C8 normalizes the
    // runner's 16.4 position before 0xE8A0 samples its four expanded corners;
    // the south corners extend seven normalized units. The 0xC002 south
    // movement vector advances forty source units, so the final free position
    // must be below the first blocked coordinate and one source step from it.
    constexpr std::size_t kStreetWallRecord = 76U;
    constexpr std::uint16_t kPositionFractionBits = 4U;
    constexpr std::uint16_t kExpandedProbeSouthExtent = 7U;
    constexpr std::uint16_t kSourceSouthMovementStep = 40U;
    const auto& source_rectangles =
        field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_rectangles;
    const bool source_wall_matches_rom =
        source_rectangles.size() > kStreetWallRecord &&
        source_rectangles[kStreetWallRecord].left == 0x0540U &&
        source_rectangles[kStreetWallRecord].right == 0x05DFU &&
        source_rectangles[kStreetWallRecord].top == 0x0320U &&
        source_rectangles[kStreetWallRecord].bottom == 0x033FU &&
        source_rectangles[kStreetWallRecord].value == 0x007FU;
    const auto first_blocked_y = source_wall_matches_rom
        ? (static_cast<std::uint32_t>(
               source_rectangles[kStreetWallRecord].top -
               kExpandedProbeSouthExtent)
           << kPositionFractionBits)
        : 0U;
    const auto normalized_runner_x =
        static_cast<std::uint16_t>(wall_position.x >> kPositionFractionBits);
    const bool runner_is_in_wall_span = source_wall_matches_rom &&
        normalized_runner_x >=
            source_rectangles[kStreetWallRecord].left &&
        normalized_runner_x <=
            source_rectangles[kStreetWallRecord].right;
    const bool stopped_at_source_wall_edge =
        source_wall_matches_rom && runner_is_in_wall_span &&
        (field_scene.field_entity_behavior_flags_for_dump() & 0x04U) != 0U &&
        wall_position.y < first_blocked_y &&
        static_cast<std::uint32_t>(wall_position.y) +
                kSourceSouthMovementStep >= first_blocked_y;
    if (!save("wall-approach.bmp") || !route_active() ||
        !blocked_animation_resets_to_idle ||
        !stopped_at_source_wall_edge) {
        std::cerr << "field Stoker-property QA: did not stop at the source "
                     "wall edge in C052 idle before the property lane "
                     "(ticks="
                  << south_ticks << ", position=" << wall_position.x << ','
                  << wall_position.y << ", event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", scene=" << field_scene.field_scene_reference_for_dump()
                  << ", walking="
                  << (field_scene.field_entity_walking_for_dump() ? "yes"
                                                                  : "no")
                  << ", selector=" << wall_animation_selector << ", frame="
                  << field_scene.field_entity_animation_frame_for_dump()
                  << ", source_wall="
                  << (source_wall_matches_rom ? "yes" : "no")
                  << ", expanded_probe="
                  << ((field_scene.field_entity_behavior_flags_for_dump() &
                       0x04U) != 0U ? "yes" : "no")
                  << ")\n";
        return 3;
    }

    // This diagonal press reaches the wall with the east/south corner probe
    // blocked. The ROM tries its two orthogonal fallback probes and commits
    // the first clear candidate, allowing the actor to slide along the wall.
    const auto reset_count_before = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.movement.reset_blocked_step"));
    const auto wall_corner_start = field_scene.field_entity_world_position();
    if (!save("wall-corner-diagonal-000.bmp")) {
        std::cerr << "field Stoker-property QA: corner-entry dump failed\n";
        return 3;
    }
    bool saw_corner_slide = false;
    bool corner_slide_was_cardinal = false;
    std::uint16_t corner_ticks = 0U;
    for (; corner_ticks < 48U && route_active(); ++corner_ticks) {
        const auto before = field_scene.field_entity_world_position();
        field_scene.set_controller_nibble(0x0AU);
        field_scene.advance_frame();
        const auto frame_name =
            "wall-corner-diagonal-" +
            (corner_ticks + 1U < 10U ? std::string("00")
             : corner_ticks + 1U < 100U ? std::string("0")
                                        : std::string()) +
            std::to_string(corner_ticks + 1U) + ".bmp";
        if (!save(frame_name)) {
            std::cerr << "field Stoker-property QA: corner-step dump failed\n";
            return 3;
        }
        const auto after = field_scene.field_entity_world_position();
        if (after.x != before.x || after.y != before.y) {
            corner_slide_was_cardinal =
                (after.x != before.x) != (after.y != before.y);
            saw_corner_slide = save("wall-corner-slide-first.bmp");
            ++corner_ticks;
            break;
        }
    }
    const auto reset_count_after_slide = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.movement.reset_blocked_step"));
    const auto wall_corner_slide_position =
        field_scene.field_entity_world_position();
    if (!saw_corner_slide || !corner_slide_was_cardinal ||
        wall_corner_slide_position.x == wall_corner_start.x &&
            wall_corner_slide_position.y == wall_corner_start.y ||
        reset_count_after_slide != reset_count_before || !route_active()) {
        std::cerr << "field Stoker-property QA: diagonal wall contact did not "
                     "commit one clear cardinal fallback candidate "
                     "(start="
                  << wall_corner_start.x << ',' << wall_corner_start.y
                  << ", after=" << wall_corner_slide_position.x << ','
                  << wall_corner_slide_position.y << ", cardinal="
                  << (corner_slide_was_cardinal ? "yes" : "no")
                  << ", reset_count=" << reset_count_after_slide << ")\n";
        return 3;
    }
    field_scene.set_controller_nibble(0U);
    auto neutral_position = wall_corner_slide_position;
    auto neutral_tail_position = wall_corner_slide_position;
    bool neutral_tail_stable = true;
    for (std::uint16_t neutral_tick = 1U; neutral_tick <= 30U;
         ++neutral_tick) {
        field_scene.advance_frame();
        const auto position = field_scene.field_entity_world_position();
        if (neutral_tick == 24U) {
            neutral_tail_position = position;
        }
        if (neutral_tick >= 24U &&
            (position.x != neutral_tail_position.x ||
             position.y != neutral_tail_position.y)) {
            neutral_tail_stable = false;
        }
        neutral_position = position;
        const auto frame_name =
            "wall-corner-release-" +
            (neutral_tick < 10U ? std::string("00")
             : neutral_tick < 100U ? std::string("0")
                                  : std::string()) +
            std::to_string(neutral_tick) + ".bmp";
        if (!save(frame_name)) {
            std::cerr << "field Stoker-property QA: neutral-frame dump failed\n";
            return 3;
        }
    }
    if (field_scene.field_controller_nibble_for_dump() != 0U ||
        !route_active() || !neutral_tail_stable ||
        !save("wall-corner-slide-release.bmp")) {
        std::cerr << "field Stoker-property QA: obstacle slide did not return "
                     "to a stable neutral-input state on the active map "
                     "(position="
                  << neutral_position.x << ',' << neutral_position.y
                  << ")\n";
        return 3;
    }

    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    std::uint16_t bypass_left_ticks = 0U;
    while (bypass_left_ticks < 48U &&
           field_scene.field_entity_world_position().x > 0x5300U &&
           route_active()) {
        field_scene.set_controller_nibble(0x04U);
        field_scene.advance_frame();
        ++bypass_left_ticks;
        if (bypass_left_ticks == 8U || bypass_left_ticks == 16U) {
            const auto name =
                "wall-bypass-left-" + std::to_string(bypass_left_ticks) +
                ".bmp";
            if (!save(name)) {
                std::cerr << "field Stoker-property QA: wall-bypass dump failed\n";
                return 3;
            }
        }
    }
    const auto bypass_position = field_scene.field_entity_world_position();
    if (!save("wall-bypass-left.bmp") ||
        bypass_position.x > 0x5340U || !route_active()) {
        std::cerr << "field Stoker-property QA: west side of the wall lane "
                     "was not reached (ticks="
                  << bypass_left_ticks << ", position=" << bypass_position.x
                  << ',' << bypass_position.y << ", scene="
                  << field_scene.field_scene_reference_for_dump() << ")\n";
        return 3;
    }

    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    std::uint16_t south_lane_ticks = 0U;
    // The wall's inclusive south edge is row 0x33F. The expanded runner
    // probe reaches seven rows beyond its center, so move the runner center
    // to row 0x348 before turning east toward record 2.
    while (south_lane_ticks < 80U &&
           field_scene.field_entity_world_position().y < 0x3480U &&
           route_active()) {
        field_scene.set_controller_nibble(0x02U);
        field_scene.advance_frame();
        ++south_lane_ticks;
        if (south_lane_ticks == 8U || south_lane_ticks == 16U ||
            south_lane_ticks == 24U) {
            const auto name = "property-lane-south-" +
                              std::to_string(south_lane_ticks) + ".bmp";
            if (!save(name)) {
                std::cerr << "field Stoker-property QA: property-lane dump failed\n";
                return 3;
            }
        }
    }
    const auto south_lane_position = field_scene.field_entity_world_position();
    if (!save("property-lane-south.bmp") ||
        (south_lane_position.y < 0x3480U &&
         !field_scene.dialogue_open()) ||
        (!route_active() && !field_scene.dialogue_open())) {
        std::cerr << "field Stoker-property QA: open south lane was not "
                     "reached (ticks="
                  << south_lane_ticks << ", position="
                  << south_lane_position.x << ',' << south_lane_position.y
                  << ", event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", scene=" << field_scene.field_scene_reference_for_dump()
                  << ")\n";
        return 3;
    }

    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    std::uint16_t property_ticks = 0U;
    std::ofstream property_probe_trace(
        output / "property-contact-probes.tsv", std::ios::trunc);
    std::ofstream property_step_trace(
        output / "property-contact-steps.tsv", std::ios::trunc);
    if (!property_probe_trace || !property_step_trace) {
        std::cerr << "field Stoker-property QA: could not create contact traces\n";
        return 3;
    }
    property_probe_trace
        << "tick\tbefore_x_fixed\tbefore_y_fixed\tafter_x_fixed"
           "\tafter_y_fixed\tcandidate_x_fixed\tcandidate_y_fixed"
           "\tnormalized_x\tnormalized_y\texpanded\tcorner0_x"
           "\tcorner0_y\tcorner0_byte\tcorner1_x\tcorner1_y"
           "\tcorner1_byte\tcorner2_x\tcorner2_y\tcorner2_byte"
           "\tcorner3_x\tcorner3_y\tcorner3_byte\tselected_tile_index"
           "\traw_terrain\tcollision_result\toutside_bounds\n";
    property_step_trace
        << "tick\tinput\tbefore_x\tbefore_y\tafter_x\tafter_y"
           "\theading\ttarget_heading\tanimation_heading\twalking"
           "\tcontroller_nibble\tbehavior_flags\n";
    field_scene.set_terrain_probe_trace_enabled_for_dump(true);
    bool property_contact_found = false;
    SceneRunnerPosition property_contact_before{};
    SceneRunnerPosition property_contact_after{};
    FieldTerrainProbeTrace property_contact_probe{};
    while (property_ticks < 64U &&
           field_scene.field_entity_world_position().x < property_approach_x &&
           route_active()) {
        const auto before = field_scene.field_entity_world_position();
        const auto before_image = render();
        field_scene.set_controller_nibble(0x08U);
        field_scene.advance_frame();
        ++property_ticks;
        const auto after = field_scene.field_entity_world_position();
        property_step_trace << property_ticks << "\t0x08\t" << before.x
                            << '\t' << before.y << '\t' << after.x << '\t'
                            << after.y << '\t'
                            << field_scene.field_entity_heading_for_dump()
                            << '\t'
                            << field_scene.field_entity_target_heading_for_dump()
                            << '\t'
                            << field_scene.field_entity_animation_heading_for_dump()
                            << '\t'
                            << (field_scene.field_entity_walking_for_dump()
                                    ? 1
                                    : 0)
                            << '\t'
                            << static_cast<unsigned>(
                                   field_scene.field_controller_nibble_for_dump())
                            << '\t'
                            << static_cast<unsigned>(
                                   field_scene.field_entity_behavior_flags_for_dump())
                            << '\n';
        const auto& probes = field_scene.terrain_probe_trace_for_dump();
        // advance_field_movement clears this trace at the start of every
        // update, so the complete per-frame sample begins at index zero.
        for (const auto& probe : probes) {
            property_probe_trace << property_ticks << '\t' << before.x << '\t'
                                 << before.y << '\t' << after.x << '\t'
                                 << after.y << '\t' << probe.candidate_x_fixed
                                 << '\t' << probe.candidate_y_fixed << '\t'
                                 << probe.normalized_x << '\t'
                                 << probe.normalized_y << '\t'
                                 << (probe.expanded_probe ? 1 : 0);
            for (std::size_t corner = 0U;
                 corner < probe.terrain_bytes.size(); ++corner) {
                property_probe_trace << '\t' << probe.corner_x[corner]
                                     << '\t' << probe.corner_y[corner]
                                     << "\t0x" << std::hex
                                     << static_cast<unsigned>(
                                            probe.terrain_bytes[corner])
                                     << std::dec;
            }
            property_probe_trace << '\t' << probe.selected_tile_index
                                 << "\t0x" << std::hex
                                 << static_cast<unsigned>(
                                        static_cast<std::uint8_t>(
                                            probe.raw_terrain_code))
                                 << "\t0x" << static_cast<unsigned>(
                                        static_cast<std::uint16_t>(
                                            probe.collision_result))
                                 << std::dec << '\t'
                                 << (probe.outside_bounds ? 1 : 0) << '\n';

            constexpr std::size_t kPropertyRecordIndex = 2U;
            const auto& source_rectangles =
                field_scene.state()
                    .field_scene_buffers.source_metadata
                    .terrain_collision_rectangles;
            if (source_rectangles.size() <= kPropertyRecordIndex) {
                continue;
            }
            const auto& record = source_rectangles[kPropertyRecordIndex];
            constexpr std::array<std::uint16_t, 4> kExpectedCornerX{
                0x0548U, 0x0560U, 0x0548U, 0x0560U};
            constexpr std::array<std::uint16_t, 4> kExpectedCornerY{
                0x034CU, 0x034CU, 0x035AU, 0x035AU};
            constexpr std::array<std::uint8_t, 4> kExpectedTerrainBytes{
                0x00U, 0x02U, 0x00U, 0x02U};
            const auto expanded_left =
                static_cast<std::int32_t>(record.left) - 12;
            const auto expanded_right =
                static_cast<std::int32_t>(record.right) + 12;
            const auto expanded_top =
                static_cast<std::int32_t>(record.top) - 7;
            const auto expanded_bottom =
                static_cast<std::int32_t>(record.bottom) + 7;
            const bool sampled_source_object = !probe.outside_bounds &&
                probe.expanded_probe && record.value == 0x0002U &&
                probe.raw_terrain_code == 0x0002 &&
                probe.collision_result == 0x007F &&
                probe.corner_x == kExpectedCornerX &&
                probe.corner_y == kExpectedCornerY &&
                probe.terrain_bytes == kExpectedTerrainBytes &&
                probe.selected_tile_index == 1707U &&
                probe.normalized_x >= expanded_left &&
                probe.normalized_x <= expanded_right &&
                probe.normalized_y >= expanded_top &&
                probe.normalized_y <= expanded_bottom &&
                std::any_of(
                    probe.terrain_bytes.begin(), probe.terrain_bytes.end(),
                    [](const std::uint8_t value) { return value == 0x02U; });
            if (!sampled_source_object || after.x != before.x ||
                after.y != before.y) {
                continue;
            }
            property_contact_found = true;
            property_contact_before = before;
            property_contact_after = after;
            property_contact_probe = probe;
            if (!save_frame("property-contact-before.bmp", before_image) ||
                !save("property-contact.bmp")) {
                std::cerr << "field Stoker-property QA: contact full-screen "
                             "dump failed\n";
                field_scene.set_controller_nibble(0U);
                field_scene.set_terrain_probe_trace_enabled_for_dump(false);
                return 3;
            }
            break;
        }
        if (property_ticks == 8U || property_ticks == 16U) {
            const auto name =
                "property-east-" + std::to_string(property_ticks) + ".bmp";
            if (!save(name)) {
                std::cerr << "field Stoker-property QA: property approach "
                             "dump failed\n";
                return 3;
            }
        }
        if (property_contact_found) {
            break;
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.set_terrain_probe_trace_enabled_for_dump(false);
    const auto property_position = field_scene.field_entity_world_position();
    constexpr std::size_t kPropertyRecordIndex = 2U;
    const auto& property_rectangles =
        field_scene.state()
            .field_scene_buffers.source_metadata.terrain_collision_rectangles;
    const bool property_record_matches_rom =
        property_rectangles.size() > kPropertyRecordIndex &&
        property_rectangles[kPropertyRecordIndex].left == 0x0560U &&
        property_rectangles[kPropertyRecordIndex].right == 0x057FU &&
        property_rectangles[kPropertyRecordIndex].top == 0x0340U &&
        property_rectangles[kPropertyRecordIndex].bottom == 0x034FU &&
        property_rectangles[kPropertyRecordIndex].value == 0x0002U;
    const auto normalized_contact_before_x =
        static_cast<std::int32_t>(property_contact_before.x >> 4U);
    const auto normalized_contact_candidate_x =
        static_cast<std::int32_t>(
            property_contact_probe.candidate_x_fixed >> 4U);
    const auto normalized_contact_candidate_y =
        static_cast<std::int32_t>(
            property_contact_probe.candidate_y_fixed >> 4U);
    const bool candidate_contacts_record_2 = property_record_matches_rom &&
        property_contact_found && property_contact_probe.expanded_probe &&
        property_contact_probe.raw_terrain_code == 0x0002 &&
        property_contact_probe.collision_result == 0x007F &&
        normalized_contact_before_x < 0x0554 &&
        normalized_contact_candidate_x >= 0x0554 &&
        normalized_contact_candidate_x <= 0x0557 &&
        normalized_contact_candidate_y >= 0x0339 &&
        normalized_contact_candidate_y <= 0x0356 &&
        property_contact_before.x == 0x5522U &&
        property_contact_before.y == 0x3534U &&
        property_contact_probe.candidate_x_fixed == 0x5540U &&
        property_contact_probe.candidate_y_fixed == 0x3534U &&
        // The ordinary on-screen runner selects the ROM 0xBEC2 vector table
        // here. Its east displacement is +30 (0x001E); 0xC002's +40 vector
        // belongs to the separate kind-0x0C attack pose.
        property_contact_probe.candidate_x_fixed ==
            property_contact_before.x + 0x001EU &&
        property_contact_probe.candidate_y_fixed ==
            property_contact_before.y &&
        property_contact_after.x == property_contact_before.x &&
        property_contact_after.y == property_contact_before.y &&
        property_position.x == property_contact_before.x &&
        property_position.y == property_contact_before.y;
    if (!candidate_contacts_record_2 ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_mode_event_code_for_dump() != 0U ||
        field_scene.field_projected_code_for_dump() != 0U ||
        field_scene.dialogue_open() || field_scene.field_interaction_open() ||
        field_scene.field_interaction_transition_active_for_dump()) {
        std::cerr << "field Stoker-property QA: type-2 collision candidate "
                     "did not retain its observed non-dialogue state "
                     "(event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", projected_code="
                  << field_scene.field_projected_code_for_dump()
                  << ", position=" << property_position.x << ','
                  << property_position.y << ", candidate="
                  << property_contact_probe.candidate_x_fixed << ','
                  << property_contact_probe.candidate_y_fixed
                  << ", candidate_matches_record_2="
                  << (candidate_contacts_record_2 ? "yes" : "no")
                  << ", probe_found="
                  << (property_contact_found ? "yes" : "no")
                  << ", raw_terrain=0x" << std::hex
                  << static_cast<unsigned>(static_cast<std::uint8_t>(
                         property_contact_probe.raw_terrain_code))
                  << ", result=0x"
                  << static_cast<unsigned>(static_cast<std::uint16_t>(
                         property_contact_probe.collision_result))
                  << std::dec
                  << ", scene=" << field_scene.field_scene_reference_for_dump()
                  << ", dialogue="
                  << (field_scene.dialogue_open() ? "open" : "closed")
                  << ", interaction="
                  << (field_scene.field_interaction_open() ? "open" : "closed")
                  << ", property_ticks=" << property_ticks << ")\n";
        const auto active_actor_positions =
            field_scene.active_default_actor_positions_for_dump();
        std::cerr << "active_scene2_actors=" << active_actor_positions.size();
        for (const auto& actor_position : active_actor_positions) {
            std::cerr << " (" << actor_position.x << ',' << actor_position.y
                      << ')';
        }
        std::cerr << '\n';
        return 3;
    }

    for (std::uint8_t idle = 1U; idle <= 30U; ++idle) {
        field_scene.advance_frame();
        if (idle == 1U || idle == 8U || idle == 30U) {
            const auto name = "idle-" +
                              (idle < 10U ? std::string("0")
                                          : std::string()) +
                              std::to_string(idle) + ".bmp";
            if (!save(name)) {
                std::cerr << "field Stoker-property QA: idle frame dump failed\n";
                return 3;
            }
        }
    }
    const bool actual_saved = save("actual.bmp");
    std::vector<std::string> actual_bmp_names;
    for (std::filesystem::directory_iterator item(output, directory_error), end;
         !directory_error && item != end; item.increment(directory_error)) {
        if (item->is_regular_file(directory_error) &&
            item->path().extension() == ".bmp") {
            actual_bmp_names.push_back(item->path().filename().string());
        }
    }
    if (directory_error) {
        std::cerr << "field Stoker-property QA: output list failed: "
                  << directory_error.message() << '\n';
        return 3;
    }
    std::sort(saved_bmp_names.begin(), saved_bmp_names.end());
    std::sort(actual_bmp_names.begin(), actual_bmp_names.end());
    const auto settled_position = field_scene.field_entity_world_position();
    if (!actual_saved || actual_bmp_names != saved_bmp_names ||
        field_scene.field_controller_nibble_for_dump() != 0U ||
        settled_position.x != property_position.x ||
        settled_position.y != property_position.y ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_mode_event_code_for_dump() != 0U ||
        field_scene.dialogue_open() || field_scene.field_interaction_open()) {
        std::cerr << "field Stoker-property QA: idle movement, no-dialogue "
                     "state, or complete full-screen dump set changed\n";
        return 3;
    }

    std::cout << "field_stoker_collision_candidate_qa=passed "
              << "scene=2 event=0 projected_code=0 "
              << "candidate="
              << property_contact_probe.candidate_x_fixed << ','
              << property_contact_probe.candidate_y_fixed
              << " outcome=no_stoker_dialogue east_ticks=" << east_ticks
              << " south_ticks=" << south_ticks
              << " blocked_animation=C052_idle"
              << " edge_probe_start=" << wall_corner_start.x << ','
              << wall_corner_start.y
              << " edge_probe_commit=" << wall_corner_slide_position.x
              << ',' << wall_corner_slide_position.y
              << " edge_slide_input_frames=" << corner_ticks
              << " neutral_tail=" << neutral_tail_position.x << ','
              << neutral_tail_position.y
              << " property_ticks=" << property_ticks
              << " property_contact_raw=0x" << std::hex
              << static_cast<unsigned>(static_cast<std::uint8_t>(
                     property_contact_probe.raw_terrain_code))
              << " property_contact_result=0x"
              << static_cast<unsigned>(static_cast<std::uint16_t>(
                     property_contact_probe.collision_result))
              << std::dec
              << " sfx_events=" << field_audio_events.size()
              << " artifacts=" << output.string() << '\n';
    return 0;
}

int run_field_scene2_motel_street_collision_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events) {
    std::filesystem::create_directories(output);
    std::error_code directory_error;
    for (std::filesystem::directory_iterator item(output, directory_error), end;
         !directory_error && item != end; item.increment(directory_error)) {
        if (item->is_regular_file(directory_error) &&
            item->path().extension() == ".bmp") {
            std::filesystem::remove(item->path(), directory_error);
            if (directory_error) {
                std::cerr << "Scene-2 motel collision QA: could not clear old "
                          << item->path().filename().string() << ": "
                          << directory_error.message() << '\n';
                return 3;
            }
        }
    }
    if (directory_error) {
        std::cerr << "Scene-2 motel collision QA: could not inspect output: "
                  << directory_error.message() << '\n';
        return 3;
    }
    // Stabilize source-PRNG-driven actor delays across repeated runs/builds;
    // this is QA determinism, not the live game's unresolved seed source.
    field_scene.set_source_random_seed_for_dump(0x1357U);

    std::ofstream trace(output / "motel-street-movement.tsv");
    if (!trace) {
        std::cerr << "Scene-2 motel collision QA: could not open movement log\n";
        return 3;
    }
    const auto audio_events_before = field_audio_events.size();
    bool animation_state_coherent = true;
    bool saw_walking_animation = false;
    trace << "phase\tframe\tinput\tx\ty\tscene\tevent\theading"
             "\ttarget_heading\tanimation_heading\tdirection\twalking"
             "\tselector\tanimation_frame\taudio_event_count\n";
    const auto record = [&] (const std::string_view phase,
                             const unsigned frame,
                             const std::uint8_t input) {
        const auto position = field_scene.field_entity_world_position();
        const auto direction = field_scene.field_entity_direction_for_dump();
        const auto walking = field_scene.field_entity_walking_for_dump();
        const auto selector =
            field_scene.field_entity_animation_selector_for_dump();
        const auto animation_frame =
            field_scene.field_entity_animation_frame_for_dump();
        if (walking) {
            saw_walking_animation = true;
            animation_state_coherent = animation_state_coherent &&
                direction == field_movement_direction_from_heading(
                                 field_scene
                                     .field_entity_animation_heading_for_dump()) &&
                selector == static_cast<std::uint16_t>(0x0020U + direction * 4U) &&
                animation_frame <= 3U;
        } else {
            const auto heading_direction =
                field_movement_direction_from_heading(
                    field_scene.field_entity_heading_for_dump());
            animation_state_coherent = animation_state_coherent &&
                direction == heading_direction &&
                selector == static_cast<std::uint16_t>(direction * 4U) &&
                animation_frame == 0U;
        }
        trace << phase << '\t' << frame << '\t'
              << static_cast<unsigned>(input) << '\t' << position.x << '\t'
              << position.y << '\t'
              << field_scene.field_scene_reference_for_dump() << '\t'
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump())
              << '\t' << field_scene.field_entity_heading_for_dump() << '\t'
              << field_scene.field_entity_target_heading_for_dump() << '\t'
              << field_scene.field_entity_animation_heading_for_dump() << '\t'
              << static_cast<unsigned>(direction) << '\t'
              << (walking ? 1 : 0) << '\t' << selector << '\t'
              << animation_frame << '\t' << field_audio_events.size()
              << '\n';
    };
    const auto save = [&field_scene, &output](const std::string_view name) {
        QImage image(kSceneWidth, kSceneHeight, QImage::Format_RGB32);
        image.fill(Qt::black);
        QPainter painter(&image);
        field_scene.paint(painter);
        painter.end();
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
               image.save(QString::fromStdWString(
                   (output / std::string(name)).wstring()));
    };
    const auto route_active = [&field_scene] {
        return field_scene.field_scene_reference_for_dump() == 2U &&
               field_scene.field_mode_event_code_for_dump() == 0U &&
               !field_scene.dialogue_open() &&
               !field_scene.field_interaction_open() &&
               !field_scene.field_interaction_transition_active_for_dump() &&
               !field_scene.field_transition_pending_for_dump();
    };
    const auto start = field_scene.field_entity_world_position();
    if (!route_active() || start.x != 0x3CE0U || start.y != 0x2D00U ||
        !save("spawn.bmp")) {
        std::cerr << "Scene-2 motel collision QA: unexpected New Game spawn "
                  << "scene=" << field_scene.field_scene_reference_for_dump()
                  << " position=" << start.x << ',' << start.y << '\n';
        return 3;
    }
    record("spawn", 0U, 0U);

    // Scene-2 ROM records 32-38 (0x172EEA..0x172F26) form the motel's north
    // wall and its short west/east returns. Record 91 (0x173138, C2) is the
    // doorway directly east of this test lane. Approach the west wall with
    // normal controller input so the QA cannot bypass the live collision path.
    constexpr std::uint16_t west_wall_lane_x = 0x3B20U;
    std::uint16_t west_ticks = 0U;
    while (west_ticks < 160U &&
           field_scene.field_entity_world_position().x > west_wall_lane_x &&
           route_active()) {
        field_scene.set_controller_nibble(0x04U);
        field_scene.advance_frame();
        ++west_ticks;
        record("approach-west", west_ticks, 0x04U);
        if (west_ticks == 8U || west_ticks == 16U || west_ticks == 32U) {
            const auto name = "approach-west-" +
                              std::to_string(west_ticks) + ".bmp";
            if (!save(name)) {
                std::cerr << "Scene-2 motel collision QA: west dump failed\n";
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    const auto wall_approach = field_scene.field_entity_world_position();
    record("approach-west-release", west_ticks, 0U);
    if (!route_active() || west_ticks == 160U ||
        wall_approach.x < 0x3A80U || wall_approach.x > 0x3C00U ||
        wall_approach.y < 0x2A00U || wall_approach.y > start.y ||
        !save("approach-west.bmp")) {
        std::cerr << "Scene-2 motel collision QA: could not reach the wall lane "
                  << "ticks=" << west_ticks << " position="
                  << wall_approach.x << ',' << wall_approach.y << '\n';
        return 3;
    }

    std::uint16_t north_ticks = 0U;
    std::uint16_t north_stationary_frames = 0U;
    for (; north_ticks < 80U && route_active(); ++north_ticks) {
        const auto before = field_scene.field_entity_world_position();
        field_scene.set_controller_nibble(0x01U);
        field_scene.advance_frame();
        const auto after = field_scene.field_entity_world_position();
        north_stationary_frames =
            after.x == before.x && after.y == before.y
                ? static_cast<std::uint16_t>(north_stationary_frames + 1U)
                : 0U;
        record("press-north", north_ticks + 1U, 0x01U);
        if (north_ticks < 19U || north_ticks == 31U ||
            north_ticks == 63U) {
            const auto frame = north_ticks + 1U;
            const auto name = north_ticks < 19U
                ? "press-north-step-" +
                      (frame < 10U ? std::string("0") : std::string()) +
                      std::to_string(frame) + ".bmp"
                : "press-north-" + std::to_string(frame) + ".bmp";
            if (!save(name)) {
                std::cerr << "Scene-2 motel collision QA: north dump failed\n";
                return 3;
            }
        }
    }
    const auto held_contact = field_scene.field_entity_world_position();
    const auto held_selector =
        field_scene.field_entity_animation_selector_for_dump();
    const auto held_frame = field_scene.field_entity_animation_frame_for_dump();
    const bool north_hold_settled =
        north_stationary_frames >= 8U &&
        !field_scene.field_entity_walking_for_dump() && held_frame == 0U &&
        held_selector <= 0x001CU && (held_selector & 0x0003U) == 0U;
    if (!route_active() || north_ticks != 80U || !north_hold_settled ||
        !save("north-held-contact.bmp")) {
        std::cerr << "Scene-2 motel collision QA: held Up did not settle at the "
                  << "source wall; position=" << held_contact.x << ','
                  << held_contact.y << " stationary_frames="
                  << north_stationary_frames << " selector=" << held_selector
                  << " frame=" << held_frame << '\n';
        return 3;
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    const auto blocked_position = field_scene.field_entity_world_position();
    record("north-release", north_ticks, 0U);
    const auto blocked_selector =
        field_scene.field_entity_animation_selector_for_dump();
    if (!route_active() || north_ticks != 80U ||
        blocked_position.y >= wall_approach.y ||
        blocked_position.x != held_contact.x ||
        blocked_position.y != held_contact.y ||
        blocked_position.x < 0x3A80U || blocked_position.x > 0x3C00U ||
        field_scene.field_entity_walking_for_dump() ||
        field_scene.field_entity_animation_frame_for_dump() != 0U ||
        blocked_selector > 0x001CU || (blocked_selector & 0x0003U) != 0U ||
        !save("north-wall-contact.bmp")) {
        std::cerr << "Scene-2 motel collision QA: did not settle against the "
                  << "ROM wall in C052 idle; position=" << blocked_position.x
                  << ',' << blocked_position.y << " selector="
                  << blocked_selector << " frame="
                  << field_scene.field_entity_animation_frame_for_dump()
                  << '\n';
        return 3;
    }

    // Walking diagonally away along the wall and then retreating tests that a
    // rejected northward candidate does not leave a stale movement state.
    const auto slide_start = field_scene.field_entity_world_position();
    std::uint16_t diagonal_ticks = 0U;
    for (; diagonal_ticks < 48U && route_active(); ++diagonal_ticks) {
        field_scene.set_controller_nibble(0x05U); // north + west
        field_scene.advance_frame();
        record("north-west", diagonal_ticks + 1U, 0x05U);
        if (diagonal_ticks < 16U || diagonal_ticks == 31U ||
            diagonal_ticks == 47U) {
            const auto frame = diagonal_ticks + 1U;
            const auto name = diagonal_ticks < 16U
                ? "north-west-step-" +
                      (frame < 10U ? std::string("0") : std::string()) +
                      std::to_string(frame) + ".bmp"
                : "north-west-" + std::to_string(frame) + ".bmp";
            if (!save(name)) {
                std::cerr << "Scene-2 motel collision QA: diagonal dump failed\n";
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    const auto slide_end = field_scene.field_entity_world_position();
    const auto slide_moved = slide_end.x != slide_start.x ||
                             slide_end.y != slide_start.y;
    record("diagonal-release", diagonal_ticks, 0U);
    if (!route_active() || diagonal_ticks != 48U || !slide_moved ||
        !save("north-west-result.bmp")) {
        std::cerr << "Scene-2 motel collision QA: diagonal escape did not "
                  << "advance from the wall; start=" << slide_start.x << ','
                  << slide_start.y << " end=" << slide_end.x << ','
                  << slide_end.y << '\n';
        return 3;
    }

    std::uint16_t retreat_ticks = 0U;
    while (retreat_ticks < 64U &&
           field_scene.field_entity_world_position().y <
               static_cast<std::uint16_t>(start.y - 0x0080U) &&
           route_active()) {
        field_scene.set_controller_nibble(0x02U); // south, away from building
        field_scene.advance_frame();
        ++retreat_ticks;
        record("retreat-south", retreat_ticks, 0x02U);
        if (retreat_ticks == 8U || retreat_ticks == 16U ||
            retreat_ticks == 32U) {
            const auto name = "retreat-south-" +
                              std::to_string(retreat_ticks) + ".bmp";
            if (!save(name)) {
                std::cerr << "Scene-2 motel collision QA: retreat dump failed\n";
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    for (std::uint16_t idle = 1U; idle <= 30U; ++idle) {
        field_scene.advance_frame();
        record("idle", idle, 0U);
    }
    const auto actual = field_scene.field_entity_world_position();
    if (!route_active() || retreat_ticks == 64U ||
        actual.y < static_cast<std::uint16_t>(start.y - 0x0080U) ||
        field_scene.field_entity_walking_for_dump() ||
        field_scene.field_entity_animation_frame_for_dump() != 0U ||
        !saw_walking_animation || !animation_state_coherent ||
        !save("actual.bmp")) {
        std::cerr << "Scene-2 motel collision QA: retreat/idle did not finish "
                  << "cleanly; position=" << actual.x << ',' << actual.y
                  << " retreat_ticks=" << retreat_ticks << '\n';
        return 3;
    }
    trace.close();
    if (!trace) {
        std::cerr << "Scene-2 motel collision QA: movement log write failed\n";
        return 3;
    }
    std::cout << "field_scene2_motel_street_collision_qa=passed scene=2 "
              << "wall_approach=" << wall_approach.x << ','
              << wall_approach.y << " wall_contact=" << blocked_position.x
              << ',' << blocked_position.y << " diagonal_escape="
              << slide_end.x << ',' << slide_end.y << " retreat=" << actual.x
              << ',' << actual.y << " frames=" << west_ticks + north_ticks +
                     diagonal_ticks + retreat_ticks
              << " animation_state="
              << (animation_state_coherent ? "source-facing" : "mismatch")
              << " north_hold_stationary_frames="
              << north_stationary_frames
              << " audio_event_delta="
              << (field_audio_events.size() >= audio_events_before
                      ? field_audio_events.size() - audio_events_before
                      : 0U)
              << " artifacts=" << output.string() << '\n';
    return 0;
}

int run_field_jump_house_entry_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::error_code output_error;
    std::filesystem::remove_all(output, output_error);
    if (output_error) {
        std::cerr << "Jump House entry QA: could not clear prior captures: "
                  << output_error.message() << '\n';
        return 3;
    }
    std::filesystem::create_directories(output, output_error);
    if (output_error) {
        std::cerr << "Jump House entry QA: could not create capture folder: "
                  << output_error.message() << '\n';
        return 3;
    }

    constexpr std::size_t kJumpHouseRecord = 85U;
    constexpr std::uint16_t kJumpHouseCollision = 0x00C4U;
    constexpr std::uint8_t kJumpHouseEvent = 4U;
    constexpr std::uint8_t kJumpHouseScene = 13U;
    const auto& metadata =
        field_scene.state().field_scene_buffers.source_metadata;
    const auto& rectangles = metadata.terrain_collision_rectangles;
    const auto initial_position = field_scene.field_entity_world_position();
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        initial_position.x != 0x1D00U || initial_position.y != 0x0A00U ||
        rectangles.size() <= kJumpHouseRecord ||
        rectangles[kJumpHouseRecord].left != 0x01C0U ||
        rectangles[kJumpHouseRecord].right != 0x01DFU ||
        rectangles[kJumpHouseRecord].top != 0x0080U ||
        rectangles[kJumpHouseRecord].bottom != 0x009FU ||
        rectangles[kJumpHouseRecord].value != kJumpHouseCollision) {
        std::cerr << "Jump House entry QA: scene-2 spawn or ROM record 85 "
                     "does not match (scene="
                  << field_scene.field_scene_reference_for_dump() << ", x="
                  << initial_position.x << ", y=" << initial_position.y
                  << ", records=" << rectangles.size() << ")\n";
        return 3;
    }

    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save = [&](const std::string_view name,
                          const std::optional<bool> expect_field_hud) {
        const auto image = render();
        const auto path = output / (std::string(name) + ".bmp");
        if (image.size() != QSize(kSceneWidth, kSceneHeight) ||
            (expect_field_hud.has_value() &&
             field_hud_chrome_survives(image, asset_root) !=
                 *expect_field_hud) ||
            (expect_field_hud == std::optional<bool>{true} &&
             count_playfield_lit(image) < 100U) ||
            !image.save(QString::fromStdWString(path.wstring()))) {
            std::cerr << "Jump House entry QA: full-screen capture failed for "
                      << name << '\n';
            return false;
        }
        return true;
    };

    if (!save("spawn", true)) {
        return 3;
    }
    std::uint16_t movement_ticks = 0U;
    for (; movement_ticks < 60U; ++movement_ticks) {
        field_scene.set_controller_nibble(0x01U); // ordinary Up into record 85
        field_scene.advance_frame();
        if (field_scene.field_interaction_transition_active_for_dump() ||
            field_scene.field_transition_pending_for_dump() ||
            field_scene.dialogue_open() ||
            field_scene.field_scene_reference_for_dump() != 2U) {
            ++movement_ticks;
            break;
        }
    }
    field_scene.set_controller_nibble(0U);
    const auto doorway_position = field_scene.field_entity_world_position();
    const auto& movement =
        field_scene.last_field_movement_transition_for_dump();
    if (movement_ticks == 0U || movement_ticks >= 60U ||
        field_scene.field_terrain_collision_code_for_dump() != 0xFFC4U ||
        field_scene.field_projected_code_for_dump() != 0xFFC4U ||
        field_scene.field_mode_event_code_for_dump() != kJumpHouseEvent ||
        !field_scene.field_interaction_transition_active_for_dump()) {
        std::cerr << "Jump House entry QA: ordinary movement did not contact "
                     "record 85/event 4 (ticks=" << movement_ticks
                  << ", position=" << doorway_position.x << ','
                  << doorway_position.y << ", collision=0x" << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << ", projected=0x"
                  << field_scene.field_projected_code_for_dump() << std::dec
                  << ", event=" << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << ", continuation="
                  << static_cast<unsigned>(movement.continuation) << ")\n";
        return 3;
    }
    if (!save("doorway-contact", std::nullopt)) {
        return 3;
    }

    for (std::uint8_t settle = 0U;
         settle < 80U && !field_scene.dialogue_open() &&
         field_scene.field_scene_reference_for_dump() == 2U;
         ++settle) {
        field_scene.advance_frame();
    }
    const auto& entry = field_scene.dialogue_panel();
    bool entry_text_found = false;
    for (std::size_t index = 0U; index < entry.text_segment_count; ++index) {
        entry_text_found = entry_text_found ||
            entry.text_segments[index].find("The Jump House") !=
                std::string_view::npos;
    }
    const auto entry_image = render();
    if (!field_scene.dialogue_open() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        !entry.source_complete || entry.option_count != 0U ||
        entry.portrait_alias != "dialogue.portraits.jump.house.entry" ||
        !entry_text_found || field_hud_chrome_survives(entry_image, asset_root) ||
        !image_has_green_ink(entry_image, 88, 16, 216, 120) ||
        !save("entry-description", false)) {
        std::cerr << "Jump House entry QA: collision did not display the "
                     "source entry description as a clean modal page\n";
        return 3;
    }
    const auto entry_opened = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.entry.jump_house_description_opened"));
    if (entry_opened != 1) {
        std::cerr << "Jump House entry QA: indexed ROM service did not open "
                     "exactly one entry page\n";
        return 3;
    }

    field_scene.set_controller_port_byte(0x40U); // ordinary A dismisses page
    field_scene.advance_frame();
    field_scene.set_controller_port_byte(0U);
    if (field_scene.dialogue_open() ||
        field_scene.field_scene_reference_for_dump() != kJumpHouseScene ||
        field_scene.field_modal_return_transition_frames_for_dump() != 60U ||
        !save("scene13-transition-start", std::nullopt)) {
        std::cerr << "Jump House entry QA: dismissing the entry page did not "
                     "resume the retained scene-13 route\n";
        return 3;
    }
    for (std::uint8_t frame = 0U; frame < 60U; ++frame) {
        field_scene.advance_frame();
        if (frame == 29U &&
            !save("scene13-transition-midpoint", std::nullopt)) {
            return 3;
        }
    }
    const auto final_image = render();
    const auto entered_scene = std::count(
        source_boundaries.begin(), source_boundaries.end(),
        std::string("field.entry.jump_house_scene_entered"));
    const bool clean_scene =
        field_scene.field_scene_reference_for_dump() == kJumpHouseScene &&
        !field_scene.dialogue_open() && !field_scene.field_interaction_open() &&
        field_scene.field_modal_return_transition_frames_for_dump() == 0U &&
        field_scene.field_palette_fade_steps_for_dump() == 0U &&
        field_scene.field_entity_visible_for_dump() &&
        field_hud_chrome_survives(final_image, asset_root) &&
        count_playfield_lit(final_image) >= 100U;
    if (!clean_scene || entered_scene != 1 || !save("actual", true)) {
        std::cerr << "Jump House entry QA: scene 13 did not finish with a "
                     "clean full-screen field redraw (scene="
                  << field_scene.field_scene_reference_for_dump()
                  << ", entered=" << entered_scene << ")\n";
        return 3;
    }

    // Continue on the same FieldSceneRuntime instance through the production
    // Gunderson Lua task and its wallet service. This deterministic dialogue
    // entry isolates the conversation after the real scene-2/event-4 route;
    // movement into scene-13/event-30 remains a separate QA gap.
    const auto panel_contains = [&field_scene](const std::string_view needle) {
        const auto& panel = field_scene.dialogue_panel();
        for (std::size_t index = 0U; index < panel.text_segment_count;
             ++index) {
            if (panel.text_segments[index].find(needle) !=
                std::string_view::npos) {
                return true;
            }
        }
        return false;
    };
    field_scene.set_field_funds_for_dump(1000U);
    if (!field_scene.open_gunderson_interaction_for_dump() ||
        !field_scene.dialogue_open() ||
        field_scene.dialogue_panel().option_count != 3U ||
        !save("gunderson-root", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x4000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        !panel_contains("Info, eh?") ||
        !save("gunderson-information-opening", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x4000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        field_scene.dialogue_panel().option_count != 3U ||
        !save("gunderson-information-topics", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x1000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        !panel_contains("Contacts!") ||
        !save("gunderson-contacts-introduction", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x4000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        field_scene.dialogue_panel().option_count != 2U ||
        !panel_contains("1000$") ||
        !save("gunderson-decker-offer", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x4000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        field_scene.field_funds_for_dump() !=
            std::optional<std::uint32_t>{0U} ||
        !panel_contains("Wilma Temmenhoff") ||
        !save("gunderson-contact-purchased", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x1000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        !panel_contains("Contacts!") ||
        !save("gunderson-contacts-repeat", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x4000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        field_scene.advance_stoker_dialogue_for_dump(0x4000U) !=
            FieldDialogueAdvanceResult::prompt_advanced ||
        field_scene.field_funds_for_dump() !=
            std::optional<std::uint32_t>{0U} ||
        !panel_contains("short on nuyen") ||
        !save("gunderson-contact-repeat-insufficient", false) ||
        field_scene.advance_stoker_dialogue_for_dump(0x2000U) !=
            FieldDialogueAdvanceResult::returned_to_field ||
        field_scene.dialogue_open()) {
        std::cerr << "Jump House entry QA: the connected Gunderson Lua/wallet "
                     "route did not present, debit, repeat, and reject the "
                     "unfunded contact purchase cleanly\n";
        return 3;
    }

    std::ofstream route(output / "route.tsv", std::ios::trunc);
    if (!route) {
        return 3;
    }
    route << "trigger_record\tcollision\tevent\tdestination_scene\t"
             "movement_ticks\taudio_requests\tcontact_wallet_after_purchase\n"
          << "85\t0x00C4\t4\t13\t" << movement_ticks << '\t'
          << field_audio_events.size() << "\t0\n";
    std::cout << "field_jump_house_entry_qa=passed record=85 event=4 "
                 "movement=ordinary-up entry=lua dismissal=ordinary-A "
                 "destination_scene=13 clean_redraw=yes audio_requests="
              << field_audio_events.size() << " artifacts=" << output.string()
              << '\n';
    return 0;
}

int run_field_redmond_vigore_search_qa(
    FieldSceneRuntime& field_scene,
    const std::filesystem::path& asset_root,
    const std::filesystem::path& output,
    const std::vector<std::uint16_t>& field_audio_events,
    const std::vector<std::string>& source_boundaries) {
    std::filesystem::create_directories(output);
    std::ofstream trace(output / "redmond-vigore-search.tsv");
    if (!trace) {
        std::cerr << "Redmond Vigore QA: could not create route trace\n";
        return 3;
    }
    const auto render = [&field_scene] { return render_qa_field(field_scene); };
    const auto save = [&](const std::string_view name) {
        const auto image = render();
        return image.size() == QSize(kSceneWidth, kSceneHeight) &&
               image.save(QString::fromStdWString(
                   (output / std::string(name)).wstring()));
    };
    const auto record = [&](const std::string_view phase, unsigned frame,
                            std::uint8_t input) {
        const auto position = field_scene.field_entity_world_position();
        trace << phase << '\t' << frame << '\t'
              << static_cast<unsigned>(input) << '\t' << position.x << '\t'
              << position.y << '\t'
              << static_cast<unsigned>(
                     field_scene.field_mode_event_code_for_dump())
              << '\t' << (field_scene.dialogue_open() ? 1 : 0) << '\t'
              << field_audio_events.size() << '\n';
    };
    const auto& records_before = field_scene.field_party_records_for_dump();
    std::vector<std::uint8_t> karma_before;
    karma_before.reserve(records_before.size());
    for (const auto& record : records_before) {
        karma_before.push_back(record.auxiliary[2U]);
    }
    constexpr std::uint8_t kUpNibble = 0x01U;
    field_scene.seed_vigore_search_for_dump();
    field_scene.set_group_item_flags_for_dump(0U);
    const auto audio_before = field_audio_events.size();
    if (field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_entity_world_position().x != 0x1B00U ||
        field_scene.field_entity_world_position().y != 0x4600U ||
        field_scene.dialogue_open() ||
        field_scene.field_mode_event_code_for_dump() != 0U ||
        !save("approach-start.bmp")) {
        std::cerr << "Redmond Vigore QA: expected a clean scene-2 pre-trigger state\n";
        return 3;
    }
    trace << "phase\tframe\tinput\tx\ty\tevent\tdialogue\taudio_count\n";
    record("approach", 0U, 0U);
    std::uint16_t approach_frames = 0U;
    for (; approach_frames < 48U && !field_scene.dialogue_open();
         ++approach_frames) {
        field_scene.set_controller_nibble(kUpNibble);
        field_scene.advance_frame();
        record("approach", approach_frames + 1U, kUpNibble);
        if (approach_frames == 0U || approach_frames == 3U ||
            approach_frames == 7U || approach_frames == 15U) {
            if (!save("approach-" +
                      std::to_string(approach_frames + 1U) + ".bmp")) {
                std::cerr << "Redmond Vigore QA: approach frame dump failed\n";
                return 3;
            }
        }
    }
    field_scene.set_controller_nibble(0U);
    field_scene.advance_frame();
    const auto first_event = field_scene.dialogue_panel();
    (void)save("page-0-candidate.bmp");
    constexpr std::array<std::array<std::string_view, 5>, 3> expected_text{{
        {{"This area seems to have been swept", "",
          "Knowing Vigore must be somewhere", "",
          "You get lucky and find a secret entrance"}},
        {{"After a quick search of the bunker", "",
          "In addition, the landmark map", "",
          "Harlequin should be most interested"}},
        {{"You leave cautiously, expecting", "",
          "Fortunately, your luck holds out", "", ""}},
    }};
    const auto page_matches = [&](const DialoguePanelView& panel,
                                  const std::size_t page) {
        if (!panel.open || panel.actor_name != "Narration" ||
            panel.portrait_alias != "none" ||
            panel.option_count != (page < 2U ? 1U : 0U) ||
            panel.text_segment_count != (page == 2U ? 3U : 5U) ||
            panel.has_more != (page < 2U)) {
            return false;
        }
        if (page < 2U &&
            (panel.options[0].role !=
                 DialoguePanelOptionRole::field_continue ||
             panel.options[0].source_label.find("MORE") ==
                 std::string_view::npos ||
             panel.continuation_label.find("MORE") ==
                 std::string_view::npos)) {
            return false;
        }
        for (std::size_t segment = 0U;
             segment < panel.text_segment_count; ++segment) {
            if ((expected_text[page][segment].empty() &&
                 !panel.text_segments[segment].empty()) ||
                (!expected_text[page][segment].empty() &&
                 panel.text_segments[segment].find(
                     expected_text[page][segment]) == std::string_view::npos)) {
                return false;
            }
        }
        return true;
    };
    if (approach_frames == 48U ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        !page_matches(first_event, 0U) ||
        std::find(source_boundaries.begin(), source_boundaries.end(),
                  "field.event.redmond_vigore_search_opened") ==
            source_boundaries.end() ||
        !save("page-0.bmp")) {
        std::cerr << "Redmond Vigore QA: ordinary movement did not open source page 0"
                  << "; frames=" << approach_frames << " scene="
                  << field_scene.field_scene_reference_for_dump() << " event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << " dialogue=" << field_scene.dialogue_open() << '\n';
        std::cerr << "  panel_open=" << first_event.open
                  << " actor='" << first_event.actor_name << "' portrait='"
                  << first_event.portrait_alias << "' segments="
                  << first_event.text_segment_count << " more="
                  << first_event.has_more << " label='"
                  << first_event.continuation_label << "' options="
                  << first_event.option_count << '\n';
        for (std::size_t index = 0U;
             index < first_event.text_segment_count; ++index) {
            std::cerr << "  text[" << index << "]=\""
                      << first_event.text_segments[index] << "\"\n";
        }
        const auto& metadata =
            field_scene.state().field_scene_buffers.source_metadata;
        std::cerr << "  runner=" << field_scene.field_entity_world_position().x
                  << ',' << field_scene.field_entity_world_position().y
                  << " active=" << field_scene.field_entity_active_for_dump()
                  << " behavior=0x" << std::hex
                  << static_cast<unsigned>(
                         field_scene.field_entity_behavior_flags_for_dump())
                  << " terrain=0x" << std::hex
                  << field_scene.field_terrain_collision_code_for_dump()
                  << " bounds=0x" << metadata.terrain_x_inclusive_lower
                  << "..0x" << metadata.terrain_x_exclusive_upper << ",0x"
                  << metadata.terrain_y_inclusive_lower << "..0x"
                  << metadata.terrain_y_exclusive_upper << std::dec
                  << " failure=" << field_scene.failure() << '\n';
        const auto& transition =
            field_scene.last_field_movement_transition_for_dump();
        std::cerr << "  mode=" << field_scene.field_interaction_mode_for_dump()
                  << " transition_kind=" << static_cast<unsigned>(transition.kind)
                  << " negative_probes="
                  << static_cast<unsigned>(transition.negative_probe_count)
                  << " transitioned_event="
                  << static_cast<unsigned>(field_collision_event_value(
                         transition.event_code))
                  << " published=" << transition.mode_event_code_published
                  << " controller=" << static_cast<unsigned>(
                         field_scene.field_controller_nibble_for_dump())
                  << '\n';
        std::cerr << "  scene-2 collision cells near event-7 (x,y,value):";
        for (const auto y : std::array<std::uint16_t, 3>{{
                 0x0420U, 0x0440U, 0x0460U}}) {
            for (const auto x : std::array<std::uint16_t, 4>{{
                     0x0180U, 0x01A0U, 0x01C0U, 0x0200U}}) {
                const auto index = static_cast<std::size_t>(
                    (x >> 5U) + ((y & 0x7FE0U) << 1U));
                if (index < metadata.terrain_collision_map.size()) {
                    std::cerr << " (0x" << std::hex << x << ",0x" << y
                              << ",0x" << static_cast<unsigned>(
                                     metadata.terrain_collision_map[index])
                              << ')';
                }
            }
        }
        std::cerr << std::dec << '\n';
        const auto first_boundary = source_boundaries.size() > 8U
            ? source_boundaries.end() - 8
            : source_boundaries.begin();
        for (auto boundary = first_boundary;
             boundary != source_boundaries.end(); ++boundary) {
            std::cerr << "  boundary=" << *boundary << '\n';
        }
        return 3;
    }
    record("page-0", approach_frames, 0U);

    // A held dialogue page should not animate its text, prompt or speaker
    // portrait. Save full frames and compare the modal rectangle while the
    // field actor services continue underneath it.
    const auto page_zero_image = render();
    for (unsigned idle = 1U; idle <= 30U; ++idle) {
        field_scene.set_controller_port_byte(0U);
        field_scene.advance_frame();
        if (idle == 15U || idle == 30U) {
            const auto image = render();
            if (!image.save(QString::fromStdWString(
                    (output / ("page-0-idle-" + std::to_string(idle) +
                               ".bmp")).wstring()))) {
                std::cerr << "Redmond Vigore QA: idle page dump failed\n";
                return 3;
            }
            if (image_region_differs(page_zero_image, image, 0, 0,
                                     kSceneWidth, kSceneHeight)) {
                std::cerr << "Redmond Vigore QA: full-screen dialogue page changed during idle\n";
                return 3;
            }
        }
    }
    const auto advance = [&field_scene] {
        tap_qa_controller_button(field_scene, 0x40U);
    };
    for (std::size_t page = 1U; page < expected_text.size(); ++page) {
        advance();
        const auto& panel = field_scene.dialogue_panel();
        if (!field_scene.dialogue_open() || !page_matches(panel, page) ||
            !save("page-" + std::to_string(page) + ".bmp")) {
            std::cerr << "Redmond Vigore QA: A did not advance to source page "
                      << page << '\n';
            return 3;
        }
        record("page-" + std::to_string(page), page, 0U);
    }
    advance();
    const auto& records_after = field_scene.field_party_records_for_dump();
    const auto item_flags = field_scene.group_item_flags_for_dump();
    const auto expected_service_flags =
        field_flag_mask(FieldTitleServiceFlag::redmond_vigore_search_consumed);
    if (field_scene.dialogue_open() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        !item_flags.has_value() ||
        (*item_flags & group_item_flag_mask(GroupItemFlag::landmark_map)) == 0U ||
        (field_scene.field_world_fact_flags_for_dump() &
         field_flag_mask(FieldWorldFactFlag::redmond_vigore_search_complete)) == 0U ||
        (field_scene.field_mode_effect_flags_for_dump() & expected_service_flags) == 0U ||
        (field_scene.field_render_effect_flags_for_dump() &
         (field_flag_mask(FieldRenderEffectFlag::redmond_search_cleanup_09) |
          field_flag_mask(FieldRenderEffectFlag::redmond_search_cleanup_14) |
          field_flag_mask(FieldRenderEffectFlag::redmond_search_cleanup_19) |
          field_flag_mask(FieldRenderEffectFlag::redmond_search_cleanup_29))) != 0U ||
        records_after.size() != karma_before.size() ||
        !std::equal(records_after.begin(), records_after.end(),
                    karma_before.begin(), [](const auto& record,
                                             const std::uint8_t karma) {
                        return record.auxiliary[2U] ==
                               static_cast<std::uint8_t>(karma + 2U);
                    }) ||
        field_audio_events.size() != audio_before ||
        !save("returned-field.bmp")) {
        std::cerr << "Redmond Vigore QA: completion did not grant the source map, "
                     "one-shot flags and party Karma, or clear the dialogue cleanly\n";
        return 3;
    }
    record("returned-field", approach_frames, 0U);
    for (unsigned idle = 1U; idle <= 60U; ++idle) {
        field_scene.advance_frame();
        auto image = render();
        std::ostringstream frame_name;
        frame_name << "return-fade-" << std::setw(2) << std::setfill('0')
                   << idle << ".bmp";
        if (!image.save(QString::fromStdWString(
                (output / frame_name.str()).wstring()))) {
            std::cerr << "Redmond Vigore QA: return fade dump failed\n";
            return 3;
        }
        const auto remaining = static_cast<unsigned>(
            field_scene.field_modal_return_transition_frames_for_dump());
        const auto expected_fade_steps = static_cast<std::uint8_t>(
            (remaining * 9U + 30U) / 60U);
        if (field_scene.dialogue_open() ||
            field_scene.field_palette_fade_steps_for_dump() !=
                expected_fade_steps) {
            std::cerr << "Redmond Vigore QA: dialogue residue or source-timed "
                         "60-frame return fade mismatch at frame "
                      << idle << " remaining=" << remaining << " fade="
                      << static_cast<unsigned>(
                             field_scene.field_palette_fade_steps_for_dump())
                      << '\n';
            return 3;
        }
    }
    if (field_scene.dialogue_open() ||
        field_scene.field_scene_reference_for_dump() != 2U ||
        field_scene.field_mode_event_code_for_dump() != 7U ||
        field_scene.field_transition_pending_for_dump() ||
        field_scene.field_modal_return_transition_frames_for_dump() != 0U ||
        field_audio_events.size() != audio_before || !save("actual.bmp")) {
        std::cerr << "Redmond Vigore QA: return did not settle on the original "
                     "field route; scene="
                  << field_scene.field_scene_reference_for_dump() << " event="
                  << static_cast<unsigned>(
                         field_scene.field_mode_event_code_for_dump())
                  << " modal=" << field_scene.dialogue_open()
                  << " transition_frames=" << static_cast<unsigned>(
                         field_scene.field_modal_return_transition_frames_for_dump())
                  << " pending="
                  << field_scene.field_transition_pending_for_dump()
                  << " audio_delta="
                  << (field_audio_events.size() - audio_before) << '\n';
        return 3;
    }
    const auto final_image = render();
    if (!field_hud_chrome_survives(final_image, asset_root) ||
        count_playfield_lit(final_image) < 100U ||
        final_image == page_zero_image) {
        std::cerr << "Redmond Vigore QA: field HUD/playfield did not replace "
                     "the full-screen dialogue panel cleanly\n";
        return 3;
    }
    std::cout << "field_redmond_vigore_search_qa=passed scene=2 event=7 "
                 "pages=3 landmark_map=yes all_party_karma_delta=2 "
                 "audio_events=0 artifacts=" << output.string() << '\n';
    return 0;
}

